async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7492);
  noiseSeed(7492);

  // Custom brushes tailored for hyperreal gouache/watercolor, wood grain, and hand-painted liner details
  brush.add("gouache", {
    type: "default",
    weight: 6.5,
    scatter: 0.18,
    sharpness: 0.62,
    grain: 14,
    opacity: 175,
    spacing: 0.25,
    pressure: [0.8, 1.15, 0.85],
    rotate: "natural",
    noise: 0.4
  });

  brush.add("fine_liner", {
    type: "default",
    weight: 1.1,
    scatter: 0.03,
    sharpness: 0.9,
    grain: 3,
    opacity: 240,
    spacing: 0.12,
    pressure: [0.75, 1.15, 0.65],
    rotate: "natural",
    noise: 0.65
  });

  brush.add("dot_tip", {
    type: "marker",
    weight: 2.0,
    scatter: 0.02,
    opacity: 245,
    spacing: 0.08,
    pressure: [1.0, 1.0],
    markerTip: true,
    noise: 0.25
  });

  brush.add("wood_fiber", {
    type: "default",
    weight: 1.5,
    scatter: 0.45,
    sharpness: 0.78,
    grain: 32,
    opacity: 95,
    spacing: 0.3,
    pressure: [0.5, 1.2, 0.4],
    rotate: "natural",
    noise: 0.8
  });

  brush.add("chisel_edge", {
    type: "marker",
    weight: 3.5,
    scatter: 0.08,
    opacity: 70,
    spacing: 0.2,
    pressure: [0.6, 1.1, 0.6],
    markerTip: false,
    noise: 0.3
  });
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawShapeFill(pts, col, opacity = 150, bleed = 0.08, tex = 0.55, border = 0.35, curve = 0.08) {
  resetBrushState();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curve);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function drawShapeWash(pts, col, opacity = 210, curve = 0.06) {
  resetBrushState();
  brush.wash(col, opacity);
  brush.beginShape(curve);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function drawOpaqueWatercolourField(pts, baseCol, layerCol, hatchCol, angle = 30, spacing = 7, curve = 0.08) {
  // 1. Solid/semi-opaque pigment under-wash so dark studio ground does not bleed through
  drawShapeWash(pts, baseCol, 225, curve);
  // 2. Layered watercolor bloom with pigment granulation and edge border
  drawShapeFill(pts, layerCol, 155, 0.04, 0.68, 0.48, curve);
  // 3. Directional gouache brush texture inside the shape
  resetBrushState();
  brush.hatchStyle("gouache", hatchCol, 0.55);
  brush.hatch(spacing, angle, { rand: 0.08, continuous: true, gradient: 0.25 });
  brush.beginShape(curve);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function drawFacetHighlight(pts, col, opacity = 65, angle = 20) {
  resetBrushState();
  brush.wash(col, opacity);
  brush.hatchStyle("chisel_edge", col, 0.5);
  brush.hatch(9, angle, { rand: 0.1, continuous: false, gradient: 0.5 });
  brush.beginShape(0.04);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function quadPt(p00, p10, p11, p01, u, v) {
  let top = lerpPt(p00, p10, u);
  let bot = lerpPt(p01, p11, u);
  return lerpPt(top, bot, v);
}

// Visibly human hand-dabbed paint dot (slight organic wobble & bristle release)
function drawHandDot(x, y, size, col, highlightCol = null) {
  let jx = x + randomGaussian(0, 0.45);
  let jy = y + randomGaussian(0, 0.45);
  let ang = random(0, 180);
  let d = max(0.8, size * 0.32);
  let dx = cos(ang) * d;
  let dy = sin(ang) * d;
  brush.set("dot_tip", col, size * random(0.92, 1.08));
  brush.line(jx - dx, jy - dy, jx + dx, jy + dy);
  if (highlightCol && size > 0.75) {
    brush.set("dot_tip", highlightCol, size * 0.42);
    brush.line(jx - dx * 0.6 - 0.5, jy - dy * 0.6 - 0.4, jx - 0.2, jy - 0.2);
  }
}

// Chain of hand-painted dots along a polyline
function drawDotChain(pts, count, sizeStart, sizeEnd, col, highlightCol = null, jitter = 0.7) {
  // Compute cumulative lengths
  let segs = [];
  let totalLen = 0;
  for (let i = 0; i < pts.length - 1; i++) {
    let d = dist(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    segs.push({ a: pts[i], b: pts[i + 1], len: d, start: totalLen });
    totalLen += d;
  }
  if (totalLen < 1) return;

  for (let i = 0; i < count; i++) {
    let t = count === 1 ? 0.5 : i / (count - 1);
    // Slight human rhythm variance in spacing
    let tHuman = constrain(t + randomGaussian(0, 0.008), 0, 1);
    let targetDist = tHuman * totalLen;
    let seg = segs[segs.length - 1];
    for (let s of segs) {
      if (targetDist >= s.start && targetDist <= s.start + s.len) {
        seg = s;
        break;
      }
    }
    let localT = seg.len > 0 ? (targetDist - seg.start) / seg.len : 0;
    let p = lerpPt(seg.a, seg.b, localT);
    let sz = lerp(sizeStart, sizeEnd, t) * random(0.9, 1.12);
    drawHandDot(p[0] + randomGaussian(0, jitter), p[1] + randomGaussian(0, jitter), sz, col, highlightCol);
  }
}

// Hand-painted fine line with slight human tremor
function drawHandLine(x1, y1, x2, y2, col, weight = 0.7, wobble = 0.9) {
  let d = dist(x1, y1, x2, y2);
  let steps = max(2, floor(d / 18));
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);
    if (i > 0 && i < steps) {
      x += randomGaussian(0, wobble);
      y += randomGaussian(0, wobble);
    }
    pts.push([x, y, random(0.85, 1.15)]);
  }
  brush.set("fine_liner", col, weight);
  if (pts.length >= 3) {
    brush.spline(pts, 0.35);
  } else {
    brush.line(x1, y1, x2, y2);
  }
}

// Hand-painted chevron ribbon inside a quadrilateral strip
function drawChevronStrip(p00, p10, p11, p01, zigCount, col, weight = 0.68, dotCol = null, secondLineCol = null) {
  // Border rails
  drawHandLine(p00[0], p00[1], p10[0], p10[1], col, weight * 0.95, 0.7);
  drawHandLine(p01[0], p01[1], p11[0], p11[1], col, weight * 0.95, 0.7);

  for (let i = 0; i < zigCount; i++) {
    let u0 = i / zigCount;
    let uMid = (i + 0.5) / zigCount + randomGaussian(0, 0.008);
    let u1 = (i + 1) / zigCount;

    let a = quadPt(p00, p10, p11, p01, u0, 0.08 + randomGaussian(0, 0.02));
    let apex = quadPt(p00, p10, p11, p01, uMid, 0.92 + randomGaussian(0, 0.02));
    let b = quadPt(p00, p10, p11, p01, u1, 0.08 + randomGaussian(0, 0.02));

    drawHandLine(a[0], a[1], apex[0], apex[1], col, weight, 0.55);
    drawHandLine(apex[0], apex[1], b[0], b[1], col, weight, 0.55);

    if (secondLineCol) {
      let a2 = quadPt(p00, p10, p11, p01, u0 + 0.08 / zigCount, 0.14);
      let apex2 = quadPt(p00, p10, p11, p01, uMid, 0.72);
      let b2 = quadPt(p00, p10, p11, p01, u1 - 0.08 / zigCount, 0.14);
      drawHandLine(a2[0], a2[1], apex2[0], apex2[1], secondLineCol, weight * 0.8, 0.45);
      drawHandLine(apex2[0], apex2[1], b2[0], b2[1], secondLineCol, weight * 0.8, 0.45);
    }

    if (dotCol) {
      let dTop = quadPt(p00, p10, p11, p01, uMid, 0.34);
      drawHandDot(dTop[0], dTop[1], weight * 1.15, dotCol);
      let dBot = quadPt(p00, p10, p11, p01, u0, 0.72);
      if (i > 0) drawHandDot(dBot[0], dBot[1], weight * 0.95, dotCol);
    }
  }
}

// Hand-painted Zapotec / Oaxacan Eye-Motif (almond or diamond eye with lashes and dots)
function drawEyeMotif(cx, cy, rx, ry, rotDeg, bgCol, ringCol, irisCol, pupilCol, dotCol) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  function rotPt(lx, ly) {
    return [cx + lx * c - ly * s, cy + lx * s + ly * c];
  }

  // Outer almond polygon
  let outerPts = [];
  let innerPts = [];
  let steps = 14;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    // Pinch corners at 0 and 180 degrees for almond eye feel
    let pinch = pow(abs(sin(a)), 0.75) * (sin(a) >= 0 ? 1 : -1);
    let lx = cos(a) * rx;
    let ly = pinch * ry;
    outerPts.push(rotPt(lx + randomGaussian(0, 0.4), ly + randomGaussian(0, 0.4)));
    innerPts.push(rotPt(lx * 0.62, ly * 0.62));
  }

  if (bgCol) {
    drawShapeWash(outerPts, bgCol, 225, 0.12);
  }

  // Hand-drawn outer & inner almond rings
  for (let i = 0; i < steps; i++) {
    let p1 = outerPts[i];
    let p2 = outerPts[(i + 1) % steps];
    drawHandLine(p1[0], p1[1], p2[0], p2[1], ringCol, 0.68, 0.3);

    let q1 = innerPts[i];
    let q2 = innerPts[(i + 1) % steps];
    drawHandLine(q1[0], q1[1], q2[0], q2[1], irisCol, 0.58, 0.25);
  }

  // Central iris & pupil dab
  drawHandDot(cx, cy, min(rx, ry) * 0.18, irisCol);
  drawHandDot(cx, cy, min(rx, ry) * 0.1, pupilCol);
  drawHandDot(cx - 1.5, cy - 1.5, min(rx, ry) * 0.045, "#fff6dc");

  // Eyelash / ray ticks & surrounding dots
  let numRays = 12;
  for (let i = 0; i < numRays; i++) {
    let a = (i / numRays) * 360;
    let pinch = pow(abs(sin(a)), 0.75) * (sin(a) >= 0 ? 1 : -1);
    let pStart = rotPt(cos(a) * (rx + 2), pinch * (ry + 2));
    let pEnd = rotPt(cos(a) * (rx + 7), pinch * (ry + 6.5));
    let pDot = rotPt(cos(a) * (rx + 10.5), pinch * (ry + 9.5));
    drawHandLine(pStart[0], pStart[1], pEnd[0], pEnd[1], ringCol, 0.52, 0.25);
    if (dotCol) {
      drawHandDot(pDot[0], pDot[1], 0.7, dotCol);
    }
  }
}

// Hand-painted circular/oval Jaguar Rosette Medallion
function drawJaguarRosette(cx, cy, rx, ry, rotDeg, fillCol, petalCol, rimCol, dotCol, centerCol) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  function rotPt(lx, ly) {
    return [cx + lx * c - ly * s, cy + lx * s + ly * c];
  }

  let discPts = [];
  for (let i = 0; i < 16; i++) {
    let a = (i / 16) * 360;
    discPts.push(rotPt(cos(a) * rx, sin(a) * ry));
  }
  drawShapeWash(discPts, fillCol, 230, 0.15);

  // Scalloped petals inside
  let petals = 10;
  for (let i = 0; i < petals; i++) {
    let a0 = (i / petals) * 360;
    let aMid = ((i + 0.5) / petals) * 360;
    let a1 = ((i + 1) / petals) * 360;
    let p0 = rotPt(cos(a0) * rx * 0.42, sin(a0) * ry * 0.42);
    let pTip = rotPt(cos(aMid) * rx * 0.92, sin(aMid) * ry * 0.92);
    let p1 = rotPt(cos(a1) * rx * 0.42, sin(a1) * ry * 0.42);
    drawHandLine(p0[0], p0[1], pTip[0], pTip[1], petalCol, 0.65, 0.35);
    drawHandLine(pTip[0], pTip[1], p1[0], p1[1], petalCol, 0.65, 0.35);

    let dPos = rotPt(cos(aMid) * rx * 0.68, sin(aMid) * ry * 0.68);
    drawHandDot(dPos[0], dPos[1], 0.78, dotCol);

    let outerDot = rotPt(cos(aMid) * (rx + 5.5), sin(aMid) * (ry + 5.5));
    drawHandDot(outerDot[0], outerDot[1], 0.72, rimCol);
  }

  // Outer hand-drawn contour
  for (let i = 0; i < 16; i++) {
    let p1 = discPts[i];
    let p2 = discPts[(i + 1) % 16];
    drawHandLine(p1[0], p1[1], p2[0], p2[1], rimCol, 0.75, 0.35);
  }

  // Center eye / core
  drawHandDot(cx, cy, min(rx, ry) * 0.25, centerCol);
  drawHandDot(cx, cy, min(rx, ry) * 0.12, fillCol);
  drawHandDot(cx, cy, min(rx, ry) * 0.05, dotCol);
}

// Stepped Zapotec Fret (Greca) motif
function drawSteppedFret(cx, cy, w, h, rotDeg, lineCol, dotCol) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  function rotPt(lx, ly) {
    return [cx + lx * c - ly * s, cy + lx * s + ly * c];
  }
  // Classic stepped spiral path in local coords (-0.5..0.5)
  let raw = [
    [-0.48, 0.42], [-0.48, -0.42], [-0.15, -0.42], [-0.15, -0.15],
    [0.15, -0.15], [0.15, 0.12], [0.45, 0.12], [0.45, 0.42],
    [-0.22, 0.42], [-0.22, 0.12], [-0.02, 0.12]
  ];
  for (let i = 0; i < raw.length - 1; i++) {
    let p1 = rotPt(raw[i][0] * w, raw[i][1] * h);
    let p2 = rotPt(raw[i + 1][0] * w, raw[i + 1][1] * h);
    drawHandLine(p1[0], p1[1], p2[0], p2[1], lineCol, 0.72, 0.3);
  }
  if (dotCol) {
    let d1 = rotPt(-0.32 * w, -0.25 * h);
    let d2 = rotPt(0.30 * w, 0.27 * h);
    drawHandDot(d1[0], d1[1], 0.75, dotCol);
    drawHandDot(d2[0], d2[1], 0.75, dotCol);
  }
}

// Hyperreal shrinkage crack along the copal wood grain (interrupting the paint layer)
function drawShrinkageCrack(pts, maxW = 1.3, isRakingLit = true) {
  // 1. Pale raw copal wood exposed along the split edges where paint flaked micro-thinly
  for (let i = 0; i < pts.length - 1; i++) {
    let t = sin((i / (pts.length - 1)) * 180);
    let w = max(0.35, maxW * t);
    brush.set("fine_liner", "#e8d2ab", w * 1.45);
    brush.line(pts[i][0] + 0.9, pts[i][1] + 0.7, pts[i + 1][0] + 0.9, pts[i + 1][1] + 0.7);
    brush.set("fine_liner", "#cbb082", w * 1.1);
    brush.line(pts[i][0] - 0.7, pts[i][1] - 0.5, pts[i + 1][0] - 0.7, pts[i + 1][1] - 0.5);
  }
  // 2. Deep dark shadow inside the wood fissure
  for (let i = 0; i < pts.length - 1; i++) {
    let t = sin((i / (pts.length - 1)) * 180);
    let w = max(0.25, maxW * t);
    brush.set("rotring", "#120c08", w * 1.15);
    brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }
  // 3. Crisp raking light catching the right/lower edge of the crack
  if (isRakingLit) {
    for (let i = 1; i < pts.length - 2; i++) {
      let t = sin((i / (pts.length - 1)) * 180);
      brush.set("rotring", "#fff2d1", 0.45 * t + 0.2);
      brush.line(pts[i][0] + 1.3, pts[i][1] + 0.9, pts[i + 1][0] + 1.3, pts[i + 1][1] + 0.9);
    }
  }
}

