function drawStudioBackdropAndWorkbench() {
  background("#0e141d");

  // 1. STUDIO BACKDROP (y = 0 to 670): Cool Prussian-slate catalogue background
  // Left side catches warm raking glow from the low workshop lamp
  drawShapeFill([[0, 0], [1200, 0], [1200, 685], [0, 655]], "#141d2b", 180, 0.05, 0.6, 0.2);
  drawShapeFill([[450, 0], [1200, 0], [1200, 685], [520, 670]], "#0c121c", 165, 0.15, 0.55, 0.2);

  // Warm low workshop lamp glow entering from left (x = 0, y = 520)
  drawShapeFill([[0, 180], [520, 260], [620, 670], [0, 660]], "#38322c", 95, 0.35, 0.5, 0.15);
  drawShapeFill([[0, 310], [340, 380], [430, 665], [0, 660]], "#634e38", 85, 0.4, 0.45, 0.1);
  drawShapeFill([[0, 420], [210, 460], [260, 660], [0, 660]], "#8f6d46", 70, 0.45, 0.4, 0.1);

  // Subtle vertical backdrop paper/linen texture in studio shadow
  for (let i = 0; i < 95; i++) {
    let x = random(0, 1200);
    let y1 = random(0, 500);
    let y2 = y1 + random(80, 260);
    let col = x < 380 ? "#2d2a28" : "#111926";
    brush.set("charcoal", col, random(0.4, 0.9));
    brush.line(x, y1, x + random(-4, 4), min(665, y2));
  }

  // 2. WORKBENCH BASE (y = 650 to 1200): Weathered cool-grey & warm-lit workshop planks
  let plankY = [
    [652, 682], // Back edge of bench
    [742, 776], // Seam 1
    [868, 906], // Seam 2
    [1025, 1068], // Seam 3
    [1200, 1200]
  ];

  let plankBaseCols = ["#2c333d", "#323944", "#282f3a", "#212730"];
  for (let p = 0; p < 4; p++) {
    let pts = [
      [0, plankY[p][0]],
      [1200, plankY[p][1]],
      [1200, plankY[p + 1][1]],
      [0, plankY[p + 1][0]]
    ];
    drawShapeWash(pts, plankBaseCols[p], 235, 0.02);
    drawShapeFill(pts, "#1e2530", 110, 0.05, 0.72, 0.4, 0.02);
  }

  // Warm raking lamp light sweeping across the left half of the workbench
  drawShapeFill([[0, 652], [680, 668], [760, 1120], [0, 1160]], "#695947", 110, 0.3, 0.65, 0.25);
  drawShapeFill([[0, 665], [460, 680], [520, 1040], [0, 1080]], "#91785b", 95, 0.35, 0.6, 0.2);
  drawShapeFill([[0, 700], [290, 725], [330, 960], [0, 990]], "#b5966e", 80, 0.35, 0.55, 0.15);

  // Cool deep shadow on right side of workbench
  drawShapeFill([[680, 668], [1200, 682], [1200, 1200], [560, 1200]], "#131924", 145, 0.25, 0.65, 0.3);

  // 3. WORKBENCH WOOD GRAIN, KNOTS, GOUGES & OLD PAINT SPECKS
  for (let p = 0; p < 4; p++) {
    let yTopL = plankY[p][0];
    let yTopR = plankY[p][1];
    let yBotL = plankY[p + 1][0];
    let yBotR = plankY[p + 1][1];

    // Longitudinal grain fibers following plank tilt
    let grainLines = 55;
    for (let g = 0; g < grainLines; g++) {
      let v = (g + random(0.1, 0.9)) / grainLines;
      let xStart = random(0, 950);
      let xEnd = min(1200, xStart + random(140, 480));
      let y1 = lerp(yTopL, yBotL, v) + (yTopR - yTopL) * (xStart / 1200);
      let y2 = lerp(yTopL, yBotL, v) + (yTopR - yTopL) * (xEnd / 1200);
      let midX = (xStart + xEnd) * 0.5;
      let midY = (y1 + y2) * 0.5 + sin(g * 28 + p * 70) * 5;

      let isLit = xStart < 520;
      let grainCol = isLit
        ? (random() < 0.45 ? "#4a3f35" : "#bfa37c")
        : (random() < 0.6 ? "#151b24" : "#384250");
      brush.set("wood_fiber", grainCol, random(0.45, 1.1));
      brush.spline([[xStart, y1], [midX, midY], [xEnd, y2]], 0.3);
    }

    // Plank seam crevices & raking warm lip highlight on top edge of each plank
    if (p > 0) {
      brush.set("charcoal", "#090c12", 1.8);
      brush.line(0, yTopL, 1200, yTopR);
      brush.set("rotring", "#161c26", 1.1);
      brush.line(0, yTopL + 1.5, 1200, yTopR + 1.5);
      // Warm raking highlight catching the plank lip on the left
      brush.set("fine_liner", "#ccb089", 0.95);
      brush.line(0, yTopL + 2.6, 580, lerp(yTopL, yTopR, 580 / 1200) + 2.6);
      brush.set("fine_liner", "#596475", 0.65);
      brush.line(580, lerp(yTopL, yTopR, 580 / 1200) + 2.6, 1200, yTopR + 2.6);
    }
  }

  // Top edge of workbench against dark backdrop
  brush.set("charcoal", "#080b10", 1.6);
  brush.line(0, 652, 1200, 682);
  brush.set("fine_liner", "#bda07a", 0.9);
  brush.line(0, 654, 540, 666);

  // Subtle dried workshop paint flecks & chisel nicks on the rough bench
  let oldColors = ["#1c6e73", "#8a244b", "#b88228", "#cbb693", "#18202c"];
  for (let i = 0; i < 65; i++) {
    let sx = random(40, 1140);
    let sy = random(690, 1160);
    let col = random(oldColors);
    brush.set("2B", col, random(0.4, 0.9));
    brush.line(sx, sy, sx + random(2, 9), sy + random(-2, 2));
  }
}

function drawCastShadowsOnBench() {
  // Long soft shadows thrown to the right by the low left-side workshop lamp
  // 1. Broad soft body shadow umbra & penumbra stretching right
