    [1022, 372], [992, 294], [932, 256], [884, 282], [892, 322]
  ];
  let tailRadii = [25, 22, 20, 18, 16, 14, 12, 10, 7];

  // Build segmented color rings along the tail
  let ringCols = [
    ["#121720", "#1b2230", "#0a0d12"], // Black base
    ["#9c6810", "#c4861b", "#754c08"], // Saffron
    ["#005e66", "#007a85", "#004248"], // Turquoise
    ["#7d123b", "#a3194e", "#590a28"], // Magenta
    ["#121720", "#1b2230", "#0a0d12"], // Black
    ["#005e66", "#007a85", "#004248"], // Turquoise
    ["#9c6810", "#c4861b", "#754c08"], // Saffron
    ["#7d123b", "#a3194e", "#590a28"]  // Magenta tip
  ];

  for (let i = 0; i < tailSpine.length - 1; i++) {
    let p0 = tailSpine[i];
    let p1 = tailSpine[i + 1];
    let r0 = tailRadii[i];
    let r1 = tailRadii[i + 1];

    let ang = atan2(p1[1] - p0[1], p1[0] - p0[0]) + 90;
    let nx0 = cos(ang) * r0;
    let ny0 = sin(ang) * r0;
    let nx1 = cos(ang) * r1;
    let ny1 = sin(ang) * r1;

    let segQuad = [
      [p0[0] - nx0, p0[1] - ny0],
      [p1[0] - nx1, p1[1] - ny1],
      [p1[0] + nx1, p1[1] + ny1],
      [p0[0] + nx0, p0[1] + ny0]
    ];
    let cols = ringCols[i % ringCols.length];
    drawOpaqueWatercolourField(segQuad, cols[0], cols[1], cols[2], ang - 90, 5, 0.1);

    // Hand-painted chevrons or dot rings on each tail segment
    let decCol = i % 2 === 0 ? "#d99b26" : "#38c5cc";
    let dotCol = i % 2 === 0 ? "#ff5998" : "#ffe07d";
    drawChevronStrip(segQuad[0], segQuad[1], segQuad[2], segQuad[3], 4, decCol, 0.62, dotCol);
    drawHandLine(segQuad[1][0], segQuad[1][1], segQuad[2][0], segQuad[2][1], "#0d1118", 0.85, 0.3);
  }

  // Authentic Oaxacan Copal Craft Detail: Fitted tail-joint seam at base of tail (826, 468..518)
  drawShrinkageCrack([[825, 468], [821, 484], [822, 502], [827, 518]], 1.4, false);
}

