function drawCurledWoodShaving(cx, cy, sc = 1.0, rotDeg = 0) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  function rotPt(lx, ly) {
    return [cx + (lx * c - ly * s) * sc, cy + (lx * s + ly * c) * sc];
  }

  // 1. Cast shadow to the right on the workbench
  let shadowPts = [
    rotPt(-18, 4), rotPt(28, 2), rotPt(46, 12), rotPt(14, 18), rotPt(-12, 12)
  ];
  drawShapeFill(shadowPts, "#080b11", 175, 0.14, 0.45, 0.25, 0.15);

  // 2. Outer shaded curl of copal wood shaving (warm golden buff)
  let outerRibbon = [
    rotPt(-28, 2), rotPt(-12, -12), rotPt(14, -14), rotPt(32, -2),
    rotPt(24, 10), rotPt(2, 12), rotPt(-18, 10)
  ];
  drawShapeWash(outerRibbon, "#cfa974", 242, 0.18);
  drawShapeFill(outerRibbon, "#b38952", 140, 0.04, 0.65, 0.4, 0.18);

  // 3. Inner lit curl catching the warm raking lamp light (creamy blond copal)
  let innerCurl = [
    rotPt(-22, -1), rotPt(-6, -10), rotPt(16, -8), rotPt(22, 2),
    rotPt(8, 6), rotPt(-10, 4)
  ];
  drawShapeWash(innerCurl, "#f7e8c8", 245, 0.18);

  // 4. Deep recessed pocket inside the spiral curl
  let curlHollow = [
    rotPt(-4, -3), rotPt(10, -3), rotPt(14, 3), rotPt(2, 5)
  ];
  drawShapeWash(curlHollow, "#6e4f28", 225, 0.15);

  // 5. Fine wood fiber lines & serrated gouge edges
  let g1 = rotPt(-22, 1);
  let g2 = rotPt(-4, -8);
  let g3 = rotPt(18, -5);
  brush.set("wood_fiber", "#9c7440", 0.65);
  brush.spline([g1, g2, g3], 0.4);

  let h1 = rotPt(-25, 0);
  let h2 = rotPt(-8, -11);
  let h3 = rotPt(14, -12);
  drawHandLine(h1[0], h1[1], h2[0], h2[1], "#fff7e2", 0.65, 0.2);
  drawHandLine(h2[0], h2[1], h3[0], h3[1], "#fff7e2", 0.55, 0.2);
}

function drawWoodChip(cx, cy, w, h, rotDeg) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  function rotPt(lx, ly) {
    return [cx + lx * c - ly * s, cy + lx * s + ly * c];
  }
  // Tiny cast shadow
  drawShapeWash([
    rotPt(-w * 0.3, h * 0.2), rotPt(w * 0.9, h * 0.1), rotPt(w * 1.1, h * 0.7), rotPt(-w * 0.2, h * 0.7)
  ], "#090d14", 205, 0.04);

  // Raw copal wood chip
  let chipPts = [
    rotPt(-w * 0.5, -h * 0.4), rotPt(w * 0.45, -h * 0.5),
    rotPt(w * 0.55, h * 0.35), rotPt(-w * 0.45, h * 0.45)
  ];
  drawShapeWash(chipPts, "#ebd6b0", 245, 0.03);
  let pA = rotPt(-w * 0.45, -h * 0.35);
  let pB = rotPt(w * 0.4, -h * 0.45);
  drawHandLine(pA[0], pA[1], pB[0], pB[1], "#fff6de", 0.55, 0.15);
}

