function draw() {
  translate(-width / 2, -height / 2);

  // 1. Studio catalogue backdrop & weathered wooden workbench with raking lamp light
  drawStudioBackdropAndWorkbench();

  // 2. Long soft cast shadows & contact occlusion on the workbench
  drawCastShadowsOnBench();

  // 3. Carved Copal-Wood Alebrije Jaguar (rendered back-to-front)
  drawFarLegs();
  drawTorsoAndChest();
  drawForegroundHindLegAndTail();
  drawForegroundFrontLeg();
  drawHeadAndChippedEar();

  // 4. Hyperreal wood shrinkage cracks & chisel facet highlights
  drawWoodFlawsAndChiselDetails();

  // 5. Curled copal-wood shavings, wood chips, sawdust & dropped detail brush
  drawDroppedBrushAndShavings();

  noLoop();
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(1084);
  noiseSeed(1084);

  // Custom brushes for dense burnished coloured pencil and wet specular highlights
  brush.add("burnish", {
    type: "default",
    weight: 1.6,
    scatter: 0.12,
    sharpness: 0.35,
    grain: 0.45,
    opacity: 185,
    spacing: 0.25,
    pressure: [0.6, 1.25, 0.5],
    noise: 0.35
  });

  brush.add("fine_pencil", {
    type: "default",
    weight: 0.55,
    scatter: 0.05,
    sharpness: 0.78,
    grain: 0.65,
    opacity: 210,
    spacing: 0.2,
    pressure: [0.4, 1.0, 0.4],
    noise: 0.5
  });

  brush.add("wet_gloss", {
    type: "marker",
    weight: 1.1,
    scatter: 0.02,
    opacity: 245,
    spacing: 0.18,
    pressure: [0.8, 1.2, 0.7],
    markerTip: false,
    noise: 0.1
  });

  brush.scaleBrushes(3);
}

