  arilKernel: "#f59ca4",
  arilCore: "#fcdcdf",
  arilGloss: "#ffffff",

  // Quince (ochre, saffron, raw sienna, green-gold, fuzz)
  quinceDeep: "#6e4611",
  quinceSienna: "#9e6016",
  quinceOchre: "#c9841c",
  quinceSaffron: "#e6a629",
  quinceGold: "#f5c542",
  quinceHighlight: "#fae28c",
  quinceGreen: "#7d7522",
  quinceFuzz: "#f2ead5",
  quinceFuzzWarm: "#ded2b6",
  quinceFlesh: "#faefd7",
  quinceFleshMid: "#ebd2a4",
  quinceCore: "#c78b56",
  quinceSeed: "#422012",

  // Leaves & vines (deep olive, moss, bronze, woody bistre)
  stemDark: "#382416",
  stemMid: "#5c3d26",
  stemLight: "#876142",
  leafAbyss: "#1f2912",
  leafDeepOlive: "#32421c",
  leafOlive: "#485c29",
  leafMoss: "#637837",
  leafWarm: "#849447",
  leafVein: "#a8b368",
  leafUnderside: "#7d8259"
};

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.linenBase);

  const cx = 600;
  const cy = 600;

  // 1. UNBLEACHED CREAM LINEN GROUND & DIRECTIONAL WEAVE
  drawLinenGround(cx, cy);

  // 2. CEREMONIAL DOWRY CLOTH DRAWN-THREAD BORDER & SUBTLE MEDALLION RINGS
  drawDowryClothEmbroidery(cx, cy);

  // 3. ROSE WATERCOLOUR JUICE STAINS (blooming into the linen weave)
  drawJuiceStains(cx, cy);

  // 4. SOFT AMBIENT & CONTACT SHADOWS UNDER VINES AND MEDALLIONS
  drawCompositionShadows(cx, cy);

  // 5. TRAILING VINES, STEMS & DEEP OLIVE LEAVES (under-layer)
  drawTrailingVinesAndLeaves(cx, cy, "under");

  // 6. OUTER MEDALLIONS: 4 GOLDEN QUINCES (DIAGONALS) & 4 HALVED POMEGRANATES (CARDINALS)
  drawOuterMedallions(cx, cy);

  // 7. INNER MEDALLION RING: 4 HALVED QUINCES & 4 CLEFT POMEGRANATE WEDGES
  drawInnerMedallionRing(cx, cy);

  // 8. CENTRAL HERO MEDALLION: GRAND EQUATORIAL HALVED POMEGRANATE
  drawHalvedPomegranateEquatorial(cx, cy, 128, 18, true);

  // 9. OVERLAPPING LEAVES & STEMS (upper-layer)
  drawTrailingVinesAndLeaves(cx, cy, "over");

  // 10. SCATTERED WET RUBY ARILS & TINY JUICE DROPLETS ON THE CLOTH
  drawScatteredArils(cx, cy);

  noLoop();
}

// ============================================================================
// 1. LINEN GROUND & DIRECTIONAL PENCIL WEAVE
// ============================================================================
function drawLinenGround(cx, cy) {
  // Subtle organic folds and warm antique vignette in watercolor wash
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.3);

  brush.fill(PAL.linenWarm, 45);
  brush.circle(cx, cy, 520, 0.15);

  // Corner warm patina
  const corners = [
    [90, 90], [1110, 90], [1110, 1110], [90, 1110],
    [600, 60], [600, 1140], [60, 600], [1140, 600]
  ];
  for (let [x, y] of corners) {
    brush.circle(x, y, 240, 0.25);
  }

  // Gentle diagonal crease folds like a folded dowry cloth
  brush.fill(PAL.linenShadow, 28);
  for (let i = -1; i <= 1; i += 2) {
    drawSoftBand(cx + i * 290, 40, cx + i * 290, 1160, 26);
    drawSoftBand(40, cy + i * 290, 1160, cy + i * 290, 26);
  }
  brush.noFill();

  // Fine directional pencil weave (warp and weft threads across the cloth)
  brush.noField();
  const step = 7;
  // Horizontal weft threads
  for (let y = 24; y < 1176; y += step) {
    let n = noise(y * 0.03);
    let col = n > 0.62 ? PAL.weaveDark : (n < 0.35 ? PAL.weaveLight : PAL.weaveMid);
    let wt = map(n, 0, 1, 0.22, 0.48);
    brush.set("2H", col, wt);
    // Draw in broken segments to mimic natural slub linen yarn
    let x = 24 + random(0, 12);
    while (x < 1176) {
      let segLen = random(95, 260);
      let x2 = min(1176, x + segLen);
      let yOff = (noise(x * 0.01, y * 0.05) - 0.5) * 1.4;
      brush.line(x, y + yOff, x2, y - yOff * 0.5);
      x = x2 + random(4, 18);
    }
  }

  // Vertical warp threads
  for (let x = 24; x < 1176; x += step) {
    let n = noise(x * 0.03 + 100);
    let col = n > 0.64 ? PAL.weaveDark : (n < 0.36 ? PAL.weaveLight : PAL.weaveMid);
    let wt = map(n, 0, 1, 0.2, 0.45);
    brush.set("2H", col, wt);
    let y = 24 + random(0, 12);
    while (y < 1176) {
      let segLen = random(95, 260);
      let y2 = min(1176, y + segLen);
      let xOff = (noise(x * 0.05, y * 0.01 + 50) - 0.5) * 1.4;
      brush.line(x + xOff, y, x - xOff * 0.5, y2);
      y = y2 + random(4, 18);
    }
  }

  // Occasional thicker slub threads (characteristic of unbleached hand-loomed linen)
  for (let i = 0; i < 85; i++) {
    let horiz = random() < 0.5;
    let col = random() < 0.45 ? PAL.weaveLight : PAL.linenDeep;
    brush.set("fine_pencil", col, random(0.45, 0.8));
    if (horiz) {
      let y = random(35, 1165);
      let x1 = random(35, 1020);
      let x2 = min(1165, x1 + random(60, 180));
      brush.line(x1, y, x2, y);
    } else {
      let x = random(35, 1165);
      let y1 = random(35, 1020);
      let y2 = min(1165, y1 + random(60, 180));
      brush.line(x, y1, x, y2);
    }
  }
}

function drawSoftBand(x1, y1, x2, y2, w) {
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang) * w * 0.5;
  let ny = cos(ang) * w * 0.5;
  brush.beginShape(0.2);
  brush.vertex(x1 + nx, y1 + ny);
  brush.vertex(x2 + nx, y2 + ny);
  brush.vertex(x2 - nx, y2 - ny);
  brush.vertex(x1 - nx, y1 - ny);
  brush.endShape(true);
}

// ============================================================================
// 2. CEREMONIAL DOWRY CLOTH BORDER & SYMMETRICAL MEDALLION RINGS
// ============================================================================
function drawDowryClothEmbroidery(cx, cy) {
  // Drawn-thread hemstitch border at margin 52 and 78
  const m1 = 52;
  const m2 = 78;

  brush.set("2H", PAL.linenDeep, 0.55);
  brush.line(m1, m1, 1200 - m1, m1);
  brush.line(1200 - m1, m1, 1200 - m1, 1200 - m1);
  brush.line(1200 - m1, 1200 - m1, m1, 1200 - m1);
  brush.line(m1, 1200 - m1, m1, m1);

  brush.line(m2, m2, 1200 - m2, m2);
  brush.line(1200 - m2, m2, 1200 - m2, 1200 - m2);
  brush.line(1200 - m2, 1200 - m2, m2, 1200 - m2);
  brush.line(m2, 1200 - m2, m2, m2);

  // Hemstitch ladder bundles around the border
  for (let p = m2; p <= 1200 - m2; p += 10) {
    brush.set("2H", PAL.weaveDark, 0.4);
    brush.line(p, m1 + 2, p, m2 - 2);
    brush.line(p, 1200 - m2 + 2, p, 1200 - m1 - 2);
    brush.line(m1 + 2, p, m2 - 2, p);
    brush.line(1200 - m2 + 2, p, 1200 - m1 - 2, p);

    brush.set("2H", PAL.weaveLight, 0.45);
    brush.line(p + 3, m1 + 3, p + 3, m2 - 3);
    brush.line(p + 3, 1200 - m2 + 3, p + 3, 1200 - m1 - 3);
  }

  // Subtle ceremonial circular medallion rings woven into the cloth
  const ringRadii = [152, 272, 286, 478, 492];
  for (let r of ringRadii) {
    brush.set("2H", PAL.weaveDark, 0.42);
    brush.circle(cx, cy, r, 0.03);
    brush.set("2H", PAL.weaveLight, 0.35);
    brush.circle(cx, cy, r + 2.5, 0.03);
  }

  // Delicate geometric needlework band between r=272 and r=286, and r=478 and r=492
  for (let a = 0; a < 360; a += 3) {
    let a2 = a + 1.5;
    let x1 = cx + cos(a) * 273;
    let y1 = cy + sin(a) * 273;
    let x2 = cx + cos(a2) * 285;
    let y2 = cy + sin(a2) * 285;
    let x3 = cx + cos(a + 3) * 273;
    let y3 = cy + sin(a + 3) * 273;
    brush.set("2H", PAL.hemThread, 0.35);
    brush.line(x1, y1, x2, y2);
    brush.line(x2, y2, x3, y3);
  }

  for (let a = 0; a < 360; a += 2) {
    let a2 = a + 1;
    let x1 = cx + cos(a) * 479;
    let y1 = cy + sin(a) * 479;
    let x2 = cx + cos(a2) * 491;
    let y2 = cy + sin(a2) * 491;
    brush.set("2H", PAL.hemThread, 0.32);
    brush.line(x1, y1, x2, y2);
  }
}

// ============================================================================
// 3. BLOOMING ROSE WATERCOLOUR JUICE STAINS
// ============================================================================
function drawJuiceStains(cx, cy) {
  // Stains positioned organically near cut pomegranates and loose aril clusters
  const stains = [
    // Near central pomegranate
    { x: cx + 95, y: cy + 108, r: 42, intensity: 1.0 },
    { x: cx - 118, y: cy - 82, r: 34, intensity: 0.85 },
    { x: cx + 28, y: cy - 135, r: 26, intensity: 0.75 },
    // Near top pomegranate
    { x: cx + 78, y: 245, r: 38, intensity: 0.95 },
    { x: cx - 92, y: 175, r: 24, intensity: 0.7 },
    // Near bottom pomegranate
    { x: cx - 84, y: 955, r: 44, intensity: 1.0 },
    { x: cx + 98, y: 1030, r: 28, intensity: 0.8 },
    // Near left pomegranate
    { x: 245, y: cy - 88, r: 36, intensity: 0.9 },
    { x: 162, y: cy + 95, r: 25, intensity: 0.75 },
    // Near right pomegranate
    { x: 955, y: cy + 84, r: 40, intensity: 0.95 },
    { x: 1035, y: cy - 76, r: 22, intensity: 0.7 },
    // Smaller spatter blooms along the cloth
    { x: 430, y: 410, r: 18, intensity: 0.7 },
    { x: 780, y: 425, r: 16, intensity: 0.65 },
    { x: 415, y: 785, r: 20, intensity: 0.75 },
    { x: 775, y: 790, r: 19, intensity: 0.7 },
    { x: 525, y: 335, r: 12, intensity: 0.6 },
    { x: 678, y: 868, r: 14, intensity: 0.65 },
    { x: 335, y: 525, r: 13, intensity: 0.6 },
    { x: 865, y: 675, r: 15, intensity: 0.65 }
  ];

  // Batch 1: Outer pale rose watercolor bleed following the linen weave
  brush.noStroke();
  brush.fillBleed(0.55, "out");
  brush.fillTexture(0.75, 0.7);
  brush.fill(PAL.stainPale, 55);
  for (let s of stains) {
    drawWovenStainShape(s.x, s.y, s.r * 1.25);
  }

  // Batch 2: Mid rose-crimson bloom with capillary tide ring
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.8, 0.85);
  brush.fill(PAL.stainMid, 68);
  for (let s of stains) {
    drawWovenStainShape(s.x + random(-2, 2), s.y + random(-2, 2), s.r * 0.82);
  }

  // Batch 3: Deep madder heart on the larger stains
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.65, 0.75);
  brush.fill(PAL.stainDeep, 75);
  for (let s of stains) {
    if (s.intensity > 0.75) {
      drawWovenStainShape(s.x, s.y, s.r * 0.42);
    }
  }
  brush.noFill();

  // Capillary wicking along individual warp/weft linen threads at stain edges
  for (let s of stains) {
    brush.set("2H", PAL.stainEdge, 0.35);
    let count = floor(s.r * 0.8);
    for (let i = 0; i < count; i++) {
      let a = random(360);
      let d = s.r * random(0.65, 1.25);
      let px = s.x + cos(a) * d;
      let py = s.y + sin(a) * d;
      let wickLen = random(4, 14);
      if (random() < 0.5) {
        brush.line(px - wickLen * 0.5, py, px + wickLen * 0.5, py);
      } else {
        brush.line(px, py - wickLen * 0.5, px, py + wickLen * 0.5);
      }
    }
  }
}

function drawWovenStainShape(x, y, r) {
  brush.beginShape(0.35);
  let steps = 16;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    // Slight cruciform/axis bias because liquid wicks faster along warp & weft
    let axisBias = 1 + 0.14 * pow(cos(a * 2), 2);
    let n = noise(x * 0.02 + cos(a) * 1.3, y * 0.02 + sin(a) * 1.3);
    let rad = r * axisBias * map(n, 0, 1, 0.72, 1.24);
    brush.vertex(x + cos(a) * rad, y + sin(a) * rad);
  }
  brush.endShape(true);
}

// ============================================================================
// 4. AMBIENT & CONTACT SHADOWS ON THE LINEN CLOTH
// ============================================================================
function drawCompositionShadows(cx, cy) {
  // Light comes from upper-left (-135 deg), so shadows fall toward lower-right (+14, +16)
  const sx = 14;
  const sy = 16;

  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.45, 0.35);

  // Soft umber ambient shadows for all major fruit medallions
  brush.fill(PAL.shadowUmber, 62);
  // Central pomegranate
  brush.circle(cx + sx, cy + sy, 132, 0.12);

  // Inner ring: 4 halved quinces (45, 135, 225, 315) & 4 pom wedges (0, 90, 180, 270)
  for (let i = 0; i < 4; i++) {
    let aQ = 45 + i * 90;
    let qx = cx + cos(aQ) * 212;
    let qy = cy + sin(aQ) * 212;
    brush.circle(qx + sx * 0.85, qy + sy * 0.85, 68, 0.15);

    let aP = i * 90;
    let px = cx + cos(aP) * 204;
    let py = cy + sin(aP) * 204;
    brush.circle(px + sx * 0.8, py + sy * 0.8, 56, 0.15);
  }

  // Outer cardinal pomegranates (radius 392)
  for (let i = 0; i < 4; i++) {
    let a = i * 90;
    let px = cx + cos(a) * 392;
    let py = cy + sin(a) * 392;
    brush.circle(px + sx, py + sy, 108, 0.14);
  }

  // Outer diagonal quinces (radius 412)
  for (let i = 0; i < 4; i++) {
    let a = 45 + i * 90;
    let qx = cx + cos(a) * 412;
    let qy = cy + sin(a) * 412;
    brush.circle(qx + sx, qy + sy, 106, 0.15);
  }

  // Deeper core contact shadows
  brush.fill(PAL.shadowDark, 72);
  brush.circle(cx + sx * 0.6, cy + sy * 0.6, 114, 0.1);
  for (let i = 0; i < 4; i++) {
    let a = i * 90;
    let px = cx + cos(a) * 392;
    let py = cy + sin(a) * 392;
    brush.circle(px + sx * 0.6, py + sy * 0.6, 92, 0.12);

    let aQ = 45 + i * 90;
    let qx = cx + cos(aQ) * 412;
    let qy = cy + sin(aQ) * 412;
    brush.circle(qx + sx * 0.6, qy + sy * 0.6, 88, 0.12);
  }
  brush.noFill();
}

// ============================================================================
// 5 & 9. TRAILING VINES, STEMS & DEEP OLIVE LEAVES
// ============================================================================
function drawTrailingVinesAndLeaves(cx, cy, layer) {
  if (layer === "under") {
    // 8 symmetrical vine arabesques weaving between the medallions
    for (let i = 0; i < 8; i++) {
      let baseAng = i * 45;
      // Inner-to-outer connecting vines
      let pts1 = [];
      for (let t = 0; t <= 1.01; t += 0.12) {
        let r = lerp(125, 435, t);
        let wave = sin(t * 360) * 16 * (i % 2 === 0 ? 1 : -1);
        let a = baseAng + wave;
        pts1.push([cx + cos(a) * r, cy + sin(a) * r]);
      }
      drawWoodyVine(pts1, 2.2);

      // Circular wreath vines around r = 295..355 connecting cardinal & diagonal medallions
      let pts2 = [];
      for (let t = 0; t <= 1.01; t += 0.12) {
        let a = baseAng + t * 45;
        let r = 320 + sin(t * 180) * 36 * (i % 2 === 0 ? 1 : -1);
        pts2.push([cx + cos(a) * r, cy + sin(a) * r]);
      }
      drawWoodyVine(pts2, 1.9);

      // Outer border trailing vine flourishes at r = 495
      let pts3 = [];
      for (let t = 0; t <= 1.01; t += 0.14) {
        let a = baseAng - 18 + t * 36;
        let r = 485 + cos(t * 360) * 18;
        pts3.push([cx + cos(a) * r, cy + sin(a) * r]);
      }
      drawWoodyVine(pts3, 1.5);
    }

    // Draw rich foliage clusters along the vines (both lance-shaped pomegranate leaves and oval quince leaves)
    for (let i = 0; i < 8; i++) {
      let baseAng = i * 45;

      // Leaves framing the inner ring (r ~ 155..265)
      drawOliveLeaf(cx + cos(baseAng + 14) * 165, cy + sin(baseAng + 14) * 165, baseAng + 58, 52, 20, "pom");
      drawOliveLeaf(cx + cos(baseAng - 14) * 165, cy + sin(baseAng - 14) * 165, baseAng - 58, 52, 20, "pom");

      drawOliveLeaf(cx + cos(baseAng + 22) * 265, cy + sin(baseAng + 22) * 265, baseAng + 75, 64, 34, "quince");
      drawOliveLeaf(cx + cos(baseAng - 22) * 265, cy + sin(baseAng - 22) * 265, baseAng - 75, 60, 32, "quince");

      // Leaves along the middle wreath (r ~ 320..365)
      drawOliveLeaf(cx + cos(baseAng + 11) * 325, cy + sin(baseAng + 11) * 325, baseAng + 35, 58, 22, "pom");
      drawOliveLeaf(cx + cos(baseAng + 33) * 335, cy + sin(baseAng + 33) * 335, baseAng + 145, 62, 24, "pom");
      drawOliveLeaf(cx + cos(baseAng + 22) * 355, cy + sin(baseAng + 22) * 355, baseAng - 65, 68, 38, "quince");

      // Outer medallion cradling leaves (r ~ 445..510)
      drawOliveLeaf(cx + cos(baseAng + 14) * 455, cy + sin(baseAng + 14) * 455, baseAng + 68, 66, 36, "quince");
      drawOliveLeaf(cx + cos(baseAng - 14) * 455, cy + sin(baseAng - 14) * 455, baseAng - 68, 66, 36, "quince");
      drawOliveLeaf(cx + cos(baseAng + 6) * 505, cy + sin(baseAng + 6) * 505, baseAng + 95, 50, 19, "pom");
      drawOliveLeaf(cx + cos(baseAng - 6) * 505, cy + sin(baseAng - 6) * 505, baseAng - 95, 50, 19, "pom");
    }
  } else {
    // Upper layer: select leaves and fine tendrils overlapping the edges of the fruit for 3D depth
    for (let i = 0; i < 4; i++) {
      let aCard = i * 90;
      // Small glossy pomegranate leaves overlapping the cardinal pomegranates
      drawOliveLeaf(cx + cos(aCard + 12) * 310, cy + sin(aCard + 12) * 310, aCard + 42, 46, 17, "pom");
      drawOliveLeaf(cx + cos(aCard - 12) * 310, cy + sin(aCard - 12) * 310, aCard - 42, 44, 16, "pom");

      // Broad velvety quince leaves overlapping the diagonal quinces
      let aDiag = 45 + i * 90;
      drawOliveLeaf(cx + cos(aDiag + 11) * 332, cy + sin(aDiag + 11) * 332, aDiag + 28, 58, 32, "quince");
      drawOliveLeaf(cx + cos(aDiag - 12) * 472, cy + sin(aDiag - 12) * 472, aDiag - 125, 54, 30, "quince");

      // Delicate leaves tucking over the rim of the central medallion
      drawOliveLeaf(cx + cos(aDiag) * 138, cy + sin(aDiag) * 138, aDiag + 72, 42, 16, "pom");
    }
  }
}

function drawWoodyVine(pts, weight) {
  // Contact shadow on cloth
  let shadowPts = pts.map(p => [p[0] + 6, p[1] + 7]);
  brush.set("cpencil", PAL.shadowUmber, weight * 1.4);
  brush.spline(shadowPts, 0.5);

  // Dark woody base
  brush.set("burnish", PAL.stemDark, weight);
  brush.spline(pts, 0.5);

  // Warm brown bark midtone
  let midPts = pts.map(p => [p[0] - 0.8, p[1] - 0.8]);
  brush.set("cpencil", PAL.stemMid, weight * 0.75);
  brush.spline(midPts, 0.5);

  // Sunlit edge highlight & nodes
  let hiPts = pts.map(p => [p[0] - 1.5, p[1] - 1.5]);
  brush.set("fine_pencil", PAL.stemLight, weight * 0.45);
  brush.spline(hiPts, 0.5);
}

function drawOliveLeaf(x, y, angleDeg, len, wid, type) {
  push();
  translate(x, y);
  rotate(angleDeg);

  // Drop shadow on linen
  brush.noStroke();
  brush.wash(PAL.shadowUmber, 65);
  drawLeafOutline(4, 5, len, wid, type);
  brush.noWash();

  // Solid base wash in deep olive
  let baseCol = type === "quince" ? PAL.leafDeepOlive : PAL.leafAbyss;
  brush.wash(baseCol, 225);
  drawLeafOutline(0, 0, len, wid, type);
  brush.noWash();

  // Burnished coloured pencil shading across the two halves of the leaf blade
  let ribs = floor(len / 4.5);
  for (let i = 1; i < ribs; i++) {
    let t = i / ribs;
    let lx = (t - 0.5) * len;
    let profile = type === "quince" ? sin(t * 180) : pow(sin(t * 180), 0.75);
    let hw = (wid * 0.5) * profile;

    // Upper blade half (sunlit moss & warm olive)
    let colUp = t < 0.7 ? PAL.leafMoss : PAL.leafWarm;
    brush.set("burnish", colUp, 0.75);
    brush.line(lx, -1, lx + 3.5, -hw * 0.92);

    brush.set("fine_pencil", PAL.leafWarm, 0.45);
    brush.line(lx + 1, -2, lx + 4, -hw * 0.65);

    // Lower blade half (shaded deep olive & abyss)
    let colDn = t < 0.5 ? PAL.leafAbyss : PAL.leafOlive;
    brush.set("burnish", colDn, 0.75);
    brush.line(lx, 1, lx + 3.5, hw * 0.92);
  }

  // Quince leaves have a faint felted/tomentose pale edge; pomegranate leaves have a bronze-red tint at tip
  if (type === "quince") {
    brush.set("fine_pencil", PAL.leafUnderside, 0.5);
    drawLeafStrokeOutline(len * 0.96, wid * 0.94);
  } else {
    brush.set("fine_pencil", PAL.pomRindWarm, 0.55);
    brush.line(len * 0.32, 0, len * 0.5, 0);
  }

  // Crisp leaf margin contour
  brush.set("fine_pencil", PAL.leafAbyss, 0.55);
  drawLeafStrokeOutline(len, wid);

  // Midrib and lateral veins
  brush.set("fine_pencil", PAL.leafVein, 0.65);
  brush.line(-len * 0.55, 0, len * 0.47, 0);
  for (let i = 2; i < ribs - 1; i += 2) {
    let t = i / ribs;
    let lx = (t - 0.5) * len;
    let hw = (wid * 0.45) * sin(t * 180);
    brush.set("fine_pencil", PAL.leafVein, 0.38);
    brush.line(lx, 0, lx + 5, -hw * 0.82);
    brush.line(lx, 0, lx + 5, hw * 0.82);
  }

  pop();
}

function drawLeafOutline(ox, oy, len, wid, type) {
  brush.beginShape(0.35);
  let steps = 16;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let px = cos(a) * (len * 0.5);
    let profile = type === "quince" ? 1 + 0.15 * cos(a) : 1;
    let py = sin(a) * (wid * 0.5) * profile;
    brush.vertex(ox + px, oy + py);
  }
  brush.endShape(true);
}

function drawLeafStrokeOutline(len, wid) {
  let pts = [];
  let steps = 16;
  for (let i = 0; i <= steps; i++) {
    let a = (i / steps) * 360;
    pts.push([cos(a) * (len * 0.5), sin(a) * (wid * 0.5)]);
  }
  brush.spline(pts, 0.35);
}

// ============================================================================
// 6 & 7. OUTER & INNER MEDALLIONS
// ============================================================================
function drawOuterMedallions(cx, cy) {
  // 4 Cardinal Medallions (Top, Right, Bottom, Left): Large halved pomegranates
  // Top & Bottom: Longitudinal halves showing the split crown/calyx and twin chambers packed with wet arils
  // Left & Right: Equatorial halves showing radial chambers of glistening arils
  drawHalvedPomegranateLongitudinal(cx, cy - 392, 102, 90);
  drawHalvedPomegranateLongitudinal(cx, cy + 392, 102, -90);
  drawHalvedPomegranateEquatorial(cx - 392, cy, 98, 12, false);
  drawHalvedPomegranateEquatorial(cx + 392, cy, 98, 48, false);

  // 4 Diagonal Medallions: Large Golden Quinces (2 whole pyriform quinces with fuzz & calyx, 2 halved quinces)
  for (let i = 0; i < 4; i++) {
    let a = 45 + i * 90;
    let qx = cx + cos(a) * 412;
    let qy = cy + sin(a) * 412;
    if (i % 2 === 0) {
      drawWholeGoldenQuince(qx, qy, 98, a + 135);
    } else {
      drawHalvedGoldenQuince(qx, qy, 96, a - 45);
    }
  }
}

function drawInnerMedallionRing(cx, cy) {
  // 4 Halved Golden Quinces at 45, 135, 225, 315 (radius 212)
  for (let i = 0; i < 4; i++) {
    let a = 45 + i * 90;
    let qx = cx + cos(a) * 212;
    let qy = cy + sin(a) * 212;
    drawHalvedGoldenQuince(qx, qy, 64, a + 90);
  }

  // 4 Cleft Pomegranate Wedges at 0, 90, 180, 270 (radius 204)
  for (let i = 0; i < 4; i++) {
    let a = i * 90;
    let px = cx + cos(a) * 204;
    let py = cy + sin(a) * 204;
    drawPomegranateWedge(px, py, 56, a + 90);
  }
}

// ============================================================================
// HYPERREAL POMEGRANATES (EQUATORIAL, LONGITUDINAL & WEDGES)
// ============================================================================
function drawHalvedPomegranateEquatorial(x, y, radius, rotAngle, isHero) {
  push();
  translate(x, y);

  // 1. Cast crimson-tinted contact glow on the cloth
  brush.noStroke();
  brush.wash(PAL.shadowCrimson, 55);
  brush.circle(8, 10, radius * 1.04, 0.12);
  brush.noWash();

  // 2. Outer leathery rind (6-sided subtly hexagonal natural pomegranate contour)
  const chambers = 6;
  let rindPts = [];
  let pithPts = [];
  for (let i = 0; i < 36; i++) {
    let a = i * 10;
    let rib = 1 + 0.045 * cos((a - rotAngle) * chambers);
    let n = noise(x * 0.01 + cos(a), y * 0.01 + sin(a));
    let rOut = radius * rib * map(n, 0, 1, 0.96, 1.04);
    let rIn = rOut * 0.89;
    rindPts.push([cos(a) * rOut, sin(a) * rOut]);
    pithPts.push([cos(a) * rIn, sin(a) * rIn]);
  }

  // Base wash for leathery crimson rind
  brush.noStroke();
  brush.wash(PAL.pomRindMid, 245);
  drawClosedShape(rindPts, 0.3);
  brush.noWash();

  // Burnished coloured pencil shading on rind bevel
  for (let i = 0; i < 36; i++) {
    let p1 = rindPts[i];
    let p2 = pithPts[i];
    let a = i * 10;
    let light = cos(a + 135);
    let col = light > 0.2 ? PAL.pomRindOchre : (light > -0.3 ? PAL.pomRindWarm : PAL.pomRindDark);
    brush.set("burnish", col, 1.1);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  brush.set("fine_pencil", PAL.pomRindDark, 0.8);
  brush.spline([...rindPts, rindPts[0]], 0.35);

  // 3. Creamy spongy pith (mesocarp) interior
  brush.noStroke();
  brush.wash(PAL.pithCream, 250);
  drawClosedShape(pithPts, 0.3);
  brush.noWash();

  // Subtle fibrous pencil texture across the cut pith rim
  for (let i = 0; i < 72; i++) {
    let a = i * 5;
    let r1 = radius * 0.82;
    let r2 = radius * 0.91;
    let col = (i % 2 === 0) ? PAL.pithLight : PAL.pithOchre;
    brush.set("fine_pencil", col, 0.55);
    brush.line(cos(a) * r1, sin(a) * r1, cos(a) * r2, sin(a) * r2);
  }

  // 4. Deep recessed carpel chambers (locules) filled with wet madder-crimson arils
  for (let c = 0; c < chambers; c++) {
    let cAng = rotAngle + c * (360 / chambers);
    let span = (360 / chambers) * 0.41;

    // Chamber void polygon
    let chPts = [];
    let rMin = radius * 0.16;
    let rMax = radius * 0.82;
    chPts.push([cos(cAng) * rMin, sin(cAng) * rMin]);
    for (let s = -span; s <= span; s += span * 0.25) {
      let a = cAng + s;
      let rEdge = rMax * (1 - 0.08 * pow(s / span, 2));
      chPts.push([cos(a) * rEdge, sin(a) * rEdge]);
    }

    // Dark claret chamber interior
    brush.noStroke();
    brush.wash(PAL.chamberVoid, 250);
    drawClosedShape(chPts, 0.25);
    brush.noWash();

    // Pack the chamber with layered, faceted, wet arils!
    let rows = isHero ? 5 : 4;
    for (let row = 0; row < rows; row++) {
      let tRow = (row + 0.55) / rows;
      let rRow = lerp(rMin * 1.35, rMax * 0.91, tRow);
      let arcSpan = span * lerp(0.55, 0.88, tRow);
      let countInRow = max(1, floor(map(tRow, 0, 1, 1.6, isHero ? 5.6 : 4.6)));

      for (let k = 0; k < countInRow; k++) {
        let frac = countInRow === 1 ? 0 : map(k, 0, countInRow - 1, -1, 1);
        let aSeed = cAng + frac * arcSpan + random(-2.2, 2.2);
        let rSeed = rRow + random(-3, 3);
        let sx = cos(aSeed) * rSeed;
        let sy = sin(aSeed) * rSeed;
        let seedSize = (isHero ? 10.5 : 9.2) * random(0.88, 1.12);
        drawWetAril(sx, sy, seedSize, aSeed + random(-25, 25));
      }
    }
  }

  // 5. Thin, papery cream carpel membranes (septa) dividing the chambers & central spongy core
  for (let c = 0; c < chambers; c++) {
    let sepAng = rotAngle + (c + 0.5) * (360 / chambers);
    let mPts = [];
    for (let t = 0.1; t <= 0.86; t += 0.15) {
      let r = radius * t;
      let wobble = (noise(c * 10 + t * 5) - 0.5) * 3.5;
      mPts.push([cos(sepAng + wobble) * r, sin(sepAng + wobble) * r]);
    }
    brush.set("burnish", PAL.pithOchre, 1.4);
    brush.spline(mPts, 0.4);
    brush.set("fine_pencil", PAL.pithLight, 0.85);
    brush.spline(mPts, 0.4);
  }

  // Central white/cream pith star
  brush.noStroke();
  brush.wash(PAL.pithLight, 240);
  brush.circle(0, 0, radius * 0.14, 0.25);
  brush.noWash();
  brush.set("fine_pencil", PAL.pithShadow, 0.6);
  brush.circle(0, 0, radius * 0.08, 0.3);

  pop();
}

function drawHalvedPomegranateLongitudinal(x, y, radius, rotAngle) {
  push();
  translate(x, y);
  rotate(rotAngle);

  // Crown/calyx at (+radius, 0), stem base at (-radius, 0)
  // 1. Leathery crimson rind with prominent crown flares
  let rindPts = [];
  for (let i = 0; i < 36; i++) {
    let a = i * 10;
    let rx = cos(a) * radius * 1.04;
    let ry = sin(a) * radius * 0.96;
    // Flare out at the calyx crown (around a = 0)
    if (abs(a) < 28 || abs(a - 360) < 28) {
      rx += radius * 0.18;
      ry *= 1.15;
    }
    rindPts.push([rx, ry]);
  }

  brush.noStroke();
  brush.wash(PAL.pomRindMid, 245);
  drawClosedShape(rindPts, 0.28);
  brush.noWash();

  // Crown calyx teeth shading
  for (let t = -3; t <= 3; t++) {
    let cyTooth = t * (radius * 0.09);
    brush.set("burnish", PAL.pomRindDark, 0.9);
    brush.line(radius * 0.88, cyTooth, radius * 1.18, cyTooth * 1.35);
    brush.set("fine_pencil", PAL.pithOchre, 0.55);
    brush.line(radius * 0.92, cyTooth + 1.5, radius * 1.14, cyTooth * 1.3);
  }

  // 2. Creamy pith interior
  let pithPts = rindPts.map(p => [p[0] * 0.88, p[1] * 0.88]);
  brush.noStroke();
  brush.wash(PAL.pithCream, 250);
  drawClosedShape(pithPts, 0.3);
  brush.noWash();

  // 3. Two large longitudinal lobes (upper and lower) separated by the central pith column
  for (let side of [-1, 1]) {
    let lobePts = [
      [-radius * 0.72, side * radius * 0.08],
      [-radius * 0.45, side * radius * 0.72],
      [radius * 0.35, side * radius * 0.76],
      [radius * 0.72, side * radius * 0.12],
      [0, side * radius * 0.06]
    ];
    brush.noStroke();
    brush.wash(PAL.chamberVoid, 250);
    drawClosedShape(lobePts, 0.35);
    brush.noWash();

    // Fill lobe with tightly packed glistening arils
    for (let gx = -radius * 0.58; gx <= radius * 0.56; gx += 14.5) {
      let maxH = radius * 0.68 * sqrt(max(0, 1 - pow(gx / (radius * 0.68), 2)));
      for (let gy = radius * 0.14; gy <= maxH; gy += 13.5) {
        let sx = gx + random(-2.5, 2.5);
        let sy = side * (gy + random(-2.5, 2.5));
        drawWetAril(sx, sy, random(8.8, 10.8), random(360));
      }
    }
  }

  // Central longitudinal pith column & papery membranes
  brush.set("burnish", PAL.pithCream, 2.2);
  brush.line(-radius * 0.78, 0, radius * 0.82, 0);
  brush.set("fine_pencil", PAL.pithLight, 1.1);
  brush.line(-radius * 0.75, -1, radius * 0.8, -1);

  // Rind contour pencil work
  brush.set("burnish", PAL.pomRindDark, 1.1);
  brush.spline([...rindPts, rindPts[0]], 0.3);

  pop();
}

function drawPomegranateWedge(x, y, radius, rotAngle) {
  push();
  translate(x, y);
  rotate(rotAngle);

  // Crescent/wedge rind on the back side, mound of ruby arils on the front
  let rindPts = [];
  for (let a = -100; a <= 100; a += 20) {
    rindPts.push([cos(a) * radius, sin(a) * radius]);
  }
  for (let a = 100; a >= -100; a -= 25) {
    rindPts.push([cos(a) * radius * 0.35, sin(a) * radius * 0.82]);
  }

  brush.noStroke();
  brush.wash(PAL.pomRindWarm, 245);
  drawClosedShape(rindPts, 0.3);
  brush.noWash();

  // Pith rim
  brush.set("burnish", PAL.pithCream, 1.8);
  brush.arc(0, 0, radius * 0.86, -92, 92);

  // Dark recess & cluster of 16-20 large wet arils
  brush.noStroke();
  brush.wash(PAL.chamberVoid, 240);
  brush.circle(radius * 0.18, 0, radius * 0.62, 0.2);
  brush.noWash();

  for (let r = 8; r <= radius * 0.68; r += 13) {
    let steps = max(1, floor((r * 2.6) / 13));
    for (let i = 0; i < steps; i++) {
      let a = map(i, 0, max(1, steps - 1), -72, 72) + random(-8, 8);
      let sx = cos(a) * r + random(-2, 2);
      let sy = sin(a) * r + random(-2, 2);
      drawWetAril(sx, sy, random(8.5, 10.5), a);
    }
  }

  brush.set("fine_pencil", PAL.pomRindDark, 0.85);
  brush.arc(0, 0, radius, -100, 100);

  pop();
}

// ============================================================================
// SINGLE HYPERREAL WET POMEGRANATE ARIL (SEED)
// ============================================================================
function drawWetAril(x, y, size, angleDeg) {
  push();
  translate(x, y);

  // Polygonal faceted jewel contour (5-6 facets like a real compressed pomegranate seed)
  let pts = [];
  let sides = 6;
  for (let i = 0; i < sides; i++) {
    let a = angleDeg + i * (360 / sides);
    let stretch = (i % 3 === 0) ? 1.16 : 0.92;
    let r = (size * 0.5) * stretch;
    pts.push([cos(a) * r, sin(a) * r]);
  }

  // 1. Deep garnet-claret outer body
  let colChoice = random();
  let bodyCol = colChoice < 0.35 ? PAL.arilRuby : (colChoice < 0.78 ? PAL.arilMadder : PAL.arilCrimson);
  brush.noStroke();
  brush.wash(bodyCol, 248);
  drawClosedShape(pts, 0.22);
  brush.noWash();

  // 2. Dark shadow facet on lower-right
  brush.set("burnish", PAL.arilDark, 0.7);
  brush.line(pts[1][0] * 0.85, pts[1][1] * 0.85, pts[2][0] * 0.85, pts[2][1] * 0.85);

  // 3. Translucent internal ruby glow & pale pink-ivory inner kernel
  let kAng = angleDeg + 30;
  let kx = cos(kAng) * (size * 0.14);
  let ky = sin(kAng) * (size * 0.14);
  brush.set("burnish", PAL.arilBright, 0.85);
  brush.line(-kx, -ky, kx, ky);

  brush.set("fine_pencil", PAL.arilKernel, 0.65);
  brush.line(-kx * 0.55, -ky * 0.55, kx * 0.55, ky * 0.55);

  // 4. Razor-sharp wet glassy specular highlight on upper-left facet
  let hx = -size * 0.16;
  let hy = -size * 0.18;
  brush.set("wet_gloss", PAL.arilGloss, 0.52);
  brush.line(hx - 1.1, hy + 0.6, hx + 1.2, hy - 0.7);

  // Secondary micro reflection pinpoint
  if (size > 9.0) {
    brush.set("wet_gloss", PAL.arilCore, 0.32);
    brush.line(size * 0.15, size * 0.15, size * 0.18, size * 0.12);
  }

  pop();
}

// ============================================================================
// HYPERREAL GOLDEN QUINCES (WHOLE WITH FUZZ & HALVED SHOWING CORE)
// ============================================================================
function drawWholeGoldenQuince(x, y, radius, rotAngle) {
  push();
  translate(x, y);
  rotate(rotAngle);

  // Warm ochre reflected glow in the contact shadow
  brush.noStroke();
  brush.wash(PAL.shadowOchre, 50);
  brush.circle(8, 10, radius * 1.05, 0.15);
  brush.noWash();

  // Lumpy, ribbed pyriform quince contour (7 subtle organic lobes)
  let qPts = [];
  for (let i = 0; i < 36; i++) {
    let a = i * 10;
    let pearShape = 1 + 0.12 * cos(a) - 0.06 * cos(a * 2);
    let ribs = 1 + 0.045 * cos(a * 5 + 20);
    let r = radius * pearShape * ribs;
    qPts.push([cos(a) * r, sin(a) * r]);
  }

  // 1. Base saffron-ochre wash
  brush.noStroke();
  brush.wash(PAL.quinceOchre, 248);
  drawClosedShape(qPts, 0.35);
  brush.noWash();

  // 2. Dense, burnished coloured pencil contour strokes sculpting the 3D lobes
  // Light comes from upper-left in global space; compute local light direction
  let lightAng = -135 - rotAngle;
  let lx = cos(lightAng) * radius * 0.32;
  let ly = sin(lightAng) * radius * 0.32;

  // Concentric burnished bands from shadow side to sunlit crown
  for (let ring = 0.95; ring >= 0.15; ring -= 0.07) {
    let col;
    if (ring > 0.78) col = PAL.quinceSienna;
    else if (ring > 0.55) col = PAL.quinceOchre;
    else if (ring > 0.32) col = PAL.quinceSaffron;
    else col = PAL.quinceGold;

    let ringPts = [];
    for (let i = 0; i <= 24; i++) {
      let a = (i / 24) * 360;
      let pear = 1 + 0.1 * cos(a);
      let rib = 1 + 0.04 * cos(a * 5);
      let rx = lerp(lx, 0, ring) + cos(a) * radius * ring * pear * rib;
      let ry = lerp(ly, 0, ring) + sin(a) * radius * ring * pear * rib;
      ringPts.push([rx, ry]);
    }
    brush.set("burnish", col, 1.35);
    brush.spline(ringPts, 0.4);
  }

  // 3. Radial rib creases in greenish-ochre and raw sienna
  let calyxX = radius * 0.38;
  let calyxY = 0;
  for (let r = 0; r < 7; r++) {
    let a = r * (360 / 7) + 15;
    let cPts = [];
    for (let t = 0.12; t <= 0.92; t += 0.2) {
      let px = lerp(calyxX, cos(a) * radius, t);
      let py = lerp(calyxY, sin(a) * radius * 0.95, t);
      cPts.push([px, py]);
    }
    let ribCol = (r % 2 === 0) ? PAL.quinceGreen : PAL.quinceSienna;
    brush.set("fine_pencil", ribCol, 0.75);
    brush.spline(cPts, 0.35);
  }

  // 4. Sunlit highlight on the upper dome
  brush.set("burnish", PAL.quinceHighlight, 1.2);
  brush.circle(lx, ly, radius * 0.22, 0.35);

  // 5. Deep puckered navel calyx with dried sepia sepals
  brush.noStroke();
  brush.wash(PAL.quinceDeep, 235);
  brush.circle(calyxX, calyxY, radius * 0.16, 0.3);
  brush.noWash();
  for (let s = 0; s < 5; s++) {
    let sa = s * 72 + 10;
    brush.set("burnish", PAL.stemDark, 0.95);
    brush.line(calyxX, calyxY, calyxX + cos(sa) * radius * 0.22, calyxY + sin(sa) * radius * 0.22);
  }

  // 6. Characteristic faint velvety quince fuzz (flocculent greyish-cream tomentum)
  // Concentrated in the rib creases, around the calyx hollow, and along the shadow terminator
  for (let i = 0; i < 110; i++) {
    let a = random(360);
    let d = radius * random(0.18, 0.96);
    let fx = cos(a) * d;
    let fy = sin(a) * d;
    let fCol = random() < 0.6 ? PAL.quinceFuzz : PAL.quinceFuzzWarm;
    brush.set("2H", fCol, random(0.35, 0.6));
    let fAng = a + 90 + random(-25, 25);
    brush.line(fx, fy, fx + cos(fAng) * 5.5, fy + sin(fAng) * 5.5);
  }

  // Outer skin contour
  brush.set("fine_pencil", PAL.quinceDeep, 0.85);
  brush.spline([...qPts, qPts[0]], 0.35);

  pop();
}

function drawHalvedGoldenQuince(x, y, radius, rotAngle) {
  push();
  translate(x, y);
  rotate(rotAngle);

  // Pyriform longitudinal half contour (stem at -radius, calyx at +radius)
  let skinPts = [];
  let fleshPts = [];
  for (let i = 0; i < 36; i++) {
    let a = i * 10;
    let pear = (a > 90 && a < 270) ? 0.82 : 1.06;
    let rx = cos(a) * radius * 1.08;
    let ry = sin(a) * radius * 0.88 * pear;
    // Slight notch at calyx (+radius) and stem (-radius)
    if (abs(a) < 12 || abs(a - 360) < 12) rx -= radius * 0.08;
    skinPts.push([rx, ry]);
    fleshPts.push([rx * 0.91, ry * 0.91]);
  }

  // 1. Saffron-ochre skin rim with faint fuzz along the outer edge
  brush.noStroke();
  brush.wash(PAL.quinceSaffron, 248);
  drawClosedShape(skinPts, 0.3);
  brush.noWash();

  for (let i = 0; i < 36; i++) {
    let p1 = skinPts[i];
    let p2 = fleshPts[i];
    let col = (i % 2 === 0) ? PAL.quinceOchre : PAL.quinceGold;
    brush.set("burnish", col, 1.0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Fuzz hairs on outer rim
    if (i % 2 === 0) {
      brush.set("2H", PAL.quinceFuzz, 0.45);
      brush.line(p1[0], p1[1], p1[0] * 1.04, p1[1] * 1.04);
    }
  }

  // 2. Dense, creamy-saffron cut flesh
  brush.noStroke();
  brush.wash(PAL.quinceFlesh, 250);
  drawClosedShape(fleshPts, 0.3);
  brush.noWash();

  // Fine radial coloured pencil shading across the dense flesh
  for (let i = 0; i < 64; i++) {
    let a = (i / 64) * 360;
    let idx = floor((i / 64) * 36) % 36;
    let pEdge = fleshPts[idx];
    let col = (i % 3 === 0) ? PAL.quinceFleshMid : PAL.quinceHighlight;
    brush.set("fine_pencil", col, 0.48);
    brush.line(cos(a) * radius * 0.22, sin(a) * radius * 0.18, pEdge[0] * 0.96, pEdge[1] * 0.96);
  }

  // 3. Oxidised rose-ochre core halo (characteristic of cut quince flesh)
  brush.noStroke();
  brush.wash(PAL.quinceCore, 115);
  brush.circle(radius * 0.06, 0, radius * 0.34, 0.25);
  brush.noWash();

  // Vascular bundle line running from stem to calyx
  brush.set("fine_pencil", PAL.quinceCore, 0.7);
  brush.line(-radius * 0.95, 0, radius * 0.92, 0);

  // 4. Two teardrop seed locules containing glossy mahogany seeds
  for (let side of [-1, 1]) {
    let sx = radius * 0.08;
    let sy = side * radius * 0.14;

    // Seed cavity
    brush.set("burnish", PAL.quinceSienna, 1.1);
    brush.circle(sx, sy, radius * 0.09, 0.2);

    // Dark mahogany seed
    brush.noStroke();
    brush.wash(PAL.quinceSeed, 250);
    brush.circle(sx, sy, radius * 0.065, 0.15);
    brush.noWash();

    // Wet specular glint on the seed
    brush.set("wet_gloss", PAL.arilGloss, 0.38);
    brush.line(sx - 1.5, sy - 1.2, sx + 0.8, sy - 1.8);
  }

  // Woody stem at (-radius) and fuzzy calyx tuft at (+radius)
  brush.set("burnish", PAL.stemDark, 1.3);
