// ============================================================================
// GEOMETRY HELPER
// ============================================================================
function drawClosedShape(pts, curvature = 0.3) {
  brush.beginShape(curvature);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

// Hyperrealistic Fauvist-Chromatic Portrait of a Jazz Trumpeter Mid-Blast
// Rendered with p5.js v2 + p5.brush in WEBGL

function ellipsePoints(cx, cy, rx, ry, rotDeg = 0, num = 36, jitter = 0) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < num; i++) {
    let a = (i / num) * 360;
    let j = jitter > 0 ? 1 + random(-jitter, jitter) : 1;
    let lx = cos(a) * rx * j;
    let ly = sin(a) * ry * j;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

function drawPoly(pts, curvature = 0.35) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawWashShape(pts, col, opacity = 255, curvature = 0.3) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, opacity);
  drawPoly(pts, curvature);
  brush.noWash();
}

function drawCrispDriedEdge(pts, edgeCol, weight = 0.35, close = true) {
  brush.noFill();
  brush.noWash();
  brush.set("2B", edgeCol, weight);
  let splinePts = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let pVal = 0.45 + 0.55 * noise(p[0] * 0.015, p[1] * 0.015);
    splinePts.push([
      p[0] + random(-1.8, 1.8),
      p[1] + random(-1.8, 1.8),
      pVal
    ]);
  }
  if (close && pts.length > 2) {
    splinePts.push([pts[0][0], pts[0][1], 0.5]);
    splinePts.push([pts[1][0], pts[1][1], 0.3]);
  }
  if (splinePts.length >= 3) {
    brush.spline(splinePts, 0.45);
  }
}

function drawWatercolorBatch(batches) {
  brush.noStroke();
  brush.noWash();
  for (let b of batches) {
    brush.fill(b.col, b.alpha);
    brush.fillBleed(b.bleed ?? 0.06, b.dir ?? "out");
    brush.fillTexture(b.tex ?? 0.78, b.border ?? 0.92);
    for (let s of b.shapes) {
      drawPoly(s.pts, s.curv ?? 0.38);
    }
  }
  brush.noFill();

  // Crisp dried pigment accumulation edges (hallmark of juicy watercolor on hot-press paper)
  for (let b of batches) {
    if (!b.edgeCol) continue;
    for (let s of b.shapes) {
      if (s.skipEdge) continue;
      drawCrispDriedEdge(s.pts, b.edgeCol, b.edgeWeight ?? 0.32, true);
    }
  }
}

function drawVein(pathPts, baseWeight, shadowCol, coreCol, highlightCol, lx = -0.7, ly = -0.7) {
  if (pathPts.length < 3) return;
  // 1. Subcutaneous diffused shadow halo
  brush.set("cpencil", shadowCol, baseWeight * 1.45);
  let shPts = pathPts.map((p, idx) => {
    let t = idx / (pathPts.length - 1);
    let pr = sin(t * 180) * 0.9 + 0.25;
    return [p[0] - lx * baseWeight * 1.4, p[1] - ly * baseWeight * 1.4, pr];
  });
  brush.spline(shPts, 0.5);

  // 2. Main raised vein body
  brush.set("2B", coreCol, baseWeight * 0.95);
  let midPts = pathPts.map((p, idx) => {
    let t = idx / (pathPts.length - 1);
    let pr = sin(t * 180) * 0.95 + 0.3;
    return [p[0], p[1], pr];
  });
  brush.spline(midPts, 0.5);

  // 3. Sharp specular ridge on light-facing side
  brush.set("rotring", highlightCol, baseWeight * 0.52);
  let hiPts = pathPts.map((p, idx) => {
    let t = idx / (pathPts.length - 1);
    let pr = sin(t * 180) * 0.9 + 0.2;
    return [p[0] + lx * baseWeight * 0.9, p[1] + ly * baseWeight * 0.9, pr];
  });
  brush.spline(hiPts, 0.5);
}

function drawSweatBead(x, y, r, shadowCol, refractCol, highlightCol = "#FFFFF2", hasTrail = false, trailAngle = -80, trailLen = 28) {
  // Optional wet glistening trickle trail above the droplet
  if (hasTrail) {
    let steps = 6;
    let trShadow = [];
    let trLight = [];
    let cx = x, cy = y;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let a = trailAngle + sin(i * 55 + x) * 12;
      let stepL = (trailLen / steps) * (1 - t * 0.2);
      let pr = (1 - t * 0.75) * 0.8 + 0.15;
      trShadow.push([cx + 1.5, cy + 1.5, pr]);
      trLight.push([cx - 1.0, cy - 1.0, pr]);
      cx += cos(a) * stepL;
      cy += sin(a) * stepL;
    }
    brush.set("cpencil", shadowCol, r * 0.08);
    brush.spline(trShadow, 0.45);
    brush.set("pen", highlightCol, r * 0.065);
    brush.spline(trLight, 0.45);
  }

  // 1. Cast shadow beneath droplet (away from top-left light source)
  let shPts = ellipsePoints(x + r * 0.34, y + r * 0.42, r * 0.95, r * 0.82, 25, 14, 0.04);
  drawWashShape(shPts, shadowCol, 185, 0.35);

  // 2. Droplet dark upper-left refractive edge
  let rimPts = ellipsePoints(x, y, r, r * 1.12, -15, 16, 0.03);
  drawWashShape(rimPts, shadowCol, 130, 0.35);

  // 3. Internal glowing caustic refraction (lower-right belly of drop)
  let glowPts = ellipsePoints(x + r * 0.16, y + r * 0.2, r * 0.72, r * 0.78, -15, 14, 0.03);
  drawWashShape(glowPts, refractCol, 225, 0.35);

  // 4. Crisp dark outline on upper meniscus
  brush.set("rotring", shadowCol, max(0.22, r * 0.055));
  brush.arc(x, y, r * 0.98, 170, 345);

  // 5. Secondary caustic bounce arc at bottom-right rim
  brush.set("pen", "#FFF200", max(0.25, r * 0.07));
  brush.arc(x + r * 0.08, y + r * 0.1, r * 0.86, 15, 125);

  // 6. Blinding primary specular pinpoint at upper-left
  let spPts = ellipsePoints(x - r * 0.32, y - r * 0.34, max(1.8, r * 0.28), max(1.4, r * 0.21), -35, 10, 0);
  drawWashShape(spPts, highlightCol, 255, 0.25);
  brush.set("rotring", "#FFFFFF", max(0.28, r * 0.09));
  brush.line(x - r * 0.42, y - r * 0.32, x - r * 0.18, y - r * 0.42);
}

function drawSkinPoresOnSphere(cx, cy, rx, ry, latStart, latEnd, lonStart, lonEnd, latSteps, lonSteps, darkCol, lightCol, clipCheck) {
  for (let i = 0; i <= latSteps; i++) {
    let u = map(i, 0, latSteps, latStart, latEnd);
    for (let j = 0; j <= lonSteps; j++) {
      let v = map(j, 0, lonSteps, lonStart, lonEnd);
      // Slight hexagonal offset on alternate rows
      let vOff = (i % 2 === 0 ? 0 : (lonEnd - lonStart) / (lonSteps * 2));
      let lon = v + vOff + random(-1.8, 1.8);
      let lat = u + random(-1.8, 1.8);

      let px = cx + cos(lat) * sin(lon) * rx;
      let py = cy + sin(lat) * ry + cos(lon) * 14;
      if (clipCheck && !clipCheck(px, py)) continue;

      // Apparent foreshortening near sphere edge
      let nz = cos(lat) * cos(lon);
      if (nz < 0.12) continue;

      let poreLen = map(nz, 0.12, 1.0, 2.2, 1.1);
      let tangAngle = atan2(py - cy, px - cx) + 90;
      let dx = cos(tangAngle) * poreLen;
      let dy = sin(tangAngle) * poreLen;

      // Dark pore pit
      brush.set("rotring", darkCol, map(nz, 0.12, 1, 0.22, 0.36));
      brush.line(px - dx * 0.5, py - dy * 0.5, px + dx * 0.5, py + dy * 0.5);

      // Tiny adjacent specular lip on light-facing side of stretched skin
      if (random() < 0.72) {
        brush.set("pen", lightCol, map(nz, 0.12, 1, 0.18, 0.3));
        brush.line(px + 1.1 - dx * 0.4, py + 1.1 - dy * 0.4, px + 1.1 + dx * 0.4, py + 1.1 + dy * 0.4);
      }
    }
  }
}

