    // Keep inside crown zone
    if (hy > 385 && hx < 925) continue;
    if (hy > 235 && hx < 815 && hy > 165) continue;
    let rCoil = random(5, 13);
    let col = i % 5 === 0 ? "#0047AB" : (i % 5 === 1 ? "#190033" : (i % 5 === 2 ? "#4B0082" : (i % 5 === 3 ? "#8C0B04" : "#FFE600")));
    brush.set("2B", col, random(0.32, 0.58));
    brush.arc(hx, hy, rCoil, random(0, 180), random(200, 355));
  }

  // =========================================================================
  // 4. TRUMPET, VALVES, HAND & FOREGROUND FLARING BELL (HOT ORANGE & VIOLET)
  // =========================================================================

  // --- 4A. Mouthpiece, Leadpipe & Valve Block ---
  // Mouthpiece rim pressed deep into the lips at (495, 602)
  const mpRim = ellipsePoints(495, 602, 18, 28, -35, 22, 0.02);
  drawWashShape(mpRim, "#FFE600", 230, 0.3);
  brush.set("2B", "#3B0059", 0.68);
  drawPoly(mpRim, 0.35);

  // Leadpipe & parallel tuning/bell stem pipes
  const pipeLines = [
    { x1: 482, y1: 618, x2: 358, y2: 742, col: "#FFE600", w: 0.85 },
    { x1: 488, y1: 624, x2: 365, y2: 748, col: "#FFFFFF", w: 0.55 },
    { x1: 496, y1: 632, x2: 374, y2: 756, col: "#FF4500", w: 0.95 },
    { x1: 505, y1: 642, x2: 384, y2: 766, col: "#4B0082", w: 0.95 },
    // Back bow & bell stem feeding into the foreground bell
    { x1: 468, y1: 668, x2: 392, y2: 745, col: "#FF6600", w: 1.1 },
    { x1: 478, y1: 678, x2: 405, y2: 755, col: "#2E004F", w: 1.1 }
  ];
  for (let pl of pipeLines) {
    brush.set("2B", pl.col, pl.w);
    brush.line(pl.x1, pl.y1, pl.x2, pl.y2);
  }

  // Three Piston Valve Casings & Mother-of-Pearl Valve Caps
  const valves = [
    { topX: 522, topY: 778, botX: 432, botY: 912 },
    { topX: 572, topY: 810, botX: 482, botY: 944 },
    { topX: 622, topY: 842, botX: 532, botY: 976 }
  ];
  for (let v of valves) {
    // Cylindrical valve casing stripes in violet, hot orange, and cadmium yellow
    for (let s = -14; s <= 14; s += 3.5) {
      let col = s < -4 ? "#FFE600" : (s < 5 ? "#FF4500" : "#3D0066");
      brush.set("2B", col, 0.58);
      brush.line(v.topX + s, v.topY + s * 0.65, v.botX + s, v.botY + s * 0.65);
    }
    // Valve cap & stem
    let capPts = ellipsePoints(v.topX + 16, v.topY - 24, 14, 9, 32, 16, 0.02);
    drawWashShape(capPts, "#FFFDF0", 245, 0.3);
    brush.set("rotring", "#2E004F", 0.45);
    drawPoly(capPts, 0.3);
    brush.set("2B", "#FFE600", 0.65);
    brush.line(v.topX + 16, v.topY - 16, v.topX, v.topY);
  }

  // --- 4B. TRUMPETER'S RIGHT HAND GRIPPING THE VALVES ---
  const fingers = [
    // Index finger pressing Valve 1
    {
      pts: [[725, 865], [648, 795], [575, 738], [538, 754]],
      w: 22
    },
    // Middle finger pressing Valve 2
    {
      pts: [[752, 905], [685, 832], [625, 772], [588, 786]],
      w: 22
    },
    // Ring finger pressing Valve 3
    {
      pts: [[772, 948], [718, 875], [672, 810], [638, 818]],
      w: 20
    },
    // Pinky finger in saddle ring
    {
      pts: [[782, 988], [742, 922], [705, 868], [675, 872]],
      w: 17
    }
  ];

  for (let f of fingers) {
    // Finger dorsal highlight in cadmium yellow & viridian, underside in vermilion & cobalt
    for (let offset = -f.w * 0.5; offset <= f.w * 0.5; offset += 3.5) {
      let col = offset < -3 ? "#FFE600" : (offset < 3 ? "#008C62" : (offset < 8 ? "#E32619" : "#002FA7"));
      brush.set("cpencil", col, 0.48);
      let fSpline = f.pts.map((p, idx) => [p[0] + offset * 0.6, p[1] + offset * 0.8, 0.6 + 0.3 * sin(idx * 60)]);
      brush.spline(fSpline, 0.42);
    }
    // Knuckle wrinkles
    for (let k = 1; k <= 2; k++) {
      let kp = f.pts[k];
      for (let r = -6; r <= 6; r += 3) {
        brush.set("rotring", "#4D0019", 0.3);
        brush.arc(kp[0] + r, kp[1] + r * 0.5, 9, -45, 75);
      }
    }
    // Fingernail specular highlight at tip
    let tip = f.pts[3];
    let nailPts = ellipsePoints(tip[0] + 4, tip[1] - 2, 7, 5, -25, 12, 0);
    drawWashShape(nailPts, "#FFFFE0", 240, 0.25);
    brush.set("rotring", "#8C0B04", 0.3);
    drawPoly(nailPts, 0.25);
  }

  // --- 4C. THE FLARING FOREGROUND BRASS BELL IN HOT ORANGE & VIOLET ---
  const bellCx = 275;
  const bellCy = 875;
  const bellRx = 236;
  const bellRy = 254;
  const bellRot = -22;
  const cRot = cos(bellRot);
  const sRot = sin(bellRot);

  // Helper to transform local bell ellipse coords to canvas coords
  function bellPt(lx, ly) {
    return [
      bellCx + lx * cRot - ly * sRot,
      bellCy + lx * sRot + ly * cRot
    ];
  }

  // 1. Concentric acoustic torus rings warping back into the off-center throat (throat at local +48, -38)
  const throatLx = 52;
  const throatLy = -42;
  for (let ring = 0; ring < 78; ring++) {
    let t = ring / 77; // 0 = outer rim, 1 = deep acoustic throat
    let curCx = lerp(0, throatLx, pow(t, 1.35));
    let curCy = lerp(0, throatLy, pow(t, 1.35));
    let curRx = lerp(bellRx, 18, pow(t, 0.88));
    let curRy = lerp(bellRy, 18, pow(t, 0.88));

    // Draw segmented arcs around the ring with dramatic hot orange, violet, magenta & cadmium yellow
    let segs = 12;
    for (let s = 0; s < segs; s++) {
      let aStart = (s / segs) * 360 + ring * 7;
      let aEnd = aStart + (360 / segs) * 1.12;
      let aMid = ((aStart + aEnd) * 0.5) % 360;

      // Determine metallic reflection color based on angle and depth
      let col;
      if (t > 0.72) {
        col = s % 2 === 0 ? "#1F003B" : "#4B0082";
      } else if (aMid > 185 && aMid < 315) {
        // Upper-left flare catching intense stage light & cheek reflection
        if (t < 0.18 || (t > 0.38 && t < 0.52)) col = "#FFEE00";
        else if (t < 0.42) col = "#FF5500";
        else col = "#D90B68";
      } else if (aMid >= 315 || aMid < 65) {
        // Right side of bell: rich violet & fiery vermilion-orange stripes
        col = (ring + s) % 3 === 0 ? "#5B0A91" : ((ring + s) % 3 === 1 ? "#FF3300" : "#2E004F");
      } else {
        // Bottom-left quadrant: deep royal violet & molten orange
        col = (ring + s) % 2 === 0 ? "#4B0082" : "#FF4D00";
      }

      let arcPts = [];
      for (let k = 0; k <= 5; k++) {
        let ang = lerp(aStart, aEnd, k / 5);
        let p = bellPt(curCx + cos(ang) * curRx, curCy + sin(ang) * curRy);
        arcPts.push([p[0], p[1], sin((k / 5) * 180) * 0.9 + 0.2]);
      }
      brush.set("cpencil", col, map(t, 0, 1, 0.65, 0.38));
      brush.spline(arcPts, 0.45);
    }
  }

  // 2. Radial spun-brass specular reflections & acoustic flare streaks
  for (let i = 0; i < 95; i++) {
    let ang = (i / 95) * 360 + random(-2, 2);
    let t1 = random(0.02, 0.35);
    let t2 = min(0.95, t1 + random(0.25, 0.58));

    let p1 = bellPt(
      lerp(0, throatLx, pow(t1, 1.35)) + cos(ang) * lerp(bellRx, 18, pow(t1, 0.88)),
      lerp(0, throatLy, pow(t1, 1.35)) + sin(ang) * lerp(bellRy, 18, pow(t1, 0.88))
    );
    let p2 = bellPt(
      lerp(0, throatLx, pow(t2, 1.35)) + cos(ang) * lerp(bellRx, 18, pow(t2, 0.88)),
      lerp(0, throatLy, pow(t2, 1.35)) + sin(ang) * lerp(bellRy, 18, pow(t2, 0.88))
    );

    let col = "#FF4500";
    if (ang > 205 && ang < 295) col = i % 2 === 0 ? "#FFFF80" : "#FFD000";
    else if (ang > 25 && ang < 145) col = i % 2 === 0 ? "#380066" : "#8A00C4";
    else col = i % 2 === 0 ? "#FF6600" : "#E32619";

    brush.set("2B", col, random(0.35, 0.62));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 3. Deep dark violet-black center of the bell bore
  const boreHolePts = ellipsePoints(
    bellPt(throatLx, throatLy)[0],
    bellPt(throatLx, throatLy)[1],
    22, 24, bellRot, 20, 0.02
  );
  drawWashShape(boreHolePts, "#120024", 250, 0.3);

  // 4. Rolled metallic bead rim of the foreground bell (double specular + violet shadow rim)
  for (let offset = -5; offset <= 5; offset += 2.5) {
    let rimPts = [];
    for (let i = 0; i <= 48; i++) {
      let ang = (i / 48) * 360;
      let p = bellPt(cos(ang) * (bellRx + offset), sin(ang) * (bellRy + offset));
      rimPts.push([p[0], p[1], 0.75]);
    }
    let rimCol = offset < 0 ? "#3A0066" : (offset === 0 ? "#FF4500" : "#FFE800");
    brush.set("2B", rimCol, offset === 0 ? 0.85 : 0.55);
    brush.spline(rimPts, 0.45);
  }

  // Blinding specular glint arcs along the upper-left and lower-right rolled bell rim
  let glintArc1 = [];
  for (let a = 195; a <= 305; a += 6) {
    let p = bellPt(cos(a) * (bellRx - 2), sin(a) * (bellRy - 2));
    glintArc1.push([p[0], p[1], sin(map(a, 195, 305, 0, 180))]);
  }
  brush.set("pen", "#FFFFFF", 0.9);
  brush.spline(glintArc1, 0.45);

  let glintArc2 = [];
  for (let a = 25; a <= 115; a += 6) {
    let p = bellPt(cos(a) * (bellRx - 3), sin(a) * (bellRy - 3));
    glintArc2.push([p[0], p[1], sin(map(a, 25, 115, 0, 180)) * 0.85]);
  }
  brush.set("pen", "#FFE800", 0.75);
  brush.spline(glintArc2, 0.45);

  // =========================================================================
  // 5. HYPERREALISTIC SKIN PORES, SUBCUTANEOUS VEINS & BEADS OF SWEAT
  // =========================================================================

  // --- 5A. PHOTOGRAPHIC PORES ON STRETCHED SKIN ---
  // 1. Pores across the massive near ballooned cheek (stretched tight like a drum)
  drawSkinPoresOnSphere(
    745, 585, 162, 155,
    -68, 68, -72, 68,
    24, 26,
    "#7A001E", "#FFF770",
    (x, y) => dist(x, y, 745, 585) < 160 && x > 590
  );

  // 2. Pores across the far ballooned cheek
  drawSkinPoresOnSphere(
    395, 525, 88, 92,
    -65, 65, -70, 55,
    14, 14,
    "#7A001E", "#FFE600",
    (x, y) => dist(x, y, 395, 525) < 86 && y < 620
  );

  // 3. Pores on the bulbous nose tip, bridge & infraorbital skin
  drawSkinPoresOnSphere(
    508, 462, 42, 45,
    -65, 65, -65, 65,
    11, 11,
    "#6B001A", "#FFFF99",
    null
  );

  // 4. Pores across the viridian forehead planes
  drawSkinPoresOnSphere(
    625, 242, 165, 82,
    -60, 60, -68, 68,
    14, 22,
    "#003826", "#B8FF66",
    (x, y) => y > 152 && y < 332 && x > 455 && x < 810
  );

  // --- 5B. PULSING SUBCUTANEOUS VEINS (Temples, Forehead, Neck, Cheeks, Hand) ---
  // 1. Prominent serpentine superficial temporal vein & branches in the cobalt temple & viridian forehead
  const temporalVeinMain = [
    [852, 428], [842, 385], [824, 342], [818, 298],
    [795, 258], [762, 224], [728, 195], [685, 174]
  ];
  const temporalBranch1 = [
    [818, 298], [848, 268], [872, 238], [888, 208]
  ];
  const temporalBranch2 = [
    [795, 258], [748, 252], [705, 238], [668, 228]
  ];
  const foreheadVeinLeft = [
    [518, 305], [502, 265], [492, 225], [478, 192]
  ];
  drawVein(temporalVeinMain, 0.85, "#001440", "#0055B3", "#80FFE5", -0.8, -0.6);
  drawVein(temporalBranch1, 0.62, "#001440", "#0047AB", "#66FFCC", -0.8, -0.6);
  drawVein(temporalBranch2, 0.58, "#002B1F", "#008C62", "#FFE800", -0.7, -0.7);
  drawVein(foreheadVeinLeft, 0.55, "#002B1F", "#007F5C", "#FFE800", -0.8, -0.5);

  // 2. Engorged external jugular & anterior neck veins straining under pressure
  const jugularMain = [
    [888, 612], [872, 685], [852, 765], [838, 845],
    [815, 922], [792, 995]
  ];
  const jugularBranch1 = [
    [852, 765], [805, 812], [762, 868], [722, 932]
  ];
  const jugularBranch2 = [
    [872, 685], [912, 738], [942, 798], [965, 855]
  ];
  const neckAnteriorVein = [
    [682, 778], [668, 838], [652, 905], [635, 975]
  ];
  drawVein(jugularMain, 1.15, "#4A001A", "#0047AB", "#FFE800", -0.85, -0.5);
  drawVein(jugularBranch1, 0.78, "#001845", "#0055B3", "#70FFD9", -0.85, -0.5);
  drawVein(jugularBranch2, 0.72, "#002B1F", "#00805A", "#FFE800", -0.85, -0.5);
  drawVein(neckAnteriorVein, 0.82, "#4A001A", "#8C0B04", "#FF9900", -0.85, -0.5);

  // 3. Stretched facial capillaries & veins on the ballooned cheeks & hand
  const cheekVein1 = [
    [835, 695], [808, 645], [792, 598], [768, 558]
  ];
  const cheekVein2 = [
    [808, 645], [845, 618], [872, 588]
  ];
  const handVein1 = [
    [748, 935], [692, 875], [638, 822], [595, 775]
  ];
  const handVein2 = [
    [692, 875], [662, 808], [618, 762]
  ];
  drawVein(cheekVein1, 0.52, "#7A001E", "#C41208", "#FFE600", -0.8, -0.6);
  drawVein(cheekVein2, 0.42, "#7A001E", "#D91E11", "#FFE600", -0.8, -0.6);
  drawVein(handVein1, 0.72, "#001F4D", "#006644", "#FFE600", -0.7, -0.7);
  drawVein(handVein2, 0.58, "#4D0019", "#007F5C", "#FFE600", -0.7, -0.7);

  // --- 5C. GLISTENING 3D BEADS OF SWEAT & TRICKLES ---
  const sweatBeads = [
    // Forehead beads (over viridian & cadmium yellow planes)
    { x: 538, y: 205, r: 9.5, sh: "#003826", ref: "#FFF200", tr: true, ang: -85, len: 26 },
    { x: 618, y: 188, r: 7.5, sh: "#003826", ref: "#80FFAA", tr: false },
    { x: 682, y: 232, r: 11.0, sh: "#003322", ref: "#00E699", tr: true, ang: -78, len: 34 },
    { x: 745, y: 268, r: 8.5, sh: "#002366", ref: "#4DFFCC", tr: true, ang: -70, len: 22 },
    { x: 488, y: 252, r: 7.0, sh: "#003826", ref: "#FFE800", tr: false },
    { x: 582, y: 278, r: 6.5, sh: "#003322", ref: "#B8FF33", tr: false },
    { x: 648, y: 302, r: 8.0, sh: "#003322", ref: "#00E699", tr: false },

    // Cobalt temple hollow & brow beads
    { x: 828, y: 312, r: 10.5, sh: "#001238", ref: "#3399FF", tr: true, ang: -82, len: 30 },
    { x: 868, y: 378, r: 8.0, sh: "#001238", ref: "#00CCFF", tr: false },
    { x: 798, y: 418, r: 7.2, sh: "#001B4D", ref: "#66FFCC", tr: false },
    { x: 718, y: 332, r: 6.8, sh: "#002B1F", ref: "#FFE600", tr: false },

    // Nose bridge & tip sweat droplets
    { x: 535, y: 412, r: 7.2, sh: "#59001E", ref: "#FFE800", tr: true, ang: -68, len: 20 },
    { x: 496, y: 452, r: 6.2, sh: "#7A001E", ref: "#FFFF66", tr: false },

    // Massive near ballooned cheek sweat beads (catching yellow, orange & vermilion caustics)
    { x: 658, y: 468, r: 9.8, sh: "#8C2D00", ref: "#FFF700", tr: true, ang: -88, len: 28 },
    { x: 742, y: 482, r: 12.0, sh: "#8C2D00", ref: "#FFEE00", tr: true, ang: -95, len: 38 },
    { x: 818, y: 512, r: 9.0, sh: "#7A0B00", ref: "#FFAA00", tr: false },
    { x: 628, y: 548, r: 10.5, sh: "#7A001E", ref: "#FF8800", tr: true, ang: -82, len: 32 },
    { x: 708, y: 575, r: 8.2, sh: "#7A001E", ref: "#FFCC00", tr: false },
    { x: 788, y: 602, r: 11.2, sh: "#660008", ref: "#FF5500", tr: true, ang: -102, len: 35 },
    { x: 862, y: 578, r: 8.5, sh: "#003826", ref: "#66FFB2", tr: false },
    { x: 668, y: 658, r: 9.5, sh: "#590004", ref: "#FF3300", tr: true, ang: -85, len: 26 },
    { x: 758, y: 692, r: 8.8, sh: "#4D0004", ref: "#FF4500", tr: false },
    { x: 835, y: 678, r: 7.5, sh: "#4D0004", ref: "#FF6600", tr: false },

    // Far ballooned cheek sweat beads
    { x: 368, y: 478, r: 8.5, sh: "#7A1F00", ref: "#FFE800", tr: true, ang: -75, len: 22 },
    { x: 342, y: 538, r: 9.2, sh: "#6B0008", ref: "#FF6600", tr: false },
    { x: 405, y: 565, r: 7.0, sh: "#6B0008", ref: "#FF9900", tr: false },

    // Jaw & straining neck sweat beads
    { x: 792, y: 795, r: 10.2, sh: "#001845", ref: "#FF5500", tr: true, ang: -75, len: 32 },
    { x: 868, y: 752, r: 8.5, sh: "#002B1F", ref: "#FFE600", tr: false },
    { x: 735, y: 885, r: 9.0, sh: "#001440", ref: "#33CCFF", tr: true, ang: -70, len: 28 },
    { x: 895, y: 845, r: 7.8, sh: "#002B1F", ref: "#66FF99", tr: false }
  ];

  for (let sb of sweatBeads) {
    drawSweatBead(sb.x, sb.y, sb.r, sb.sh, sb.ref, "#FFFFF5", sb.tr, sb.ang, sb.len);
  }

  // Tiny micro-sweat dewdrops scattered across the brow, nose, and cheek highlight zones
  for (let i = 0; i < 55; i++) {
    let zone = i % 3;
    let mx, my, msh, mref;
    if (zone === 0) {
      mx = random(475, 775);
      my = random(175, 325);
      msh = "#003826";
      mref = "#FFE800";
    } else if (zone === 1) {
      let a = random(0, 360);
      let d = random(15, 145);
      mx = 742 + cos(a) * d;
      my = 578 + sin(a) * d;
      msh = "#7A0B00";
      mref = "#FFF200";
    } else {
      mx = random(482, 575);
      my = random(375, 485);
      msh = "#66001A";
      mref = "#FFFF80";
    }
    drawSweatBead(mx, my, random(2.8, 4.8), msh, mref, "#FFFFFF", false);
  }

  // =========================================================================
  // 6. FINAL CRISP ARCHITECTURAL RESTATEMENT & SPECULAR HIGHLIGHTS
  // =========================================================================
  // Restate outer portrait contour against the flat emerald background
  const leftContour = [
    [475, 165, 0.5], [452, 202, 0.8], [436, 260, 0.8], [430, 326, 0.9],
    [416, 362, 0.9], [428, 392, 0.9], [362, 422, 1.0], [312, 478, 1.0],
    [304, 552, 1.0], [342, 618, 0.9], [412, 645, 0.6]
  ];
  brush.set("2B", "#002366", 0.68);
  brush.spline(leftContour, 0.42);

  // Specular skin sheen streaks on the apex of the ballooned cheeks & nose tip
  brush.set("pen", "#FFFFCC", 0.72);
  brush.arc(718, 525, 68, 205, 265);
  brush.arc(372, 488, 38, 195, 255);
  brush.arc(502, 464, 18, 200, 285);

  noLoop();
}

