    opacity: 28,
    spacing: 0.4,
    pressure: [0.3, 0.9, 0.3],
    noise: 0.5
  });
}

// Helper: create regular or modulated polygon vertices
function ringVertices(cx, cy, rFn, steps, rotOffset = 0) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let ang = rotOffset + (i * 360) / steps;
    let r = typeof rFn === "function" ? rFn(ang, i) : rFn;
    pts.push([cx + r * cos(ang), cy + r * sin(ang)]);
  }
  return pts;
}

// Helper: create small elliptical/diamond spot polygon aligned radially
function spotPolygon(cx, cy, r, theta, radLen, tanLen, sides = 10) {
  let pts = [];
  let ca = cos(theta);
  let sa = sin(theta);
  let px = cx + r * ca;
  let py = cy + r * sa;
  for (let i = 0; i < sides; i++) {
    let a = (i * 360) / sides;
    let u = radLen * cos(a);
    let v = tanLen * sin(a);
    pts.push([px + u * ca - v * sa, py + u * sa + v * ca]);
  }
  return new brush.Polygon(pts);
}

// Helper: polar to cartesian
function pol(cx, cy, r, ang) {
  return [cx + r * cos(ang), cy + r * sin(ang)];
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();
  brush.noClip();

  const CX = 600;
  const CY = 600;
  const SYM = 24; // 24-fold cut-crystal symmetry
  const STEP = 360 / SYM; // 15 degrees

  // =========================================================================
  // 1. BLACK VELVET FIELD & SUBTLE RADIAL AMBIENCE
  // =========================================================================
  background("#040407");

  // Deep velvet tonal under-washes
  let ambientRadii = [590, 500, 420, 350, 290, 250];
  let ambientCols = ["#07070c", "#090912", "#0c0b16", "#0f0e1c", "#121122", "#08080e"];
  let ambientAlphas = [90, 60, 45, 40, 35, 120];
  for (let i = 0; i < ambientRadii.length; i++) {
    let poly = new brush.Polygon(ringVertices(CX, CY, ambientRadii[i], 64));
    poly.wash(ambientCols[i], ambientAlphas[i]);
  }

  // Tactile black-velvet pile texture (fine directional nap & light absorption)
  for (let i = 0; i < 420; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let d = dist(x, y, CX, CY);
    if (d > 205) {
      let col = d < 460 ? (random() < 0.5 ? "#131221" : "#0d1621") : "#090910";
      brush.set("velvet_nap", col, random(0.6, 1.4));
      let len = random(18, 48);
      let ang = random(-12, 12) + 35;
      brush.line(x, y, x + len * cos(ang), y + len * sin(ang));
    }
  }

  // =========================================================================
  // 2. REFRACTED OPTICAL WEB (SUBTLE SCIENTIFIC CAUSTIC ENVELOPES)
  // =========================================================================
  // Concentric ring definitions for the projected crystal facets
  const causticRings = [
    { r: 227, offset: 0.0,  scale: 0.52, intensity: 0.92, split: true,  spread: 2.2 },
    { r: 244, offset: 0.0,  scale: 0.85, intensity: 1.00, split: false, spread: 0.0 },
    { r: 266, offset: 0.5,  scale: 1.05, intensity: 0.98, split: false, spread: 0.0 },
    { r: 294, offset: 0.0,  scale: 1.18, intensity: 0.94, split: true,  spread: 3.1 },
    { r: 326, offset: 0.5,  scale: 1.25, intensity: 0.88, split: false, spread: 0.0 },
    { r: 362, offset: 0.0,  scale: 1.35, intensity: 0.80, split: false, spread: 0.0 },
    { r: 402, offset: 0.5,  scale: 1.42, intensity: 0.70, split: true,  spread: 3.6 },
    { r: 444, offset: 0.0,  scale: 1.48, intensity: 0.58, split: false, spread: 0.0 },
    { r: 488, offset: 0.5,  scale: 1.54, intensity: 0.44, split: false, spread: 0.0 },
    { r: 534, offset: 0.0,  scale: 1.60, intensity: 0.30, split: false, spread: 0.0 },
    { r: 576, offset: 0.5,  scale: 1.65, intensity: 0.17, split: false, spread: 0.0 }
  ];

  // Whispered refractive lattice linking facet projections (like optical ray diagrams)
  for (let i = 0; i < SYM; i++) {
    let baseAng = i * STEP;
    let cwPts = [];
    let ccwPts = [];
    for (let m = 0; m < causticRings.length; m++) {
      let rk = causticRings[m].r;
      let a1 = baseAng + m * 7.5;
      let a2 = baseAng - m * 7.5;
      let p1 = pol(CX, CY, rk, a1);
      let p2 = pol(CX, CY, rk, a2);
      cwPts.push([p1[0], p1[1], map(m, 0, 10, 0.7, 0.15)]);
      ccwPts.push([p2[0], p2[1], map(m, 0, 10, 0.7, 0.15)]);
    }
    brush.set("silver_pen", i % 2 === 0 ? "#232942" : "#1d313d", 0.38);
    brush.spline(cwPts, 0.45);
    brush.set("silver_pen", i % 2 === 0 ? "#29213d" : "#1e2d3b", 0.38);
    brush.spline(ccwPts, 0.45);
  }

  // Faint harmonic measurement/refraction rings on the velvet
  for (let m = 0; m < causticRings.length; m++) {
    let rk = causticRings[m].r;
    let col = m % 2 === 0 ? "#242038" : "#1b2e38";
    let w = map(m, 0, causticRings.length - 1, 0.45, 0.18);
    for (let i = 0; i < SYM; i++) {
      let aStart = i * STEP + causticRings[m].offset * STEP - 4.5;
      let aEnd = aStart + 9.0;
      brush.set("silver_pen", col, w);
      brush.arc(CX, CY, rk, aStart, aEnd);
    }
  }

  // =========================================================================
  // 3. CONCENTRIC CAUSTIC LIGHT SPOTS (SOFT PASTEL HALOS + HARD WHITE CORES)
  // =========================================================================
  // Precompute all caustic spot descriptors for color-batched washes and strokes
  let spots = [];
  for (let m = 0; m < causticRings.length; m++) {
    let ring = causticRings[m];
    for (let i = 0; i < SYM; i++) {
      let centerAng = (i + ring.offset) * STEP;
      if (ring.split) {
        // Split mitre-cut doublet spots
        spots.push({
          r: ring.r,
          ang: centerAng - ring.spread,
          sc: ring.scale * 0.76,
          intensity: ring.intensity * 0.88,
          ringIdx: m,
          isSplit: true
        });
        spots.push({
          r: ring.r,
          ang: centerAng + ring.spread,
          sc: ring.scale * 0.76,
          intensity: ring.intensity * 0.88,
          ringIdx: m,
          isSplit: true
        });
      } else {
        // Primary diamond-facet spot
        spots.push({
          r: ring.r,
          ang: centerAng,
          sc: ring.scale,
          intensity: ring.intensity,
          ringIdx: m,
          isSplit: false
        });
        // Secondary interstitial micro-caustic on inner/mid rings
        if (m >= 1 && m <= 6 && m !== 3) {
          spots.push({
            r: ring.r + 3,
            ang: centerAng + STEP * 0.5,
            sc: ring.scale * 0.48,
            intensity: ring.intensity * 0.52,
            ringIdx: m,
            isSplit: true
          });
        }
      }
    }
  }

  // PASS 3A: Soft chromatic dispersion washes (Inner Pastel Violet & Outer Pastel Cyan)
  // Batched by color for smooth optical glow
  for (let s of spots) {
    let disp = map(s.r, 225, 580, 2.2, 6.8) * s.sc;
    let radW = 9.5 * s.sc;
    let tanW = 6.2 * s.sc;
    let alpha = Math.round(32 * s.intensity);
    if (alpha > 3) {
      let pViolet = spotPolygon(CX, CY, s.r - disp, s.ang, radW, tanW, 8);
      pViolet.wash("#c4b5fd", alpha); // soft pastel lavender-violet
    }
  }

  for (let s of spots) {
    let disp = map(s.r, 225, 580, 2.2, 6.8) * s.sc;
    let radW = 9.5 * s.sc;
    let tanW = 6.2 * s.sc;
    let alpha = Math.round(32 * s.intensity);
    if (alpha > 3) {
      let pCyan = spotPolygon(CX, CY, s.r + disp, s.ang, radW, tanW, 8);
      pCyan.wash("#67e8f9", alpha); // soft pastel aqua-cyan
    }
  }

  // Warm champagne-rose chromatic middle wash on inner rings (amber whisky transmission)
  for (let s of spots) {
    if (s.ringIdx <= 5) {
      let alpha = Math.round(26 * s.intensity);
      let pWarm = spotPolygon(CX, CY, s.r - 1.0, s.ang, 7.5 * s.sc, 5.2 * s.sc, 8);
      pWarm.wash(s.ringIdx <= 2 ? "#fde68a" : "#f5d0fe", alpha);
    }
  }

  // PASS 3B: Sprayed pastel halos (soft stippled grain around each caustic spot)
  for (let s of spots) {
    let [px, py] = pol(CX, CY, s.r, s.ang);
    let ca = cos(s.ang);
    let sa = sin(s.ang);
    let disp = map(s.r, 225, 580, 2.5, 6.5) * s.sc;
    let sprayW = s.sc * (0.55 + 0.55 * s.intensity);

    // Inner violet sprayed halo
    brush.set("halo_spray", "#d8b4fe", sprayW);
    brush.line(
      px - (disp + 2.5) * ca,
      py - (disp + 2.5) * sa,
      px - (disp - 2.5) * ca,
      py - (disp - 2.5) * sa
    );

    // Outer cyan sprayed halo
    brush.set("halo_spray", "#a5f3fc", sprayW);
    brush.line(
      px + (disp - 2.5) * ca,
      py + (disp - 2.5) * sa,
      px + (disp + 2.5) * ca,
      py + (disp + 2.5) * sa
    );

    // Tighter central pastel-white mist
    if (s.intensity > 0.25) {
      brush.set("tight_spray", "#e0f2fe", sprayW * 0.85);
      brush.line(
        px - 2.2 * sa,
        py + 2.2 * ca,
        px + 2.2 * sa,
        py - 2.2 * ca
      );
    }
  }

  // PASS 3C: Luminous ice-white inner glow washes
  for (let s of spots) {
    let alpha = Math.round(78 * Math.pow(s.intensity, 1.15));
    if (alpha > 5) {
      let pCoreGlow = spotPolygon(CX, CY, s.r, s.ang, 4.6 * s.sc, 3.1 * s.sc, 8);
      pCoreGlow.wash("#e0f2fe", alpha);
    }
  }

  for (let s of spots) {
    let alpha = Math.round(145 * Math.pow(s.intensity, 1.3));
    if (alpha > 8) {
      let pCoreHot = spotPolygon(CX, CY, s.r, s.ang, 2.5 * s.sc, 1.65 * s.sc, 6);
      pCoreHot.wash("#ffffff", alpha);
    }
  }

  // PASS 3D: Hard white cores & sharp astigmatic caustic cusps
  for (let s of spots) {
    let [px, py] = pol(CX, CY, s.r, s.ang);
    let ca = cos(s.ang);
    let sa = sin(s.ang);

    // Crisp white marker core
    let coreLen = (1.6 + 2.2 * s.intensity) * s.sc;
    let coreWeight = (0.35 + 0.65 * s.intensity) * Math.min(1.15, s.sc);
    brush.set("white_marker", "#ffffff", coreWeight);
    brush.line(
      px - coreLen * 0.45 * ca,
      py - coreLen * 0.45 * sa,
      px + coreLen * 0.45 * ca,
      py + coreLen * 0.45 * sa
    );

    // Razor-sharp optical cusp wings on primary spots
    if (!s.isSplit && s.intensity > 0.35) {
      let wingLen = (4.5 + 4.5 * s.intensity) * s.sc;
      let wingSpread = 24; // degrees of caustic V-cusp
      let a1 = s.ang + 180 - wingSpread;
      let a2 = s.ang + 180 + wingSpread;
      brush.set("knife_edge", s.ringIdx % 2 === 0 ? "#e0f2fe" : "#f3e8ff", 0.55 * s.intensity);
      brush.line(px, py, px + wingLen * cos(a1), py + wingLen * sin(a1));
      brush.line(px, py, px + wingLen * cos(a2), py + wingLen * sin(a2));
    }

    // Pinpoint specular hot-spot in pure white
    brush.set("knife_edge", "#ffffff", 0.75 * s.intensity + 0.25);
    brush.line(px - 0.8 * sa, py + 0.8 * ca, px + 0.8 * sa, py - 0.8 * ca);
  }

  // =========================================================================
  // 4. BASAL CONTACT SHADOW MOAT & ESCAPING LIGHT SPLINTERS (r = 210..223)
  // =========================================================================
  let shadowMoat = new brush.Polygon(
    ringVertices(CX, CY, (ang) => 219 + 2.5 * cos(ang * SYM), 144)
  );
  shadowMoat.wash("#020204", 215);

  // 24 razor-thin refracted light needles escaping directly from the basal vertices
  for (let i = 0; i < SYM; i++) {
    let ang = i * STEP;
    let [x1, y1] = pol(CX, CY, 212, ang);
    let [x2, y2] = pol(CX, CY, 225, ang);
    brush.set("knife_edge", "#c4b5fd", 0.65);
    brush.line(x1, y1, x2, y2);
    let [x3, y3] = pol(CX, CY, 221, ang);
    brush.set("knife_edge", "#ffffff", 0.85);
    brush.line(x1, y1, x3, y3);
  }

  // =========================================================================
  // 5. THE AMBER WHISKY & SUBMERGED CUT-CRYSTAL BASE (r = 0..184)
  // =========================================================================
  // Base liquid amber layers (from deep cognac edge to glowing golden-white center)
  const whiskyLayers = [
    { r: 184, col: "#2e1002", alpha: 210 },
    { r: 178, col: "#451a03", alpha: 165 },
    { r: 168, col: "#78350f", alpha: 130 },
    { r: 152, col: "#92400e", alpha: 110 },
    { r: 132, col: "#b45309", alpha: 95 },
    { r: 110, col: "#d97706", alpha: 90 },
    { r: 86,  col: "#f59e0b", alpha: 95 },
    { r: 62,  col: "#fbbf24", alpha: 110 },
    { r: 42,  col: "#fde68a", alpha: 130 },
    { r: 24,  col: "#fef9c3", alpha: 165 },
    { r: 11,  col: "#ffffff", alpha: 210 }
  ];

  for (let wl of whiskyLayers) {
    let poly = new brush.Polygon(ringVertices(CX, CY, wl.r, 96));
    poly.wash(wl.col, wl.alpha);
  }

  // -------------------------------------------------------------------------
  // 5A. SUBMERGED HOBSTAR / DIAMOND-CUT BASE SEEN THROUGH THE WHISKY
  // -------------------------------------------------------------------------
  // Ring of 24 outer submerged diamond facets (r = 104 to 164)
  for (let i = 0; i < SYM; i++) {
    let aMid = i * STEP;
    let aLeft = (i - 0.5) * STEP;
    let aRight = (i + 0.5) * STEP;

    let pIn = pol(CX, CY, 104, aMid);
    let pLeft = pol(CX, CY, 134, aLeft);
    let pOut = pol(CX, CY, 164, aMid);
    let pRight = pol(CX, CY, 134, aRight);
    let pCtr = pol(CX, CY, 134, aMid);

    // Left half-bevel (lit golden honey / pastel peach)
    let leftBevel = new brush.Polygon([pIn, pLeft, pOut, pCtr]);
    leftBevel.wash(i % 2 === 0 ? "#fcd34d" : "#fdba74", 72);

    // Right half-bevel (deep rich mahogany-amber shadow)
    let rightBevel = new brush.Polygon([pIn, pCtr, pOut, pRight]);
    rightBevel.wash(i % 2 === 0 ? "#451a03" : "#78350f", 95);

    // Prismatic pastel edge glint inside the whisky (soft cyan/lavender dispersion)
    if (i % 2 === 0) {
      let glintTri = new brush.Polygon([
        pLeft,
        pOut,
        pol(CX, CY, 146, aMid - 2.5)
      ]);
      glintTri.wash("#bae6fd", 48);
    } else {
      let glintTri = new brush.Polygon([
        pRight,
        pOut,
        pol(CX, CY, 146, aMid + 2.5)
      ]);
      glintTri.wash("#e9d5ff", 48);
    }

    // Fine internal cut-crystal hatching inside alternating facets
    brush.hatchStyle("silver_pen", "#fde68a", 0.35);
    leftBevel.hatch(4.5, aMid + 35, { rand: 0.02 });
    brush.noHatch();
  }

  // Ring of 24 middle kite wedges (r = 52 to 104)
  for (let i = 0; i < SYM; i++) {
    let aMid = (i + 0.5) * STEP;
    let aLeft = i * STEP;
    let aRight = (i + 1) * STEP;

    let pIn = pol(CX, CY, 52, aMid);
    let pLeft = pol(CX, CY, 78, aLeft);
    let pOut = pol(CX, CY, 104, aMid);
    let pRight = pol(CX, CY, 78, aRight);

    let kite = new brush.Polygon([pIn, pLeft, pOut, pRight]);
    kite.wash(i % 2 === 0 ? "#fef08a" : "#d97706", 68);

    // Bright specular facet slice
    let slice = new brush.Polygon([pIn, pLeft, pOut]);
    slice.wash("#fffbeb", 64);
  }

  // Central 24-Pointed Star Cut (r = 4 to 52) directly over the point light
  for (let i = 0; i < SYM; i++) {
    let aTip = i * STEP;
    let aValleyL = (i - 0.5) * STEP;
    let aValleyR = (i + 0.5) * STEP;

    let pCenter = pol(CX, CY, 4, aTip);
    let pTip = pol(CX, CY, 54, aTip);
    let pValL = pol(CX, CY, 25, aValleyL);
    let pValR = pol(CX, CY, 25, aValleyR);

    let rayL = new brush.Polygon([pCenter, pValL, pTip]);
    rayL.wash("#ffffff", 135);

    let rayR = new brush.Polygon([pCenter, pTip, pValR]);
    rayR.wash("#fbbf24", 110);
  }

  // Knife-edge facet ridges of the submerged base (gold, champagne, and white)
  for (let i = 0; i < SYM; i++) {
    let a0 = i * STEP;
    let aHalf = (i + 0.5) * STEP;
    let aNext = (i + 1) * STEP;

    let pCenter = pol(CX, CY, 4, a0);
    let pVal = pol(CX, CY, 25, aHalf);
    let pStarTip = pol(CX, CY, 54, a0);
    let pKiteIn = pol(CX, CY, 52, aHalf);
    let pKiteSide = pol(CX, CY, 78, a0);
    let pKiteOut = pol(CX, CY, 104, aHalf);
    let pDiaIn = pol(CX, CY, 104, a0);
    let pDiaSide = pol(CX, CY, 134, aHalf);
    let pDiaOut = pol(CX, CY, 164, a0);

    // Outer diamond ridges
    brush.set("silver_pen", "#fde68a", 0.55);
    brush.line(pDiaIn[0], pDiaIn[1], pDiaSide[0], pDiaSide[1]);
    brush.line(pDiaSide[0], pDiaSide[1], pDiaOut[0], pDiaOut[1]);
    brush.set("silver_pen", "#92400e", 0.5);
    brush.line(pDiaIn[0], pDiaIn[1], pDiaOut[0], pDiaOut[1]);

    // Middle kite ridges
    brush.set("knife_edge", "#fef9c3", 0.65);
    brush.line(pKiteIn[0], pKiteIn[1], pKiteSide[0], pKiteSide[1]);
    brush.line(pKiteSide[0], pKiteSide[1], pKiteOut[0], pKiteOut[1]);
    brush.line(pKiteIn[0], pKiteIn[1], pKiteOut[0], pKiteOut[1]);

    // Central star-cut ridges (blazing white & champagne over the point light)
    brush.set("knife_edge", "#ffffff", 0.9);
    brush.line(pCenter[0], pCenter[1], pStarTip[0], pStarTip[1]);
    brush.set("silver_pen", "#fef08a", 0.55);
    brush.line(pVal[0], pVal[1], pStarTip[0], pStarTip[1]);
    let pNextTip = pol(CX, CY, 54, aNext);
    brush.line(pVal[0], pVal[1], pNextTip[0], pNextTip[1]);
  }

  // =========================================================================
  // 6. THE MENISCUS OF AMBER WHISKY (r = 166..185)
  // =========================================================================
  // Surface tension pulls the amber whisky up the inside crystal wall, creating
  // concentric rings of dark mahogany absorption, liquid gold glow, and razor-white arcs
  for (let i = 0; i < SYM; i++) {
    let aStart = i * STEP;
    let aEnd = (i + 1) * STEP;
    let aMid = (i + 0.5) * STEP;

    // Subtle scalloped optical warp from the 24 vertical wall facets
    let p1 = pol(CX, CY, 168, aStart);
    let p2 = pol(CX, CY, 170, aMid);
    let p3 = pol(CX, CY, 168, aEnd);
    let p4 = pol(CX, CY, 177, aEnd);
    let p5 = pol(CX, CY, 178, aMid);
    let p6 = pol(CX, CY, 177, aStart);

    // Dark mahogany meniscus trough
    let trough = new brush.Polygon([p1, p2, p3, p4, p5, p6]);
    trough.wash("#3b1101", 155);

    // Luminous golden-amber meniscus crest (r = 177..183)
    let q1 = pol(CX, CY, 177, aStart);
    let q2 = pol(CX, CY, 178.5, aMid);
    let q3 = pol(CX, CY, 177, aEnd);
    let q4 = pol(CX, CY, 183, aEnd);
    let q5 = pol(CX, CY, 184, aMid);
    let q6 = pol(CX, CY, 183, aStart);

    let crest = new brush.Polygon([q1, q2, q3, q4, q5, q6]);
    crest.wash(i % 2 === 0 ? "#f59e0b" : "#fbbf24", 160);

    // Fine golden-orange & white specular meniscus arcs
    brush.set("silver_pen", "#fde047", 0.75);
    brush.arc(CX, CY, 180.5, aStart + 0.8, aEnd - 0.8);

    brush.set("white_marker", "#fffbeb", 0.42);
    brush.arc(CX, CY, 182.8, aStart + 2.0, aEnd - 2.0);

    brush.set("knife_edge", "#ffffff", 0.85);
    brush.arc(CX, CY, 183.6, aStart + 3.2, aEnd - 3.2);
  }

  // Hyperrealist detail: 3 tiny air micro-bubbles clinging to the amber meniscus
  const bubbles = [
    { r: 179.5, ang: 38,  rad: 2.8 },
    { r: 180.2, ang: 41.5, rad: 1.7 },
    { r: 179.8, ang: 214, rad: 2.3 }
  ];
  for (let b of bubbles) {
    let [bx, by] = pol(CX, CY, b.r, b.ang);
    let bPoly = new brush.Polygon(ringVertices(bx, by, b.rad, 12));
    bPoly.wash("#451a03", 180);
    brush.set("knife_edge", "#fef08a", 0.55);
    brush.circle(bx, by, b.rad, 0.05);
    brush.set("knife_edge", "#ffffff", 0.7);
    brush.arc(bx, by, b.rad * 0.7, b.ang - 60, b.ang + 60);
  }

  // =========================================================================
  // 7. THE CUT-CRYSTAL TUMBLER WALLS & RIM (r = 184..216)
  //    Drawn in fine silver pen and white marker with knife-edge facets
  // =========================================================================
  // Dark crystal wall base ring (total internal reflection contrast)
  let crystalWallBg = new brush.Polygon([
    ...ringVertices(CX, CY, (ang) => 214 + 3.0 * cos(ang * SYM), 144)
  ]);
  // Draw individual wall segments between r = 184 and outer scalloped edge r = 211..217
  for (let i = 0; i < SYM; i++) {
    let aLeft = i * STEP;
    let aMid = (i + 0.5) * STEP;
    let aRight = (i + 1) * STEP;
    let aQ1 = (i + 0.25) * STEP;
    let aQ3 = (i + 0.75) * STEP;

    // Inner cylinder boundary (r = 184)
    let inL = pol(CX, CY, 184, aLeft);
    let inM = pol(CX, CY, 184, aMid);
    let inR = pol(CX, CY, 184, aRight);

    // Mid-wall rim ridge (r = 198)
    let midL = pol(CX, CY, 198, aLeft);
    let midQ1 = pol(CX, CY, 196, aQ1);
    let midM = pol(CX, CY, 200, aMid);
    let midQ3 = pol(CX, CY, 196, aQ3);
    let midR = pol(CX, CY, 198, aRight);

    // Outer cut-crystal scalloped wall (vertices at r = 216, facet flats at r = 210)
    let outL = pol(CX, CY, 216.5, aLeft);
    let outM = pol(CX, CY, 210.5, aMid);
    let outR = pol(CX, CY, 216.5, aRight);

    // 1) Deep obsidian/slate base for the crystal wall sector
    let wallSector = new brush.Polygon([inL, inM, inR, outR, outM, outL]);
    wallSector.wash("#0b0f19", 225);

    // 2) Inner bevel facets (r = 184..198): silver-blue & white marker planes
    let innerLeft = new brush.Polygon([inL, inM, midM, midQ1, midL]);
    innerLeft.wash(i % 2 === 0 ? "#cbd5e1" : "#334155", 155);

    let innerRight = new brush.Polygon([inM, inR, midR, midQ3, midM]);
    innerRight.wash(i % 2 === 0 ? "#1e293b" : "#e2e8f0", 165);

    // 3) Outer steep diamond wedge facets (r = 198..216.5)
    // Left mitre bevel — brilliant white & pastel cyan/violet dispersion
    let outerLeft = new brush.Polygon([midL, midQ1, midM, outM, outL]);
    outerLeft.wash(i % 2 === 0 ? "#ffffff" : "#bae6fd", i % 2 === 0 ? 195 : 135);

    // Right mitre bevel — crisp silver & pastel lavender contrast
    let outerRight = new brush.Polygon([midM, midQ3, midR, outR, outM]);
    outerRight.wash(i % 2 === 0 ? "#475569" : "#f3e8ff", i % 2 === 0 ? 160 : 175);

    // 4) Flat White Marker specular planes on the cut facets
    if (i % 2 === 0) {
      let [mx1, my1] = pol(CX, CY, 204, aLeft + 2.2);
      let [mx2, my2] = pol(CX, CY, 202, aMid - 1.5);
      brush.set("white_marker", "#ffffff", 1.15);
      brush.line(mx1, my1, mx2, my2);

      let [mx3, my3] = pol(CX, CY, 190, aMid + 2.0);
      let [mx4, my4] = pol(CX, CY, 191, aRight - 2.0);
      brush.set("white_marker", "#e2e8f0", 0.85);
      brush.line(mx3, my3, mx4, my4);
    } else {
      let [mx1, my1] = pol(CX, CY, 202, aMid + 1.5);
      let [mx2, my2] = pol(CX, CY, 204, aRight - 2.2);
      brush.set("white_marker", "#ffffff", 1.15);
      brush.line(mx1, my1, mx2, my2);

      let [mx3, my3] = pol(CX, CY, 190, aLeft + 2.0);
      let [mx4, my4] = pol(CX, CY, 191, aMid - 2.0);
      brush.set("white_marker", "#f1f5f9", 0.85);
      brush.line(mx3, my3, mx4, my4);
    }

    // 5) Fine silver-pen hatching inside dark crystal facets
    brush.hatchStyle("silver_pen", "#94a3b8", 0.38);
    if (i % 2 === 0) {
      outerRight.hatch(3.2, aMid - 40, { rand: 0.01 });
    } else {
      innerLeft.hatch(3.2, aMid + 40, { rand: 0.01 });
    }
    brush.noHatch();
  }

  // -------------------------------------------------------------------------
  // 7B. KNIFE-EDGE FACET LINES IN FINE SILVER PEN & RAZOR WHITE
  // -------------------------------------------------------------------------
  for (let i = 0; i < SYM; i++) {
    let aLeft = i * STEP;
    let aMid = (i + 0.5) * STEP;
    let aRight = (i + 1) * STEP;
    let aQ1 = (i + 0.25) * STEP;
    let aQ3 = (i + 0.75) * STEP;

    let inL = pol(CX, CY, 184, aLeft);
    let inM = pol(CX, CY, 184, aMid);
    let inR = pol(CX, CY, 184, aRight);

    let midL = pol(CX, CY, 198, aLeft);
    let midQ1 = pol(CX, CY, 195.5, aQ1);
    let midM = pol(CX, CY, 200.5, aMid);
    let midQ3 = pol(CX, CY, 195.5, aQ3);
    let midR = pol(CX, CY, 198, aRight);

    let outL = pol(CX, CY, 216.5, aLeft);
    let outM = pol(CX, CY, 210.5, aMid);
    let outR = pol(CX, CY, 216.5, aRight);

    // Silver pen structural facet geometry
    brush.set("silver_pen", "#cbd5e1", 0.65);
    brush.line(inL[0], inL[1], midQ1[0], midQ1[1]);
    brush.line(midQ1[0], midQ1[1], inM[0], inM[1]);
    brush.line(inM[0], inM[1], midQ3[0], midQ3[1]);
    brush.line(midQ3[0], midQ3[1], inR[0], inR[1]);

    brush.line(midQ1[0], midQ1[1], outL[0], outL[1]);
    brush.line(midQ1[0], midQ1[1], outM[0], outM[1]);
    brush.line(midQ3[0], midQ3[1], outM[0], outM[1]);
    brush.line(midQ3[0], midQ3[1], outR[0], outR[1]);

    // Knife-edge primary radial ridges & outer crystal cuts in crisp white
    brush.set("knife_edge", "#ffffff", 0.95);
    brush.line(inL[0], inL[1], outL[0], outL[1]);
    brush.line(midM[0], midM[1], outM[0], outM[1]);
    brush.line(outL[0], outL[1], outM[0], outM[1]);
    brush.line(outM[0], outM[1], outR[0], outR[1]);

    // Secondary internal reflection double-line (classic thick crystal look)
    let outL2 = pol(CX, CY, 214.2, aLeft);
    let outM2 = pol(CX, CY, 208.4, aMid);
    brush.set("silver_pen", i % 2 === 0 ? "#bae6fd" : "#e9d5ff", 0.48);
    brush.line(outL2[0], outL2[1], outM2[0], outM2[1]);
  }

  // -------------------------------------------------------------------------
  // 7C. POLISHED TOP RIM OVERLAY (CONCENTRIC SILVER & WHITE MARKER ARCS)
  // -------------------------------------------------------------------------
  // The circular top lip of the tumbler viewed from straight above
  for (let i = 0; i < SYM; i++) {
    let aStart = i * STEP;
    let aEnd = (i + 1) * STEP;

    // Fine silver pen concentric rim rings
    brush.set("silver_pen", "#94a3b8", 0.55);
    brush.arc(CX, CY, 185.2, aStart, aEnd);
    brush.arc(CX, CY, 194.5, aStart, aEnd);
    brush.arc(CX, CY, 205.5, aStart, aEnd);

    // Bright white marker specular arcs along the polished top rim
    if (i % 2 === 0) {
      brush.set("white_marker", "#ffffff", 0.58);
      brush.arc(CX, CY, 198.5, aStart + 1.5, aEnd - 1.5);
    } else {
      brush.set("silver_pen", "#e2e8f0", 0.75);
      brush.arc(CX, CY, 198.5, aStart + 1.0, aEnd - 1.0);
    }

    // Razor-sharp white rim highlights & vertex glints
    brush.set("knife_edge", "#ffffff", 0.9);
    brush.arc(CX, CY, 199.2, aStart + 2.5, aEnd - 2.5);

    // Tiny star-glint on each of the 24 outer crystal vertices
    let [vx, vy] = pol(CX, CY, 216.5, aStart);
    let ca = cos(aStart);
    let sa = sin(aStart);
    brush.set("knife_edge", "#ffffff", 1.05);
    brush.line(vx - 3.2 * ca, vy - 3.2 * sa, vx + 3.2 * ca, vy + 3.2 * sa);
    brush.line(vx - 2.6 * sa, vy + 2.6 * ca, vx + 2.6 * sa, vy - 2.6 * ca);
  }

  // =========================================================================
  // 8. CENTRAL POINT-LIGHT APEX (DEAD CENTER REFRACTION CORONA)
  // =========================================================================
  // The single point light directly underneath the center of the crystal base
  brush.set("tight_spray", "#ffffff", 1.2);
  brush.line(CX - 3, CY, CX + 3, CY);
  brush.line(CX, CY - 3, CX, CY + 3);

  brush.set("white_marker", "#ffffff", 1.3);
  brush.circle(CX, CY, 4.5, 0.02);

  for (let i = 0; i < 12; i++) {
    let ang = i * 30;
    let rLen = i % 2 === 0 ? 19 : 12;
    brush.set("knife_edge", "#ffffff", 0.95);
    brush.line(
      CX - rLen * cos(ang),
      CY - rLen * sin(ang),
      CX + rLen * cos(ang),
      CY + rLen * sin(ang)
    );
  }

  noLoop();
}

