// =============================================================================
// GEOMETRY & ETCHING HELPERS
// =============================================================================

function tissuePoint(lx, ly) {
  let rad = TISSUE.angle * (Math.PI / 180);
  let c = Math.cos(rad), s = Math.sin(rad);
  return [
    TISSUE.cx + lx * c - ly * s,
    TISSUE.cy + lx * s + ly * c
  ];
}

function evalCatmull(pts, t) {
  let n = pts.length - 1;
  let f = constrain(t, 0, 1) * n;
  let i = Math.min(Math.floor(f), n - 1);
  let u = f - i;
  let p0 = pts[Math.max(0, i - 1)];
  let p1 = pts[i];
  let p2 = pts[Math.min(n, i + 1)];
  let p3 = pts[Math.min(n, i + 2)];

  let u2 = u * u, u3 = u2 * u;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * u +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * u +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3
  );
  return [x, y];
}

function evalTangent(pts, t) {
  let dt = 0.01;
  let a = evalCatmull(pts, Math.max(0, t - dt));
  let b = evalCatmull(pts, Math.min(1, t + dt));
  let dx = b[0] - a[0], dy = b[1] - a[1];
  let len = Math.hypot(dx, dy) || 1;
  return [dx / len, dy / len];
}

function fillShapePts(pts, curvature = 0.35) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Sculpt a 3D cylindrical/organic leather form using form-following cross-contour
// etching needles and multi-angle diamond cross-hatching.
function etchForm(leftRail, rightRail, opts = {}) {
  let uSteps = opts.uSteps || 42;
  let vSteps = opts.vSteps || 10;
  let archBulge = opts.archBulge !== undefined ? opts.archBulge : 14;
  let lightCenter = opts.lightCenter !== undefined ? opts.lightCenter : -0.28; // -1..1
  let lightWidth = opts.lightWidth !== undefined ? opts.lightWidth : 0.32;
  let shadowSide = opts.shadowSide || 1; // 1 = right/bottom darker, -1 = left darker
  let pinchList = opts.pinches || []; // [{u, depth, width}]
  let crossHatch = opts.crossHatch !== undefined ? opts.crossHatch : true;
  let tertiary = opts.tertiary !== undefined ? opts.tertiary : true;
  let baseInk = opts.baseInk || PAL.sepiaInk;
  let midInk = opts.midInk || PAL.sepiaMid;
  let softInk = opts.softInk || PAL.sepiaWarm;
  let weightScale = opts.weightScale || 1.0;

  function surfacePt(u, v) {
    let pL = evalCatmull(leftRail, u);
    let pR = evalCatmull(rightRail, u);
    let t = (v + 1) * 0.5;

    // Apply joint pinches
    let pinchFactor = 0;
    for (let k = 0; k < pinchList.length; k++) {
      let pk = pinchList[k];
      let du = (u - pk.u) / (pk.width || 0.08);
      if (Math.abs(du) < 2.2) {
        pinchFactor += pk.depth * Math.exp(-du * du * 2.0);
      }
    }

    let mx = (pL[0] + pR[0]) * 0.5;
    let my = (pL[1] + pR[1]) * 0.5;
    let lx = lerp(pL[0], mx, pinchFactor * 0.45);
    let ly = lerp(pL[1], my, pinchFactor * 0.45);
    let rx = lerp(pR[0], mx, pinchFactor * 0.45);
    let ry = lerp(pR[1], my, pinchFactor * 0.45);

    let bx = lerp(lx, rx, t);
    let by = lerp(ly, ry, t);

    // Axis perpendicular to cross-span gives cross-contour arch
    let dx = rx - lx, dy = ry - ly;
    let span = Math.hypot(dx, dy) || 1;
    let nx = dy / span, ny = -dx / span;
    if (opts.flipArch) { nx = -nx; ny = -ny; }

    let profile = (1 - v * v);
    let nVal = (noise(u * 6 + (opts.seed || 0), v * 4 + 10) - 0.5) * 3.5;
    let lift = (archBulge * (span / 65) * (1 - pinchFactor * 0.8)) * profile + nVal;

    return [bx + nx * lift, by + ny * lift, pinchFactor, span];
  }

  function shadeAt(u, v) {
    let dLight = Math.abs(v - lightCenter);
    let lit = Math.max(0, 1 - dLight / lightWidth);
    let core = shadowSide > 0
      ? constrain(map(v, -0.1, 0.82, 0, 1), 0, 1)
      : constrain(map(v, 0.1, -0.82, 0, 1), 0, 1);
    // Slight reflected light right at the far shadow edge
    if (shadowSide > 0 && v > 0.82) core -= (v - 0.82) * 1.4;
    if (shadowSide < 0 && v < -0.82) core -= (-0.82 - v) * 1.4;

    // Darken in joint pinches
    let pinchDark = 0;
    for (let k = 0; k < pinchList.length; k++) {
      let pk = pinchList[k];
      let du = (u - pk.u) / (pk.width || 0.07);
      if (Math.abs(du) < 2.0) {
        pinchDark += Math.abs(pk.depth) * 1.35 * Math.exp(-du * du * 2.5);
      }
    }

    // Darken near u ends if specified
    let endDark = 0;
    if (opts.darkStart) endDark += opts.darkStart * Math.exp(-u * u / 0.04);
    if (opts.darkEnd) endDark += opts.darkEnd * Math.exp(-(1 - u) * (1 - u) / 0.04);

    let nTex = (noise(u * 12 + 30, v * 12 + (opts.seed || 0)) - 0.45) * 0.22;
    return constrain(core * 0.78 - lit * 0.58 + pinchDark + endDark + nTex + (opts.baseTone || 0.15), 0, 1);
  }

  brush.noFill();

  // PASS 1: Primary cross-contour lines wrapping across v (-1 -> 1)
  for (let i = 0; i <= uSteps; i++) {
    let u = i / uSteps;
    let jitterU = u + random(-0.25, 0.25) / uSteps;
    jitterU = constrain(jitterU, 0.01, 0.99);

    // Split into left-of-highlight and right-of-highlight segments if highlight breaks the stroke
    let segPts = [];
    for (let j = 0; j <= vSteps; j++) {
      let v = -1 + (2 * j) / vSteps;
      let s = shadeAt(jitterU, v);
      let p = surfacePt(jitterU, v);

      if (s < 0.11 && random() < 0.78) {
        if (segPts.length >= 2) {
          brush.set("needle", softInk, 0.55 * weightScale);
          brush.spline(segPts, 0.35);
        }
        segPts = [];
      } else {
        let pr = constrain(map(s, 0.08, 0.95, 0.28, 1.35), 0.25, 1.4);
        segPts.push([p[0], p[1], pr]);
      }
    }
    if (segPts.length >= 2) {
      let avgUShade = shadeAt(jitterU, shadowSide * 0.45);
      let col = avgUShade > 0.58 ? baseInk : (avgUShade > 0.32 ? midInk : softInk);
      brush.set("needle", col, (0.52 + avgUShade * 0.32) * weightScale);
      brush.spline(segPts, 0.35);
    }
  }

  // PASS 2: Diagonal / Longitudinal cross-hatching in halftone & shadow zones
  if (crossHatch) {
    let lLines = Math.floor(vSteps * 2.1);
    let uSegs = Math.max(8, Math.floor(uSteps * 0.45));
    for (let j = 0; j <= lLines; j++) {
      let vBase = -0.96 + (1.92 * j) / lLines;
      let run = [];
      for (let i = 0; i <= uSegs; i++) {
        let u = i / uSegs;
        // Diagonal shear across v creates classic engraved diamond lozenges
        let v = constrain(vBase + (u - 0.5) * 0.36, -0.98, 0.98);
        let s = shadeAt(u, v);
        if (s > 0.32) {
          let p = surfacePt(u, v);
          let pr = constrain(map(s, 0.3, 0.95, 0.25, 1.25), 0.2, 1.3);
          run.push([p[0], p[1], pr]);
        } else {
          if (run.length >= 2) {
            brush.set("needle", midInk, 0.5 * weightScale);
            brush.spline(run, 0.3);
          }
          run = [];
        }
      }
      if (run.length >= 2) {
        brush.set("needle", midInk, 0.52 * weightScale);
        brush.spline(run, 0.3);
      }
    }
  }

  // PASS 3: Tertiary oblique cross-hatching in deep core shadows & joint folds
  if (tertiary) {
    let tLines = Math.floor(uSteps * 0.72);
    for (let i = 0; i <= tLines; i++) {
      let uStart = i / tLines;
      let run = [];
      let steps = 7;
      for (let k = 0; k <= steps; k++) {
        let t = k / steps;
        let v = shadowSide > 0 ? lerp(-0.15, 0.95, t) : lerp(0.15, -0.95, t);
        let u = constrain(uStart + (t - 0.5) * 0.16, 0.01, 0.99);
        let s = shadeAt(u, v);
        if (s > 0.54) {
          let p = surfacePt(u, v);
          run.push([p[0], p[1], map(s, 0.52, 1.0, 0.35, 1.35)]);
        } else {
          if (run.length >= 2) {
            brush.set("drypoint", baseInk, 0.55 * weightScale);
            brush.spline(run, 0.25);
          }
          run = [];
        }
      }
      if (run.length >= 2) {
        brush.set("drypoint", baseInk, 0.58 * weightScale);
        brush.spline(run, 0.25);
      }
    }
  }

  // PASS 4: Crisp etched contour outlines with variable burin pressure
  let leftContour = [], rightContour = [];
  let cSteps = Math.max(14, Math.floor(uSteps * 0.5));
  for (let i = 0; i <= cSteps; i++) {
    let u = i / cSteps;
    let pL = surfacePt(u, -1);
    let pR = surfacePt(u, 1);
    let sL = shadeAt(u, -0.95);
    let sR = shadeAt(u, 0.95);
    leftContour.push([pL[0], pL[1], map(sL, 0, 1, 0.35, 1.25)]);
    rightContour.push([pR[0], pR[1], map(sR, 0, 1, 0.45, 1.4)]);
  }
  brush.set("rotring", midInk, 0.52 * weightScale);
  brush.spline(leftContour, 0.35);
  brush.set("rotring", baseInk, 0.65 * weightScale);
  brush.spline(rightContour, 0.35);

  // PASS 5: Sharp transverse crease fissures at joint pinches
  for (let k = 0; k < pinchList.length; k++) {
    let pk = pinchList[k];
    let creasePts = [];
    let highlightPts = [];
    for (let j = 0; j <= 8; j++) {
      let v = lerp(-0.92, 0.92, j / 8);
      let p = surfacePt(pk.u, v);
      let ph = surfacePt(Math.max(0.01, pk.u - 0.018), v);
      let pr = (1 - Math.abs(v) * 0.6) * (0.7 + Math.abs(pk.depth) * 1.4);
      creasePts.push([p[0] + random(-0.8, 0.8), p[1] + random(-0.8, 0.8), pr]);
      highlightPts.push([ph[0], ph[1], pr * 0.7]);
    }
    brush.set("rotring", PAL.sepiaInk, 0.72 * weightScale);
    brush.spline(creasePts, 0.35);
    // Faint secondary fold echo
    let echoPts = creasePts.map(pt => [pt[0] + random(1.2, 2.8), pt[1] + random(1.5, 3.2), pt[2] * 0.65]);
    brush.set("needle", PAL.sepiaMid, 0.48 * weightScale);
    brush.spline(echoPts, 0.35);
    // Luminous ridge catch-light above deep crease
    brush.set("cpencil", PAL.highlightChalk, 0.48 * weightScale);
    brush.spline(highlightPts, 0.35);
  }
}

// Draw heavy stitched industrial leather seam with optional split-seam tears & frayed threads
function drawLeatherSeam(pts, opts = {}) {
  let count = opts.stitches || 28;
  let offset = opts.offset || 3.5;
  let doubleRow = opts.doubleRow !== undefined ? opts.doubleRow : true;
  let splitRanges = opts.splits || []; // [[t0, t1], ...]

  function isSplit(t) {
    for (let r of splitRanges) {
      if (t >= r[0] && t <= r[1]) return true;
    }
    return false;
  }

  // Draw main indented seam channel or split gap
  let leftLip = [], rightLip = [];
  let steps = Math.max(20, count);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = evalCatmull(pts, t);
    let tan = evalTangent(pts, t);
    let nx = -tan[1], ny = tan[0];

    let gap = 0.6;
    for (let r of splitRanges) {
      if (t >= r[0] && t <= r[1]) {
        let mid = (r[0] + r[1]) * 0.5;
        let half = (r[1] - r[0]) * 0.5;
        let u = (t - mid) / half;
        gap = 0.6 + (opts.splitWidth || 4.8) * (1 - u * u);
      }
    }
    leftLip.push([p[0] - nx * gap, p[1] - ny * gap, 0.9]);
    rightLip.push([p[0] + nx * gap, p[1] + ny * gap, 1.1]);
  }

  // Dark void inside split seams
  for (let r of splitRanges) {
    let voidPoly = [];
    for (let i = 0; i <= 10; i++) {
      let t = lerp(r[0], r[1], i / 10);
      let p = evalCatmull(pts, t);
      let tan = evalTangent(pts, t);
      let nx = -tan[1], ny = tan[0];
      let u = (i / 5) - 1;
      let g = (opts.splitWidth || 4.8) * (1 - u * u);
      voidPoly.push([p[0] - nx * g, p[1] - ny * g]);
    }
    for (let i = 10; i >= 0; i--) {
      let t = lerp(r[0], r[1], i / 10);
      let p = evalCatmull(pts, t);
      let tan = evalTangent(pts, t);
      let nx = -tan[1], ny = tan[0];
      let u = (i / 5) - 1;
      let g = (opts.splitWidth || 4.8) * (1 - u * u);
      voidPoly.push([p[0] + nx * g, p[1] + ny * g]);
    }
    // Dense cross-hatch inside split seam void
    for (let k = 0; k < voidPoly.length / 2 - 1; k++) {
      let a = voidPoly[k], b = voidPoly[voidPoly.length - 1 - k];
      brush.set("rotring", PAL.sepiaInk, 0.75);
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }

  brush.set("rotring", PAL.sepiaInk, 0.72);
  brush.spline(leftLip, 0.35);
  brush.set("rotring", PAL.sepiaInk, 0.82);
  brush.spline(rightLip, 0.35);

  // Raised leather welt highlight along one side of seam
  let weltPts = leftLip.map(p => [p[0] - 1.5, p[1] - 1.5, 0.65]);
  brush.set("cpencil", PAL.highlightChalk, 0.55);
  brush.spline(weltPts, 0.35);

  // Individual stitches, needle holes, and snapped frayed threads at split ranges
  for (let i = 0; i < count; i++) {
    let t0 = i / count;
    let t1 = (i + 0.62) / count;
    let p0 = evalCatmull(pts, t0);
    let p1 = evalCatmull(pts, t1);
    let tan = evalTangent(pts, t0);
    let nx = -tan[1], ny = tan[0];

    let rows = doubleRow ? [-offset, offset] : [offset * 0.7];
    for (let rOff of rows) {
      let sx0 = p0[0] + nx * rOff, sy0 = p0[1] + ny * rOff;
      let sx1 = p1[0] + nx * rOff, sy1 = p1[1] + ny * rOff;

      // Dark needle hole pricks
      brush.set("rotring", PAL.sepiaInk, 0.85);
      brush.line(sx0 - 0.8, sy0 - 0.8, sx0 + 0.8, sy0 + 0.8);

      if (isSplit(t0)) {
        // Broken thread ends curling out of torn stitch holes
        if (random() < 0.85) {
          let dir = rOff > 0 ? 1 : -1;
          let len = random(6, 16);
          let midX = sx0 + nx * dir * (len * 0.5) + tan[0] * random(-5, 5);
          let midY = sy0 + ny * dir * (len * 0.5) + tan[1] * random(-5, 5);
          let endX = midX + nx * dir * (len * 0.45) + random(-5, 5);
          let endY = midY + ny * dir * (len * 0.45) + random(-5, 5);
          brush.set("needle", PAL.sepiaInk, 0.55);
          brush.spline([[sx0, sy0, 0.9], [midX, midY, 0.6], [endX, endY, 0.2]], 0.5);
          brush.set("cpencil", PAL.threadLight, 0.45);
          brush.spline([[sx0, sy0, 0.8], [midX - 0.5, midY - 0.5, 0.5]], 0.5);
        }
      } else {
        // Intact heavy waxed thread segment (shadow under-stroke + light thread top-stroke)
        brush.set("rotring", PAL.sepiaMid, 0.65);
        brush.line(sx0 + 0.7, sy0 + 0.9, sx1 + 0.7, sy1 + 0.9);
        brush.set("cpencil", random() < 0.4 ? PAL.threadDirty : PAL.threadLight, 0.65);
        brush.line(sx0, sy0, sx1, sy1);
      }
    }
  }
}

// Dense sepia-black stipple cluster for oil stains, worn suede, and deep grain
function drawStipplePatch(cx, cy, rx, ry, angleDeg, count, inkColor, weightScale = 1.0) {
  let rad = angleDeg * (Math.PI / 180);
  let c = Math.cos(rad), s = Math.sin(rad);
  brush.set("rotring", inkColor || PAL.sepiaInk, 0.58 * weightScale);

  for (let i = 0; i < count; i++) {
    // Gaussian-like radial falloff
    let r = Math.pow(random(), 0.68);
    let th = random(0, Math.PI * 2);
    let lx = Math.cos(th) * rx * r;
    let ly = Math.sin(th) * ry * r;
    let x = cx + lx * c - ly * s;
    let y = cy + lx * s + ly * c;

    // Slight organic noise clustering
    let n = noise(x * 0.025, y * 0.025);
    if (n < 0.28 && r > 0.5) continue;

    let flick = random(1.1, 2.6);
    let fa = random(0, Math.PI * 2);
    brush.line(x, y, x + Math.cos(fa) * flick, y + Math.sin(fa) * flick);
  }
}

// Cracked epidermis / leather craquelure network on high-stress domes & oil stains
function drawCraquelure(cx, cy, rx, ry, count, seedOffset = 0) {
  for (let i = 0; i < count; i++) {
    let a = random(0, Math.PI * 2);
    let r = Math.pow(random(), 0.75);
    let x = cx + Math.cos(a) * rx * r;
    let y = cy + Math.sin(a) * ry * r;

    let pts = [[x, y, 0.3]];
    let dir = random(0, 360);
    let segs = Math.floor(random(3, 6));
    for (let k = 0; k < segs; k++) {
      let step = random(4, 10);
      dir += random(-42, 42);
      x += Math.cos(dir * Math.PI / 180) * step;
      y += Math.sin(dir * Math.PI / 180) * step;
      let pr = k === Math.floor(segs / 2) ? 0.95 : 0.35;
      pts.push([x, y, pr]);

      // Occasional Y-branch micro-crack
      if (k === 1 && random() < 0.55) {
        let bDir = dir + (random() < 0.5 ? 55 : -55);
        let bx = x + Math.cos(bDir * Math.PI / 180) * random(5, 11);
        let by = y + Math.sin(bDir * Math.PI / 180) * random(5, 11);
        brush.set("needle", PAL.sepiaInk, 0.45);
        brush.line(x, y, bx, by);
      }
    }
    brush.set("needle", PAL.sepiaInk, 0.52);
    brush.spline(pts, 0.25);
  }
}

// Unravelling frayed canvas/cotton cuff threads
function drawFrayedThreads(edgePts, count, normalFlip = 1) {
  for (let i = 0; i < count; i++) {
    let t = random(0.02, 0.98);
    let p = evalCatmull(edgePts, t);
    let tan = evalTangent(edgePts, t);
    let nx = -tan[1] * normalFlip;
    let ny = tan[0] * normalFlip;

    let len = random(12, 46);
    let curl = random(-1.2, 1.2);
    let pts = [[p[0], p[1], 0.9]];
    let cx = p[0], cy = p[1];
    let dirX = nx + tan[0] * random(-0.45, 0.45);
    let dirY = ny + tan[1] * random(-0.45, 0.45);
    let dLen = Math.hypot(dirX, dirY) || 1;
    dirX /= dLen; dirY /= dLen;

    let steps = 5;
    for (let s = 1; s <= steps; s++) {
      let stepLen = len / steps;
      let ang = Math.atan2(dirY, dirX) + curl * (s / steps) * 0.55 + random(-0.25, 0.25);
      dirX = Math.cos(ang);
      dirY = Math.sin(ang);
      cx += dirX * stepLen;
      cy += dirY * stepLen;
      pts.push([cx, cy, map(s, 1, steps, 0.85, 0.2)]);
    }

    // Cast shadow of loose thread on surface
    let shadPts = pts.map(pt => [pt[0] + 2.2, pt[1] + 3.0, pt[2] * 0.6]);
    brush.set("needle", PAL.sepiaSoft, 0.38);
    brush.spline(shadPts, 0.45);

    // Dark core + light fiber edge of thread
    brush.set("needle", PAL.sepiaInk, 0.5);
    brush.spline(pts, 0.45);
    if (random() < 0.65) {
      let hiPts = pts.map(pt => [pt[0] - 0.6, pt[1] - 0.6, pt[2] * 0.7]);
      brush.set("cpencil", PAL.threadLight, 0.42);
      brush.spline(hiPts, 0.45);
    }
  }
}

// =============================================================================
// 1. ARCHIVAL PAPER & GHOSTLY COPPERPLATE BEVEL
// =============================================================================

function drawPaperAndPlateMark() {
  brush.noStroke();

  // Subtle archival rag paper edge warming
  brush.fill(PAL.ivoryDeep, 45);
  brush.fillBleed(0.35, "in");
  brush.fillTexture(0.55, 0.2);
  brush.rect(0, 0, 1200, 95, "corner");
  brush.rect(0, 1105, 1200, 95, "corner");
  brush.rect(0, 95, 120, 1010, "corner");
  brush.rect(1080, 95, 120, 1010, "corner");

  // Ghostly warm plate-tone wiped onto the copperplate [125, 95] -> [1075, 1105]
  let px = 125, py = 95, pw = 950, ph = 1010;
  brush.fill(PAL.plateTone, 38);
  brush.fillBleed(0.02, "in");
  brush.fillTexture(0.45, 0.18);
  brush.rect(px, py, pw, ph, "corner");

  // Debossed plate-mark bevel (14px bevel trough pressed into damp rag paper)
  // Light comes from upper-left:
  // Top & Left bevel slopes are in shadow; Bottom & Right bevel slopes catch light
  let bw = 13;
  brush.fill(PAL.bevelShadow, 72);
  brush.fillBleed(0.01);
  brush.fillTexture(0.25, 0.15);
  // Top bevel shadow strip
  fillShapePts([
    [px - bw, py - bw], [px + pw + bw, py - bw],
    [px + pw, py], [px, py]
  ], 0.02);
  // Left bevel shadow strip
  fillShapePts([
    [px - bw, py - bw], [px, py],
    [px, py + ph], [px - bw, py + ph + bw]
  ], 0.02);

  // Subtle inner shadow at bottom & right inner plate rim
  brush.fill(PAL.bevelShadow, 48);
  fillShapePts([
    [px, py + ph - 5], [px + pw, py + ph - 5],
    [px + pw, py + ph], [px, py + ph]
  ], 0.02);
  fillShapePts([
    [px + pw - 5, py], [px + pw, py],
    [px + pw, py + ph], [px + pw - 5, py + ph]
  ], 0.02);

  // Luminous debossed bevel highlight on Bottom & Right slopes + inner Top/Left lip
  brush.fill(PAL.bevelLight, 140);
  fillShapePts([
    [px, py + ph], [px + pw, py + ph],
    [px + pw + bw, py + ph + bw], [px - bw, py + ph + bw]
  ], 0.02);
  fillShapePts([
    [px + pw, py], [px + pw + bw, py - bw],
    [px + pw + bw, py + ph + bw], [px + pw, py + ph]
  ], 0.02);

  brush.noFill();

  // Delicate drypoint/embossed line definition along the rounded copperplate corners
  let cRad = 12;
  // Outer bevel rim shadow lines (top & left)
  brush.set("2H", PAL.bevelDark, 0.55);
  brush.line(px - bw + cRad, py - bw, px + pw + bw - cRad, py - bw);
  brush.line(px - bw, py - bw + cRad, px - bw, py + ph + bw - cRad);

  // Inner plate-mark rim (where copper edge bit into the paper)
  brush.set("2H", PAL.bevelDark, 0.7);
  brush.line(px + cRad, py, px + pw - cRad, py);
  brush.line(px, py + cRad, px, py + ph - cRad);
  brush.set("2H", PAL.bevelShadow, 0.55);
  brush.line(px + cRad, py + ph, px + pw - cRad, py + ph);
  brush.line(px + pw, py + cRad, px + pw, py + ph - cRad);

  // Crisp white paper highlight along inner top/left and outer bottom/right bevel
  brush.set("cpencil", PAL.bevelLight, 0.8);
  brush.line(px + cRad, py + 1.5, px + pw - cRad, py + 1.5);
  brush.line(px + 1.5, py + cRad, px + 1.5, py + ph - cRad);
  brush.line(px - bw + cRad, py + ph + bw, px + pw + bw - cRad, py + ph + bw);
  brush.line(px + pw + bw, py - bw + cRad, px + pw + bw, py + ph + bw - cRad);

  // Rounded plate corners + faint wiped ink residue trapped in plate corners
  let corners = [
    [px, py, -1, -1],
    [px + pw, py, 1, -1],
    [px + pw, py + ph, 1, 1],
    [px, py + ph, -1, 1]
  ];
  for (let c of corners) {
    let [cx, cy, sx, sy] = c;
    brush.set("2H", PAL.bevelDark, 0.65);
    brush.spline([
      [cx - sx * cRad, cy, 0.6],
      [cx - sx * 3, cy - sy * 3, 0.9],
      [cx, cy - sy * cRad, 0.6]
    ], 0.4);
    // Tiny sepia plate-ink trace in corner
    drawStipplePatch(cx - sx * 6, cy - sy * 6, 8, 8, 0, 12, PAL.sepiaFaint, 0.65);
  }

  // Subtle archival rag fibers & foxing flecks in paper margins
  for (let i = 0; i < 160; i++) {
    let x = random(25, 1175);
    let y = random(25, 1175);
    // Keep mostly in margins or very faint
    if (x > 220 && x < 980 && y > 180 && y < 1000 && random() < 0.7) continue;
    brush.set("2H", random() < 0.5 ? PAL.bevelShadow : PAL.sepiaFaint, 0.35);
    let a = random(0, 360);
    let l = random(1.5, 5);
    brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
  }
}

// =============================================================================
// 2. OFF-REGISTER PALE CELADON CHINE-COLLÉ TISSUE
// =============================================================================

function drawCeladonTissue() {
  let hw = TISSUE.w / 2;
  let hh = TISSUE.h / 2;

  // Build crisp cut-tissue perimeter with minute hand-cut micro-waviness
  let tissuePoly = [];
  let segs = 28;
  // Top edge
  for (let i = 0; i < segs; i++) {
    let t = i / segs;
    let x = lerp(-hw, hw, t);
    let y = -hh + (noise(t * 8, 1) - 0.5) * 1.8;
    tissuePoly.push(tissuePoint(x, y));
  }
  // Right edge
  for (let i = 0; i < segs; i++) {
    let t = i / segs;
    let x = hw + (noise(t * 8, 2) - 0.5) * 1.8;
    let y = lerp(-hh, hh, t);
    tissuePoly.push(tissuePoint(x, y));
  }
  // Bottom edge
  for (let i = 0; i < segs; i++) {
    let t = i / segs;
    let x = lerp(hw, -hw, t);
    let y = hh + (noise(t * 8, 3) - 0.5) * 1.8;
    tissuePoly.push(tissuePoint(x, y));
  }
  // Left edge
  for (let i = 0; i < segs; i++) {
    let t = i / segs;
    let x = -hw + (noise(t * 8, 4) - 0.5) * 1.8;
    let y = lerp(hh, -hh, t);
    tissuePoly.push(tissuePoint(x, y));
  }

  brush.noStroke();

  // Pass 1: Crisp pale watercolour celadon tissue body
  brush.fill(PAL.celadonBase, 118);
  brush.fillBleed(0.015, "in");
  brush.fillTexture(0.68, 0.38);
  fillShapePts(tissuePoly, 0.05);

  // Pass 2: Second subtle uneven mineral glaze pass inside tissue
  brush.fill(PAL.celadonMid, 52);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.75, 0.42);
  fillShapePts(tissuePoly, 0.05);

  brush.noFill();

  // Crisp knife-cut tissue border (slight shadow on bottom/right, crisp highlight on top/left)
  let tl = tissuePoint(-hw, -hh);
  let tr = tissuePoint(hw, -hh);
  let br = tissuePoint(hw, hh);
  let bl = tissuePoint(-hw, hh);

  brush.set("2H", PAL.celadonEdge, 0.62);
  brush.line(tl[0], tl[1], tr[0], tr[1]);
  brush.line(tr[0], tr[1], br[0], br[1]);
  brush.line(br[0], br[1], bl[0], bl[1]);
  brush.line(bl[0], bl[1], tl[0], tl[1]);

  // Paper thickness step shadow along bottom and right edges of tissue
  brush.set("rotring", PAL.celadonDeep, 0.45);
  brush.line(tr[0] + 1.2, tr[1] + 1.2, br[0] + 1.2, br[1] + 1.2);
  brush.line(br[0] + 1.2, br[1] + 1.2, bl[0] + 1.2, bl[1] + 1.2);

  // Thin Mulberry/Gampi tissue highlight along top and left edges
  brush.set("cpencil", PAL.bevelLight, 0.72);
  brush.line(tl[0] - 0.8, tl[1] - 0.8, tr[0] - 0.8, tr[1] - 0.8);
  brush.line(tl[0] - 0.8, tl[1] - 0.8, bl[0] - 0.8, bl[1] - 0.8);

  // Characteristic chine-collé press wrinkles (delicate tension creases compressed under the roller)
  let wrinkles = [
    [[-hw + 22, -hh + 110], [-hw + 145, -hh + 165], [-hw + 270, -hh + 195]],
    [[hw - 18, -hh + 85], [hw - 130, -hh + 150], [hw - 245, -hh + 220], [hw - 310, -hh + 255]],
    [[-hw + 35, hh - 190], [-hw + 160, hh - 245], [-hw + 290, hh - 280]],
    [[hw - 30, hh - 140], [hw - 170, hh - 195], [hw - 295, hh - 225]],
    [[-90, -hh + 15], [-45, -hh + 135], [-15, -hh + 240]],
    [[110, hh - 12], [65, hh - 120], [25, hh - 215]],
    [[-210, -40], [-95, 15], [35, 55], [165, 82]]
  ];

  for (let w of wrinkles) {
    let shPts = [], hiPts = [];
    for (let i = 0; i < w.length; i++) {
      let p = tissuePoint(w[i][0], w[i][1]);
      let pr = (i === 0 || i === w.length - 1) ? 0.25 : 0.85;
      shPts.push([p[0], p[1], pr]);
      hiPts.push([p[0] - 1.4, p[1] - 1.4, pr * 0.9]);
    }
    brush.set("2H", PAL.celadonDeep, 0.52);
    brush.spline(shPts, 0.45);
    brush.set("cpencil", PAL.celadonLight, 0.65);
    brush.spline(hiPts, 0.45);

    // Subtle branching Fork on longer tissue wrinkles
    if (w.length >= 3) {
      let mid = tissuePoint(w[1][0], w[1][1]);
      let end = tissuePoint(w[1][0] + random(-55, 55), w[1][1] + random(25, 55));
      brush.set("2H", PAL.celadonEdge, 0.4);
      brush.line(mid[0], mid[1], end[0], end[1]);
      brush.set("cpencil", PAL.celadonLight, 0.5);
      brush.line(mid[0] - 1, mid[1] - 1, end[0] - 1, end[1] - 1);
    }
  }

  // Faint laid-paper chain & wire lines inside the celadon tissue
  for (let y = -hh + 18; y < hh - 18; y += 26) {
    let p0 = tissuePoint(-hw + 10, y);
    let p1 = tissuePoint(hw - 10, y);
    brush.set("2H", PAL.celadonLight, 0.28);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
}

