function drawLeftGlove() {
  // --- 5A. Cast shadow cross-hatching on tissue & across left/bottom/top borders ---
  // Left thumb & side shadow (crosses left celadon border at x ~ 280)
  drawShadowBed([
    [218, 520], [260, 438], [322, 468], [305, 645], [232, 595]
