      { u: 0.58, depth: 0.42, width: 0.07 }, // Head line flexion crease
      { u: 0.80, depth: 0.45, width: 0.07 }  // Heart line / metacarpal crease
    ],
    darkStart: 0.25, darkEnd: 0.35, seed: 201
  });

  // Hypothenar (ulnar/pinky side) reinforced leather palm patch
  let lPatchLeft = [[375, 705], [402, 608], [438, 525], [452, 438]];
  let lPatchRight = [[522, 722], [558, 625], [572, 525], [575, 445]];
  etchForm(lPatchLeft, lPatchRight, {
    uSteps: 40, vSteps: 9, archBulge: 12,
    lightCenter: -0.25, shadowSide: 1, baseTone: 0.28,
    pinches: [{ u: 0.52, depth: 0.35, width: 0.08 }],
    seed: 205
  });

  // Heavy double-stitched reinforcement seam curving across the Left Palm
  drawLeatherSeam(
    [[375, 705], [402, 608], [442, 528], [515, 518], [572, 528]],
    {
      stitches: 32, offset: 2.8, doubleRow: true,
      splits: [[0.38, 0.56]], splitWidth: 4.6
    }
  );

  // Deep anatomical palm flexion fissures (Heart line, Head line, Thenar line)
  let palmCreases = [
    [[318, 468], [395, 455], [478, 468], [562, 495]], // Distal palmar (heart) crease
    [[308, 522], [388, 528], [465, 558], [532, 598]], // Proximal palmar (head) crease
    [[355, 458], [385, 535], [372, 622], [335, 695]]  // Thenar (life) crease around thumb pad
  ];
  for (let pc of palmCreases) {
    let sh = pc.map(p => [p[0], p[1], 1.25]);
    let hi = pc.map(p => [p[0] - 1.8, p[1] - 1.8, 0.85]);
    brush.set("rotring", PAL.sepiaInk, 0.88);
    brush.spline(sh, 0.4);
    brush.set("drypoint", PAL.sepiaMid, 0.72);
    brush.spline(pc.map(p => [p[0] + 1.6, p[1] + 2.0, 0.9]), 0.4);
    brush.set("cpencil", PAL.highlightChalk, 0.68);
    brush.spline(hi, 0.4);
  }

  // --- 5C. Left Wing Thumb (Arching out on the left across the celadon tissue border!) ---
  // Note: Left thumb reaches x = 228, crossing the celadon tissue border at x ~ 282!
  let lThumbOuter = [[315, 685], [262, 615], [228, 535], [242, 462], [298, 412]];
  let lThumbInner = [[388, 628], [358, 565], [312, 515], [318, 472], [342, 442]];
  etchForm(lThumbOuter, lThumbInner, {
    uSteps: 44, vSteps: 11, archBulge: 16,
    lightCenter: -0.32, lightWidth: 0.36, shadowSide: 1, baseTone: 0.16,
    pinches: [
      { u: 0.45, depth: 0.42, width: 0.08 }, // MCP thumb joint
      { u: 0.74, depth: 0.48, width: 0.07 }  // IP thumb joint
    ],
    darkStart: 0.2, darkEnd: 0.35, seed: 215
  });

  // Heavy keystone wing-thumb seam & split thumb-crotch seam
  drawLeatherSeam(lThumbInner, {
    stitches: 28, offset: 2.8, doubleRow: true,
    splits: [[0.42, 0.62]], splitWidth: 4.8
  });
  drawLeatherSeam(
    [[242, 462], [278, 422], [318, 418], [342, 442]],
    { stitches: 16, offset: 2.2, doubleRow: false, splits: [[0.35, 0.65]], splitWidth: 3.8 }
  );

  // --- 5D. Four Curled Fingers of Left Glove (Rising from palm & curling forward toward viewer) ---
  // Each finger has:
  //   1) Proximal/Middle arched segment rising from the metacarpal line to the top bend
  //   2) Foreshortened Distal fingertip pad curled over the top, facing forward and casting a deep crescent shadow below it!

  let leftFingers = [
    {
      name: "index",
      // Shaft rising from palm to top knuckle bend
      shaftL: [[320, 428], [312, 345], [315, 268], [332, 232]],
      shaftR: [[384, 422], [380, 342], [382, 268], [375, 232]],
      // Curled distal fingertip pad facing viewer
      tipL: [[322, 250], [322, 292], [336, 332]],
      tipR: [[384, 248], [388, 290], [374, 330]],
      splitTip: [[0.25, 0.68]],
      seed: 221
    },
    {
      name: "middle", // Crosses top border of celadon tissue at y ~ 212!
      shaftL: [[384, 420], [384, 325], [388, 238], [405, 192]],
      shaftR: [[450, 422], [452, 328], [456, 240], [445, 194]],
      tipL: [[392, 212], [392, 258], [408, 304]],
      tipR: [[458, 214], [462, 260], [446, 304]],
      splitTip: [[0.35, 0.72]],
      seed: 222
    },
    {
      name: "ring",
      shaftL: [[450, 424], [456, 338], [464, 258], [482, 218]],
      shaftR: [[515, 434], [520, 346], [526, 266], [515, 224]],
      tipL: [[462, 242], [460, 286], [474, 328]],
      tipR: [[526, 248], [526, 292], [510, 330]],
      splitTip: [],
      seed: 223
    },
    {
      name: "pinky",
      shaftL: [[515, 436], [524, 368], [534, 306], [552, 272]],
      shaftR: [[574, 452], [582, 382], [590, 318], [580, 280]],
      tipL: [[528, 296], [522, 336], [534, 374]],
      tipR: [[586, 304], [582, 344], [566, 378]],
      splitTip: [[0.4, 0.7]],
      seed: 224
    }
  ];

  for (let fg of leftFingers) {
    // 1. Etch the rising proximal/middle shaft (deeply shadowed under the curled tip)
    etchForm(fg.shaftL, fg.shaftR, {
      uSteps: 34, vSteps: 9, archBulge: 12,
      lightCenter: -0.32, shadowSide: 1, baseTone: 0.26,
      pinches: [
        { u: 0.12, depth: 0.42, width: 0.07 }, // Base palmar-digital crease
        { u: 0.52, depth: 0.48, width: 0.08 }  // Deep shadowed PIP crease under curled tip
      ],
      darkStart: 0.35, darkEnd: 0.25, seed: fg.seed
    });

    // Side gusset (fourchette) seam along left & right edges of finger shaft
    drawLeatherSeam(fg.shaftL, { stitches: 16, offset: 2.0, doubleRow: false });
    drawLeatherSeam(fg.shaftR, { stitches: 16, offset: 2.0, doubleRow: false });

    // 2. Deep crescent occlusion shadow cast by the curled fingertip onto the middle phalanx
    let tBotL = fg.tipL[2], tBotR = fg.tipR[2];
    let sMidX = (tBotL[0] + tBotR[0]) / 2;
    let sMidY = (tBotL[1] + tBotR[1]) / 2 + 16;
    drawShadowBed([
      [tBotL[0] - 4, tBotL[1] - 4],
      [tBotR[0] + 4, tBotR[1] - 4],
      [tBotR[0] + 2, tBotR[1] + 18],
      [sMidX, sMidY + 8],
      [tBotL[0] - 2, tBotL[1] + 16]
    ], 18, 15, true);

    // 3. Etch the bulbous curled distal fingertip pad facing the viewer
    etchForm(fg.tipL, fg.tipR, {
      uSteps: 24, vSteps: 9, archBulge: 14,
      lightCenter: -0.3, shadowSide: 1, baseTone: 0.28,
