    // Wrap-around horseshoe seam around the curled fingertip pad (with split seams on index/middle/pinky)
    let tipSeam = [
      fg.tipL[0], fg.tipL[1], fg.tipL[2],
      [(fg.tipL[2][0] + fg.tipR[2][0]) / 2, (fg.tipL[2][1] + fg.tipR[2][1]) / 2 + 7],
      fg.tipR[2], fg.tipR[1], fg.tipR[0]
    ];
    drawLeatherSeam(tipSeam, {
      stitches: 18, offset: 2.2, doubleRow: false,
      splits: fg.splitTip, splitWidth: 4.2
    });

    // Dark stippled grease & oil saturation on every fingertip pad
    let tipCx = (fg.tipL[1][0] + fg.tipR[1][0]) / 2;
    let tipCy = (fg.tipL[1][1] + fg.tipR[1][1]) / 2;
    drawStipplePatch(tipCx, tipCy, 26, 30, 5, 290, PAL.sepiaInk, 0.9);
    drawCraquelure(tipCx, tipCy, 24, 26, 14, fg.seed);
