// =============================================================================
// SHADOW BED ETCHING HELPER
// =============================================================================

function drawShadowBed(polyPts, numLines, angleDeg, crossPass = true) {
  // Bounding box of polygon
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (let p of polyPts) {
    if (p[0] < minX) minX = p[0];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[1] > maxY) maxY = p[1];
  }
  let poly = new brush.Polygon(polyPts);
  let cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
  let diag = Math.hypot(maxX - minX, maxY - minY) * 0.75;

  function hatchPass(ang, steps, col, w) {
    let rad = ang * (Math.PI / 180);
    let dx = Math.cos(rad), dy = Math.sin(rad);
    let nx = -dy, ny = dx;

    brush.set("needle", col, w);
    for (let i = -steps; i <= steps; i++) {
      let off = (i / steps) * diag;
      let ox = cx + nx * off, oy = cy + ny * off;
      let lineSeg = {
        point1: { x: ox - dx * diag, y: oy - dy * diag },
        point2: { x: ox + dx * diag, y: oy + dy * diag }
      };
      let hits = poly.intersect(lineSeg);
      if (hits && hits.length >= 2) {
        hits.sort((a, b) => (a.x - b.x) * dx + (a.y - b.y) * dy);
        for (let k = 0; k + 1 < hits.length; k += 2) {
          let a = hits[k], b = hits[k + 1];
          let midX = (a.x + b.x) / 2 + random(-1.5, 1.5);
          let midY = (a.y + b.y) / 2 + random(-1.5, 1.5);
          brush.spline([[a.x, a.y, 0.3], [midX, midY, 1.05], [b.x, b.y, 0.3]], 0.2);
        }
      }
    }
  }

  hatchPass(angleDeg, numLines, PAL.sepiaInk, 0.62);
  if (crossPass) {
    hatchPass(angleDeg + 34, Math.floor(numLines * 0.8), PAL.sepiaMid, 0.54);
    hatchPass(angleDeg - 26, Math.floor(numLines * 0.55), PAL.sepiaInk, 0.58);
  }
}

