// Helper to draw closed polygon shapes safely via beginShape/vertex/endShape
function drawClosedPoly(pts, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Generates a slightly squarish, organic maki roll contour point
function rollPoint(roll, rFrac, angDeg) {
  let a = angDeg;
  let rotA = a - roll.rot;
  // Bamboo mat (makisu) subtle 4-sided compression + organic harmonics
  let sq = 1.0 + roll.squareness * cos(4 * rotA);
  let w1 = 1.0 + roll.wobble1 * sin(2 * rotA + roll.phase1) + roll.wobble2 * cos(3 * rotA + roll.phase2);
  let r = roll.R * rFrac * sq * w1;
  return [
    roll.cx + r * cos(a),
    roll.cy + r * sin(a)
  ];
}

// Generates a ring polygon around a roll
function getRollRingPoly(roll, rFrac, steps = 28, jitter = 0) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let rf = rFrac + (jitter > 0 ? random(-jitter, jitter) : 0);
    pts.push(rollPoint(roll, rf, a));
  }
  return pts;
}

// Generates a sector/chamber polygon inside the core [rIn..rOut, aStart..aEnd]
function getCoreChamberPoly(roll, rIn, rOut, aStart, aEnd, insetPx = 2.2) {
  let pts = [];
  let span = aEnd - aStart;
  let midA = (aStart + aEnd) * 0.5;
  // Push chamber slightly outward from center by insetPx to leave crisp seam
  let ox = insetPx * cos(midA);
  let oy = insetPx * sin(midA);

  let stepsArc = 10;
  // Outer arc
  for (let i = 0; i <= stepsArc; i++) {
    let t = i / stepsArc;
    let a = lerp(aStart + 2.5, aEnd - 2.5, t);
    let p = rollPoint(roll, rOut, a);
    pts.push([p[0] + ox * 0.3, p[1] + oy * 0.3]);
  }
  // Inner return
  if (rIn <= 0.02) {
    let pc = rollPoint(roll, 0.03, midA);
    pts.push([pc[0] + ox, pc[1] + oy]);
  } else {
    for (let i = stepsArc; i >= 0; i--) {
      let t = i / stepsArc;
      let a = lerp(aStart + 4, aEnd - 4, t);
      let p = rollPoint(roll, rIn, a);
      pts.push([p[0] + ox * 0.5, p[1] + oy * 0.5]);
    }
  }
  return pts;
}

// Shrinks/offsets a polygon toward its centroid for wet-into-wet inner pooling
function scalePolyAroundCenter(pts, scaleX, scaleY, shiftX = 0, shiftY = 0) {
  let cx = 0, cy = 0;
  for (let p of pts) {
    cx += p[0];
    cy += p[1];
  }
  cx /= pts.length;
  cy /= pts.length;
  let out = [];
  for (let p of pts) {
    out.push([
      cx + (p[0] - cx) * scaleX + shiftX,
      cy + (p[1] - cy) * scaleY + shiftY
    ]);
  }
  return out;
}

function buildMakiData() {
  let rolls = [];
  let cols = 5;
  let rows = 5;
  let startX = 246;
  let startY = 246;
  let spacingX = 177;
  let spacingY = 177;

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      // Break the grid in the bottom-right for the soy smear & wasabi dab
      if ((row === 3 && col === 4) || (row === 4 && col === 3) || (row === 4 && col === 4)) {
        continue;
      }

      let cx = startX + col * spacingX + random(-3.5, 3.5);
      let cy = startY + row * spacingY + random(-3.5, 3.5);
      let rot = random(0, 360);

      // The roll adjacent to the missing corner is slightly nudged out of the grid
      let isNudged = (row === 3 && col === 3);
      let isSoyStained = (row === 3 && col === 3) || (row === 4 && col === 2);
      if (isNudged) {
        cx -= 14;
        cy -= 18;
        rot += 22;
      }
      if (row === 4 && col === 2) {
        cx -= 5;
        cy += 6;
      }

      let R = random(83.5, 86.5);
      let roll = {
        col,
        row,
        cx,
        cy,
        R,
        rot,
        isNudged,
        isSoyStained,
        squareness: random(0.022, 0.042),
        wobble1: random(0.012, 0.026),
        wobble2: random(0.008, 0.018),
        phase1: random(0, 360),
        phase2: random(0, 360),
        seamAngle: random(0, 360),
        coreType: (row * 5 + col) % 3, // 3 subtle jewel cane variations
        rNoriOuter: 1.0,
        rNoriInner: 0.905,
        rCore: 0.565,
        rCenterJewel: random(0.135, 0.165)
      };

      // Precompute polygons
      roll.outerPoly = getRollRingPoly(roll, roll.rNoriOuter, 32, 0.004);
      roll.riceOuterPoly = getRollRingPoly(roll, roll.rNoriInner, 30, 0.005);
      roll.coreWrapPoly = getRollRingPoly(roll, roll.rCore + 0.025, 26, 0.005);
      roll.corePoly = getRollRingPoly(roll, roll.rCore, 26, 0.005);
      roll.centerJewelPoly = getRollRingPoly(roll, roll.rCenterJewel, 18, 0.004);

      // Three main core filling angles: Salmon coral, Avocado chartreuse, Tamago yellow
      let baseA = roll.rot;
      let a1 = baseA;
      let a2 = baseA + random(122, 134); // Salmon gets a generous ~128 deg wedge
      let a3 = a2 + random(112, 122);    // Avocado gets ~117 deg wedge
      let a4 = baseA + 360;              // Tamago gets ~115 deg wedge

      roll.angles = [a1, a2, a3, a4];
      roll.salmonPoly = getCoreChamberPoly(roll, roll.rCenterJewel + 0.015, roll.rCore - 0.018, a1, a2, 1.8);
      roll.avocadoPoly = getCoreChamberPoly(roll, roll.rCenterJewel + 0.015, roll.rCore - 0.018, a2, a3, 1.8);
      roll.tamagoPoly = getCoreChamberPoly(roll, roll.rCenterJewel + 0.015, roll.rCore - 0.018, a3, a4, 1.8);

      // Generate tightly packed individual rice grains in 3 concentric tiers
      roll.grains = [];
      let tiers = [
        { rFrac: 0.845, count: 22, len: 12.5 },
        { rFrac: 0.735, count: 18, len: 12.0 },
        { rFrac: 0.630, count: 14, len: 11.2 }
      ];

      for (let tIdx = 0; tIdx < tiers.length; tIdx++) {
        let tier = tiers[tIdx];
        let angleOffset = tIdx * 11 + random(0, 20);
        for (let i = 0; i < tier.count; i++) {
          let a = angleOffset + (i / tier.count) * 360 + random(-4.5, 4.5);
          let rf = tier.rFrac + random(-0.025, 0.025);
          let p = rollPoint(roll, rf, a);
          // Tangential orientation with organic tilt
          let grainAng = a + 90 + random(-28, 28);
          let halfL = (tier.len * random(0.85, 1.12)) * 0.5;
          let toneIdx = floor(random(3));
          // Check if near bottom-right edge of soy-stained roll
          let stained = false;
          if (roll.row === 3 && roll.col === 3 && a > 25 && a < 105 && tIdx === 0) stained = true;
          if (roll.row === 4 && roll.col === 2 && a > 330 || (roll.row === 4 && roll.col === 2 && a < 45 && tIdx === 0)) stained = true;

          roll.grains.push({
            x: p[0],
            y: p[1],
            ang: grainAng,
            halfL: halfL,
            toneIdx: toneIdx,
            stained: stained,
            hasSesame: random() < 0.07,
            sesameBlack: random() < 0.45
          });
        }
      }

      rolls.push(roll);
    }
  }
  return rolls;
}

