    [972, 856], [994, 848], [1014, 860], [1008, 882], [984, 888], [966, 874]
  ];
  let drop2 = [
    [728, 956], [748, 950], [758, 965], [745, 980], [725, 974]
  ];

  brush.noStroke();

  // Amber-sienna translucent outer soy bleed
  brush.fill("#8f4119", 145);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.65, 0.75);
  drawClosedPoly(soyOuter, 0.35);
  drawClosedPoly(drop1, 0.35);
  drawClosedPoly(drop2, 0.35);

  // Rich roasted mahogany mid-layer
  brush.fill("#4d1c0a", 190);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.55, 0.65);
  drawClosedPoly(soyMid, 0.35);
  drawClosedPoly(scalePolyAroundCenter(drop1, 0.7, 0.7), 0.35);

  // Deep espresso-black center pool
  brush.fill("#1c0803", 230);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.4, 0.5);
  drawClosedPoly(soyDeep, 0.35);
  brush.noFill();

  // Crisp meniscus rim of the soy sauce pool
  brush.set("rotring", "#381508", 0.75);
  drawClosedPoly(soyOuter, 0.35);
  drawClosedPoly(drop1, 0.35);
  drawClosedPoly(drop2, 0.35);

  // Warm amber internal rim glow
  brush.set("pen", "#b05825", 0.65);
  for (let i = 0; i < soyOuter.length - 1; i += 2) {
    let p1 = soyOuter[i];
    let p2 = soyOuter[i + 1];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // High-gloss liquid specular reflection arcs on the soy sauce smear
  brush.set("specular", "#fff7ed", 1.35);
  brush.spline([
    [702, 852, 0.3], [745, 822, 1.0], [782, 782, 0.8], [804, 744, 0.2]
  ], 0.4);
  brush.spline([
    [872, 792, 0.2], [932, 764, 1.0], [988, 752, 0.7], [1015, 766, 0.2]
  ], 0.4);
  brush.set("specular", "#ffffff", 0.95);
  brush.spline([
    [728, 898, 0.3], [778, 908, 0.9], [828, 882, 0.4]
  ], 0.4);
  brush.line(980, 858, 998, 856);
  brush.line(734, 958, 746, 956);
}

function drawWasabiDab() {
  let wx = 905;
  let wy = 962;
  let wR = 47;

  // Cast shadow of the wasabi mound on the black lacquer
  let shadowPts = [];
  for (let i = 0; i < 20; i++) {
    let a = (i / 20) * 360;
    let r = wR * (1.05 + 0.08 * sin(3 * a));
    shadowPts.push([wx + 9 + r * cos(a), wy + 11 + r * sin(a)]);
  }
  brush.noStroke();
  brush.wash("#050404", 230);
  drawClosedPoly(shadowPts, 0.3);

  // Base organic contour of the wasabi dab
  let basePts = [];
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * 360;
    let r = wR * (0.94 + 0.07 * cos(3 * a + 20) + 0.05 * sin(5 * a));
    basePts.push([wx + r * cos(a), wy + r * sin(a)]);
  }

  // Opaque underwash so the earthy sage-moss pops on the dark ground
  brush.wash("#465732", 250);
  drawClosedPoly(basePts, 0.3);
  brush.noWash();

  // Wet-into-wet watercolor layers on the wasabi mound
  brush.fill("#586e3e", 190);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.75, 0.65);
  drawClosedPoly(basePts, 0.3);

  let midPts = scalePolyAroundCenter(basePts, 0.74, 0.74, -5, -5);
  brush.fill("#7b9457", 185);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.7, 0.55);
  drawClosedPoly(midPts, 0.3);

  let topPts = scalePolyAroundCenter(basePts, 0.45, 0.45, -9, -8);
  brush.fill("#9eb576", 175);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.65, 0.5);
  drawClosedPoly(topPts, 0.3);
  brush.noFill();

  // Fibrous grated wasabi rhizome texture using custom paste brush & pencils
  for (let i = 0; i < 130; i++) {
    let a = random(0, 360);
    let d = pow(random(), 0.65) * (wR - 4);
    let px = wx + d * cos(a);
    let py = wy + d * sin(a);
    // Light source from upper-left (-135 deg)
    let isLit = (cos(a + 135) > -0.15) || (d < wR * 0.4);
    let col = isLit
      ? (random() < 0.4 ? "#bed194" : "#8ca665")
      : (random() < 0.5 ? "#354524" : "#4b5e35");
    brush.set("wasabi_paste", col, random(0.45, 0.95));
    let ang = a + 90 + random(-40, 40);
    let len = random(3, 7.5);
    brush.line(px, py, px + len * cos(ang), py + len * sin(ang));
  }

  // Sculpted central ridge & crisp botanical ink accents on the wasabi mound
  brush.set("rotring", "#243018", 0.65);
  drawClosedPoly(basePts, 0.3);

  // Molded crest line where chopsticks or knife shaped the paste
  brush.set("pen", "#2f3d20", 0.75);
  brush.spline([
    [wx - 26, wy + 12, 0.3],
    [wx - 8, wy - 4, 0.9],
    [wx + 6, wy - 14, 1.0],
    [wx + 24, wy - 22, 0.3]
  ], 0.35);

  brush.set("specular", "#dce8be", 0.85);
  brush.spline([
    [wx - 24, wy + 9, 0.3],
    [wx - 9, wy - 6, 1.0],
    [wx + 5, wy - 16, 0.8],
    [wx + 18, wy - 22, 0.2]
  ], 0.35);

  // Tiny moist highlights on the grated fibers
  brush.set("specular", "#f4f7eb", 0.65);
  for (let i = 0; i < 18; i++) {
    let a = random(-170, 20);
    let d = random(4, wR * 0.65);
    let px = wx + d * cos(a);
    let py = wy + d * sin(a);
    brush.line(px, py, px + 2.2, py - 1.5);
  }
}

function drawStrayGrainsAndSeeds() {
  // Loose rice grains & toasted sesame seeds near the broken grid corner
  let strayGrains = [
    { x: 670, y: 782, ang: 34, stained: true },
    { x: 682, y: 794, ang: 112, stained: false },
    { x: 838, y: 702, ang: -28, stained: false },
    { x: 752, y: 992, ang: 65, stained: false },
    { x: 1022, y: 895, ang: 18, stained: false }
  ];

  for (let g of strayGrains) {
    let dx = 5.5 * cos(g.ang);
    let dy = 5.5 * sin(g.ang);
    // Faint reflection on black lacquer directly below grain
    brush.set("rice_plump", "#2b2824", 0.9);
    brush.line(g.x - dx, g.y + 4 - dy, g.x + dx, g.y + 4 + dy);

    // Grain body
    let bodyCol = g.stained ? "#b87a4b" : "#ede7da";
    brush.set("rice_plump", bodyCol, 1.15);
    brush.line(g.x - dx, g.y - dy, g.x + dx, g.y + dy);

    // Crisp ink contour
    brush.set("rotring", "#241d18", 0.55);
    brush.circle(g.x, g.y, 4.8, 0.2);

    // Specular highlight
    brush.set("specular", "#ffffff", 0.8);
    brush.line(g.x - dx * 0.4, g.y - dy * 0.4 - 1, g.x + dx * 0.3, g.y + dy * 0.3 - 1);
  }

  // Scattered sesame seeds
  let seeds = [
    { x: 718, y: 748, a: 15 },
    { x: 862, y: 842, a: 75 },
    { x: 812, y: 965, a: -40 },
    { x: 952, y: 912, a: 30 },
    { x: 855, y: 725, a: 110 }
  ];
  for (let s of seeds) {
    brush.set("pen", "#d6b272", 1.3);
    brush.line(s.x - 2 * cos(s.a), s.y - 2 * sin(s.a), s.x + 2 * cos(s.a), s.y + 2 * sin(s.a));
    brush.set("rotring", "#291e14", 0.4);
    brush.circle(s.x, s.y, 2.2, 0.15);
  }
}

function draw() {
  if (!customReady) return;
  translate(-width / 2, -height / 2);

  // =========================================================================
  // PASS 1: BLACK URUSHI LACQUER TRAY & SUBTLE REFLECTIONS
  // =========================================================================
  drawLacquerTray();

  let rolls = buildMakiData();

  // Subtle ghostly reflections of the outer rolls on the glossy black lacquer
  brush.noStroke();
  for (let roll of rolls) {
    let reflPoly = scalePolyAroundCenter(roll.outerPoly, 1.03, 1.03, 7, 9);
    brush.wash("#050404", 235);
    drawClosedPoly(reflPoly, 0.25);
  }
  brush.noWash();

  // =========================================================================
  // PASS 2: OPAQUE UNDERPAINTING WASHES (BATCHED FOR DARK GROUND VIBRANCY)
  // =========================================================================
  brush.noStroke();

  // 2A. Seaweed black (Nori) outer ring base
  brush.wash("#121a15", 255);
  for (let roll of rolls) {
    drawClosedPoly(roll.outerPoly, 0.25);
  }

  // 2B. Warm parchment-ivory Rice ring base
  brush.wash("#ddd5c5", 255);
  for (let roll of rolls) {
    drawClosedPoly(roll.riceOuterPoly, 0.25);
  }

  // 2C. Inner Nori / dark botanical core boundary ring
  brush.wash("#141c17", 255);
  for (let roll of rolls) {
    drawClosedPoly(roll.coreWrapPoly, 0.25);
  }

  // 2D. Core chambers opaque base washes (Salmon, Avocado, Tamago, Center Jewel)
  brush.wash("#c7563e", 250);
  for (let roll of rolls) {
    drawClosedPoly(roll.salmonPoly, 0.2);
  }

  brush.wash("#7d9147", 250);
  for (let roll of rolls) {
    drawClosedPoly(roll.avocadoPoly, 0.2);
  }

  brush.wash("#d6a33e", 250);
  for (let roll of rolls) {
    drawClosedPoly(roll.tamagoPoly, 0.2);
  }

  // Center jewel cane base
  for (let roll of rolls) {
    let cCol = roll.coreType === 0 ? "#b84327" : (roll.coreType === 1 ? "#4b6130" : "#5c3d28");
    brush.wash(cCol, 250);
    drawClosedPoly(roll.centerJewelPoly, 0.25);
  }
  brush.noWash();

  // =========================================================================
  // PASS 3: SATURATED WET-INTO-WET WATERCOLOUR POOLS (BATCHED BY COLOR)
  // =========================================================================
  brush.noStroke();

  // 3A. Rice ring watercolor granulation (warm alabaster + subtle starchy stone shadow)
  brush.fill("#f2ece1", 175);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.75, 0.6);
  for (let roll of rolls) {
    drawClosedPoly(scalePolyAroundCenter(roll.riceOuterPoly, 0.96, 0.96), 0.25);
  }

  // Re-establish dark inner core wrap after rice wash
  brush.wash("#151f19", 255);
  for (let roll of rolls) {
    drawClosedPoly(roll.coreWrapPoly, 0.25);
  }
  brush.noWash();

  // 3B. Salmon Coral wet-into-wet watercolor pools (Terracotta Coral + Rich Burnt Rose)
  brush.fill("#d9694f", 175);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.78, 0.72);
  for (let roll of rolls) {
    drawClosedPoly(roll.salmonPoly, 0.22);
  }

  brush.fill("#9e3322", 155);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.82, 0.68);
  for (let roll of rolls) {
    let pool = scalePolyAroundCenter(roll.salmonPoly, 0.66, 0.66, 3, 2);
    drawClosedPoly(pool, 0.22);
  }

  // 3C. Avocado Chartreuse wet-into-wet pools (Buttery Pistachio + Deep Moss Rind)
  brush.fill("#b5c468", 180);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.75, 0.65);
  for (let roll of rolls) {
    drawClosedPoly(roll.avocadoPoly, 0.22);
  }

  brush.fill("#485c29", 170);
  brush.fillBleed(0.24, "in");
  brush.fillTexture(0.82, 0.75);
  for (let roll of rolls) {
    // Shift toward the outer arc of the avocado wedge (rind side)
    let midA = (roll.angles[1] + roll.angles[2]) * 0.5;
    let pool = scalePolyAroundCenter(
      roll.avocadoPoly,
      0.72,
      0.72,
      8 * cos(midA),
      8 * sin(midA)
    );
    drawClosedPoly(pool, 0.22);
  }

  // 3D. Tamago Yellow wet-into-wet pools (Luminous Saffron + Warm Amber Ochre)
  brush.fill("#edc868", 180);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.72, 0.65);
  for (let roll of rolls) {
    drawClosedPoly(roll.tamagoPoly, 0.22);
  }

  brush.fill("#b37824", 155);
  brush.fillBleed(0.20, "in");
  brush.fillTexture(0.78, 0.7);
  for (let roll of rolls) {
    let pool = scalePolyAroundCenter(roll.tamagoPoly, 0.64, 0.64, -3, 3);
    drawClosedPoly(pool, 0.22);
  }

  // 3E. Soy sauce stain bleeding onto the two rolls bordering the soy smear
  brush.fill("#7a3312", 155);
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.75, 0.7);
  for (let roll of rolls) {
    if (roll.isSoyStained) {
      let stainPts = [];
      let aStart = (roll.row === 3 && roll.col === 3) ? 25 : -30;
      let aEnd = (roll.row === 3 && roll.col === 3) ? 105 : 50;
      for (let a = aStart; a <= aEnd; a += 12) {
        stainPts.push(rollPoint(roll, 0.95, a));
      }
      for (let a = aEnd; a >= aStart; a -= 12) {
        stainPts.push(rollPoint(roll, 0.68, a));
      }
      drawClosedPoly(stainPts, 0.3);
    }
  }
  brush.noFill();

  // =========================================================================
  // PASS 4: SOY SAUCE SMEAR & SINGLE WASABI DAB IN THE OPEN GRID CORNER
  // =========================================================================
  drawSoyAndWasabiUnderlay();
  drawWasabiDab();
  drawStrayGrainsAndSeeds();

  // =========================================================================
  // PASS 5: HYPERREALISTIC RICE GRAINS, CORE TEXTURES & CLOISONNÉ PEN LINES
  // =========================================================================
  let riceTones = ["#f5f0e6", "#ebe4d5", "#e0d7c5"];

  for (let roll of rolls) {
    // -----------------------------------------------------------------------
    // 5A. Seaweed Black (Nori) Outer Ring Texture & Seam
    // -----------------------------------------------------------------------
    // Radial crinkles & roasted olive-black sheen along the nori ring
    for (let i = 0; i < 36; i++) {
      let a = (i / 36) * 360 + random(-3, 3);
      let pOut = rollPoint(roll, 0.995, a);
      let pIn = rollPoint(roll, 0.905, a + random(-2, 2));
      let col = i % 3 === 0 ? "#2b382e" : "#0a0f0c";
      brush.set("pen", col, random(0.55, 0.95));
      brush.line(pOut[0], pOut[1], pIn[0], pIn[1]);
    }

    // Nori overlap seam on the exterior of the slice
    let pSeam1 = rollPoint(roll, 1.02, roll.seamAngle);
    let pSeam2 = rollPoint(roll, 0.89, roll.seamAngle + 8);
    brush.set("rotring", "#060807", 1.15);
    brush.line(pSeam1[0], pSeam1[1], pSeam2[0], pSeam2[1]);

    // -----------------------------------------------------------------------
    // 5B. Packed Individual Rice Grains with Crisp Ink Contours & Highlights
    // -----------------------------------------------------------------------
    // Subtle starchy shadow crevices between grains first
    for (let g of roll.grains) {
      let dx = g.halfL * cos(g.ang);
      let dy = g.halfL * sin(g.ang);
      let shCol = g.stained ? "#59230b" : "#9e9280";
      brush.set("pen", shCol, 1.1);
      brush.line(g.x - dx * 0.8 + 1.2, g.y - dy * 0.8 + 1.5, g.x + dx * 0.8 + 1.2, g.y + dy * 0.8 + 1.5);
    }

    // Plump oval rice grain bodies
    for (let g of roll.grains) {
      let dx = g.halfL * cos(g.ang);
      let dy = g.halfL * sin(g.ang);
      let col = g.stained ? "#b36c3e" : riceTones[g.toneIdx];
      brush.set("rice_plump", col, random(0.95, 1.22));
      brush.line(g.x - dx, g.y - dy, g.x + dx, g.y + dy);
    }

    // Crisp fine ink boundary around each individual rice grain
    for (let g of roll.grains) {
      let dx = g.halfL * cos(g.ang);
      let dy = g.halfL * sin(g.ang);
      let nx = -sin(g.ang) * 3.1;
      let ny = cos(g.ang) * 3.1;
      let inkCol = g.stained ? "#2e1206" : "#362e28";
      brush.set("rotring", inkCol, 0.45);
      // Curved top and bottom arcs of each grain
      brush.spline([
        [g.x - dx * 1.05, g.y - dy * 1.05, 0.3],
        [g.x + nx, g.y + ny, 0.85],
        [g.x + dx * 1.05, g.y + dy * 1.05, 0.3]
      ], 0.45);
      brush.spline([
        [g.x - dx * 1.05, g.y - dy * 1.05, 0.3],
        [g.x - nx, g.y - ny, 0.85],
        [g.x + dx * 1.05, g.y + dy * 1.05, 0.3]
      ], 0.45);
    }

    // Tiny white specular highlights on rice grains + occasional sesame seeds
    for (let g of roll.grains) {
      let dx = g.halfL * 0.45 * cos(g.ang);
      let dy = g.halfL * 0.45 * sin(g.ang);
      let hiCol = g.stained ? "#f2cfb3" : "#ffffff";
      brush.set("specular", hiCol, random(0.65, 1.05));
      brush.line(g.x - dx - 0.6, g.y - dy - 0.8, g.x + dx - 0.6, g.y + dy - 0.8);

      if (g.hasSesame) {
        let sCol = g.sesameBlack ? "#1a1715" : "#d4ae6a";
        brush.set("pen", sCol, 1.25);
        brush.line(g.x - 1.5, g.y + 2.2, g.x + 1.8, g.y + 3.2);
      }
    }

    // -----------------------------------------------------------------------
    // 5C. Inner Core Fillings: Salmon, Avocado, Tamago & Center Jewel Details
    // -----------------------------------------------------------------------
    let a1 = roll.angles[0];
    let a2 = roll.angles[1];
    let a3 = roll.angles[2];
    let a4 = roll.angles[3];

    // 1. SALMON CORAL: white/cream connective fat marbling striations & wet glaze
    let salMidA = (a1 + a2) * 0.5;
    let salSpan = a2 - a1;
    for (let s = 0; s < 5; s++) {
      let t = (s + 0.7) / 5.5;
      let sa = lerp(a1 + 10, a2 - 10, t);
      let pIn = rollPoint(roll, roll.rCenterJewel + 0.04, sa - 8);
      let pMid = rollPoint(roll, (roll.rCenterJewel + roll.rCore) * 0.52, sa + 4);
      let pOut = rollPoint(roll, roll.rCore - 0.04, sa + 14);

      // Soft warm shadow along marbling line
      brush.set("pen", "#942d1e", 0.65);
      brush.spline([
        [pIn[0] + 1, pIn[1] + 1, 0.4],
        [pMid[0] + 1, pMid[1] + 1, 0.9],
        [pOut[0] + 1, pOut[1] + 1, 0.4]
      ], 0.35);

      // Creamy white fat striation
      brush.set("pen", "#f7ece0", 0.85);
      brush.spline([
        [pIn[0], pIn[1], 0.3],
        [pMid[0], pMid[1], 1.0],
        [pOut[0], pOut[1], 0.3]
      ], 0.35);
    }

    // Glistening cut-face highlight on the salmon
    let pSalHi1 = rollPoint(roll, 0.36, salMidA - salSpan * 0.22);
    let pSalHi2 = rollPoint(roll, 0.40, salMidA + salSpan * 0.18);
    brush.set("glaze", "#ffffff", 0.7);
    brush.line(pSalHi1[0], pSalHi1[1], pSalHi2[0], pSalHi2[1]);
    brush.set("specular", "#ffffff", 0.85);
    brush.line(pSalHi1[0], pSalHi1[1], lerp(pSalHi1[0], pSalHi2[0], 0.55), lerp(pSalHi1[1], pSalHi2[1], 0.55));

    // 2. AVOCADO CHARTREUSE: creamy radial shading, vascular pores & buttery sheen
    let avoMidA = (a2 + a3) * 0.5;
    // Inner buttery cream-chartreuse highlight near the center
    for (let i = 0; i < 6; i++) {
      let aa = lerp(a2 + 12, a3 - 12, i / 5);
      let p1 = rollPoint(roll, roll.rCenterJewel + 0.05, aa);
      let p2 = rollPoint(roll, 0.36, aa);
      brush.set("cpencil", "#dce396", 0.85);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
    // Fine dark olive vascular dots along the outer green edge of the avocado
    brush.set("rotring", "#33421b", 0.55);
    for (let i = 0; i < 9; i++) {
      let aa = lerp(a2 + 10, a3 - 10, (i + 0.5) / 9) + random(-3, 3);
      let pr = rollPoint(roll, random(0.44, 0.51), aa);
      brush.line(pr[0], pr[1], pr[0] + 0.8, pr[1] + 0.8);
    }
    // Moist specular sheen on avocado
    let pAvoHi1 = rollPoint(roll, 0.34, avoMidA - 18);
    let pAvoHi2 = rollPoint(roll, 0.35, avoMidA + 18);
    brush.set("specular", "#f7fae6", 0.75);
    brush.line(pAvoHi1[0], pAvoHi1[1], pAvoHi2[0], pAvoHi2[1]);

    // 3. TAMAGO YELLOW: rolled omelet laminations, caramelized lines & air pores
    for (let l = 1; l <= 3; l++) {
      let rf = lerp(roll.rCenterJewel + 0.07, roll.rCore - 0.06, l / 4);
      let layerPts = [];
      for (let s = 0; s <= 6; s++) {
        let ta = lerp(a3 + 9, a4 - 9, s / 6);
        let p = rollPoint(roll, rf, ta);
        layerPts.push([p[0], p[1], 0.8]);
      }
      brush.set("rotring", "#7a491c", 0.55);
      brush.spline(layerPts, 0.3);
    }
    // Tiny aerated omelet pores & bright wet highlight
    let tamMidA = (a3 + a4) * 0.5;
    brush.set("rotring", "#8c5622", 0.45);
    for (let i = 0; i < 6; i++) {
      let ta = lerp(a3 + 14, a4 - 14, random());
      let tr = random(roll.rCenterJewel + 0.06, roll.rCore - 0.06);
      let pt = rollPoint(roll, tr, ta);
      brush.line(pt[0], pt[1], pt[0] + 1.2, pt[1] - 0.6);
    }
    let pTamHi1 = rollPoint(roll, 0.35, tamMidA - 16);
    let pTamHi2 = rollPoint(roll, 0.37, tamMidA + 16);
    brush.set("specular", "#fff9e6", 0.85);
    brush.line(pTamHi1[0], pTamHi1[1], pTamHi2[0], pTamHi2[1]);

    // 4. CENTER JEWEL CANE (Ikura roe cluster, Cucumber seed jewel, or Gobo spiral)
    let pc = rollPoint(roll, 0, 0);
    if (roll.coreType === 0) {
      // Glistening translucent Ikura / Tobiko roe spheres in the very center
      let roeOffsets = [[0, 0, 5.5], [-4.5, -3.5, 4.2], [4.5, -3.0, 4.2], [0.5, 4.8, 4.2]];
      for (let ro of roeOffsets) {
        let rx = pc[0] + ro[0];
        let ry = pc[1] + ro[1];
        let rr = ro[2];
        brush.set("pen", "#e85d38", 1.2);
        brush.circle(rx, ry, rr * 0.7, 0.1);
        // Dark amber nucleus eye
        brush.set("rotring", "#6e1808", 0.9);
        brush.circle(rx + 0.5, ry + 0.5, rr * 0.25, 0.05);
        // Crisp ink outline
        brush.set("rotring", "#24120c", 0.5);
        brush.circle(rx, ry, rr, 0.1);
        // Bright white crescent highlight
        brush.set("specular", "#ffffff", 0.85);
        brush.line(rx - rr * 0.45, ry - rr * 0.45, rx + rr * 0.1, ry - rr * 0.55);
      }
    } else if (roll.coreType === 1) {
      // Concentric cucumber jewel core
      brush.set("pen", "#c8d6a3", 1.3);
      brush.circle(pc[0], pc[1], roll.R * roll.rCenterJewel * 0.55, 0.15);
      brush.set("rotring", "#2a381b", 0.55);
      brush.circle(pc[0], pc[1], roll.R * roll.rCenterJewel * 0.65, 0.15);
      brush.set("specular", "#ffffff", 0.75);
      brush.line(pc[0] - 3, pc[1] - 3, pc[0] + 2, pc[1] - 4);
    } else {
      // Earthy gobo (burdock) & black sesame jewel center
      brush.set("pen", "#b58b63", 1.2);
      brush.circle(pc[0], pc[1], roll.R * roll.rCenterJewel * 0.55, 0.15);
      brush.set("rotring", "#291c12", 0.6);
      brush.circle(pc[0], pc[1], roll.R * roll.rCenterJewel * 0.3, 0.1);
      brush.set("specular", "#fff5e8", 0.7);
      brush.line(pc[0] - 2.5, pc[1] - 2.5, pc[0] + 2, pc[1] - 2.5);
    }

    // -----------------------------------------------------------------------
    // 5D. CRISP PEN BOUNDARIES (POLISHED GLASS CANE / CLOISONNÉ OUTLINES)
    // -----------------------------------------------------------------------
    // Outer Nori perimeter & inner rice-nori boundary
    brush.set("rotring", "#070908", 0.95);
    drawClosedPoly(roll.outerPoly, 0.25);

    brush.set("rotring", "#121714", 0.82);
    drawClosedPoly(roll.riceOuterPoly, 0.25);

    // Inner core nori wrap boundary
    brush.set("rotring", "#0c120e", 0.95);
    drawClosedPoly(roll.coreWrapPoly, 0.25);
    drawClosedPoly(roll.corePoly, 0.25);

    // Crisp pen boundaries around each colored core chamber
    brush.set("rotring", "#1a1310", 0.82);
    drawClosedPoly(roll.salmonPoly, 0.2);
    drawClosedPoly(roll.avocadoPoly, 0.2);
    drawClosedPoly(roll.tamagoPoly, 0.2);
    drawClosedPoly(roll.centerJewelPoly, 0.25);

    // Delicate wet knife-cut sheen across the entire slice face (diagonal 35 deg)
    let pGlide1 = rollPoint(roll, 0.48, -145);
    let pGlide2 = rollPoint(roll, 0.48, -55);
    brush.set("specular", "#ffffff", 0.55);
    brush.line(pGlide1[0], pGlide1[1], pGlide2[0], pGlide2[1]);

    // Subtle moist rim highlight along the upper-left nori cut edge
    for (let a = -165; a <= -75; a += 18) {
      let pn1 = rollPoint(roll, 0.955, a);
      let pn2 = rollPoint(roll, 0.955, a + 10);
      brush.set("specular", "#7c8c80", 0.55);
      brush.line(pn1[0], pn1[1], pn2[0], pn2[1]);
    }
  }

  noLoop();
}

// Hyperrealistic Sequential Pineapple Cross-Sections (Ananas comosus)
