// =============================================================================
// ANATOMICAL GEOMETRY ENGINE
// =============================================================================

function buildAllSliceGeometry() {
  // 9 sequential transverse planes from basal peduncle (z=0.07) to apical crown base (z=0.95)
  const specs = [
    { idx: 0, z: 0.07, outerR: 76,  coreR: 30, sectors: 13, crown: 0.00, woody: 0.85 },
    { idx: 1, z: 0.18, outerR: 105, coreR: 28, sectors: 13, crown: 0.00, woody: 0.35 },
    { idx: 2, z: 0.29, outerR: 124, coreR: 27, sectors: 14, crown: 0.00, woody: 0.10 },
    { idx: 3, z: 0.40, outerR: 136, coreR: 27, sectors: 15, crown: 0.00, woody: 0.00 },
    { idx: 4, z: 0.51, outerR: 142, coreR: 28, sectors: 15, crown: 0.00, woody: 0.00 },
    { idx: 5, z: 0.62, outerR: 134, coreR: 26, sectors: 15, crown: 0.00, woody: 0.00 },
    { idx: 6, z: 0.74, outerR: 118, coreR: 25, sectors: 14, crown: 0.05, woody: 0.15 },
    { idx: 7, z: 0.85, outerR: 95,  coreR: 24, sectors: 13, crown: 0.38, woody: 0.25 },
    { idx: 8, z: 0.95, outerR: 74,  coreR: 21, sectors: 13, crown: 1.00, woody: 0.40 }
  ];

  const gridStart = 105;
  const cellSize = 330;

  for (let i = 0; i < specs.length; i++) {
    let sp = specs[i];
    let col = i % 3;
    let row = floor(i / 3);
    let cx = gridStart + cellSize * 0.5 + col * cellSize;
    let cy = gridStart + cellSize * 0.5 + row * cellSize;

    // Slight organic eccentricity per slice
    let rotOffset = i * 27.69 + 14.0;
    let ellipX = 1.0 + 0.018 * cos(i * 53);
    let ellipY = 1.0 + 0.018 * sin(i * 53);

    let sectorList = [];
    let dAng = 360 / sp.sectors;

    for (let s = 0; s < sp.sectors; s++) {
      let a0 = s * dAng + rotOffset;
      let a1 = (s + 1) * dAng + rotOffset;
      let aMid = (a0 + a1) * 0.5;

      // Fibonacci helical phase: determines how deeply the scan plane cuts each spiral eye
      // Adjacent sectors step by 5 in Fibonacci parastichy order around the perimeter
      let fibStep = (s * 5) % sp.sectors;
      let phase = (fibStep / sp.sectors + sp.z * 2.65) % 1.0;
      // eyeDepth: 1.0 when cutting directly through the center of the blossom cup, 0.0 on the cortical bridge
      let eyeDepth = pow(max(0, sin(phase * 180)), 1.35);

      let nVal = noise(i * 3.1 + s * 0.7, sp.z * 4.0);
      let rMod = 1.0 + (nVal - 0.5) * 0.055;

      sectorList.push({
        sIndex: s,
        a0: a0,
        a1: a1,
        aMid: aMid,
        dAng: dAng,
        phase: phase,
        eyeDepth: eyeDepth,
        rMod: rMod
      });
    }

    // Build high-resolution perimeter contour and sub-contours
    let haloPts = [];
    let outerPts = [];
    let fleshPts = [];
    let corePts = [];

    let stepsPerSector = 12;
    for (let s = 0; s < sp.sectors; s++) {
      let sec = sectorList[s];
      for (let k = 0; k < stepsPerSector; k++) {
        let t = k / stepsPerSector; // 0..1 across sector
        let ang = lerp(sec.a0, sec.a1, t);
        let radInfo = evaluatePineappleRadius(t, sec, sp, ang);

        let rx = cos(ang) * ellipX;
        let ry = sin(ang) * ellipY;

        outerPts.push([cx + rx * radInfo.rOuter, cy + ry * radInfo.rOuter]);
        haloPts.push([cx + rx * (radInfo.rOuter + 11), cy + ry * (radInfo.rOuter + 11)]);
        fleshPts.push([cx + rx * radInfo.rFlesh, cy + ry * radInfo.rFlesh]);
      }
    }

    let coreSteps = 48;
    for (let k = 0; k < coreSteps; k++) {
      let ang = (k / coreSteps) * 360 + rotOffset;
      let cNoise = 1.0 + (noise(i * 4.2 + cos(ang) * 1.2, sin(ang) * 1.2) - 0.5) * 0.06;
      let cr = sp.coreR * cNoise;
      corePts.push([
        cx + cos(ang) * ellipX * cr,
        cy + sin(ang) * ellipY * cr
      ]);
    }

    slicesData.push({
      ...sp,
      col,
      row,
      cx,
      cy,
      ellipX,
      ellipY,
      rotOffset,
      sectorsData: sectorList,
      haloPts,
      outerPts,
      fleshPts,
      corePts
    });
  }
}

// Evaluates exact anatomical outer rind & inner cortex radius at normalized sector angle t in [0,1]
function evaluatePineappleRadius(t, sec, sp, ang) {
  let baseR = sp.outerR * sec.rMod;
  let ed = sec.eyeDepth;

  // Sinus cleft at boundaries t=0 and t=1 between adjacent fruitlets
  let edgeDist = min(t, 1.0 - t) * 2.0; // 0 at boundary, 1 at center
  let lobeArch = pow( max(0.001, sin(t * 180)), 0.55 );

  let rOuter = baseR;
  let rFlesh = baseR * 0.84;

  if (sp.crown >= 0.95) {
    // Slice 9: Apical crown rosette — imbricated foliar bract tips
    let imbrication = (t - 0.5) * 5.5;
    rOuter = baseR * (0.91 + 0.11 * lobeArch) + imbrication;
    rFlesh = baseR * 0.52;
  } else {
    // Standard syncarp fruit body with spiral blossom cups (W-shaped craters when eyeDepth is high)
    let shoulder = baseR * (0.89 + 0.13 * lobeArch);

    // Deep blossom cup invagination around t in [0.22, 0.78]
    let cupProfile = 0;
    let floralTongue = 0;
    if (t > 0.18 && t < 0.82) {
      let u = (t - 0.5) / 0.32; // -1..1
      cupProfile = exp(-u * u * 3.2) * (5.5 + 11.5 * ed) * (1.0 - sp.woody * 0.45);
      // Central style / floral remnant tongue inside the middle of the blossom cup
      let u2 = (t - 0.5) / 0.09;
      floralTongue = exp(-u2 * u2 * 4.5) * (2.5 + 6.2 * ed) * (1.0 - sp.woody * 0.5);
    }

    rOuter = shoulder - cupProfile + floralTongue;
    // If transitioning to crown (Slice 8), sharpen bract shoulders
    if (sp.crown > 0) {
      rOuter += sp.crown * (t - 0.5) * 4.0;
    }

    // Sub-epidermal translucent flesh boundary sits inward from the deepest eye clefts
    rFlesh = baseR * (0.79 - 0.06 * ed * exp(-pow((t - 0.5) / 0.35, 2)));
  }

  return { rOuter, rFlesh };
}

// =============================================================================
// PASS 1: LIGHTBOX GROUND & SURFACE TEXTURE
// =============================================================================

function renderLightboxGround() {
  brush.noStroke();
  brush.noHatch();

  // Deep velvety charcoal border washes to give subtle central lightbox luminance
  brush.wash(PALETTE.bgUmber, 140);
  brush.rect(30, 30, 1140, 1140, "corner");

  // Subtle dark vignette bands along edges
  brush.wash("#060505", 170);
  brush.rect(0, 0, 1200, 62, "corner");
  brush.rect(0, 1138, 1200, 62, "corner");
  brush.rect(0, 62, 62, 1076, "corner");
  brush.rect(1138, 62, 62, 1076, "corner");

  brush.noWash();

  // Compressed charcoal paper grain across the lightbox
  brush.set("charcoal", "#161412", 1.1);
  for (let i = 0; i < 160; i++) {
    let x1 = random(40, 1160);
    let y1 = random(40, 1160);
    let len = random(60, 220);
    let ang = random(-8, 8) + (i % 2 === 0 ? 0 : 90);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }

  // Ultra-faint chalk dust specks on the glass lightbox
  brush.set("spray", PALETTE.greyShadow, 0.55);
  for (let i = 0; i < 45; i++) {
    let sx = random(75, 1125);
    let sy = random(75, 1125);
    brush.line(sx, sy, sx + random(15, 45), sy + random(-15, 15));
  }
}

// =============================================================================
// PASS 2: BATCHED WATERCOLOR FILLS & WASHES (PERFORMANCE-OPTIMIZED)
// =============================================================================

function renderBatchedSliceFills() {
  brush.noStroke();
  brush.noHatch();

  // BATCH A: Backlit outer halation glow around every slice
  brush.fill(PALETTE.greyShadow, 36);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.25);
  for (let i = 0; i < slicesData.length; i++) {
    drawPolyShape(slicesData[i].haloPts, 0.25);
  }

  // BATCH B: Translucent mid-grey syncarp flesh base
  brush.fill(PALETTE.greyMid, 62);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.68, 0.42);
  for (let i = 0; i < slicesData.length; i++) {
    drawPolyShape(slicesData[i].fleshPts, 0.2);
  }

  // BATCH C: Luminous wet mesocarp cushions inside fruitlet sectors (Slices 0..7)
  brush.fill(PALETTE.chalkWarm, 46);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.72, 0.45);
  for (let i = 0; i < slicesData.length; i++) {
    let sl = slicesData[i];
    if (sl.crown >= 0.95) continue;
    for (let s = 0; s < sl.sectorsData.length; s++) {
      let sec = sl.sectorsData[s];
      let rIn = sl.coreR * 1.12;
      let rOut = sl.outerR * 0.52 * sec.rMod;
      let aL = sec.a0 + sec.dAng * 0.16;
      let aR = sec.a1 - sec.dAng * 0.16;
      let aM = sec.aMid;
      let cushionPts = [
        [sl.cx + cos(aL) * sl.ellipX * rIn, sl.cy + sin(aL) * sl.ellipY * rIn],
        [sl.cx + cos(aM) * sl.ellipX * (rIn * 0.96), sl.cy + sin(aM) * sl.ellipY * (rIn * 0.96)],
        [sl.cx + cos(aR) * sl.ellipX * rIn, sl.cy + sin(aR) * sl.ellipY * rIn],
        [sl.cx + cos(aR) * sl.ellipX * rOut, sl.cy + sin(aR) * sl.ellipY * rOut],
        [sl.cx + cos(aM) * sl.ellipX * (rOut * 1.08), sl.cy + sin(aM) * sl.ellipY * (rOut * 1.08)],
        [sl.cx + cos(aL) * sl.ellipX * rOut, sl.cy + sin(aL) * sl.ellipY * rOut]
      ];
      drawPolyShape(cushionPts, 0.3);
    }
  }

  // BATCH D: Central fibrous stele core base tone
  brush.fill(PALETTE.charcoalSoft, 85);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.6, 0.5);
  for (let i = 0; i < slicesData.length; i++) {
    drawPolyShape(slicesData[i].corePts, 0.2);
  }

  brush.noFill();

  // BATCH E: Fast opaque dark charcoal washes for ovarian locules & deep eye cavities
  brush.wash(PALETTE.charcoalDark, 210);
  for (let i = 0; i < slicesData.length; i++) {
    let sl = slicesData[i];
    if (sl.crown >= 0.95) continue;

    for (let s = 0; s < sl.sectorsData.length; s++) {
      let sec = sl.sectorsData[s];
      // Twin ovarian locule cavities per fruitlet sector
      let rLocBase = lerp(sl.coreR, sl.outerR * sec.rMod, 0.56);
      let locLen = (sl.outerR - sl.coreR) * (0.15 - 0.04 * sl.woody);
      let locHalfW = sec.dAng * 0.12;

      for (let side = -1; side <= 1; side += 2) {
        let aCenter = sec.aMid + side * sec.dAng * 0.18;
        let locPts = buildLoculePolygon(
          sl.cx, sl.cy, sl.ellipX, sl.ellipY,
          aCenter, locHalfW, rLocBase - locLen * 0.5, rLocBase + locLen * 0.5
        );
        drawPolyShape(locPts, 0.25);
      }
    }
  }
  brush.noWash();
}

function buildLoculePolygon(cx, cy, ex, ey, aCenter, halfAng, rInner, rOuter) {
  let rMid = (rInner + rOuter) * 0.5;
  return [
    [cx + cos(aCenter) * ex * rInner, cy + sin(aCenter) * ey * rInner],
    [cx + cos(aCenter + halfAng) * ex * rMid, cy + sin(aCenter + halfAng) * ey * rMid],
    [cx + cos(aCenter) * ex * rOuter, cy + sin(aCenter) * ey * rOuter],
    [cx + cos(aCenter - halfAng) * ex * rMid, cy + sin(aCenter - halfAng) * ey * rMid]
  ];
}

function drawPolyShape(pts, curv) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

// =============================================================================
// PASS 3: HYPERREALISTIC ANATOMICAL RENDERING PER SLICE
// =============================================================================

function renderSliceAnatomy(sl) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // 1. Backlit outer halo dust & peripheral rim glow
  renderBacklitPerimeter(sl);

  if (sl.crown >= 0.95) {
    // Slice 9: Apical Crown Base (concentric Fibonacci spiral of leaf-bract crescents)
    renderCrownRosetteSlice(sl);
  } else {
    // Slices 1..8: Syncarp Flesh, Radial Vascular Traces, Septa, Locules & Spiral Eyes
    renderSyncarpFleshAndFibers(sl);
    renderLoculesAndSepta(sl);
    renderSpiralRindEyes(sl);
    if (sl.crown > 0.1) {
      // Slice 8 transition: outer ring of overlapping crown bracts
      renderOuterCrownTransition(sl);
    }
  }

  // 5. Central Fibrous Core (Stele, Pericycle Ring, Vascular Bundles & Medullary Pith)
  renderCentralCore(sl);
}

function renderBacklitPerimeter(sl) {
  let pts = sl.outerPts;
  let n = pts.length;

  // Soft white-chalk outer glow hugging the scalloped epidermis
  brush.set("chalk_soft", PALETTE.chalkWarm, 1.35);
  for (let i = 0; i < n; i += 2) {
    let p0 = pts[i];
    let p1 = pts[(i + 2) % n];
    let dx = p0[0] - sl.cx;
    let dy = p0[1] - sl.cy;
    let d = sqrt(dx * dx + dy * dy) || 1;
    let ox = (dx / d) * 2.5;
    let oy = (dy / d) * 2.5;
    brush.line(p0[0] + ox, p0[1] + oy, p1[0] + ox, p1[1] + oy);
  }

  // Crisp backlit epidermal edge in luminous ivory chalk
  brush.set("chalk_fine", PALETTE.chalkIvory, 0.95);
  for (let i = 0; i < n; i++) {
    let p0 = pts[i];
    let p1 = pts[(i + 1) % n];
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Pure white chalk specular rim highlights on protruding bract tips
  brush.set("diag_needle", PALETTE.chalkPure, 0.9);
  for (let i = 0; i < n; i += 3) {
    let p0 = pts[i];
    let p1 = pts[(i + 1) % n];
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
}

function renderSyncarpFleshAndFibers(sl) {
  let numS = sl.sectorsData.length;

  for (let s = 0; s < numS; s++) {
    let sec = sl.sectorsData[s];
    let rStart = sl.coreR * 1.04;
    let rEnd = sl.outerR * sec.rMod * 0.78;
    let rLocMid = lerp(sl.coreR, sl.outerR * sec.rMod, 0.56);

    // A. Radial parenchyma striae & vascular fibers that part smoothly around the locule chambers
    let numFibers = 15;
    for (let f = 0; f < numFibers; f++) {
      let u = (f + 0.5) / numFibers; // 0..1 across sector
      let baseAng = lerp(sec.a0, sec.a1, u);

      // Deflect angle around the twin locules at u ~ 0.32 and u ~ 0.68
      let deflect = 0;
      if (u < 0.5) {
        deflect = (u < 0.32 ? -1 : 1) * exp(-pow((u - 0.32) / 0.14, 2)) * sec.dAng * 0.085;
      } else {
        deflect = (u < 0.68 ? -1 : 1) * exp(-pow((u - 0.68) / 0.14, 2)) * sec.dAng * 0.085;
      }

      let isMainBundle = (f === 4 || f === 7 || f === 10);
      if (isMainBundle) {
        brush.set("chalk_fine", PALETTE.chalkBright, 0.75);
      } else if (f % 2 === 0) {
        brush.set("chalk_soft", PALETTE.greyLuminous, 0.65);
      } else {
        brush.set("cpencil", PALETTE.greyMid, 0.45);
      }

      let segs = 5;
      let prevX = sl.cx + cos(baseAng) * sl.ellipX * rStart;
      let prevY = sl.cy + sin(baseAng) * sl.ellipY * rStart;

      for (let k = 1; k <= segs; k++) {
        let frac = k / segs;
        let rCur = lerp(rStart, rEnd, frac);
        // Maximum deflection near the locule ring (frac ~ 0.55)
        let bell = sin(frac * 180);
        let curAng = baseAng + deflect * bell + (noise(sl.idx * 5 + s, f * 0.4, frac * 2) - 0.5) * 1.4;

        let nx = sl.cx + cos(curAng) * sl.ellipX * rCur;
        let ny = sl.cy + sin(curAng) * sl.ellipY * rCur;

        // Skip drawing directly through the dark interior of the locule cavities
        let inLoculeR = (rCur > rLocMid - 10 && rCur < rLocMid + 10);
        let inLoculeA = (abs(u - 0.32) < 0.08 || abs(u - 0.68) < 0.08);
        if (!(inLoculeR && inLoculeA)) {
          brush.line(prevX, prevY, nx, ny);
        }
        prevX = nx;
        prevY = ny;
      }
    }

    // B. Translucent wet cellular parenchyma cross-walls & reflections in the inner mesocarp
    let innerMidR = lerp(sl.coreR * 1.12, rLocMid * 0.86, 0.5);
    brush.set("chalk_soft", PALETTE.chalkIvory, 0.55);
    let aSpan1 = sec.aMid - sec.dAng * 0.24;
    let aSpan2 = sec.aMid + sec.dAng * 0.24;
    let wx1 = sl.cx + cos(aSpan1) * sl.ellipX * innerMidR;
    let wy1 = sl.cy + sin(aSpan1) * sl.ellipY * innerMidR;
    let wx2 = sl.cx + cos(aSpan2) * sl.ellipX * innerMidR;
    let wy2 = sl.cy + sin(aSpan2) * sl.ellipY * innerMidR;
    brush.line(wx1, wy1, wx2, wy2);

    // Fine cellular water-droplet stipples showing wet translucency
    brush.set("diag_needle", PALETTE.chalkPure, 0.65);
    for (let m = 0; m < 7; m++) {
      let rr = random(sl.coreR * 1.15, rLocMid * 0.88);
      let aa = random(sec.a0 + 2, sec.a1 - 2);
      let px = sl.cx + cos(aa) * sl.ellipX * rr;
      let py = sl.cy + sin(aa) * sl.ellipY * rr;
      brush.line(px, py, px + cos(aa + 90) * 1.8, py + sin(aa + 90) * 1.8);
    }
  }
}

function renderLoculesAndSepta(sl) {
  let numS = sl.sectorsData.length;

  for (let s = 0; s < numS; s++) {
    let sec = sl.sectorsData[s];
    let rLocBase = lerp(sl.coreR, sl.outerR * sec.rMod, 0.56);
    let locLen = (sl.outerR - sl.coreR) * (0.165 - 0.04 * sl.woody);
    let locHalfW = sec.dAng * 0.125;

    // 1. Inter-fruitlet Septal Membrane (faint luminous double-wall along sector boundary a0)
    let rSepIn = sl.coreR * 1.03;
    let rSepOut = sl.outerR * sec.rMod * 0.86;
    let sx1 = sl.cx + cos(sec.a0) * sl.ellipX * rSepIn;
    let sy1 = sl.cy + sin(sec.a0) * sl.ellipY * rSepIn;
    let sx2 = sl.cx + cos(sec.a0) * sl.ellipX * rSepOut;
    let sy2 = sl.cy + sin(sec.a0) * sl.ellipY * rSepOut;

    brush.set("charcoal_comp", PALETTE.charcoalMid, 0.55);
    brush.line(sx1, sy1, sx2, sy2);
    brush.set("diag_needle", PALETTE.chalkWarm, 0.65);
    brush.line(sx1, sy1, sx2, sy2);

    // 2. Central carpel septum dividing the twin/triplet locule chambers along aMid
    let cIn = rLocBase - locLen * 0.65;
    let cOut = rLocBase + locLen * 0.75;
    brush.set("chalk_fine", PALETTE.chalkBright, 0.7);
    brush.line(
      sl.cx + cos(sec.aMid) * sl.ellipX * cIn,
      sl.cy + sin(sec.aMid) * sl.ellipY * cIn,
      sl.cx + cos(sec.aMid) * sl.ellipX * cOut,
      sl.cy + sin(sec.aMid) * sl.ellipY * cOut
    );

    // 3. Render the paired Ovarian Locules (deep charcoal cavity + bright endocarp lining + ovule)
    for (let side = -1; side <= 1; side += 2) {
      let aCenter = sec.aMid + side * sec.dAng * 0.18;
      let rIn = rLocBase - locLen * 0.52;
      let rOut = rLocBase + locLen * 0.52;
      let locPts = buildLoculePolygon(sl.cx, sl.cy, sl.ellipX, sl.ellipY, aCenter, locHalfW, rIn, rOut);

      // Deep compressed charcoal interior stroke
      brush.set("charcoal_comp", PALETTE.bgDeep, 0.85);
      brush.line(locPts[0][0], locPts[0][1], locPts[2][0], locPts[2][1]);

      // Luminous white-chalk endocarp lining around the chamber perimeter
      brush.set("chalk_fine", PALETTE.chalkIvory, 0.75);
      for (let k = 0; k < 4; k++) {
        let pA = locPts[k];
        let pB = locPts[(k + 1) % 4];
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }

      // Specular inner rim highlight
      brush.set("diag_needle", PALETTE.chalkPure, 0.75);
      brush.line(locPts[0][0], locPts[0][1], locPts[1][0], locPts[1][1]);
      brush.line(locPts[1][0], locPts[1][1], locPts[2][0], locPts[2][1]);

      // Occasional abortive ovule / seed trace attached to axial placenta
      if ((s + sl.idx + (side > 0 ? 1 : 0)) % 3 === 0 && sl.woody < 0.5) {
        let ovR = lerp(rIn, rOut, 0.38);
        let ovA = aCenter - side * locHalfW * 0.35;
        let ox = sl.cx + cos(ovA) * sl.ellipX * ovR;
        let oy = sl.cy + sin(ovA) * sl.ellipY * ovR;
        brush.set("chalk_fine", PALETTE.chalkPure, 0.9);
        brush.circle(ox, oy, 1.6, 0.2);
      }
    }

    // 4. Schizogenous Nectary Duct just centrifugal to the locule pair
    let rNect = rLocBase + locLen * 0.88;
    let nx = sl.cx + cos(sec.aMid) * sl.ellipX * rNect;
    let ny = sl.cy + sin(sec.aMid) * sl.ellipY * rNect;
    brush.set("charcoal_comp", PALETTE.bgDeep, 0.65);
    brush.circle(nx, ny, 2.2, 0.25);
    brush.set("diag_needle", PALETTE.chalkWarm, 0.6);
    brush.circle(nx, ny, 2.6, 0.25);
  }
}

function renderSpiralRindEyes(sl) {
  let numS = sl.sectorsData.length;

  for (let s = 0; s < numS; s++) {
    let sec = sl.sectorsData[s];
    let ed = sec.eyeDepth;
    let baseR = sl.outerR * sec.rMod;

    // Sub-epidermal dark compressed charcoal cortical shadow band
    let rCortexIn = baseR * (0.76 - 0.05 * ed);
    let rCortexOut = baseR * (0.90 - 0.06 * ed);

    brush.set("charcoal_comp", PALETTE.charcoalDark, 0.95);
    for (let k = 0; k < 5; k++) {
      let t = (k + 0.5) / 5;
      let ang = lerp(sec.a0 + 1.5, sec.a1 - 1.5, t);
      let r1 = lerp(rCortexIn, rCortexOut, 0.25);
      let r2 = lerp(rCortexIn, rCortexOut, 0.88);
      brush.line(
        sl.cx + cos(ang) * sl.ellipX * r1,
        sl.cy + sin(ang) * sl.ellipY * r1,
        sl.cx + cos(ang) * sl.ellipX * r2,
        sl.cy + sin(ang) * sl.ellipY * r2
      );
    }

    // When eyeDepth is significant, render the intricate Blossom Cup (eye chamber) architecture
    if (ed > 0.25) {
      let aCupL = lerp(sec.a0, sec.a1, 0.24);
      let aCupR = lerp(sec.a0, sec.a1, 0.76);
      let aCupM = sec.aMid;

      let rCupFloor = baseR * (0.83 - 0.07 * ed);
      let rShoulder = baseR * 0.96;

      // Dark sclerenchyma crypts on left and right of the floral tongue
      brush.set("charcoal_comp", PALETTE.bgDeep, 0.8);
      for (let side = -1; side <= 1; side += 2) {
        let aCrypt = aCupM + side * sec.dAng * 0.14;
        brush.line(
          sl.cx + cos(aCrypt) * sl.ellipX * rCupFloor,
          sl.cy + sin(aCrypt) * sl.ellipY * rCupFloor,
          sl.cx + cos(aCrypt) * sl.ellipX * rShoulder,
          sl.cy + sin(aCrypt) * sl.ellipY * rShoulder
        );
      }

      // Luminous backlit trichome hairs (fuzzy white chalk filaments lining the blossom cup)
      brush.set("diag_needle", PALETTE.chalkIvory, 0.7);
      let numHairs = floor(5 + ed * 6);
      for (let h = 0; h < numHairs; h++) {
        let th = lerp(aCupL, aCupR, h / (numHairs - 1));
        let rh1 = rCupFloor + 1.5;
        let rh2 = rh1 + 3.5 + ed * 3.0;
        brush.line(
          sl.cx + cos(th) * sl.ellipX * rh1,
          sl.cy + sin(th) * sl.ellipY * rh1,
          sl.cx + cos(th) * sl.ellipX * rh2,
          sl.cy + sin(th) * sl.ellipY * rh2
        );
      }
    }

    // Cortical vascular bundle dots along the sub-rind arch
    brush.set("diag_needle", PALETTE.chalkBright, 0.75);
    for (let b = 0; b < 6; b++) {
      let tb = (b + 0.5) / 6;
      let ab = lerp(sec.a0 + 1, sec.a1 - 1, tb);
      let rb = rCortexIn + (noise(sl.idx * 2 + s, b) - 0.5) * 5;
      let bx = sl.cx + cos(ab) * sl.ellipX * rb;
      let by = sl.cy + sin(ab) * sl.ellipY * rb;
      brush.line(bx, by, bx + cos(ab) * 1.4, by + sin(ab) * 1.4);
    }
  }
}

function renderOuterCrownTransition(sl) {
  // Slice 8: overlapping crescentic bract scales around the outer cortex
  let numBracts = sl.sectorsData.length;
  for (let s = 0; s < numBracts; s++) {
    let sec = sl.sectorsData[s];
    let a1 = sec.a0 - sec.dAng * 0.15;
    let a2 = sec.a1 + sec.dAng * 0.15;
    let rIn = sl.outerR * 0.78 * sec.rMod;
    let rOut = sl.outerR * 0.94 * sec.rMod;

    // Dark separation cleft under each imbricated leaf-bract base
    brush.set("charcoal_comp", PALETTE.bgDeep, 0.75);
    drawEllipticalArc(sl.cx, sl.cy, sl.ellipX, sl.ellipY, rIn, a1, a2, 8);

    // Bright backlit leaf-scale margin and parallel leaf veins
    brush.set("chalk_fine", PALETTE.chalkIvory, 0.75);
    drawEllipticalArc(sl.cx, sl.cy, sl.ellipX, sl.ellipY, rOut, a1, a2, 8);

    brush.set("diag_needle", PALETTE.chalkWarm, 0.65);
    for (let v = 1; v < 6; v++) {
      let av = lerp(a1, a2, v / 6);
      let rm = lerp(rIn, rOut, 0.5);
      let vx = sl.cx + cos(av) * sl.ellipX * rm;
      let vy = sl.cy + sin(av) * sl.ellipY * rm;
      brush.line(vx, vy, vx + cos(av) * 1.2, vy + sin(av) * 1.2);
    }
  }
}

function renderCrownRosetteSlice(sl) {
  // Slice 9: Apical Crown Base — nested Fibonacci whorls of crescent-shaped foliar blades
  let whorls = 3;
  let bladesPerWhorl = 13;

  for (let w = 0; w < whorls; w++) {
    let rWhorlIn = lerp(sl.coreR * 1.12, sl.outerR * 0.74, w / whorls);
    let rWhorlOut = lerp(sl.coreR * 1.12, sl.outerR * 0.95, (w + 0.92) / whorls);
    let thick = rWhorlOut - rWhorlIn;

    for (let b = 0; b < bladesPerWhorl; b++) {
      let aCenter = b * (360 / bladesPerWhorl) + w * 137.5 + sl.rotOffset;
      let halfSpan = 18 - w * 1.5;
      let aStart = aCenter - halfSpan;
      let aEnd = aCenter + halfSpan;

      // Dark inter-foliar air gap
      brush.set("charcoal_comp", PALETTE.bgDeep, 0.85);
      drawEllipticalArc(sl.cx, sl.cy, sl.ellipX, sl.ellipY, rWhorlIn, aStart, aEnd, 7);

      // Mid-grey mesophyll body of the crescent leaf cross-section
      brush.set("chalk_soft", PALETTE.greyLuminous, 0.7);
      drawEllipticalArc(sl.cx, sl.cy, sl.ellipX, sl.ellipY, rWhorlIn + thick * 0.45, aStart + 3, aEnd - 3, 6);

      // Luminous backlit abaxial epidermis of each leaf crescent
      brush.set("chalk_fine", PALETTE.chalkIvory, 0.8);
      drawEllipticalArc(sl.cx, sl.cy, sl.ellipX, sl.ellipY, rWhorlOut, aStart, aEnd, 8);

      // Row of microscopic parallel vascular vein bundles inside each cut leaf blade
      brush.set("diag_needle", PALETTE.chalkPure, 0.75);
      let veins = 6;
      for (let v = 1; v < veins; v++) {
        let av = lerp(aStart + 2, aEnd - 2, v / veins);
        let rv = rWhorlIn + thick * 0.52 * sin(((v / veins) * 180));
        let vx = sl.cx + cos(av) * sl.ellipX * (rWhorlIn + rv * 0.5);
        let vy = sl.cy + sin(av) * sl.ellipY * (rWhorlIn + rv * 0.5);
        brush.line(vx, vy, vx + cos(av) * 1.3, vy + sin(av) * 1.3);
      }
    }
  }
}

function renderCentralCore(sl) {
  let cr = sl.coreR;

  // 1. Dark pericycle boundary ring just outside the core vascular cylinder
  brush.set("charcoal_comp", PALETTE.charcoalDark, 0.75);
  drawEllipticalArc(sl.cx, sl.cy, sl.ellipX, sl.ellipY, cr * 1.05, 0, 360, 28);

  // 2. Luminous vascular cambium / stele perimeter ring
  brush.set("chalk_fine", PALETTE.chalkIvory, 0.85);
  drawEllipticalArc(sl.cx, sl.cy, sl.ellipX, sl.ellipY, cr * 0.96, 0, 360, 28);

  // 3. Concentric woody rings in basal slice (Slice 1) or radial vascular traces
  if (sl.woody > 0.3) {
    brush.set("chalk_soft", PALETTE.chalkWarm, 0.6);
    drawEllipticalArc(sl.cx, sl.cy, sl.ellipX, sl.ellipY, cr * 0.68, 0, 360, 20);
    drawEllipticalArc(sl.cx, sl.cy, sl.ellipX, sl.ellipY, cr * 0.42, 0, 360, 16);
  }

  // 4. Dense phyllotactic field of cross-sectioned longitudinal vascular bundles inside the stele
  let numBundles = floor(42 + cr * 1.2);
  let goldenAngle = 137.50776;
  for (let k = 3; k < numBundles; k++) {
    let frac = sqrt(k / numBundles);
    let rBun = cr * 0.92 * frac;
    let aBun = k * goldenAngle + sl.rotOffset;
    let bx = sl.cx + cos(aBun) * sl.ellipX * rBun;
    let by = sl.cy + sin(aBun) * sl.ellipY * rBun;

    if (frac > 0.65) {
      brush.set("diag_needle", PALETTE.chalkPure, 0.85);
    } else {
      brush.set("diag_needle", PALETTE.chalkWarm, 0.7);
    }
    brush.line(bx, by, bx + cos(aBun) * 1.4, by + sin(aBun) * 1.4);
  }

  // 5. Central medullary pith fissure (tiny dark 3- or 4-rayed star cleft at exact axis center)
  brush.set("charcoal_comp", PALETTE.bgDeep, 0.85);
  let cleftR = cr * (0.24 - 0.08 * sl.woody);
  for (let ray = 0; ray < 3; ray++) {
    let aRay = ray * 120 + sl.rotOffset;
    brush.line(
      sl.cx - cos(aRay) * cleftR * 0.5,
      sl.cy - sin(aRay) * cleftR * 0.5,
      sl.cx + cos(aRay) * cleftR,
      sl.cy + sin(aRay) * cleftR
    );
  }
}

function drawEllipticalArc(cx, cy, ex, ey, r, aStart, aEnd, steps) {
  for (let i = 0; i < steps; i++) {
    let a0 = lerp(aStart, aEnd, i / steps);
    let a1 = lerp(aStart, aEnd, (i + 1) / steps);
    brush.line(
      cx + cos(a0) * ex * r,
      cy + sin(a0) * ey * r,
      cx + cos(a1) * ex * r,
      cy + sin(a1) * ey * r
    );
  }
}

// =============================================================================
// PASS 4: DIAGNOSTIC CALIBRATION LINES, TINY TICK MARKS & SCAN FRAMING
// =============================================================================

function renderCalibrationMargins() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  const mL = 66;
  const mR = 1134;
  const mT = 66;
  const mB = 1134;

  // 1. Thin dotted calibration line along all four outer margins
  drawDottedCalibrationLine(mL, mT, mR, mT, 2.2, 4.8);
  drawDottedCalibrationLine(mL, mB, mR, mB, 2.2, 4.8);
  drawDottedCalibrationLine(mL, mT, mL, mB, 2.2, 4.8);
  drawDottedCalibrationLine(mR, mT, mR, mB, 2.2, 4.8);

  // 2. Graduated tiny tick marks along top, bottom, left, and right margins
  let span = mR - mL; // 1068 px
  let step = 6;       // minor tick every 6px
  let totalSteps = floor(span / step);

  for (let i = 0; i <= totalSteps; i++) {
    let offset = i * step;
    let pos = mL + offset;

    let isMajor = (i % 20 === 0);
    let isMed = (i % 5 === 0 && !isMajor);

    let tickLen = isMajor ? 11.5 : (isMed ? 6.5 : 3.0);
    let col = isMajor ? PALETTE.calibBright : (isMed ? PALETTE.calibMid : PALETTE.calibDim);
    let w = isMajor ? 0.85 : 0.6;

    brush.set("diag_needle", col, w);

    // Top margin ticks (pointing outward/up)
    brush.line(pos, mT, pos, mT - tickLen);
    // Bottom margin ticks (pointing outward/down)
    brush.line(pos, mB, pos, mB + tickLen);
    // Left margin ticks (pointing outward/left)
    brush.line(mL, pos, mL - tickLen, pos);
    // Right margin ticks (pointing outward/right)
    brush.line(mR, pos, mR + tickLen, pos);

    // Tiny cross-bar on major calibration ticks
    if (isMajor) {
      brush.line(pos - 2.5, mT - tickLen, pos + 2.5, mT - tickLen);
      brush.line(pos - 2.5, mB + tickLen, pos + 2.5, mB + tickLen);
      brush.line(mL - tickLen, pos - 2.5, mL - tickLen, pos + 2.5);
      brush.line(mR + tickLen, pos - 2.5, mR + tickLen, pos + 2.5);
    }
  }

  // 3. Internal 3x3 scan grid dotted dividers & fiducial crosshairs
  const div1 = 435;
  const div2 = 765;
  drawSparseDottedLine(div1, 95, div1, 1105, 1.5, 10);
  drawSparseDottedLine(div2, 95, div2, 1105, 1.5, 10);
  drawSparseDottedLine(95, div1, 1105, div1, 1.5, 10);
  drawSparseDottedLine(95, div2, 1105, div2, 1.5, 10);

  // Precision fiducial crosshairs at grid intersections
  const gridCoords = [105, 435, 765, 1095];
  for (let gx of gridCoords) {
    for (let gy of gridCoords) {
      drawFiducialTarget(gx, gy);
    }
  }

  // 4. Per-slice diagnostic Z-depth indicator & sequential scan index in top-left of each cell
  for (let i = 0; i < slicesData.length; i++) {
    let sl = slicesData[i];
    let cellX = 105 + sl.col * 330 + 16;
    let cellY = 105 + sl.row * 330 + 18;

    // 9-tick mini scan sequence bar highlighting current slice index i
    for (let k = 0; k < 9; k++) {
      let tx = cellX + k * 5.5;
      if (k === i) {
        brush.set("diag_needle", PALETTE.chalkPure, 1.0);
        brush.line(tx, cellY - 4, tx, cellY + 6);
        brush.circle(tx, cellY - 6.5, 1.2, 0.1);
      } else {
        brush.set("diag_needle", PALETTE.calibDim, 0.65);
        brush.line(tx, cellY - 1, tx, cellY + 3);
      }
    }

    // Microscopic elevation gauge showing Z plane height [0..1]
    let gaugeX = cellX + 62;
    brush.set("diag_needle", PALETTE.calibDim, 0.6);
    brush.line(gaugeX, cellY + 5, gaugeX + 26, cellY + 5);
    let zTickX = gaugeX + sl.z * 26;
    brush.set("diag_needle", PALETTE.calibBright, 0.85);
    brush.line(zTickX, cellY + 1, zTickX, cellY + 9);
  }

  // 5. Bottom margin master longitudinal scan-plane key (100mm diagnostic scale bar)
  let barY = 1166;
  let barX1 = 480;
  let barX2 = 720;
  brush.set("diag_needle", PALETTE.calibBright, 0.85);
  brush.line(barX1, barY, barX2, barY);
  for (let k = 0; k <= 24; k++) {
    let bx = lerp(barX1, barX2, k / 24);
    let h = (k % 6 === 0) ? 5.5 : 2.5;
    brush.line(bx, barY - h, bx, barY + h);
  }
}

function drawDottedCalibrationLine(x1, y1, x2, y2, dashLen, gapLen) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let distTotal = sqrt(dx * dx + dy * dy);
  let step = dashLen + gapLen;
  let count = floor(distTotal / step);
  let ux = dx / distTotal;
  let uy = dy / distTotal;

  brush.set("diag_needle", PALETTE.calibMid, 0.72);
  for (let i = 0; i <= count; i++) {
    let d0 = i * step;
    let d1 = min(distTotal, d0 + dashLen);
    brush.line(x1 + ux * d0, y1 + uy * d0, x1 + ux * d1, y1 + uy * d1);
  }
}

function drawSparseDottedLine(x1, y1, x2, y2, dotLen, gapLen) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let distTotal = sqrt(dx * dx + dy * dy);
  let step = dotLen + gapLen;
  let count = floor(distTotal / step);
  let ux = dx / distTotal;
  let uy = dy / distTotal;

  brush.set("diag_needle", PALETTE.calibDim, 0.55);
  for (let i = 0; i <= count; i++) {
    let d0 = i * step;
    let d1 = min(distTotal, d0 + dotLen);
    brush.line(x1 + ux * d0, y1 + uy * d0, x1 + ux * d1, y1 + uy * d1);
  }
}

function drawFiducialTarget(x, y) {
  brush.set("diag_needle", PALETTE.calibBright, 0.75);
  brush.line(x - 6, y, x - 2, y);
  brush.line(x + 2, y, x + 6, y);
  brush.line(x, y - 6, x, y - 2);
  brush.line(x, y + 2, x, y + 6);
  brush.circle(x, y, 3.2, 0.1);
}

