// ============================================================================
// GEOMETRY & SPLINE HELPERS
// ============================================================================

function safeSpline(pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 0.6) {
      clean.push(pts[i]);
    }
  }
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curv);
  }
}

function drawShapePoly(pts, curv = 0.25, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed ? CLOSE : undefined);
}

function evalCatmullRom(pts, t) {
  let n = pts.length - 1;
  let f = constrain(t, 0, 0.999999) * n;
  let idx = Math.floor(f);
  let u = f - idx;

  let p0 = pts[Math.max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[Math.min(n, idx + 1)];
  let p3 = pts[Math.min(n, idx + 2)];

  let u2 = u * u;
  let u3 = u2 * u;

  let x =
    0.5 *
    (2 * p1[0] +
      (-p0[0] + p2[0]) * u +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3);
  let y =
    0.5 *
    (2 * p1[1] +
      (-p0[1] + p2[1]) * u +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3);

  return [x, y];
}

function sampleSpineFrame(ctrlPts, steps) {
  let samples = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = evalCatmullRom(ctrlPts, t);
    let pPrev = evalCatmullRom(ctrlPts, Math.max(0, t - 0.005));
    let pNext = evalCatmullRom(ctrlPts, Math.min(1, t + 0.005));
    let tx = pNext[0] - pPrev[0];
    let ty = pNext[1] - pPrev[1];
    let len = Math.hypot(tx, ty) || 1;
    tx /= len;
    ty /= len;
    // Outward normal (+N points "north/east" depending on spine direction)
    let nx = -ty;
    let ny = tx;
    samples.push({ t, x: p[0], y: p[1], tx, ty, nx, ny });
  }
  return samples;
}

function decimatePts(pts, step) {
  let out = [];
  for (let i = 0; i < pts.length; i += step) {
    out.push(pts[i]);
  }
  if (out[out.length - 1] !== pts[pts.length - 1]) {
    out.push(pts[pts.length - 1]);
  }
  return out;
}

