// ============================================================================
// 2. PORTOLAN RHUMB LINE NETWORK
// ============================================================================

function clipLineToBox(x1, y1, dx, dy, xmin, ymin, xmax, ymax) {
  let tMin = 0;
  let tMax = 2400;
  const p = [-dx, dx, -dy, dy];
  const q = [x1 - xmin, xmax - x1, y1 - ymin, ymax - y1];
  for (let i = 0; i < 4; i++) {
    if (Math.abs(p[i]) < 1e-6) {
      if (q[i] < 0) return null;
    } else {
      let t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > tMax) return null;
        if (t > tMin) tMin = t;
      } else {
        if (t < tMin) return null;
        if (t < tMax) tMax = t;
      }
    }
  }
  if (tMin >= tMax) return null;
  return [x1 + tMin * dx, y1 + tMin * dy, x1 + tMax * dx, y1 + tMax * dy];
}

function drawPortolanRhumbNetwork(roseA, roseB, weightScale, isOverlay) {
  const xmin = 56,
    ymin = 56,
    xmax = 1144,
    ymax = 1144;
  const roses = [roseA, roseB];

  for (let rIdx = 0; rIdx < roses.length; rIdx++) {
    let rose = roses[rIdx];
    let numRays = 32;
    for (let i = 0; i < numRays; i++) {
      let ang = i * (360 / numRays);
      let dx = cos(ang);
      let dy = sin(ang);
      let seg = clipLineToBox(rose.x, rose.y, dx, dy, xmin, ymin, xmax, ymax);
      if (!seg) continue;

      // Start outside inner core of compass rose on overlay pass
      let startDist = isOverlay ? rose.r * 0.42 : 0;
      let sx = rose.x + dx * startDist;
      let sy = rose.y + dy * startDist;

      // Determine wind color: Cardinal/Intercardinal = Vermilion, Half-winds = Verdigris, Quarter-winds = Sepia/Faded
      let col, w;
      if (i % 4 === 0) {
        col = PAL.vermilion;
        w = 0.52 * weightScale;
      } else if (i % 2 === 0) {
        col = PAL.verdigris;
        w = 0.46 * weightScale;
      } else {
        if (isOverlay && i % 4 === 3 && rIdx === 1) continue; // Keep overlay crisp & uncrowded
        col = i % 4 === 1 ? PAL.vermilionLight : PAL.verdigrisLight;
        w = 0.32 * weightScale;
      }

      brush.set("rotring", col, w);
      brush.line(sx, sy, seg[2], seg[3]);
    }
  }

  // Satellite Marteloio chord lines connecting perimeter wind nodes
  if (!isOverlay) {
    let martR = 460;
    let cx = 600,
      cy = 600;
    let nodes = [];
    for (let i = 0; i < 16; i++) {
      let a = i * 22.5;
      nodes.push([cx + cos(a) * martR, cy + sin(a) * martR]);
    }
    for (let i = 0; i < 16; i++) {
      for (let step of [3, 5, 7]) {
        let j = (i + step) % 16;
        let col = (i + step) % 2 === 0 ? PAL.verdigris : PAL.vermilion;
        brush.set("rotring", col, 0.26);
        let dx = nodes[j][0] - nodes[i][0];
        let dy = nodes[j][1] - nodes[i][1];
        let len = Math.hypot(dx, dy);
        let seg = clipLineToBox(nodes[i][0], nodes[i][1], dx / len, dy / len, xmin, ymin, xmax, ymax);
        if (seg) {
          brush.line(seg[0], seg[1], seg[2], seg[3]);
        }
      }
    }
  }
}

