function evalCoastalFeatures(t, features, nOff) {
  let delta = 0;
  for (let f of features) {
    let d = (t - f.t) / f.w;
    if (Math.abs(d) < 3.2) {
      // Asymmetric coastal headland / fjord profile
      let skew = 1 + 0.25 * Math.sin(d * 1.8);
      delta += f.amp * Math.exp(-0.5 * d * d) * skew;
    }
  }
  // Multi-octave fractal coastline ruggedness (small coves, spits & rocky points)
  let n1 = (noise(t * 18, nOff) - 0.5) * 22;
  let n2 = (noise(t * 48, nOff + 17) - 0.5) * 11;
  let n3 = (noise(t * 110, nOff + 43) - 0.5) * 5.5;
  return delta + n1 + n2 + n3;
}

function constructRibbon(cfg) {
  const steps = 180;
  const spine = sampleSpineFrame(cfg.ctrl, steps);

  let coastN = [];
  let junctionN = [];
  let inlandFascia = [];
  let junctionS = [];
  let coastS = [];

  for (let i = 0; i <= steps; i++) {
    let s = spine[i];
    let t = s.t;

    // Taper smoothly at the very ends of the ribbon like shaved charcuterie
    let endTaper = Math.sin(Math.pow(constrain(t, 0, 1), 0.75) * 180);
    endTaper = 0.32 + 0.68 * Math.pow(Math.max(0.01, endTaper), 0.55);

    // Draped pleat wave along ribbon length
    let drapeWave = Math.sin(t * 360 * 3.2 + cfg.noiseOff) * 14;

    let featN = evalCoastalFeatures(t, cfg.featuresN, cfg.noiseOff);
    let featS = evalCoastalFeatures(t, cfg.featuresS, cfg.noiseOff + 77);

    // Meat half-widths
    let mN = (cfg.baseMeatN + (noise(t * 12, cfg.noiseOff + 5) - 0.5) * 24 + featN * 0.35) * endTaper;
    let mS = (cfg.baseMeatS + (noise(t * 12, cfg.noiseOff + 15) - 0.5) * 24 + featS * 0.45) * endTaper;

    // Fat coastal band widths (meandering inlets & peninsulas)
    let fN = Math.max(10, (cfg.baseFatN + featN * 0.85 + (noise(t * 28, cfg.noiseOff + 31) - 0.5) * 18) * endTaper);
    let fS = Math.max(6, (cfg.baseFatS + featS * 0.65 + (noise(t * 28, cfg.noiseOff + 51) - 0.5) * 10) * endTaper);

    let cx = s.x + s.nx * drapeWave;
    let cy = s.y + s.ny * drapeWave;

    junctionN.push([cx + s.nx * mN, cy + s.ny * mN]);
    coastN.push([cx + s.nx * (mN + fN), cy + s.ny * (mN + fN)]);

    // Inland connective fascia river running near the center-north of the meat
    let fasOffset = (mN * 0.25 - mS * 0.18) + (noise(t * 22, cfg.noiseOff + 99) - 0.5) * 18;
    inlandFascia.push([cx + s.nx * fasOffset, cy + s.ny * fasOffset]);

    junctionS.push([cx - s.nx * mS, cy - s.ny * mS]);
    coastS.push([cx - s.nx * (mS + fS), cy - s.ny * (mS + fS)]);
  }

  // Build closed polygon for entire slice (for cast shadow & base glaze)
  let fullOutlineHi = coastN.concat(coastS.slice().reverse());
  let fullOutlineLo = decimatePts(coastN, 4).concat(decimatePts(coastS, 4).reverse());

  // Build closed polygon for lean meat territory
  let meatPolyLo = decimatePts(junctionN, 4).concat(decimatePts(junctionS, 4).reverse());

  // Build closed polygon for Northern pearly fat coastal shelf
  let fatNorthPolyLo = decimatePts(coastN, 3).concat(decimatePts(junctionN, 3).reverse());

  // Build closed polygon for Southern cured rim / fat shelf
  let fatSouthPolyLo = decimatePts(junctionS, 4).concat(decimatePts(coastS, 4).reverse());

  // Build draped fold / pleat polygons (where translucent prosciutto doubles over itself)
  let folds = [];
  const numFolds = 6;
  for (let f = 0; f < numFolds; f++) {
    let tStart = 0.06 + (f / numFolds) * 0.82;
    let tSpan = 0.11 + (f % 2) * 0.04;
    let i0 = Math.floor(tStart * steps);
    let i1 = Math.min(steps, Math.floor((tStart + tSpan) * steps));

    let foldPts = [];
    for (let i = i0; i <= i1; i += 2) {
      let u = (i - i0) / (i1 - i0);
      let pinch = Math.sin(u * 180);
      let pN = junctionN[i];
      let pS = junctionS[i];
      let x = lerp(pS[0], pN[0], 0.85 * pinch + 0.1);
      let y = lerp(pS[1], pN[1], 0.85 * pinch + 0.1);
      foldPts.push([x, y]);
    }
    for (let i = i1; i >= i0; i -= 2) {
      let u = (i - i0) / (i1 - i0);
      let pinch = Math.sin(u * 180);
      let pN = junctionN[i];
      let pS = junctionS[i];
      let x = lerp(pS[0], pN[0], 0.15 * pinch);
      let y = lerp(pS[1], pN[1], 0.15 * pinch);
      foldPts.push([x, y]);
    }
    folds.push({ pts: foldPts, deep: f % 2 === 0 });
  }

  // Build longitudinal deep-garnet muscle cushion polygons (anatomical ham sections)
  let garnetCushionNorth = decimatePts(junctionN, 4).concat(decimatePts(inlandFascia, 4).reverse());
  let garnetCushionSouth = decimatePts(inlandFascia, 4).concat(decimatePts(junctionS, 4).reverse());

  // Build plump pearly fat cushions on each Cape peninsula
  let fatLobes = [];
  for (let feat of cfg.featuresN) {
    if (feat.amp > 0) {
      let iCenter = Math.floor(feat.t * steps);
      let iSpan = Math.max(4, Math.floor(feat.w * steps * 1.4));
      let i0 = Math.max(0, iCenter - iSpan);
      let i1 = Math.min(steps, iCenter + iSpan);
      let lobe = [];
      for (let i = i0; i <= i1; i += 2) lobe.push(coastN[i]);
      for (let i = i1; i >= i0; i -= 2) {
        lobe.push([
          lerp(junctionN[i][0], coastN[i][0], 0.22),
          lerp(junctionN[i][1], coastN[i][1], 0.22)
        ]);
      }
      fatLobes.push(lobe);
    }
  }

  // Record exact Cape & Bay label anchors along both coasts
  let labelAnchors = [];
  for (let feat of cfg.featuresN) {
    let idx = constrain(Math.round(feat.t * steps), 2, steps - 2);
    let pt = coastN[idx];
    let s = spine[idx];
    labelAnchors.push({
      x: pt[0],
      y: pt[1],
      nx: s.nx,
      ny: s.ny,
      name: feat.name,
      rub: !!feat.rub,
      bay: !!feat.bay
    });
  }
  for (let feat of cfg.featuresS) {
    let idx = constrain(Math.round(feat.t * steps), 2, steps - 2);
    let pt = coastS[idx];
    let s = spine[idx];
    labelAnchors.push({
      x: pt[0],
      y: pt[1],
      nx: -s.nx,
      ny: -s.ny,
      name: feat.name,
      rub: !!feat.rub,
      bay: !!feat.bay
    });
  }

  return {
    id: cfg.id,
    spine,
    coastN,
    junctionN,
    inlandFascia,
    junctionS,
    coastS,
    fullOutlineHi,
    fullOutlineLo,
    meatPolyLo,
    fatNorthPolyLo,
    fatSouthPolyLo,
    folds,
    garnetCushionNorth,
    garnetCushionSouth,
    fatLobes,
    labelAnchors,
    noiseOff: cfg.noiseOff
  };
}

// ============================================================================
// 5. RENDER PROSCIUTTO WATERCOLOUR LAYERS (ROSE, GARNET, PEARLY WHITE FAT)
// ============================================================================

function renderProsciuttoWatercolors(ribbons) {
  brush.noField();
  brush.noStroke();

  // --- PASS 1: Dusky Twilight Cast Shadows on Parchment Board ---
  brush.fill(PAL.shadow1, 52);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.25);
  for (let r of ribbons) {
    let shPts = r.fullOutlineLo.map((p) => [p[0] + 10, p[1] + 13]);
    drawShapePoly(shPts, 0.25, true);
  }

  brush.fill(PAL.shadow2, 65);
  brush.fillBleed(0.14, "out");
  for (let r of ribbons) {
    let shPts = r.fullOutlineLo.map((p) => [p[0] + 4.5, p[1] + 6]);
    drawShapePoly(shPts, 0.25, true);
  }

  // --- PASS 2: Translucent Amber-Rose Base Glaze Across Entire Meat ---
  brush.fill(PAL.roseAmber, 68);
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.55, 0.35);
  for (let r of ribbons) {
    drawShapePoly(r.meatPolyLo, 0.25, true);
  }

  // --- PASS 3: Glassy Rose Watercolour Layer ---
  brush.fill(PAL.roseGlass, 82);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.65, 0.45);
  for (let r of ribbons) {
    drawShapePoly(r.garnetCushionNorth, 0.25, true);
    drawShapePoly(r.garnetCushionSouth, 0.25, true);
  }

  // --- PASS 4: Mid Carmine-Rose Draped Folds ---
  brush.fill(PAL.roseMid, 88);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.7, 0.5);
  for (let r of ribbons) {
    for (let f of r.folds) {
      drawShapePoly(f.pts, 0.3, true);
    }
  }

  // --- PASS 5: Rich Garnet Translucent Overlaps & Muscle Hearts ---
  brush.fill(PAL.garnet, 96);
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.75, 0.55);
  for (let r of ribbons) {
    // Inner contracted garnet core
    let corePts = [];
    for (let i = 8; i < r.junctionN.length - 8; i += 5) {
      corePts.push([
        lerp(r.inlandFascia[i][0], r.junctionN[i][0], 0.72),
        lerp(r.inlandFascia[i][1], r.junctionN[i][1], 0.72)
      ]);
    }
    for (let i = r.junctionS.length - 9; i >= 8; i -= 5) {
      corePts.push([
        lerp(r.inlandFascia[i][0], r.junctionS[i][0], 0.68),
        lerp(r.inlandFascia[i][1], r.junctionS[i][1], 0.68)
      ]);
    }
    drawShapePoly(corePts, 0.25, true);

    for (let f of r.folds) {
      if (f.deep) drawShapePoly(f.pts, 0.3, true);
    }
  }

  // --- PASS 6: Deep Twilight Oxblood / Garnet Creases ---
  brush.fill(PAL.garnetDeep, 92);
  brush.fillBleed(0.1, "in");
  brush.fillTexture(0.8, 0.6);
  for (let r of ribbons) {
    for (let i = 0; i < r.folds.length; i += 2) {
      let f = r.folds[i];
      // Shrink fold slightly for deepest crease shadow
      let cx = 0,
        cy = 0;
      for (let p of f.pts) {
        cx += p[0];
        cy += p[1];
      }
      cx /= f.pts.length;
      cy /= f.pts.length;
      let innerFold = f.pts.map((p) => [lerp(cx, p[0], 0.65), lerp(cy, p[1], 0.65)]);
      drawShapePoly(innerFold, 0.3, true);
    }
  }
  brush.noFill();

  // --- PASS 7: Pearly White Fat Coastal Shelves (Opaque Wash + Glassy Fill) ---
  // Wash lifts the value above the dusky parchment so the fat glows pearly white
  brush.wash(PAL.fatPearl, 175);
  for (let r of ribbons) {
    drawShapePoly(r.fatNorthPolyLo, 0.2, true);
    drawShapePoly(r.fatSouthPolyLo, 0.2, true);
  }

  brush.wash(PAL.fatBright, 155);
  for (let r of ribbons) {
    for (let lobe of r.fatLobes) {
      drawShapePoly(lobe, 0.22, true);
    }
  }
  brush.noWash();

  // Watercolor glaze over the fat for organic texture & soft bleed into the rose meat
  brush.fill(PAL.fatBright, 115);
  brush.fillBleed(0.09, "out");
  brush.fillTexture(0.45, 0.3);
  for (let r of ribbons) {
    drawShapePoly(r.fatNorthPolyLo, 0.2, true);
  }

  // Delicate rose-blush transitional shelf where lean meat meets pearly fat
  brush.fill(PAL.fatBlush, 80);
  brush.fillBleed(0.15, "out");
  brush.fillTexture(0.5, 0.3);
  for (let r of ribbons) {
    let transPts = [];
    for (let i = 0; i < r.junctionN.length; i += 4) {
      transPts.push([
        lerp(r.junctionN[i][0], r.coastN[i][0], 0.32),
        lerp(r.junctionN[i][1], r.coastN[i][1], 0.32)
      ]);
    }
    for (let i = r.junctionN.length - 1; i >= 0; i -= 4) {
      transPts.push([
        lerp(r.junctionN[i][0], r.inlandFascia[i][0], 0.22),
        lerp(r.junctionN[i][1], r.inlandFascia[i][1], 0.22)
      ]);
    }
    drawShapePoly(transPts, 0.25, true);
  }

  // Cool twilight pearl-lavender shadows in the fat valleys (inlets)
  brush.fill(PAL.fatTwil, 72);
  brush.fillBleed(0.12, "in");
  for (let r of ribbons) {
    for (let k = 15; k < r.coastN.length - 20; k += 28) {
      let valley = [
        r.coastN[k],
        r.coastN[k + 4],
        r.junctionN[k + 6],
        r.junctionN[k - 2]
      ];
      drawShapePoly(valley, 0.2, true);
    }
  }
  brush.noFill();
}

// ============================================================================
// 6. MUSCLE GRAIN, INTRAMUSCULAR FAT MARBLING & WAXY SHEEN
// ============================================================================

function renderProsciuttoDetails(ribbons) {
  brush.noField();

  for (let r of ribbons) {
    const steps = r.coastN.length - 1;

    // 1. Silky Muscle Fiber Striations (following the draped ribbon flow)
    for (let band = 0; band < 26; band++) {
      let v = (band + 0.5) / 26; // 0 = South junction, 1 = North junction
      let iStart = Math.floor(random(0, 25));
      let iEnd = Math.floor(random(steps - 25, steps));
      let fiberPts = [];
      for (let i = iStart; i <= iEnd; i += 5) {
        let jitter = (noise(i * 0.1, band * 2.3, r.noiseOff) - 0.5) * 0.08;
        let vv = constrain(v + jitter, 0.03, 0.97);
        let x = lerp(r.junctionS[i][0], r.junctionN[i][0], vv);
        let y = lerp(r.junctionS[i][1], r.junctionN[i][1], vv);
        fiberPts.push([x, y, 0.5 + 0.6 * Math.sin(((i - iStart) / (iEnd - iStart)) * 180)]);
      }
      let col =
        band % 4 === 0
          ? PAL.oxblood
          : band % 4 === 1
          ? PAL.garnet
          : band % 4 === 2
          ? PAL.roseMid
          : PAL.fatBlush;
      let w = band % 4 === 3 ? 0.42 : 0.55;
      brush.set("cpencil", col, w);
      safeSpline(fiberPts, 0.45);
    }

    // 2. Inland Fascia River & Dendritic Intramuscular Fat Marbling
    // Main fascia vein running down the center of the slice
    let fasciaPts = [];
    for (let i = 4; i < steps - 4; i += 3) {
      let p = r.inlandFascia[i];
      let pres = 0.4 + 0.9 * noise(i * 0.12, r.noiseOff);
      fasciaPts.push([p[0], p[1], pres]);
    }
    brush.set("waxySheen", PAL.fatPearl, 1.15);
    safeSpline(fasciaPts, 0.45);
    brush.set("cpencil", PAL.fatBright, 0.75);
    safeSpline(fasciaPts, 0.45);

    // Branching marbling deltas from the North fat coast into the garnet meat
    for (let i = 10; i < steps - 10; i += 7) {
      let pCoast = r.junctionN[i];
      let pMid = r.inlandFascia[Math.min(steps, i + Math.floor(random(-6, 7)))];
      let pSouth = r.junctionS[Math.min(steps, i + Math.floor(random(-10, 11)))];

      let vein1 = [];
      let segs = 6;
      for (let s = 0; s <= segs; s++) {
        let u = s / segs;
        let bx = lerp(pCoast[0], pMid[0], u) + (noise(i, s * 0.7, r.noiseOff) - 0.5) * 18;
        let by = lerp(pCoast[1], pMid[1], u) + (noise(i + 30, s * 0.7, r.noiseOff) - 0.5) * 18;
        vein1.push([bx, by, (1 - u * 0.65) * 1.1]);
      }
      brush.set("waxySheen", PAL.fatPearl, random(0.55, 0.95));
      safeSpline(vein1, 0.5);

      // Secondary capillary fork into southern muscle cushion
      if (i % 14 === 3) {
        let forkStart = vein1[Math.floor(segs * 0.5)];
        let vein2 = [
          [forkStart[0], forkStart[1], 0.85],
          [
            lerp(forkStart[0], pSouth[0], 0.5) + random(-10, 10),
            lerp(forkStart[1], pSouth[1], 0.5) + random(-10, 10),
            0.55
          ],
          [
            lerp(forkStart[0], pSouth[0], 0.92),
            lerp(forkStart[1], pSouth[1], 0.92),
            0.2
          ]
        ];
        brush.set("cpencil", PAL.fatBright, 0.65);
        safeSpline(vein2, 0.5);
      }
    }

    // 3. Cured Golden-Amber Rind (*Cotenna*) Along the Outer Fat Coastline
    let rindChunks = 6;
    for (let c = 0; c < rindChunks; c++) {
      let i0 = Math.floor((c / rindChunks) * steps);
      let i1 = Math.min(steps, Math.floor(((c + 0.85) / rindChunks) * steps));
      let rPts = [];
      for (let i = i0; i <= i1; i += 2) {
        let pC = r.coastN[i];
        let pJ = r.junctionN[i];
        rPts.push([lerp(pC[0], pJ[0], 0.05), lerp(pC[1], pJ[1], 0.05), 0.9]);
      }
      brush.set("cpencil", PAL.fatRind, 1.35);
      safeSpline(rPts, 0.35);
      brush.set("pen", PAL.fatRindDark, 0.6);
      safeSpline(rPts, 0.35);
    }

    // 4. WAXY SHEEN (Glossy Specular Highlights on Fat Pillows & Draped Meat Crests)
    // A. Specular sheen ridges along the plump pearly fat peninsulas
    for (let k = 6; k < steps - 8; k += 9) {
      let sheenPts = [];
      for (let j = 0; j <= 5; j++) {
        let idx = Math.min(steps, k + j);
        let u = 0.35 + 0.25 * Math.sin(j * 45);
        let sx = lerp(r.junctionN[idx][0], r.coastN[idx][0], u);
        let sy = lerp(r.junctionN[idx][1], r.coastN[idx][1], u);
        let pres = Math.sin((j / 5) * 180) * 1.35 + 0.15;
        sheenPts.push([sx, sy, pres]);
      }
      brush.set("waxySheen", PAL.sheen, 1.25);
      safeSpline(sheenPts, 0.45);
    }

    // B. Glassy waxy sheen along the crests of the draped meat folds
    for (let f of r.folds) {
      let half = Math.floor(f.pts.length / 2);
      if (half >= 4) {
        let crestPts = [];
        for (let j = 1; j < half - 1; j++) {
          let p1 = f.pts[j];
          let p2 = f.pts[f.pts.length - 1 - j];
          let gx = lerp(p1[0], p2[0], 0.28);
          let gy = lerp(p1[1], p2[1], 0.28);
          let pres = Math.sin((j / (half - 1)) * 180) * 1.2 + 0.15;
          crestPts.push([gx, gy, pres]);
        }
        brush.set("waxySheen", PAL.sheen, 0.95);
        safeSpline(crestPts, 0.5);
        brush.set("pen", PAL.sheen, 0.45);
        safeSpline(crestPts, 0.5);
      }
    }

    // C. Tiny glistening waxy moisture / fat micro-beads
    for (let b = 0; b < 32; b++) {
      let idx = Math.floor(random(8, steps - 8));
      let u = random(0.15, 0.9);
      let bx = lerp(r.junctionS[idx][0], r.coastN[idx][0], u);
      let by = lerp(r.junctionS[idx][1], r.coastN[idx][1], u);
      brush.set("pen", PAL.sheen, random(0.55, 0.95));
      brush.line(bx, by, bx + random(2, 5.5), by + random(-2, 2));
    }
  }
}

// ============================================================================
// 8. PORTOLAN COASTLINE INK CONTOURS, HATCHING & BAY SHOAL STIPPLING
// ============================================================================

function renderPortolanCoastlines(ribbons) {
  brush.noField();
  brush.noFill();

  for (let r of ribbons) {
    const steps = r.coastN.length - 1;

    // Crisp iron-gall brown ink coastline along the meandering North fat edge
    brush.set("rotring", PAL.inkDark, 0.68);
    safeSpline(r.coastN, 0.35);

    // Secondary fine coastal contour slightly inland (classic portolan double-shoreline)
    let innerShoreN = [];
    for (let i = 0; i <= steps; i += 2) {
      innerShoreN.push([
        lerp(r.coastN[i][0], r.junctionN[i][0], 0.08),
        lerp(r.coastN[i][1], r.junctionN[i][1], 0.08)
      ]);
    }
    brush.set("rotring", PAL.inkBrown, 0.32);
    safeSpline(innerShoreN, 0.35);

    // Crisp ink coastline along the South edge
    brush.set("rotring", PAL.inkDark, 0.58);
    safeSpline(r.coastS, 0.35);

    // Portolan coastal shading ticks (short perpendicular hachures on the landward side)
    brush.set("rotring", PAL.inkBrown, 0.28);
    for (let i = 2; i < steps - 2; i += 2) {
      let pC = r.coastN[i];
      let pJ = r.junctionN[i];
      let tickLen = (i % 4 === 0 ? 0.16 : 0.1);
      brush.line(
        pC[0],
        pC[1],
        lerp(pC[0], pJ[0], tickLen),
        lerp(pC[1], pJ[1], tickLen)
      );
    }

    // Shallow-bay sandbank/shoal stippling (dots of brown ink & vermilion in inlets, doubling as pepper/salt grains)
    for (let anc of r.labelAnchors) {
      let spread = anc.bay ? 22 : 14;
      let count = anc.bay ? 24 : 10;
      for (let d = 0; d < count; d++) {
        let distOut = random(3, spread);
        let lat = random(-spread * 0.9, spread * 0.9);
        let px = anc.x + anc.nx * distOut - anc.ny * lat;
        let py = anc.y + anc.ny * distOut + anc.nx * lat;
        let col = d % 3 === 0 ? PAL.vermilion : PAL.inkDark;
        brush.set("rotring", col, random(0.45, 0.75));
        brush.line(px, py, px + 0.8, py + 0.4);
      }
    }

    // Tiny offshore "islets" of shaved fat & meat flecks near major capes
    for (let i = 0; i < r.labelAnchors.length; i += 2) {
      let anc = r.labelAnchors[i];
      if (anc.bay) continue;
      let ix = anc.x + anc.nx * random(10, 18) - anc.ny * random(-8, 8);
      let iy = anc.y + anc.ny * random(10, 18) + anc.nx * random(-8, 8);
      brush.noStroke();
      brush.wash(PAL.fatPearl, 175);
      brush.circle(ix, iy, random(3.2, 5.8), 0.45);
      brush.noWash();
      brush.set("rotring", PAL.inkDark, 0.45);
      brush.circle(ix, iy, random(3.2, 5.8), 0.45);
    }
  }
}

// ============================================================================
// 9. TWO PEN-DRAWN COMPASS ROSES
// ============================================================================

function drawCompassRose(cx, cy, R, isPrimary) {
  brush.noField();

  // Subtle parchment clearing / aureole inside compass rings
  brush.noStroke();
  brush.wash(PAL.parchGlow, 145);
  brush.circle(cx, cy, R * 0.42, 0.15);
  brush.noWash();

  // Concentric outer degree rings
  brush.set("rotring", PAL.inkDark, 0.65);
  brush.circle(cx, cy, R, 0.08);
  brush.set("rotring", PAL.inkBrown, 0.42);
  brush.circle(cx, cy, R * 0.93, 0.08);
  brush.circle(cx, cy, R * 0.78, 0.08);

  // Degree ticks between outer rings
  for (let a = 0; a < 360; a += 5) {
    let rIn = a % 15 === 0 ? R * 0.78 : R * 0.93;
    let col = a % 45 === 0 ? PAL.vermilion : PAL.inkBrown;
    brush.set("rotring", col, a % 15 === 0 ? 0.45 : 0.28);
    brush.line(cx + cos(a) * rIn, cy + sin(a) * rIn, cx + cos(a) * R, cy + sin(a) * R);
  }

  // 16-Point Wind Rose Star (drawn back-to-front: Quarter-winds -> Half-winds -> Principal winds)
  const layers = [
    { step: 45, offset: 22.5, rTip: R * 0.76, rBase: R * 0.16, wAng: 9, colL: PAL.verdigris, colR: PAL.verdigrisDark },
    { step: 45, offset: 0, rTip: R * 0.92, rBase: R * 0.22, wAng: 12, colL: PAL.vermilionLight, colR: PAL.vermilionDark }
  ];

  for (let lay of layers) {
    for (let a = lay.offset; a < 360; a += lay.step) {
      let tip = [cx + cos(a) * lay.rTip, cy + sin(a) * lay.rTip];
      let left = [cx + cos(a - lay.wAng) * lay.rBase, cy + sin(a - lay.wAng) * lay.rBase];
      let right = [cx + cos(a + lay.wAng) * lay.rBase, cy + sin(a + lay.wAng) * lay.rBase];
      let cen = [cx, cy];

      // Colored watercolor/wash halves of each wind pointer
      brush.noStroke();
      brush.wash(lay.colL, 175);
      drawShapePoly([cen, left, tip], 0.05, true);
      brush.wash(lay.colR, 195);
      drawShapePoly([cen, tip, right], 0.05, true);
      brush.noWash();

      // Pen-drawn hatching on the shaded half of the pointer
      brush.set("rotring", PAL.inkDark, 0.28);
      for (let h = 0.2; h <= 0.85; h += 0.16) {
        let hx1 = lerp(cen[0], tip[0], h);
        let hy1 = lerp(cen[1], tip[1], h);
        let hx2 = lerp(right[0], tip[0], h);
        let hy2 = lerp(right[1], tip[1], h);
        brush.line(hx1, hy1, hx2, hy2);
      }

      // Crisp ink outlines
      brush.set("rotring", PAL.inkDark, 0.52);
      brush.line(left[0], left[1], tip[0], tip[1]);
      brush.line(right[0], right[1], tip[0], tip[1]);
      brush.line(cen[0], cen[1], tip[0], tip[1]);
    }
  }

  // Center medallion
  brush.noStroke();
  brush.wash(PAL.ochreGold, 190);
  brush.circle(cx, cy, R * 0.14, 0.1);
  brush.wash(PAL.vermilion, 180);
  brush.circle(cx, cy, R * 0.07, 0.1);
  brush.noWash();

  brush.set("rotring", PAL.inkDark, 0.55);
  brush.circle(cx, cy, R * 0.14, 0.1);
  brush.circle(cx, cy, R * 0.07, 0.1);

  // Ornate North Fleur-de-Lis (at angle -90 deg = North / Tramontana)
  let ny = cy - R * 0.93;
  let fScale = isPrimary ? 1.0 : 0.82;
  let fCenter = [
    [cx, ny - 28 * fScale],
    [cx - 6 * fScale, ny - 10 * fScale],
    [cx, ny + 2 * fScale],
    [cx + 6 * fScale, ny - 10 * fScale]
  ];
  brush.noStroke();
  brush.wash(PAL.vermilion, 200);
  drawShapePoly(fCenter, 0.2, true);
  brush.noWash();

  brush.set("rotring", PAL.inkDark, 0.55);
  drawShapePoly(fCenter, 0.2, true);
  safeSpline(
    [
      [cx, ny - 4 * fScale],
      [cx - 12 * fScale, ny - 14 * fScale],
      [cx - 16 * fScale, ny - 6 * fScale],
      [cx - 8 * fScale, ny - 2 * fScale]
    ],
    0.5
  );
  safeSpline(
    [
      [cx, ny - 4 * fScale],
      [cx + 12 * fScale, ny - 14 * fScale],
      [cx + 16 * fScale, ny - 6 * fScale],
      [cx + 8 * fScale, ny - 2 * fScale]
    ],
    0.5
  );

  // Traditional Mediterranean Wind Initials around the rose
  if (isPrimary) {
    const winds = [
      { a: -90, lbl: "T", d: R + 32 },
      { a: -45, lbl: "G", d: R + 14 },
      { a: 0, lbl: "L", d: R + 14 },
      { a: 45, lbl: "S", d: R + 14 },
      { a: 90, lbl: "O", d: R + 14 },
      { a: 135, lbl: "A", d: R + 14 },
      { a: 180, lbl: "P", d: R + 14 },
      { a: -135, lbl: "M", d: R + 14 }
    ];
    for (let w of winds) {
      let wx = cx + cos(w.a) * w.d - 4;
      let wy = cy + sin(w.a) * w.d - 5;
      drawCalligraphy(w.lbl, wx, wy, 0, 10.5, PAL.inkDark, 0.5);
    }
  }
}

// ============================================================================
// 10. TINY CARTOGRAPHER'S LETTERING IN BROWN INK ALONG EACH "CAPE"
// ============================================================================

function drawCalligraphy(str, x, y, angleDeg, charH, col, weight) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  let charW = charH * 0.62;
  let spacing = charH * 0.78;
  let slant = 0.22; // Renaissance italic chancery slant

  brush.set("cartoNib", col, weight);

  let cursorX = 0;
  for (let cIdx = 0; cIdx < str.length; cIdx++) {
    let ch = str[cIdx];
    if (ch === " ") {
      cursorX += spacing * 0.65;
      continue;
    }
    let strokes = GLYPHS[ch] || GLYPHS[ch.toUpperCase()];
    if (!strokes) {
      cursorX += spacing * 0.5;
      continue;
    }

    for (let s of strokes) {
      let pts = [];
      for (let p of s) {
        // Local character coords with italic slant
        let lx = cursorX + (p[0] + (1 - p[1]) * slant) * charW;
        let ly = (p[1] - 0.5) * charH;
        // Rotate & translate into canvas space
        let gx = x + lx * ca - ly * sa;
        let gy = y + lx * sa + ly * ca;
        pts.push([gx, gy]);
      }
      if (pts.length === 2) {
        brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
      } else {
        safeSpline(pts, 0.35);
      }
    }

    // Advance cursor (narrower for i, l, ., ', r, t)
    let narrow = "il.'rtI".includes(ch) ? 0.62 : "mwMW".includes(ch) ? 1.18 : 0.92;
    cursorX += spacing * narrow;
  }
}

function renderAllCapeLabels(ribbons) {
  brush.noField();

  for (let r of ribbons) {
    for (let anc of r.labelAnchors) {
      // Outward angle from coastline into the parchment sea
      let outAng = atan2(anc.ny, anc.nx);

      // Tiny cartographer's pointer cross / anchor dot just off the cape tip
      let dotX = anc.x + anc.nx * 7;
      let dotY = anc.y + anc.ny * 7;
      let col = anc.rub ? PAL.vermilionDark : PAL.inkDark;

      brush.set("rotring", col, 0.45);
      brush.circle(dotX, dotY, 1.6, 0.2);
      brush.line(anc.x + anc.nx * 2, anc.y + anc.ny * 2, dotX - anc.nx * 1.5, dotY - anc.ny * 1.5);

      // Orient text so it is always right-side up (-85 deg to +85 deg)
      let textAng = outAng;
      let startDist = 14;
      let textLen = anc.name.length * 6.8;

      if (cos(outAng) < 0) {
        // Pointing left: flip text angle by 180 so letters read left-to-right toward the cape
        textAng = outAng + 180;
        let tx = anc.x + anc.nx * (startDist + textLen);
        let ty = anc.y + anc.ny * (startDist + textLen);
        drawCalligraphy(anc.name, tx, ty, textAng, 9.2, col, anc.rub ? 0.42 : 0.38);
      } else {
        let tx = anc.x + anc.nx * startDist;
        let ty = anc.y + anc.ny * startDist;
        drawCalligraphy(anc.name, tx, ty, textAng, 9.2, col, anc.rub ? 0.42 : 0.38);
      }
    }
  }
}

// ============================================================================
// 11. CARTOGRAPHIC BORDER FRAME, DEGREE SCALE & SCHOLARLY CARTOUCHE
// ============================================================================

function drawMapFrameAndScale() {
  brush.noField();
  brush.noFill();

  const mOut = 38;
  const mMid = 46;
  const mIn = 56;
  const wOut = 1200 - mOut * 2;
  const wMid = 1200 - mMid * 2;
  const wIn = 1200 - mIn * 2;

  // Shaded border band wash
  brush.noStroke();
  brush.fill(PAL.parchTwil1, 45);
  brush.fillBleed(0.1, "in");
  brush.rect(mOut, mOut, wOut, mIn - mOut);
  brush.rect(mOut, 1200 - mIn, wOut, mIn - mOut);
  brush.rect(mOut, mIn, mIn - mOut, wIn);
  brush.rect(1200 - mIn, mIn, mIn - mOut, wIn);
  brush.noFill();

  // Triple-ruled cartographic border lines
  brush.set("rotring", PAL.inkDark, 0.85);
  brush.rect(mOut, mOut, wOut, wOut);
  brush.set("rotring", PAL.inkBrown, 0.45);
  brush.rect(mMid, mMid, wMid, wMid);
  brush.set("rotring", PAL.inkDark, 0.7);
  brush.rect(mIn, mIn, wIn, wIn);

  // Alternating latitude/longitude degree scale blocks along inner track
  let segLen = wIn / 36;
  for (let i = 0; i < 36; i++) {
    let p0 = mIn + i * segLen;
    let p1 = p0 + segLen;

    // Tick marks on all 4 edges
    brush.set("rotring", PAL.inkDark, 0.45);
    brush.line(p0, mMid, p0, mIn);
    brush.line(p0, 1200 - mIn, p0, 1200 - mMid);
    brush.line(mMid, p0, mIn, p0);
    brush.line(1200 - mIn, p0, 1200 - mMid, p0);

    // Alternating shaded degree bars in brown and faded vermilion
    if (i % 2 === 0) {
      let col = i % 4 === 0 ? PAL.inkBrown : PAL.vermilion;
      brush.set("rotring", col, 0.35);
      for (let h = 2; h < segLen - 1; h += 3.5) {
        brush.line(p0 + h, mMid + 1.5, p0 + h, mIn - 1.5);
        brush.line(p0 + h, 1200 - mIn + 1.5, p0 + h, 1200 - mMid - 1.5);
        brush.line(mMid + 1.5, p0 + h, mIn - 1.5, p0 + h);
        brush.line(1200 - mIn + 1.5, p0 + h, 1200 - mMid - 1.5, p0 + h);
      }
    }
  }

  // Corner foliate/compass bosses
  const cPts = [
    [mMid, mMid],
    [1200 - mMid, mMid],
    [mMid, 1200 - mMid],
    [1200 - mMid, 1200 - mMid]
  ];
  for (let c of cPts) {
    brush.noStroke();
    brush.wash(PAL.vermilion, 175);
    brush.circle(c[0], c[1], 7, 0.15);
    brush.noWash();
    brush.set("rotring", PAL.inkDark, 0.55);
    brush.circle(c[0], c[1], 7, 0.15);
  }

  // Scholarly Title Banner & Scale Bar in Upper-Left / Lower-Right
  // Title inscription at top left sea
  drawCalligraphy("CARTA MARINA PROSCIUTTI", 92, 92, 0, 13.5, PAL.inkDark, 0.58);
  drawCalligraphy("Tabula Hydrographica Carnis Salatae et Lardi", 92, 112, 0, 9.5, PAL.vermilionDark, 0.42);

  // Navigator's Scale Bar & Brass Dividers in lower-left corner
  const sx = 95,
    sy = 1095,
    sw = 220,
    sh = 12;
  brush.noStroke();
  brush.wash(PAL.parchGlow, 150);
  brush.rect(sx - 10, sy - 28, sw + 20, 48);
  brush.noWash();

  brush.set("rotring", PAL.inkDark, 0.55);
  brush.rect(sx, sy, sw, sh);
  brush.line(sx, sy + sh / 2, sx + sw, sy + sh / 2);

  let unit = sw / 10;
  for (let u = 0; u <= 10; u++) {
    let ux = sx + u * unit;
    brush.line(ux, sy - 3, ux, sy + sh + 3);
    if (u < 10 && u % 2 === 0) {
      brush.noStroke();
      brush.wash(u % 4 === 0 ? PAL.vermilion : PAL.verdigris, 165);
      brush.rect(ux, sy, unit, sh / 2);
      brush.rect(ux, sy + sh / 2, unit, sh / 2);
      brush.noWash();
      brush.set("rotring", PAL.inkDark, 0.45);
    }
  }
  drawCalligraphy("Scala Unciarum et Miliarum", sx + 18, sy - 14, 0, 9.0, PAL.inkDark, 0.4);

  // Pair of navigator's dividers straddling the scale bar
  let pivotX = sx + sw * 0.5,
    pivotY = sy - 54;
  let legL = [sx + unit * 3, sy];
  let legR = [sx + unit * 7, sy];

  brush.noStroke();
  brush.wash(PAL.ochreGold, 180);
  drawShapePoly([
    [pivotX - 4, pivotY],
    [pivotX, pivotY - 5],
    [legL[0], legL[1]]
  ], 0.1, true);
  drawShapePoly([
    [pivotX + 4, pivotY],
    [pivotX, pivotY - 5],
    [legR[0], legR[1]]
  ], 0.1, true);
  brush.circle(pivotX, pivotY - 4, 7, 0.1);
  brush.noWash();

  brush.set("rotring", PAL.inkDark, 0.55);
  brush.line(pivotX - 3, pivotY, legL[0], legL[1]);
  brush.line(pivotX, pivotY - 4, legL[0], legL[1]);
  brush.line(pivotX + 3, pivotY, legR[0], legR[1]);
  brush.line(pivotX, pivotY - 4, legR[0], legR[1]);
  brush.circle(pivotX, pivotY - 4, 7, 0.1);
  brush.circle(pivotX, pivotY - 4, 2.5, 0.1);
}

