// Natural-dye watercolor washes (indigo, madder red, myrobalan yellow, iron-black)
// with confident hand-drawn black pen outlines and fine parallel weave/hair hatching.

const PAL = {
  cottonBase: "#f2e8d5",
  cottonWarm: "#e8dac0",
  cottonDark: "#dcc8a8",
  weaveInk: "#cbb694",
  weaveDark: "#b8a07c",

  inkBlack: "#1a1715",
  inkIron: "#2b2521",
  inkSoft: "#453c35",
  inkFaint: "#6e6053",

  indigoDeep: "#253646",
  indigoMid: "#3c5266",
  indigoWash: "#5b7285",
  indigoPale: "#8396a3",

  madderDeep: "#8f2920",
  madderMid: "#b33f2e",
  madderWash: "#cc6249",
  madderPale: "#de8c73",

  myrobalanDeep: "#ba7a1e",
  myrobalanMid: "#d69c32",
  myrobalanBright: "#e6b94c",
  myrobalanPale: "#edd07e",

  earthDark: "#5c402c",
  earthMid: "#825e43",
  earthWarm: "#a68263",
  earthPale: "#cab092",

