  leafMid: "#5d6e4e",
  leafPale: "#7f8f6b",

  hoofBlack: "#171615",
  alumCream: "#fbf6ec"
};

function polyShape(pts, curvature = 0.25, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function makeEllipsePts(cx, cy, rx, ry, n = 24, rotDeg = 0, wobble = 0) {
  let pts = [];
  let rad = rotDeg * (Math.PI / 180);
  let c = Math.cos(rad);
  let s = Math.sin(rad);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let rMod = 1 + (noise(cx * 0.01 + Math.cos(a) * 1.5, cy * 0.01 + Math.sin(a) * 1.5) - 0.5) * wobble;
    let px = Math.cos(a) * rx * rMod;
    let py = Math.sin(a) * ry * rMod;
    pts.push([cx + px * c - py * s, cy + px * s + py * c]);
  }
  return pts;
}

function makeBlobPts(cx, cy, r, n = 20, irregularity = 0.25, spikiness = 0) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let nv = noise(cx * 0.02 + Math.cos(a) * 1.8, cy * 0.02 + Math.sin(a) * 1.8);
    let spike = (i % 2 === 0 ? 1 : -1) * spikiness;
    let rad = r * (1 + (nv - 0.5) * irregularity + spike);
    pts.push([cx + Math.cos(a) * rad, cy + Math.sin(a) * rad]);
  }
  return pts;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(108);
  noiseSeed(108);

  // Custom reed-pen ("kalam") brush for crisp swelling hand-drawn contours
  brush.add("kalam", {
    type: "default",
    weight: 1.1,
    scatter: 0.04,
    sharpness: 0.85,
    grain: 12,
    opacity: 235,
    spacing: 0.12,
    pressure: [0.35, 1.15, 0.3],
    noise: 0.35
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.cottonBase);

  // 1. WATERCOLOR GROUND & NATURAL-DYE BLEED WASHES (Batched by dye family)
  drawCottonGroundWashes();
  drawSubjectWatercolorWashes();

  // 2. FINE PARALLEL PEN WEAVE (Mimicking hand-spun temple cotton ground)
  drawCottonWeaveTexture();

  // 3. SLENDER FLORAL KALAMKARI BORDER & TEMPLE ARCH
  drawFloralBorderAndArch();

  // 4. ANATOMICAL SHADING, PARALLEL PEN FILLS & DIRECTIONAL FUR TRACTS
  drawForelegsAndHooves();
  drawNeckChestAndCoatHatching();
  drawHornsDetailed();
  drawEarsDetailed();
  drawHeadAndSkullPlanes();
  drawEyesHyperreal();
  drawMuzzleNoseAndBeard();

  // 5. BRASS BELL & MARIGOLD GARLAND (Washes already laid; now hyperreal line & petal work)
  drawNeckCordAndBrassBell();
  drawMarigoldGarlandDetailed();

  // 6. FINAL CONFIDENT OUTLINES, WHISKERS, EYELASHES & SACRED ACCENTS
  drawWhiskersAndFinalAccents();

  noLoop();
}

