function drawCottonWeaveTexture() {
  // Subtle woven khadi threads across background & margins
  brush.set("2H", PAL.weaveInk, 0.22);
  for (let y = 58; y < 1142; y += 9) {
    // Skip dense center of goat head to keep washes luminous, let weave show around & into edges
    if (y > 280 && y < 860) {
      let xLeftEnd = map(noise(y * 0.03), 0, 1, 330, 440);
      let xRightStart = map(noise(y * 0.03 + 99), 0, 1, 760, 870);
      brush.line(58, y, xLeftEnd, y + random(-0.8, 0.8));
      brush.line(xRightStart, y + random(-0.8, 0.8), 1142, y);
    } else {
      brush.line(58, y, 1142, y + random(-1, 1));
    }
  }

  // Vertical warp thread clusters (fine parallel pen texture)
  brush.set("2H", PAL.weaveDark, 0.18);
  for (let x = 62; x < 1138; x += 11) {
    if (x > 370 && x < 830) {
      brush.line(x, 58, x + random(-0.6, 0.6), 275);
      brush.line(x, 890, x + random(-0.6, 0.6), 1142);
    } else {
      brush.line(x, 58, x + random(-1, 1), 1142);
    }
  }

  // Cross-hatched cloth slubs in corners of the inner field
  brush.set("rotring", PAL.weaveDark, 0.18);
  const patches = [
    [155, 175], [1025, 185], [165, 480], [1035, 510],
    [160, 820], [1030, 830], [230, 995], [965, 990], [600, 985]
  ];
  for (let p of patches) {
    let px = p[0], py = p[1];
    for (let i = -28; i <= 28; i += 4) {
      brush.line(px - 32, py + i, px + 32, py + i);
      brush.line(px + i, py - 26, px + i, py + 26);
    }
  }
}

