function drawFloralBorderAndArch() {
  // First: Watercolor dabs for border blossoms & leaves
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.4);

  const step = 68;
  // Collect blossom positions along top, bottom, left, right bands (center of band at 85 and 1115)
  let borderFlowers = [];
  for (let t = 153; t <= 1047; t += step) {
    borderFlowers.push({ x: t, y: 85, horiz: true, idx: Math.round(t / step) });
    borderFlowers.push({ x: t, y: 1115, horiz: true, idx: Math.round(t / step) + 1 });
    borderFlowers.push({ x: 85, y: t, horiz: false, idx: Math.round(t / step) });
    borderFlowers.push({ x: 1115, y: t, horiz: false, idx: Math.round(t / step) + 1 });
  }

  // Madder red blossoms
  brush.fill(PAL.madderWash, 130);
  for (let bf of borderFlowers) {
    if (bf.idx % 2 === 0) {
      polyShape(makeBlobPts(bf.x, bf.y, 13, 12, 0.2, 0.05), 0.25);
    }
  }
  // Myrobalan yellow blossoms
  brush.fill(PAL.myrobalanBright, 135);
  for (let bf of borderFlowers) {
    if (bf.idx % 2 !== 0) {
      polyShape(makeBlobPts(bf.x, bf.y, 13, 12, 0.2, 0.05), 0.25);
    }
  }
  // Corner medallions (madder + myrobalan)
  const corners = [[85, 85], [1115, 85], [85, 1115], [1115, 1115]];
  brush.fill(PAL.madderDeep, 135);
  for (let c of corners) {
    polyShape(makeBlobPts(c[0], c[1], 20, 16, 0.15, 0.08), 0.25);
  }
  brush.fill(PAL.myrobalanBright, 150);
  for (let c of corners) {
    polyShape(makeBlobPts(c[0], c[1], 10, 12, 0.12, 0), 0.25);
  }

  // Olive-indigo leaves along vine
  brush.fill(PAL.leafMid, 115);
  for (let bf of borderFlowers) {
    if (bf.horiz) {
      polyShape(makeEllipsePts(bf.x + 22, bf.y - 9, 10, 5, 10, -25, 0.15), 0.2);
      polyShape(makeEllipsePts(bf.x - 22, bf.y + 9, 10, 5, 10, 25, 0.15), 0.2);
    } else {
      polyShape(makeEllipsePts(bf.x - 9, bf.y + 22, 5, 10, 10, 25, 0.15), 0.2);
      polyShape(makeEllipsePts(bf.x + 9, bf.y - 22, 5, 10, 10, -25, 0.15), 0.2);
    }
  }

  // Confident hand-drawn Kalamkari frame rules
  brush.set("kalam", PAL.inkBlack, 0.72);
  brush.noFill();
  brush.rect(52, 52, 1096, 1096, "corner");
  brush.rect(58, 58, 1084, 1084, "corner");
  brush.rect(112, 112, 976, 976, "corner");
  brush.rect(120, 120, 960, 960, "corner");

  // Fine sawtooth / bead band between inner double rules (112..120) and outer rules (52..58)
  brush.set("rotring", PAL.inkIron, 0.28);
  for (let i = 120; i < 1080; i += 8) {
    brush.line(i, 112, i + 4, 120);
    brush.line(i + 4, 120, i + 8, 112);
    brush.line(i, 1080, i + 4, 1088);
    brush.line(i + 4, 1088, i + 8, 1080);
    brush.line(112, i, 120, i + 4);
    brush.line(120, i + 4, 112, i + 8);
    brush.line(1080, i, 1088, i + 4);
    brush.line(1088, i + 4, 1080, i + 8);
  }

  // Undulating vine stems along all 4 sides
  brush.set("kalam", PAL.inkBlack, 0.45);
  let topVine = [], botVine = [], leftVine = [], rightVine = [];
  for (let x = 115; x <= 1085; x += 17) {
    let wy = Math.sin((x - 115) * 0.092) * 11;
    topVine.push([x, 85 + wy]);
    botVine.push([x, 1115 - wy]);
  }
  for (let y = 115; y <= 1085; y += 17) {
    let wx = Math.sin((y - 115) * 0.092) * 11;
    leftVine.push([85 + wx, y]);
    rightVine.push([1115 - wx, y]);
  }
  brush.spline(topVine, 0.5);
  brush.spline(botVine, 0.5);
  brush.spline(leftVine, 0.5);
  brush.spline(rightVine, 0.5);

  // Hand-drawn ink petals & parallel shading on each border rosette
  for (let bf of borderFlowers) {
    drawSmallRosette(bf.x, bf.y, 13, 8);
    brush.set("rotring", PAL.inkIron, 0.26);
    if (bf.horiz) {
      drawSmallLeaf(bf.x + 22, bf.y - 9, 11, -25);
      drawSmallLeaf(bf.x - 22, bf.y + 9, 11, 155);
    } else {
      drawSmallLeaf(bf.x - 9, bf.y + 22, 11, 65);
      drawSmallLeaf(bf.x + 9, bf.y - 22, 11, -115);
    }
  }

  // Corner lotus medallions
  for (let c of corners) {
    brush.set("kalam", PAL.inkBlack, 0.55);
    brush.rect(c[0] - 27, c[1] - 27, 54, 54, "corner");
    drawSmallRosette(c[0], c[1], 21, 12);
    drawSmallRosette(c[0], c[1], 10, 8);
  }

  // Temple-cloth cusped arch (Torana) in upper inner field + hanging mango-leaf festoon
  brush.set("kalam", PAL.inkIron, 0.42);
  const archLeft = [
    [120, 355], [150, 290], [205, 235], [280, 185], [375, 148], [485, 126], [600, 120]
  ];
  const archRight = [
    [600, 120], [715, 126], [825, 148], [920, 185], [995, 235], [1050, 290], [1080, 355]
  ];
  brush.spline(archLeft, 0.45);
  brush.spline(archRight, 0.45);

  // Scalloped cusps along the arch & delicate spandrel hatching
  brush.set("rotring", PAL.inkSoft, 0.25);
  for (let i = 0; i < archLeft.length - 1; i++) {
    let p1 = archLeft[i], p2 = archLeft[i + 1];
    let mx = (p1[0] + p2[0]) / 2 + 8, my = (p1[1] + p2[1]) / 2 + 12;
    brush.spline([p1, [mx, my], p2], 0.5);
    // Vertical parallel temple-cloth lines in spandrel
    for (let sx = p1[0]; sx < p2[0]; sx += 7) {
      let sy = map(sx, p1[0], p2[0], p1[1], p2[1]);
      brush.line(sx, 120, sx, sy);
    }
  }
  for (let i = 0; i < archRight.length - 1; i++) {
    let p1 = archRight[i], p2 = archRight[i + 1];
    let mx = (p1[0] + p2[0]) / 2 - 8, my = (p1[1] + p2[1]) / 2 + 12;
    brush.spline([p1, [mx, my], p2], 0.5);
    for (let sx = p1[0]; sx < p2[0]; sx += 7) {
      let sy = map(sx, p1[0], p2[0], p1[1], p2[1]);
      brush.line(sx, 120, sx, sy);
    }
  }

  // Lower plinth / threshold band where the goat's iron-black hooves stand
  brush.set("kalam", PAL.inkBlack, 0.45);
  brush.line(120, 1052, 1080, 1052);
  brush.set("rotring", PAL.inkSoft, 0.24);
  for (let x = 124; x < 1076; x += 6) {
    brush.line(x, 1052, x - 4, 1080);
  }
}

function drawSmallRosette(cx, cy, r, petals) {
  brush.set("kalam", PAL.inkBlack, 0.36);
  for (let i = 0; i < petals; i++) {
    let a1 = (i / petals) * 360;
    let a2 = ((i + 0.5) / petals) * 360;
    let a3 = ((i + 1) / petals) * 360;
    let p1 = [cx + cos(a1) * r * 0.28, cy + sin(a1) * r * 0.28];
    let p2 = [cx + cos(a2) * r, cy + sin(a2) * r];
    let p3 = [cx + cos(a3) * r * 0.28, cy + sin(a3) * r * 0.28];
    brush.spline([p1, p2, p3], 0.5);
    // Fine internal petal vein
    brush.set("rotring", PAL.inkIron, 0.2);
    brush.line(cx + cos(a2) * r * 0.32, cy + sin(a2) * r * 0.32, cx + cos(a2) * r * 0.78, cy + sin(a2) * r * 0.78);
    brush.set("kalam", PAL.inkBlack, 0.36);
  }
  brush.circle(cx, cy, r * 0.26, 0.15);
}

function drawSmallLeaf(cx, cy, len, angleDeg) {
  let c = cos(angleDeg), s = sin(angleDeg);
  let nx = -s, ny = c;
  let p0 = [cx - c * len * 0.5, cy - s * len * 0.5];
  let pTip = [cx + c * len * 0.6, cy + s * len * 0.6];
  let pTop = [cx + nx * len * 0.28, cy + ny * len * 0.28];
  let pBot = [cx - nx * len * 0.28, cy - ny * len * 0.28];
  brush.set("kalam", PAL.inkBlack, 0.3);
  brush.spline([p0, pTop, pTip], 0.45);
  brush.spline([p0, pBot, pTip], 0.45);
  brush.set("rotring", PAL.inkIron, 0.18);
  brush.line(p0[0], p0[1], pTip[0], pTip[1]);
}

