function drawHairTract(cx, cy, len, angleDeg, count, spreadW, spreadH, curveAmt, col, w) {
  brush.set("rotring", col, w);
  for (let i = 0; i < count; i++) {
    let ox = random(-spreadW * 0.5, spreadW * 0.5);
    let oy = random(-spreadH * 0.5, spreadH * 0.5);
    let sx = cx + ox;
    let sy = cy + oy;
    let a = angleDeg + random(-8, 8);
    let l = len * random(0.75, 1.25);
    let mx = sx + cos(a) * l * 0.5 + cos(a + 90) * curveAmt * random(0.6, 1.4);
    let my = sy + sin(a) * l * 0.5 + sin(a + 90) * curveAmt * random(0.6, 1.4);
    let ex = sx + cos(a + curveAmt * 0.8) * l;
    let ey = sy + sin(a + curveAmt * 0.8) * l;
    brush.spline([[sx, sy], [mx, my], [ex, ey]], 0.45);
  }
}

function drawForelegsAndHooves() {
  // Forelegs at xCenter = 470 (left) and 730 (right), y = 840..1070
  const legs = [
    { cx: 470, side: -1 },
    { cx: 730, side: 1 }
