  for (let leg of legs) {
    let cx = leg.cx;
    let s = leg.side;

    // Parallel cylindrical pen hatching along cannon bone & carpal joint (knee at y=895)
    brush.set("rotring", PAL.inkSoft, 0.24);
    for (let y = 845; y <= 1005; y += 3.5) {
      let halfW = y < 910 ? map(y, 845, 900, 42, 30) : map(y, 900, 1005, 30, 26);
      // Horizontal form-following contour hatch on shadow side
      let x0 = cx - halfW;
      let x1 = cx + halfW;
      brush.spline([
        [x0, y],
        [cx, y + 4],
        [x1, y]
      ], 0.4);
    }

    // Fine vertical tendon & hair direction lines down the shin
    drawHairTract(cx, 865, 28, 90 + s * 3, 45, 68, 45, s * 3, PAL.inkIron, 0.26);
    drawHairTract(cx, 930, 26, 90, 42, 52, 55, -s * 2, PAL.inkBlack, 0.25);
    drawHairTract(cx, 985, 24, 90 - s * 4, 48, 56, 30, s * 4, PAL.inkBlack, 0.3);

    // Shaggy fetlock tufts overhanging the coronary band of the hooves
    brush.set("kalam", PAL.inkBlack, 0.42);
    for (let tx = cx - 32; tx <= cx + 32; tx += 5) {
      let droop = random(16, 26);
      let flare = (tx - cx) * 0.35;
      brush.spline([
        [tx, 992 + random(-4, 4)],
        [tx + flare * 0.5, 992 + droop * 0.6],
        [tx + flare, 992 + droop]
      ], 0.45);
    }

    // Dewclaws on outer-back aspect of fetlock
    let dcx = cx + s * 28;
    brush.set("kalam", PAL.inkBlack, 0.5);
    brush.spline([[dcx - s * 4, 978], [dcx + s * 11, 990], [dcx + s * 5, 1004], [dcx - s * 5, 995]], 0.4);

    // IRON-BLACK CLOVEN HOOVES (y = 1006..1068)
    // Medial digit & lateral digit separated by sharp interdigital cleft at cx
    const digits = [
      { xOuter: cx - 34, xInner: cx - 3, dir: -1 },
      { xOuter: cx + 34, xInner: cx + 3, dir: 1 }
    ];

    for (let d of digits) {
      // Dense keratin growth striations & vertical glossy iron-black hatching
      brush.set("rotring", PAL.inkBlack, 0.28);
      for (let vy = 1010; vy <= 1065; vy += 2.5) {
        let t = (vy - 1010) / 55;
        let ox = d.xOuter + d.dir * t * 9;
        let ix = d.xInner - d.dir * t * 1.5;
        brush.spline([
          [ix, vy],
          [(ix + ox) * 0.5, vy - 2.5],
          [ox, vy + 2]
        ], 0.35);
      }

      // Vertical shadow hatching along hoof wall
      for (let f = 0; f <= 1; f += 0.08) {
        if (f > 0.25 && f < 0.48) continue; // Leave slender indigo/alum specular vertical strip
        let topX = lerp(d.xInner, d.xOuter, f);
        let botX = lerp(d.xInner - d.dir * 1.5, d.xOuter + d.dir * 9, f);
        brush.line(topX, 1009, botX, 1066);
      }

      // Subtle specular reflection line on polished black hoof keratin
      brush.set("rotring", PAL.indigoPale, 0.32);
      let specTop = lerp(d.xInner, d.xOuter, 0.36);
      let specBot = lerp(d.xInner, d.xOuter + d.dir * 9, 0.36);
      brush.line(specTop, 1014, specBot, 1060);

      // Authoritative hand-drawn black pen outline of each cloven hoof digit
      brush.set("kalam", PAL.inkBlack, 0.72);
      brush.spline([
        [d.xInner, 1008],
        [d.xInner - d.dir * 2, 1038],
        [d.xInner - d.dir * 1.5, 1066],
        [(d.xInner + d.xOuter) * 0.5 + d.dir * 4, 1069],
        [d.xOuter + d.dir * 9, 1066],
        [d.xOuter + d.dir * 4, 1035],
        [d.xOuter, 1008]
      ], 0.25);
    }

    // Outer leg contour lines with tuft breaks
    brush.set("kalam", PAL.inkBlack, 0.58);
    brush.spline([[cx - 42, 845], [cx - 32, 895], [cx - 28, 955], [cx - 32, 1002]], 0.35);
    brush.spline([[cx + 42, 845], [cx + 32, 895], [cx + 28, 955], [cx + 32, 1002]], 0.35);
  }
}

