function drawHornsDetailed() {
  // Majestic scimitar-swept ridged goat horns
  const sides = [-1, 1];
  for (let s of sides) {
    let spine = [];
    const steps = 42;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      // Start at frontal skull boss (600 + s*48, 286), sweep up and out to (600 + s*242, 168)
      let x = 600 + s * (46 + Math.pow(t, 1.18) * 198);
      let y = 286 - Math.sin(t * Math.PI * 0.72) * 138 - t * 12;
      let r = (1 - t * 0.78) * 33 + 4;
      // Tangent angle
      let tx = s * 1.18 * Math.pow(Math.max(0.01, t), 0.18) * 198;
      let ty = -Math.cos(t * Math.PI * 0.72) * Math.PI * 0.72 * 138 - 12;
      let len = Math.hypot(tx, ty);
      let nx = -ty / len;
      let ny = tx / len;
      spine.push({ x, y, r, nx, ny, t });
    }

    // Build upper and lower serrated horn profiles (keratin growth rings create ribbed notches)
    let upperPts = [];
    let lowerPts = [];
    for (let i = 0; i < spine.length; i++) {
      let p = spine[i];
      let rib = (i % 2 === 0 ? 2.4 : -1.2) * (1 - p.t * 0.6);
      upperPts.push([p.x + p.nx * (p.r + rib), p.y + p.ny * (p.r + rib)]);
      lowerPts.push([p.x - p.nx * (p.r + rib * 0.6), p.y - p.ny * (p.r + rib * 0.6)]);
    }

    // Draw transverse curved keratin growth rings (annuli) along the entire horn
    for (let i = 1; i < spine.length - 1; i++) {
      let p = spine[i];
      let u = upperPts[i];
      let l = lowerPts[i];
      // Bulge the ring forward along the horn growth direction
      let bulgeX = p.x + s * p.r * 0.35;
      let bulgeY = p.y - p.r * 0.15;

      brush.set("kalam", PAL.inkBlack, i % 2 === 0 ? 0.48 : 0.28);
      brush.spline([u, [bulgeX, bulgeY], l], 0.45);

      // Fine longitudinal keratin striations between rings on the lower/shadow half
      if (i < spine.length - 2) {
        let pNext = spine[i + 1];
        brush.set("rotring", PAL.inkIron, 0.22);
        for (let f = -0.9; f <= 0.35; f += 0.18) {
          let sx = p.x + p.nx * p.r * f;
          let sy = p.y + p.ny * p.r * f;
          let ex = pNext.x + pNext.nx * pNext.r * f;
          let ey = pNext.y + pNext.ny * pNext.r * f;
          brush.line(sx, sy, ex, ey);
        }
      }
    }

    // Bold hand-drawn outer contours of the horn
    brush.set("kalam", PAL.inkBlack, 0.72);
    brush.spline(upperPts, 0.35);
    brush.spline(lowerPts, 0.35);

    // Ring of stiff crown hair tufts wrapping around the horn base
    brush.set("kalam", PAL.inkBlack, 0.45);
    let base = spine[0];
    for (let k = -6; k <= 6; k++) {
      let bx = base.x + base.nx * k * 5.2;
      let by = base.y + base.ny * k * 5.2 + 8;
      brush.spline([
        [bx, by + 14],
        [bx + s * 5, by - 4],
        [bx + s * 9, by - 18]
      ], 0.4);
    }
  }
}

