function drawEyesHyperreal() {
  // Frontal-lateral goat eyes with horizontal rectangular slit pupils & concentric lid folds
  const eyeConfigs = [
    { cx: 490, cy: 395, side: -1, tilt: -11 },
    { cx: 710, cy: 395, side: 1, tilt: 11 }
  ];

  for (let e of eyeConfigs) {
    let cx = e.cx, cy = e.cy, s = e.side;

    // 1. Concentric bony orbital & eyelid skin folds (above and below the eye)
    brush.set("rotring", PAL.inkIron, 0.28);
    for (let ring = 1; ring <= 4; ring++) {
      let rx = 28 + ring * 5.5;
      let ry = 19 + ring * 4.5;
      // Upper orbital fold lines
      brush.spline([
        [cx - s * rx * 0.85, cy + s * 4],
        [cx - s * rx * 0.2, cy - ry],
        [cx + s * rx * 0.55, cy - ry * 0.78],
        [cx + s * rx * 0.95, cy + 4]
      ], 0.45);
      // Lower eyelid pouch lines
      brush.spline([
        [cx - s * rx * 0.8, cy + 6],
        [cx, cy + ry * 0.92],
        [cx + s * rx * 0.88, cy + 8]
      ], 0.45);
    }

    // 2. Iris radial stroma fibers (fine radiating pen lines around the pupil)
    brush.set("rotring", PAL.earthDark, 0.2);
    for (let a = 0; a < 360; a += 8) {
      let rIn = 8;
      let rOut = 23;
      let x1 = cx + cos(a) * rIn;
      let y1 = cy + sin(a) * rIn * 0.72;
      let x2 = cx + cos(a) * rOut;
      let y2 = cy + sin(a) * rOut * 0.76;
      brush.line(x1, y1, x2, y2);
    }

    // Dark limbal ring around the golden iris
    brush.set("kalam", PAL.inkBlack, 0.48);
    polyShape(makeEllipsePts(cx, cy, 24, 18, 20, e.tilt, 0.04), 0.35);

    // 3. THE HORIZONTAL RECTANGULAR CAPRINE EYE-SLIT PUPIL
    // Filled with dense iron-black parallel pen strokes + sharp slit contour
    push();
    translate(cx, cy);
    rotate(e.tilt);

    brush.set("rotring", PAL.inkBlack, 0.32);
    for (let py = -4.5; py <= 4.5; py += 0.9) {
      let indent = Math.abs(py) < 1.5 ? 1.2 : 0; // Characteristic slight hourglass constriction of goat pupil
      brush.line(-15.5 + indent, py, 15.5 - indent, py);
    }
    brush.set("kalam", PAL.inkBlack, 0.52);
    polyShape([
      [-15.5, -4.2], [0, -3.4], [15.5, -4.2],
      [16.2, 0], [15.5, 4.2], [0, 3.4], [-15.5, 4.2], [-16.2, 0]
    ], 0.15);

    // Crisp corneal catchlight in alum cream
    brush.set("kalam", PAL.alumCream, 0.58);
    brush.line(-8, -6.5, -2, -6.5);
    brush.line(-7, -5.2, -3, -5.2);
    pop();

    // 4. Heavy upper and lower eyelid margins & medial tear-duct caruncle
    brush.set("kalam", PAL.inkBlack, 0.72);
    // Upper lid margin (confident overhanging arch)
    brush.spline([
      [cx - s * 29, cy + 5],
      [cx - s * 10, cy - 19],
      [cx + s * 14, cy - 16],
      [cx + s * 28, cy + 2]
    ], 0.4);
    // Lower lid margin
    brush.set("kalam", PAL.inkBlack, 0.58);
    brush.spline([
      [cx - s * 29, cy + 5],
      [cx - s * 4, cy + 18],
      [cx + s * 16, cy + 16],
      [cx + s * 28, cy + 2]
    ], 0.4);

    // Medial tear-duct caruncle
    brush.set("kalam", PAL.inkBlack, 0.5);
    brush.circle(cx - s * 26, cy + 4, 3.2, 0.1);

    // 5. Straight projecting upper eyelashes (characteristic of goats, shading the eye from sun)
    brush.set("rotring", PAL.inkBlack, 0.3);
    for (let i = 0; i < 14; i++) {
      let t = i / 13;
      let lx = lerp(cx - s * 18, cx + s * 24, t);
      let ly = cy - 16 + Math.pow(t - 0.45, 2) * 26;
      let ex = lx + s * (8 + t * 10);
      let ey = ly - 7 + t * 9;
      brush.line(lx, ly, ex, ey);
    }
  }
}

function drawMuzzleNoseAndBeard() {
