function getGarlandFlowerCenters() {
  // 15 lush marigold blossoms forming a heavy catenary garland + 2 hanging tassel blooms
  let centers = [];
  const n = 15;
  for (let i = 0; i < n; i++) {
    let u = (i / (n - 1)) * 2 - 1; // -1 to +1
    let x = 600 + u * 212;
    let y = 528 + (1 - u * u) * 304;
    let r = map(1 - Math.abs(u), 0, 1, 27, 36);
    // Avoid overlapping the center of the brass bell (bell sits at 600, 688..788, garland drapes right below & around it)
    let type = (i % 3 === 1) ? "crimson" : (i % 2 === 0 ? "yellow" : "saffron");
    let tangentAngle = atan2(-2 * u * 304, 212);
    centers.push({ x, y, r, type, angle: tangentAngle });
  }
  // Hanging central floral tassel below the bottom-most marigold
  centers.push({ x: 600, y: 882, r: 25, type: "crimson", angle: 90 });
  centers.push({ x: 600, y: 924, r: 19, type: "yellow", angle: 90 });
  return centers;
}

function drawMarigoldGarlandDetailed() {
  const garlandPts = getGarlandFlowerCenters();

  // First: Draw mango/ashoka leaves peeking out from behind the marigold spheres
  for (let i = 0; i < garlandPts.length - 2; i++) {
    let g = garlandPts[i];
    for (let side of [-1, 1]) {
      let la = g.angle + side * 78 + random(-8, 8);
      let lx = g.x + cos(la) * (g.r + 12);
      let ly = g.y + sin(la) * (g.r + 12);
      drawDetailedGarlandLeaf(lx, ly, 26, la);
    }
  }

  // Second: Draw every marigold blossom with concentric tiers of ruffled, scalloped hand-drawn petals
  for (let i = 0; i < garlandPts.length; i++) {
    let g = garlandPts[i];
    drawHyperrealMarigold(g.x, g.y, g.r, g.type);
  }

  // Hanging cotton thread tassel at the very bottom of the garland (600, 942..982)
  brush.set("kalam", PAL.madderDeep, 0.52);
  for (let s = -4; s <= 4; s++) {
    brush.spline([
      [600 + s * 1.2, 942],
