  brush.set("kalam", PAL.inkBlack, 0.55);
  brush.line(593, 945, 607, 945);
  brush.line(593, 949, 607, 949);
}

function drawDetailedGarlandLeaf(cx, cy, len, angleDeg) {
  let c = cos(angleDeg), s = sin(angleDeg);
  let nx = -s, ny = c;
  let pBase = [cx - c * len * 0.45, cy - s * len * 0.45];
  let pTip = [cx + c * len * 0.65, cy + s * len * 0.65];
  let pSide1 = [cx + nx * len * 0.28, cy + ny * len * 0.28];
  let pSide2 = [cx - nx * len * 0.28, cy - ny * len * 0.28];

  // Parallel vein hatching inside leaf
  brush.set("rotring", PAL.inkIron, 0.2);
  for (let t = -0.3; t <= 0.45; t += 0.12) {
    let vx = cx + c * len * t;
    let vy = cy + s * len * t;
    let w = (1 - Math.abs(t) * 1.4) * len * 0.25;
    brush.line(vx, vy, vx + (c * 0.4 + nx * 0.9) * w, vy + (s * 0.4 + ny * 0.9) * w);
    brush.line(vx, vy, vx + (c * 0.4 - nx * 0.9) * w, vy + (s * 0.4 - ny * 0.9) * w);
  }

  // Confident hand-drawn leaf outline & midrib
  brush.set("kalam", PAL.inkBlack, 0.45);
  brush.spline([pBase, pSide1, pTip], 0.45);
  brush.spline([pBase, pSide2, pTip], 0.45);
  brush.set("rotring", PAL.inkBlack, 0.28);
  brush.line(pBase[0], pBase[1], pTip[0], pTip[1]);
}

function drawHyperrealMarigold(cx, cy, rad, type) {
  // Concentric rings of tightly packed, ruffled cup-like marigold florets (outer to inner)
  const rings = [
    { rFrac: 1.0, count: 18, petalW: 0.34, weight: 0.44 },
    { rFrac: 0.76, count: 14, petalW: 0.38, weight: 0.38 },
    { rFrac: 0.52, count: 11, petalW: 0.42, weight: 0.34 },
    { rFrac: 0.28, count: 7, petalW: 0.5, weight: 0.3 }
  ];

  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let rg = rings[rIdx];
    let r = rad * rg.rFrac;
    let rInner = r * 0.58;
    let rotOffset = rIdx * 17;

    for (let i = 0; i < rg.count; i++) {
      let aMid = (i / rg.count) * 360 + rotOffset + random(-3, 3);
      let aSpan = (360 / rg.count) * 0.62;
      let a1 = aMid - aSpan;
      let a2 = aMid + aSpan;
      let aNotch1 = aMid - aSpan * 0.32;
      let aNotch2 = aMid + aSpan * 0.32;

      let pStart = [cx + cos(a1) * rInner, cy + sin(a1) * rInner];
      let pLobe1 = [cx + cos(aNotch1) * (r * 1.04), cy + sin(aNotch1) * (r * 1.04)];
      let pCleft = [cx + cos(aMid) * (r * 0.91), cy + sin(aMid) * (r * 0.91)];
      let pLobe2 = [cx + cos(aNotch2) * (r * 1.04), cy + sin(aNotch2) * (r * 1.04)];
      let pEnd = [cx + cos(a2) * rInner, cy + sin(a2) * rInner];

      // Fine parallel pen shading lines inside the base of each ruffled petal
      brush.set("rotring", type === "crimson" ? PAL.inkBlack : PAL.inkIron, 0.18);
      for (let v = -0.35; v <= 0.35; v += 0.35) {
        let va = aMid + v * aSpan;
        brush.line(
          cx + cos(va) * rInner,
          cy + sin(va) * rInner,
          cx + cos(va) * (r * 0.85),
          cy + sin(va) * (r * 0.85)
        );
      }

      // Crisp hand-drawn ruffled petal edge
      brush.set("kalam", PAL.inkBlack, rg.weight);
      brush.spline([pStart, pLobe1, pCleft, pLobe2, pEnd], 0.45);
    }
  }

  // Dense core whorl of tiny unopened florets in the center
  brush.set("kalam", PAL.inkBlack, 0.35);
  for (let k = 0; k < 6; k++) {
    let a = k * 60;
    brush.arc(cx + cos(a) * 3, cy + sin(a) * 3, 4.5, a, a + 200);
  }
}

