function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Flat Warm Barbershop Mint Background (clipped cleanly around the head/neck silhouette)
  drawMintBackground();

  // 2. Base Umber-Brown & Terracotta Skin Washes (head, ears, neck)
  drawSkinUnderpainting();

  // 3. Sculpted 3D Anatomical Colored-Pencil Shading (muscles, nuchal hollow, ears, creases)
  drawAnatomicalSkinShading();

  // 4. Fine Skin Pores, Rhomboid Nape Grain & Specular Highlights
  drawSkinMicroTexture();

  // 5. Box-Top Hedge Architectural Underlayer (Roof deck, side bevels, rear monolith)
  drawBoxTopUnderlayer();

  // 6. Thousands of Graphite & Blue-Black Coloured-Pencil Ticks, Fade Stipple & Razor Line-Up
  drawClippedHedgeAndFade();

