// =============================================================================
// GEOMETRY & CONTOUR HELPERS
// =============================================================================

function drawPolyShape(pts, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Slight 3D crown arch at the top of the box
function getRoofTopY(x) {
  let u = constrain((x - 334) / (866 - 334), 0, 1);
  return ROOF_TOP_Y - 3.5 * sin(u * 180);
}

// Crown bevel ridge where top deck meets the vertical back plane
function getCrownRidgeY(x) {
  let u = constrain((x - 302) / (898 - 302), 0, 1);
  return CROWN_RIDGE_Y + 7.0 * sin(u * 180);
}

// Outer silhouette X of the head/box/neck on Left (-1) or Right (+1)
function getHeadNeckEdgeX(y, side) {
  // side: -1 for left, +1 for right
  let offset = 0;
  if (y <= CROWN_RIDGE_Y) {
    // Roof side edge sloping outward from y=138 to y=232
    let t = constrain((y - ROOF_TOP_Y) / (CROWN_RIDGE_Y - ROOF_TOP_Y), 0, 1);
    offset = lerp(266, 298, t);
  } else if (y <= 500) {
    // Crisp architectural box side wall tapering slightly inward toward temples
    let t = (y - CROWN_RIDGE_Y) / (500 - CROWN_RIDGE_Y);
    offset = lerp(298, 276, pow(t, 1.05));
  } else if (y <= 725) {
    // Behind-the-ear cranial/mastoid attachment line
    let t = (y - 500) / (725 - 500);
    offset = lerp(276, 256, t) - 4 * sin(t * 180);
  } else if (y <= 885) {
    // Upper neck taper (sternocleidomastoid / splenius contour)
    let t = (y - 725) / (885 - 725);
    offset = lerp(256, 244, sin(t * 90));
  } else {
    // Lower neck / trapezius flare toward shoulders
    let t = (y - 885) / (1200 - 885);
    offset = lerp(244, 362, pow(t, 1.45));
  }
  return CX + side * offset;
}

// Outer ear contour for Left (-1) or Right (+1) ear between y=496 and y=734
function getEarOuterX(y, side) {
  if (y < 496 || y > 734) return getHeadNeckEdgeX(y, side);
  let t = (y - 496) / (734 - 496);
  let attachX = getHeadNeckEdgeX(y, side);
  let protrusion = 0;
  if (t < 0.14) {
    // Upper helix curve emerging from head
    protrusion = 68 * sin((t / 0.14) * 90);
  } else if (t < 0.58) {
    // Outer helix rim
    let u = (t - 0.14) / 0.44;
    protrusion = 68 + 10 * sin(u * 180) - 8 * u;
  } else if (t < 0.86) {
    // Lower helix to earlobe transition
    let u = (t - 0.58) / 0.28;
    protrusion = lerp(60, 42, u) + 4 * sin(u * 180);
  } else {
    // Earlobe curving back into neck at y=734
    let u = (t - 0.86) / 0.14;
    protrusion = 42 * cos(u * 90);
  }
  return attachX + side * protrusion;
}

// Razor-lined lateral boundary of the haircut (including the C-arch behind the ears)
function getHairRazorSideX(y, side) {
  if (y <= 462) {
    return getHeadNeckEdgeX(y, side);
  } else if (y <= 558) {
    // Crisp curved barber C-arch stepping inward behind the ear
    let t = (y - 462) / (558 - 462);
    let smoothT = t * t * (3 - 2 * t);
    let outerX = getHeadNeckEdgeX(462, side);
    let innerX = CX + side * 236;
    return lerp(outerX, innerX, smoothT);
  } else {
    // Razor-straight vertical/slightly tapered lower nape box side line
    let t = constrain((y - 558) / (RAZOR_NAPE_Y - 558), 0, 1);
    return CX + side * lerp(236, 228, t);
  }
}

// Razor-lined bottom nape boundary (with subtle architectural curve across the neck)
function getRazorNapeY(x) {
  let u = constrain((x - (CX - 228)) / 456, 0, 1);
  return RAZOR_NAPE_Y + 5.5 * sin(u * 180);
}

// Internal bevel ridge separating side planes of the box from the central rear wall
function getSideBevelRidgeX(y, side) {
  let t = constrain((y - CROWN_RIDGE_Y) / (FADE_START_Y + 60 - CROWN_RIDGE_Y), 0, 1);
  return CX + side * lerp(232, 214, t);
}

