// =============================================================================
// 3. SCULPTED 3D ANATOMICAL COLORED-PENCIL SHADING
// =============================================================================

// Compute skin lighting & anatomical elevation at (x, y)
function evaluateSkinTone(x, y) {
  let leftEdge = getHeadNeckEdgeX(y, -1);
  let rightEdge = getHeadNeckEdgeX(y, 1);
  let halfW = max(10, (rightEdge - leftEdge) * 0.5);
  let nx = (x - CX) / halfW; // -1 to +1 across neck

  // Overall cylindrical curve of the neck
  let cylinder = sqrt(max(0, 1 - nx * nx));

  // Two vertical semispinalis/trapezius muscle ridges at nx ≈ -0.36 and +0.36
  let leftMuscle = exp(-pow((nx + 0.35) / 0.26, 2));
  let rightMuscle = exp(-pow((nx - 0.35) / 0.26, 2));

  // Central nuchal furrow (vertical depression along nx = 0)
  let furrowDepth = exp(-pow(nx / 0.15, 2)) * constrain((y - 540) / 350, 0.2, 1.0);

  // Occipital prominence swell (y = 440..570) vs suboccipital tuck (y = 585..675)
  let occipitalSwell = 0.28 * exp(-pow((y - 500) / 58, 2)) * cylinder;
  let subOccipitalTuck = -0.22 * exp(-pow((y - 625) / 52, 2));

  // Light source slightly left of center & overhead
  let lightBias = -0.08 * nx;

  let val = 0.25
    + 0.42 * cylinder
    + 0.32 * leftMuscle
    + 0.28 * rightMuscle
    - 0.34 * furrowDepth
    + occipitalSwell
    + subOccipitalTuck
    + lightBias;

  // Rim reflection zone near |nx| > 0.82
  let rimMint = pow(constrain((abs(nx) - 0.78) / 0.22, 0, 1), 1.6);

  return {
    val: constrain(val, 0, 1),
    nx: nx,
    rimMint: rimMint,
    leftMuscle: leftMuscle,
    rightMuscle: rightMuscle,
    furrowDepth: furrowDepth
  };
}

function drawAnatomicalSkinShading() {
  // Group cross-contour colored-pencil strokes into color buckets for speed and richness
  let buckets = {
    deepUmber: [],      // #3B1408
    darkMahogany: [],   // #59210E
    warmSienna: [],     // #7D3418
    richTerracotta: [], // #A64B25
    vividAmber: [],     // #CC6638
    goldenOchre: [],    // #E38452
    specularPeach: [],  // #F2A879
    coolMintRim: []     // #5C756B
  };

  // Sample stratified cross-contour strokes across the neck and lower skull
  for (let y = 430; y <= 1194; y += 5.5) {
    let lx = getHeadNeckEdgeX(y, -1) + 4;
    let rx = getHeadNeckEdgeX(y, 1) - 4;
    for (let x = lx; x <= rx; x += 6.5) {
      let jx = x + random(-2.5, 2.5);
      let jy = y + random(-2.2, 2.2);
      let info = evaluateSkinTone(jx, jy);

      // Cross-contour angle wraps around the muscle pillars and nuchal hollow
      let contourSlope = 14 * sin(info.nx * 180) + 8 * sin(info.nx * 360);
      let angle = contourSlope + random(-14, 14);
      let len = random(11, 22);

      let seg = [jx, jy, angle, len];

      if (info.rimMint > 0.35 && random() < info.rimMint * 0.85) {
        buckets.coolMintRim.push(seg);
      } else if (info.val < 0.38) {
        buckets.deepUmber.push(seg);
      } else if (info.val < 0.52) {
        buckets.darkMahogany.push(seg);
      } else if (info.val < 0.66) {
        buckets.warmSienna.push(seg);
      } else if (info.val < 0.78) {
        buckets.richTerracotta.push(seg);
      } else if (info.val < 0.89) {
        buckets.vividAmber.push(seg);
      } else {
        buckets.goldenOchre.push(seg);
        if (info.val > 0.93 && jy > 650 && random() < 0.55) {
          buckets.specularPeach.push([jx + random(-2, 2), jy + random(-2, 2), angle + 75, random(8, 15)]);
        }
      }
    }
  }

  // Render each tonal colored-pencil pass
  const renderBucket = (arr, brushName, col, weight) => {
    brush.set(brushName, col, weight);
    for (let i = 0; i < arr.length; i++) {
      let [x, y, ang, len] = arr[i];
      let dx = cos(ang) * len * 0.5;
      let dy = sin(ang) * len * 0.5;
      brush.line(x - dx, y - dy, x + dx, y + dy);
    }
  };

  renderBucket(buckets.deepUmber, "skin_pastel", "#3B1408", 1.1);
  renderBucket(buckets.darkMahogany, "skin_pastel", "#59210E", 1.05);
  renderBucket(buckets.warmSienna, "skin_pastel", "#7D3418", 1.0);
  renderBucket(buckets.richTerracotta, "skin_pastel", "#A64B25", 1.0);
  renderBucket(buckets.vividAmber, "skin_pastel", "#CC6638", 1.05);
  renderBucket(buckets.goldenOchre, "skin_pencil", "#E38452", 1.15);
  renderBucket(buckets.specularPeach, "skin_pencil", "#F4AD82", 0.95);
  renderBucket(buckets.coolMintRim, "skin_pencil", "#5D7A6E", 1.1);

  // Sculpt the three horizontal anatomical neck creases
  const creases = [
    { y0: 742, arch: 14, width: 390, strength: 0.95 },
    { y0: 834, arch: 19, width: 410, strength: 1.0 },
    { y0: 942, arch: 22, width: 370, strength: 0.65 }
  ];

  for (let c of creases) {
    let xStart = CX - c.width * 0.5;
    let xEnd = CX + c.width * 0.5;

    // Dark umber crease core
    brush.set("skin_pencil", "#381307", 0.95 * c.strength);
    for (let x = xStart; x < xEnd; x += 4.5) {
      let u = (x - xStart) / c.width;
      let env = sin(u * 180);
      if (random() < env * 0.9) {
        let cy = c.y0 + c.arch * sin(u * 180) + 2.5 * sin(u * 540);
        let ny = c.y0 + c.arch * sin((u + 0.02) * 180);
        brush.line(x, cy + random(-0.8, 0.8), x + 7, ny + random(-0.8, 0.8));
      }
    }

    // Soft mahogany transition just above the crease
    brush.set("skin_pencil", "#692812", 0.85 * c.strength);
    for (let x = xStart + 15; x < xEnd - 15; x += 6) {
      let u = (x - xStart) / c.width;
      let cy = c.y0 + c.arch * sin(u * 180) - 2.2;
      brush.line(x, cy, x + 8, cy + random(-1.5, 1.5));
    }

    // Warm golden-amber lower rim highlight catching overhead light below the fold
    brush.set("skin_pencil", "#E58956", 0.9 * c.strength);
    for (let x = xStart + 25; x < xEnd - 25; x += 5.5) {
      let u = (x - xStart) / c.width;
      let env = pow(sin(u * 180), 1.4);
      if (random() < env * 0.85) {
        let cy = c.y0 + c.arch * sin(u * 180) + 3.2;
        brush.line(x, cy, x + 7, cy + random(-1, 1));
      }
    }
  }

  // Detailed rendering of Left and Right Ears (seen from behind)
  drawEarDetails(-1);
  drawEarDetails(1);
}

function drawEarDetails(side) {
  // 1. Deep retroauricular sulcus (crease where the ear joins the skull)
  brush.set("skin_pencil", "#280C04", 1.25);
  for (let y = 502; y <= 724; y += 3.5) {
    let ax = getHeadNeckEdgeX(y, side);
    let ax2 = getHeadNeckEdgeX(y + 4, side);
    brush.line(ax + side * 1.5, y, ax2 + side * 1.5, y + 4);
    if (y > 520 && y < 700) {
      brush.line(ax + side * 4.5, y, ax + side * 14, y + random(2, 6));
    }
  }

  // 2. Posterior concha bowl (warm sienna & mahogany rounded cartilage)
  brush.set("skin_pastel", "#6E2912", 0.95);
  for (let y = 515; y <= 695; y += 5) {
    let ax = getHeadNeckEdgeX(y, side);
    let ox = getEarOuterX(y, side);
    let midX = lerp(ax, ox, 0.45);
    let ang = side * 68 + random(-12, 12);
    brush.line(midX - cos(ang) * 7, y - sin(ang) * 7, midX + cos(ang) * 7, y + sin(ang) * 7);
  }

  // 3. Subsurface coral-vermilion translucency inside the outer helix & lobe
  brush.set("skin_pencil", "#DF5A2E", 1.1);
  for (let y = 504; y <= 722; y += 3.5) {
    let ax = getHeadNeckEdgeX(y, side);
    let ox = getEarOuterX(y, side);
    let rimInnerX = lerp(ax, ox, 0.72);
    brush.line(rimInnerX, y + random(-2, 2), ox - side * 4, y + random(2, 6));
  }

  // 4. Luminous golden-amber & peach highlight along the curled helix rim
  brush.set("skin_pencil", "#F09B67", 1.0);
  for (let y = 500; y <= 715; y += 3) {
    let ox1 = getEarOuterX(y, side);
    let ox2 = getEarOuterX(y + 4, side);
    brush.line(ox1 - side * 2.5, y, ox2 - side * 2.5, y + 4);
  }

  // 5. Cool mint reflected light on the underside of the helix & lobe
  brush.set("skin_pencil", "#698579", 0.85);
  for (let y = 610; y <= 730; y += 4.5) {
    let ox1 = getEarOuterX(y, side);
    let ox2 = getEarOuterX(y + 4, side);
    brush.line(ox1 - side * 1.0, y, ox2 - side * 1.0, y + 4);
  }
}

// =============================================================================
// 4. FINE SKIN PORES, RHOMBOID NAPE GRAIN & SPECULAR HIGHLIGHTS
// =============================================================================

function drawSkinMicroTexture() {
  let darkPores = [];
  let warmGrain = [];
  let specularDots = [];

  for (let y = 665; y <= 1190; y += 6.5) {
    let lx = getHeadNeckEdgeX(y, -1) + 14;
    let rx = getHeadNeckEdgeX(y, 1) - 14;
    for (let x = lx; x <= rx; x += 6.5) {
      let px = x + random(-2.8, 2.8);
      let py = y + random(-2.8, 2.8);
      let info = evaluateSkinTone(px, py);

      // Subtle diamond rhomboid skin micro-lines (±32 degrees)
      if (random() < 0.52) {
        let ang = (random() < 0.5 ? 32 : -32) + 10 * sin(info.nx * 180) + random(-6, 6);
        warmGrain.push([px, py, ang, random(2.5, 4.8)]);
      }

      // Tiny follicular skin pores in shadow/midtone zones
      if (random() < 0.38) {
        darkPores.push([px, py]);
      }

      // Micro-specular skin sheen on the two vertical muscle crowns & upper nape
      if (info.val > 0.80 && random() < 0.42) {
        specularDots.push([px + random(-1, 1), py + random(-1, 1), random(-25, 25), random(1.2, 2.6)]);
      }
    }
  }

  // Draw fine rhomboid skin grain
  brush.set("hair_fine", "#5E2310", 0.52);
  for (let i = 0; i < warmGrain.length; i++) {
    let [x, y, ang, len] = warmGrain[i];
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Draw follicular skin pores
  brush.set("follicle_stipple", "#441709", 0.58);
  for (let i = 0; i < darkPores.length; i++) {
    let [x, y] = darkPores[i];
    brush.line(x, y, x + 0.7, y + 0.9);
  }

  // Draw tiny warm-white / peach skin specular glints
  brush.set("hair_fine", "#F9C59E", 0.62);
  for (let i = 0; i < specularDots.length; i++) {
    let [x, y, ang, len] = specularDots[i];
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

// =============================================================================
// 5. BOX-TOP HEDGE ARCHITECTURAL UNDERLAYER
// =============================================================================

function drawBoxTopUnderlayer() {
  brush.noStroke();
  brush.noHatch();

  // Plane 1: Top Roof Deck (y = 138 to y = 232) catching overhead barbershop light
  let roofPoly = [];
  for (let x = 334; x <= 866; x += 16) {
    roofPoly.push([x, getRoofTopY(x)]);
  }
  roofPoly.push([866, getRoofTopY(866)]);
  for (let x = 898; x >= 302; x -= 16) {
    roofPoly.push([x, getCrownRidgeY(x)]);
  }
  roofPoly.push([302, getCrownRidgeY(302)]);

  brush.wash("#14223D", 245);
  drawPolyShape(roofPoly, 0);
  brush.noWash();

  // Plane 2 & 3: Left and Right Vertical Bevel Facets (y = 232 to y = 470)
  let leftBevel = [];
  let rightBevel = [];
  for (let y = CROWN_RIDGE_Y; y <= 468; y += 12) {
    leftBevel.push([getHairRazorSideX(y, -1), y]);
    rightBevel.push([getHairRazorSideX(y, 1), y]);
  }
  for (let y = 468; y >= CROWN_RIDGE_Y; y -= 12) {
    leftBevel.push([getSideBevelRidgeX(y, -1), y]);
    rightBevel.push([getSideBevelRidgeX(y, 1), y]);
  }

  brush.wash("#0E1A30", 240);
  drawPolyShape(leftBevel, 0);
  drawPolyShape(rightBevel, 0);
  brush.noWash();

  // Plane 4: Central Monolithic Rear Wall of the Box (y = 232 to y = 445)
  let centerWall = [];
  for (let x = getSideBevelRidgeX(CROWN_RIDGE_Y, -1) - 4; x <= getSideBevelRidgeX(CROWN_RIDGE_Y, 1) + 4; x += 16) {
    centerWall.push([x, getCrownRidgeY(x) - 2]);
  }
  for (let y = CROWN_RIDGE_Y; y <= 445; y += 12) {
    centerWall.push([getSideBevelRidgeX(y, 1) + 4, y]);
  }
  for (let y = 445; y >= CROWN_RIDGE_Y; y -= 12) {
    centerWall.push([getSideBevelRidgeX(y, -1) - 4, y]);
  }

  brush.wash("#080D18", 250);
  drawPolyShape(centerWall, 0);
  brush.noWash();

  // Graduated soft watercolor shadow bands for the upper-to-mid fade (y = 420 to y = 590)
  const fadeBands = [
    { y1: 420, y2: 478, col: "#0C1322", alpha: 185 },
    { y1: 465, y2: 525, col: "#171C28", alpha: 135 },
    { y1: 510, y2: 572, col: "#291B18", alpha: 90 },
    { y1: 558, y2: 622, col: "#3D2016", alpha: 52 }
  ];

  for (let b of fadeBands) {
    let bandPoly = [];
    for (let y = b.y1; y <= b.y2; y += 8) {
      bandPoly.push([getHairRazorSideX(y, -1) + 3, y]);
    }
    for (let y = b.y2; y >= b.y1; y -= 8) {
      bandPoly.push([getHairRazorSideX(y, 1) - 3, y]);
    }
    brush.fill(b.col, b.alpha);
    brush.fillBleed(0.16, "out");
    brush.fillTexture(0.55, 0.15);
    drawPolyShape(bandPoly, 0.08);
    brush.noFill();
  }
}

// =============================================================================
// 6. CLIPPED HEDGE ARCHITECTURE, FADE STIPPLE & RAZOR-LINED EDGE
// =============================================================================

function drawClippedHedgeAndFade() {
  // Batched stroke arrays for high-speed, dense hyperrealist rendering
  let pitchBlackTicks = [];     // #06080E (Core deep shadow ticks)
  let indigoBlackTicks = [];    // #0C1426 (Dense blue-black hair mass)
  let prussianBlueTicks = [];   // #182E57 (Saturated blue-black coloured pencil)
  let cobaltSheenTicks = [];    // #284B87 (Vivid blue sheen on planes & occipital swell)
  let darkGraphiteTicks = [];   // #2E3846 (2B/4B graphite core ticks)
  let silverGraphiteTicks = []; // #5B6F8A (HB graphite architectural bevel highlights)
  let brightSlateTicks = [];    // #8BA2BF (Crown ridge & top-deck specular graphite ticks)
  let mintReflectTicks = [];    // #39666E (Side-bevel ticks catching the mint wall)
  let espressoFadeTicks = [];   // #2B140C (Shortening warm-black fade ticks)
  let umberStippleDots = [];    // #38190E (Lowest skin-fade follicle stipple)
  let graphiteStippleDots = []; // #1E2633 (Crisp blue-graphite follicle stipple)

  // ---------------------------------------------------------------------------
  // A. TOP ROOF DECK PLANE (y = 135..238)
  // ---------------------------------------------------------------------------
  for (let y = ROOF_TOP_Y - 3; y <= CROWN_RIDGE_Y + 8; y += 2.7) {
    let tRoof = constrain((y - ROOF_TOP_Y) / (CROWN_RIDGE_Y - ROOF_TOP_Y), 0, 1);
    let lx = lerp(334, 302, tRoof);
    let rx = lerp(866, 898, tRoof);

    for (let x = lx; x <= rx; x += 2.7) {
      let topLimit = getRoofTopY(x);
      let botLimit = getCrownRidgeY(x);
      if (y < topLimit - 1 || y > botLimit + 2) continue;

      let px = x + random(-1.1, 1.1);
      let py = y + random(-1.0, 1.0);
      let n = noise(px * 0.035, py * 0.035);

      // Clipped coiled afro ticks on the flat top plane (short foreshortened strokes)
      let ang1 = random(-180, 180);
      let ang2 = ang1 + random(65, 115);
      let len = random(3.2, 5.8);

      let distToRidge = abs(py - botLimit);
      if (distToRidge < 7.5) {
        // Sharp architectural Crown Ridge bevel highlight
        brightSlateTicks.push([px, py, random(-22, 22), random(3.5, 6.2)]);
        silverGraphiteTicks.push([px, py, ang1, len]);
      } else if (n > 0.56) {
        silverGraphiteTicks.push([px, py, ang1, len]);
        prussianBlueTicks.push([px + 0.8, py + 0.5, ang2, len * 0.85]);
        if (random() < 0.35) brightSlateTicks.push([px, py, random(-35, 35), len * 0.75]);
      } else if (n > 0.38) {
        cobaltSheenTicks.push([px, py, ang1, len]);
        darkGraphiteTicks.push([px - 0.6, py + 0.6, ang2, len * 0.9]);
      } else {
        indigoBlackTicks.push([px, py, ang1, len]);
        prussianBlueTicks.push([px + 0.5, py - 0.5, ang2, len * 0.85]);
      }
    }
  }

  // ---------------------------------------------------------------------------
  // B. VERTICAL BOX WALLS & GRADUATED SKIN FADE (y = 230..688)
  // ---------------------------------------------------------------------------
  for (let y = CROWN_RIDGE_Y - 2; y <= RAZOR_NAPE_Y + 6; y += 2.8) {
    let lx = getHairRazorSideX(y, -1);
    let rx = getHairRazorSideX(y, 1);

    for (let x = lx; x <= rx; x += 2.8) {
      let crownY = getCrownRidgeY(x);
      let napeY = getRazorNapeY(x);
      if (y < crownY - 1 || y > napeY) continue;

      let px = x + random(-1.1, 1.1);
      let py = min(napeY - 0.4, y + random(-1.1, 1.1));

      // Determine which architectural plane we are on
      let leftRidgeX = getSideBevelRidgeX(py, -1);
      let rightRidgeX = getSideBevelRidgeX(py, 1);
      let onLeftBevel = px < leftRidgeX;
      let onRightBevel = px > rightRidgeX;
      let nearBevelCrease = (abs(px - leftRidgeX) < 6.5 || abs(px - rightRidgeX) < 6.5) && py < 490;

      // Normalized fade progress f: 0.0 in dense box top (y <= 412), 1.0 at razor nape (y = 684)
      // Subtle occipital contour in the fade transition
      let occCurve = 12 * sin(constrain((px - lx) / (rx - lx), 0, 1) * 180);
      let fadeStartLocal = FADE_START_Y + occCurve * 0.4;
      let f = constrain((py - fadeStartLocal) / (napeY - fadeStartLocal), 0, 1);

      let coilNoise = noise(px * 0.04, py * 0.04);
      let microNoise = noise(px * 0.14, py * 0.14);

      if (f <= 0.02) {
        // SOLID CLIPPED HEDGE MONOLITH (y < 418)
        let len = random(4.5, 7.2);
        let a1 = 90 + random(-65, 65);
        let a2 = a1 + random(60, 120);

        // Deep shadow band right under the crown ridge overhang (y = 235..285)
        let underCrownShadow = exp(-pow((py - (crownY + 22)) / 28, 2));
        // Secondary occipital luster band (y = 345..410)
        let occipitalLuster = exp(-pow((py - 375) / 42, 2)) * (1 - abs(px - CX) / 280);

        if (nearBevelCrease) {
          // Crisp architectural corner ridge between side bevel and back wall
          silverGraphiteTicks.push([px, py, 90 + random(-18, 18), len * 0.95]);
          cobaltSheenTicks.push([px + 0.6, py, a1, len * 0.85]);
        } else if (onLeftBevel || onRightBevel) {
          // Side bevel facets catching ambient barbershop mint reflection
          indigoBlackTicks.push([px, py, a1, len]);
          if (coilNoise > 0.46) {
            mintReflectTicks.push([px, py, a2, len * 0.85]);
          } else {
            prussianBlueTicks.push([px, py, a2, len * 0.85]);
          }
          if (microNoise > 0.62) {
            silverGraphiteTicks.push([px, py, 85 + random(-25, 25), len * 0.75]);
          }
        } else {
          // Central Rear Wall of the Box
          pitchBlackTicks.push([px, py, a1, len]);
          if (underCrownShadow > 0.5 && random() < 0.7) {
            indigoBlackTicks.push([px + 0.6, py + 0.6, a2, len]);
          } else if (occipitalLuster > 0.35 && coilNoise > 0.42) {
            cobaltSheenTicks.push([px, py, a2, len * 0.9]);
            if (microNoise > 0.55) silverGraphiteTicks.push([px, py, 90 + random(-30, 30), len * 0.8]);
          } else if (coilNoise > 0.48) {
            prussianBlueTicks.push([px + 0.5, py - 0.4, a2, len * 0.9]);
            darkGraphiteTicks.push([px - 0.4, py + 0.5, a1 + 45, len * 0.8]);
          } else {
            indigoBlackTicks.push([px + 0.5, py + 0.5, a2, len * 0.9]);
          }
        }
      } else {
        // GRADUATED SKIN FADE ZONE (f from 0.02 to 1.0)
        // Natural hair growth flow angle (downward, flaring slightly toward mastoid/sides)
        let nx = (px - CX) / 240;
        let growthAngle = 90 - nx * 16 + random(-22 * (1 - f * 0.6), 22 * (1 - f * 0.6));

        // Density probability drops smoothly down the fade
        let keepProb = lerp(1.0, 0.42, pow(f, 1.15));
        if (random() > keepProb) continue;

        // Tick length shortens continuously from 5.8px down to 0.55px stipple
        let tickLen = lerp(5.8, 0.55, pow(f, 0.78)) * random(0.82, 1.18);

        if (f < 0.34) {
          // Upper Fade: tight 2-tick micro-clusters with skin peeking through
          let a2 = growthAngle + random(-55, 55);
          if (coilNoise > 0.5) {
            indigoBlackTicks.push([px, py, growthAngle, tickLen]);
            prussianBlueTicks.push([px + 0.6, py + 0.4, a2, tickLen * 0.85]);
          } else {
            pitchBlackTicks.push([px, py, growthAngle, tickLen]);
            darkGraphiteTicks.push([px - 0.5, py + 0.5, a2, tickLen * 0.85]);
          }
          if (onLeftBevel || onRightBevel) {
            mintReflectTicks.push([px, py, growthAngle, tickLen * 0.8]);
          }
        } else if (f < 0.68) {
          // Mid Fade: crisp individual directional ticks (1.8px to 3.6px)
          if (microNoise > 0.58) {
            darkGraphiteTicks.push([px, py, growthAngle, tickLen]);
          } else if (microNoise > 0.32) {
            indigoBlackTicks.push([px, py, growthAngle, tickLen]);
          } else {
            espressoFadeTicks.push([px, py, growthAngle, tickLen]);
          }
          // Secondary tiny companion follicle in upper-mid fade
          if (f < 0.52 && random() < 0.45) {
            prussianBlueTicks.push([px + random(-1.2, 1.2), py + random(-1, 1), growthAngle + random(-30, 30), tickLen * 0.8]);
          }
        } else {
          // Lower Fade: pointillist stippled shadow (0.55px to 1.7px)
          if (microNoise > 0.48) {
            umberStippleDots.push([px, py, growthAngle, tickLen]);
          } else {
            graphiteStippleDots.push([px, py, growthAngle, tickLen]);
          }
        }
      }
    }
  }

  // ---------------------------------------------------------------------------
  // C. LASER-CRISP ARCHITECTURAL PERIMETER & RAZOR LINE-UP EDGES
  // ---------------------------------------------------------------------------

  // 1. Top Horizontal Roof Edge (y = 138): hundreds of tiny sheared tips along the hedge line
  for (let x = 334; x <= 866; x += 1.3) {
    let ry = getRoofTopY(x);
    let ang = -90 + random(-24, 24);
    let len = random(2.4, 4.6);
    // Tips terminate within ±0.8px of the mathematical roof line
    let tipX = x + random(-0.5, 0.5);
    let tipY = ry + random(-0.8, 0.8);
    let baseX = tipX - cos(ang) * len;
    let baseY = tipY - sin(ang) * len;
    if (random() < 0.55) {
      indigoBlackTicks.push([ (baseX + tipX) * 0.5, (baseY + tipY) * 0.5, ang, len ]);
    } else {
      prussianBlueTicks.push([ (baseX + tipX) * 0.5, (baseY + tipY) * 0.5, ang, len ]);
    }
  }

  // 2. Left & Right Outer Box Walls (y = 138 to y = 462): sheared vertical hedge walls
  for (let side of [-1, 1]) {
    for (let y = ROOF_TOP_Y; y <= 462; y += 1.4) {
      let ex = (y <= CROWN_RIDGE_Y)
        ? CX + side * lerp(266, 298, (y - ROOF_TOP_Y) / (CROWN_RIDGE_Y - ROOF_TOP_Y))
        : getHeadNeckEdgeX(y, side);
      let ang = (side === -1 ? 180 : 0) + random(-28, 28);
      let len = random(2.6, 5.0);
      let tipX = ex + side * random(-0.7, 0.9);
      let tipY = y + random(-0.6, 0.6);
      let midX = tipX - cos(ang) * len * 0.5;
      let midY = tipY - sin(ang) * len * 0.5;
      if (random() < 0.6) {
        pitchBlackTicks.push([midX, midY, ang, len]);
      } else {
        prussianBlueTicks.push([midX, midY, ang, len]);
      }
    }
  }

  // 3. Behind-the-Ear Razor C-Arches & Lower Vertical Nape Box Sides (y = 462 to y = 684)
  for (let side of [-1, 1]) {
    for (let y = 462; y <= RAZOR_NAPE_Y; y += 1.2) {
      let rx = getHairRazorSideX(y, side);
      let f = constrain((y - FADE_START_Y) / (RAZOR_NAPE_Y - FADE_START_Y), 0, 1);
      let len = lerp(3.2, 0.75, pow(f, 0.75));
      let inwardX = rx - side * (len * 0.5 + random(0.1, 1.4));
      let ang = 90 - side * 20 + random(-18, 18);
      if (f < 0.55) {
        indigoBlackTicks.push([inwardX, y + random(-0.6, 0.6), ang, len]);
      } else {
        graphiteStippleDots.push([inwardX, y + random(-0.5, 0.5), ang, len]);
        if (random() < 0.65) {
          umberStippleDots.push([rx - side * random(0.2, 2.2), y + random(-0.6, 0.6), ang, len * 0.85]);
        }
      }
    }
  }

  // 4. Bottom Horizontal Razor-Lined Nape Edge (x = 372 to x = 828 at y ≈ 684)
  for (let x = CX - 228; x <= CX + 228; x += 1.1) {
    let ny = getRazorNapeY(x);
    let ang = 90 + random(-15, 15);
    let len = random(0.65, 1.45);
    let sy = ny - random(0.3, 2.8);
    if (random() < 0.55) {
      umberStippleDots.push([x + random(-0.5, 0.5), sy, ang, len]);
    } else {
      graphiteStippleDots.push([x + random(-0.5, 0.5), sy, ang, len]);
    }
  }

  // ---------------------------------------------------------------------------
  // D. RENDER ALL HAIR TICK & STIPPLE BATCHES
  // ---------------------------------------------------------------------------
  const renderTicks = (arr, brushName, col, weight) => {
    brush.set(brushName, col, weight);
    for (let i = 0; i < arr.length; i++) {
      let [x, y, ang, len] = arr[i];
      let dx = cos(ang) * len * 0.5;
      let dy = sin(ang) * len * 0.5;
      brush.line(x - dx, y - dy, x + dx, y + dy);
    }
  };

  renderTicks(pitchBlackTicks, "hair_tick", "#06080E", 1.0);
  renderTicks(indigoBlackTicks, "hair_tick", "#0C1426", 0.95);
  renderTicks(espressoFadeTicks, "hair_fine", "#2B140C", 0.9);
  renderTicks(prussianBlueTicks, "hair_tick", "#182E57", 0.9);
  renderTicks(darkGraphiteTicks, "hair_fine", "#2E3846", 0.88);
  renderTicks(mintReflectTicks, "hair_fine", "#39666E", 0.85);
  renderTicks(cobaltSheenTicks, "hair_fine", "#284B87", 0.85);
  renderTicks(silverGraphiteTicks, "hair_fine", "#5B6F8A", 0.82);
  renderTicks(brightSlateTicks, "hair_fine", "#8CA4C2", 0.78);
  renderTicks(umberStippleDots, "follicle_stipple", "#36170B", 0.78);
  renderTicks(graphiteStippleDots, "follicle_stipple", "#1C2432", 0.75);

  // ---------------------------------------------------------------------------
  // E. STRAIGHT-RAZOR LINE-UP HIGHLIGHT & EDGE DEFINITION
  // ---------------------------------------------------------------------------
  // Micro-razor skin highlight (barber blade exfoliation / chalk-pencil trace)
  // 1.5px outside the behind-ear C-arches and bottom nape line
  brush.set("hair_fine", "#F5B88E", 0.75);
  for (let side of [-1, 1]) {
    for (let y = 468; y <= RAZOR_NAPE_Y + 1; y += 2.6) {
      if (random() < 0.82) {
        let rx1 = getHairRazorSideX(y, side) + side * 1.8;
        let rx2 = getHairRazorSideX(y + 2.5, side) + side * 1.8;
        brush.line(rx1, y, rx2, y + 2.5);
      }
    }
  }
  for (let x = CX - 228; x <= CX + 226; x += 2.8) {
    if (random() < 0.8) {
      let ny1 = getRazorNapeY(x) + 1.8;
      let ny2 = getRazorNapeY(x + 2.6) + 1.8;
      brush.line(x, ny1, x + 2.6, ny2);
    }
  }

  // Ultra-fine razor pore line right on the blade boundary
  brush.set("hair_fine", "#2A1108", 0.62);
  for (let side of [-1, 1]) {
    for (let y = 466; y <= RAZOR_NAPE_Y; y += 2.2) {
      if (random() < 0.75) {
        let rx = getHairRazorSideX(y, side);
        brush.line(rx, y, rx - side * 0.8, y + 1.4);
      }
    }
  }
  for (let x = CX - 228; x <= CX + 228; x += 2.2) {
    if (random() < 0.72) {
      let ny = getRazorNapeY(x);
      brush.line(x, ny, x + 1.3, ny - 0.6);
    }
  }
}

// =============================================================================
// 7. LOOSE HAIR CLIPPINGS CLINGING TO THE NECK
// =============================================================================

function drawLooseClippings() {
  let straightClippings = [];
  let curvedClippings = [];
  let microDust = [];

  // Generate natural clusters of freshly sheared clippings on the neck and behind the ears
  const clusterCenters = [
    { x: 455, y: 718, rx: 55, ry: 28, count: 22 }, // Left just below razor nape
    { x: 745, y: 722, rx: 58, ry: 30, count: 24 }, // Right just below razor nape
    { x: 602, y: 748, rx: 45, ry: 35, count: 20 }, // Central upper nuchal furrow & first crease
    { x: 515, y: 832, rx: 65, ry: 26, count: 18 }, // Caught along middle neck crease (left)
    { x: 685, y: 836, rx: 62, ry: 26, count: 16 }, // Caught along middle neck crease (right)
    { x: 596, y: 925, rx: 42, ry: 55, count: 15 }, // Trailing down the central nuchal hollow
    { x: 468, y: 985, rx: 55, ry: 48, count: 12 }, // Left lower trapezius highlight
    { x: 738, y: 1015, rx: 60, ry: 52, count: 14 }, // Right lower trapezius highlight
    { x: 348, y: 585, rx: 12, ry: 42, count: 10 }, // Behind left ear channel
    { x: 852, y: 590, rx: 12, ry: 42, count: 10 }  // Behind right ear channel
  ];

  for (let c of clusterCenters) {
    for (let i = 0; i < c.count; i++) {
      let r = pow(random(), 0.7);
      let theta = random(360);
      let px = c.x + cos(theta) * c.rx * r;
      let py = c.y + sin(theta) * c.ry * r;

      // Ensure clipping is strictly on bare skin
      let lx = getHeadNeckEdgeX(py, -1) + 10;
      let rx = getHeadNeckEdgeX(py, 1) - 10;
      if (px < lx || px > rx || py > 1185) continue;

      let roll = random();
      if (roll < 0.42) {
        // Tiny trimmer dust speck (0.8px to 1.8px)
        microDust.push([px, py, random(360), random(0.8, 1.8)]);
      } else if (roll < 0.78) {
        // Short straight clipper tick (2.4px to 5.2px)
        straightClippings.push([px, py, random(360), random(2.4, 5.2)]);
      } else {
        // Signature tiny C-curl / comma-shaped coil fragment (3.5px to 6.8px)
        curvedClippings.push([
          px, py,
          random(360),
          random(2.2, 4.0),
          random(45, 95) * (random() < 0.5 ? 1 : -1)
        ]);
      }
    }
  }

  // 1. Contact shadows on the warm umber skin (+0.7px, +1.1px offset)
  brush.set("hair_fine", "#361206", 0.65);
  for (let [x, y, ang, len] of straightClippings) {
    let dx = cos(ang) * len * 0.5;
    let dy = sin(ang) * len * 0.5;
    brush.line(x - dx + 0.7, y - dy + 1.1, x + dx + 0.7, y + dy + 1.1);
  }
  for (let [x, y, a1, len, bend] of curvedClippings) {
    let a2 = a1 + bend;
    let xMid = x + cos(a1) * len * 0.55;
    let yMid = y + sin(a1) * len * 0.55;
    let xEnd = xMid + cos(a2) * len * 0.55;
    let yEnd = yMid + sin(a2) * len * 0.55;
    brush.line(x + 0.7, y + 1.1, xMid + 0.7, yMid + 1.1);
    brush.line(xMid + 0.7, yMid + 1.1, xEnd + 0.7, yEnd + 1.1);
  }

  // 2. Render micro trimmer dust specks
  brush.set("follicle_stipple", "#0D1322", 0.75);
  for (let [x, y, ang, len] of microDust) {
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // 3. Render straight & C-curved clippings in deep indigo-black
  brush.set("hair_fine", "#070B14", 0.85);
  for (let [x, y, ang, len] of straightClippings) {
    let dx = cos(ang) * len * 0.5;
    let dy = sin(ang) * len * 0.5;
    brush.line(x - dx, y - dy, x + dx, y + dy);
  }
  for (let [x, y, a1, len, bend] of curvedClippings) {
    let a2 = a1 + bend;
    let xMid = x + cos(a1) * len * 0.55;
    let yMid = y + sin(a1) * len * 0.55;
    let xEnd = xMid + cos(a2) * len * 0.55;
    let yEnd = yMid + sin(a2) * len * 0.55;
    brush.line(x, y, xMid, yMid);
    brush.line(xMid, yMid, xEnd, yEnd);
  }

  // 4. Tiny blue-graphite specular glint on the larger coil clippings
  brush.set("hair_fine", "#2B4D87", 0.55);
  for (let i = 0; i < curvedClippings.length; i += 2) {
    let [x, y, a1, len] = curvedClippings[i];
    brush.line(x, y, x + cos(a1) * len * 0.45, y + sin(a1) * len * 0.45);
  }
}

// Three Magpie Tail Feathers on a Wet Slate Step
// Hyperrealistic p5.brush rendering — translucent watercolor nacre glazes,
// barbule-by-barbule iridescence, hairline pen rachis & splits, charcoal mass slate beaded with water.

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);
}

// ============================================================================
// GEOMETRY & COLOR HELPERS
// ============================================================================

function evalBezierPoint(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let tt = t * t, uu = u * u;
  let uuu = uu * u, ttt = tt * t;
  return {
    x: uuu * p0.x + 3 * uu * t * p1.x + 3 * u * tt * p2.x + ttt * p3.x,
    y: uuu * p0.y + 3 * uu * t * p1.y + 3 * u * tt * p2.y + ttt * p3.y
  };
}

function evalBezierTangent(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let dx = 3 * u * u * (p1.x - p0.x) + 6 * u * t * (p2.x - p1.x) + 3 * t * t * (p3.x - p2.x);
  let dy = 3 * u * u * (p1.y - p0.y) + 6 * u * t * (p2.y - p1.y) + 3 * t * t * (p3.y - p2.y);
  let len = Math.hypot(dx, dy) || 1;
  return { x: dx / len, y: dy / len, rawLen: len };
}

function evalFeatherSpine(f, t) {
  t = constrain(t, 0, 1);
  let pt = evalBezierPoint(f.p0, f.p1, f.p2, f.p3, t);
  let tan = evalBezierTangent(f.p0, f.p1, f.p2, f.p3, t);
  let norm = { x: -tan.y, y: tan.x };
  return { x: pt.x, y: pt.y, tx: tan.x, ty: tan.y, nx: norm.x, ny: norm.y };
}

// Magpie tail feather outer profile width at spine coordinate t, side s (-1 upper/left, +1 lower/right)
function getVaneEnvelopeWidth(f, t, s) {
  if (t <= f.vaneStart) return 0;
  let u = (t - f.vaneStart) / (1 - f.vaneStart);
  u = constrain(u, 0, 1);

  let maxW = s < 0 ? f.wLeft : f.wRight;

  // Smooth emergence from calamus, gradual widening to distal paddle, rounded spatulate tip
  let baseRamp = Math.pow(constrain(u / 0.12, 0, 1), 0.75);
  let paddleSwell = 0.72 + 0.34 * Math.sin(Math.pow(u, 0.85) * Math.PI * 0.88);
  let tipRound = u > 0.86 ? Math.pow(constrain((1 - u) / 0.14, 0, 1), 0.52) : 1.0;

  // Subtle organic undulation along margin
  let edgeWaviness = 1.0 + 0.035 * (noise(f.id * 17 + t * 8, s > 0 ? 5 : 15) - 0.5);

  return maxW * baseRamp * paddleSwell * tipRound * edgeWaviness;
}

// Compute 2D coordinates of a barb originating at shaft t0, side s, at fraction u in [0, 1]
// Incorporates lobe split spread (lobeStart, lobeEnd) for authentic V-cleft separation
function evalBarbPoint(f, t0, s, u, lobeStart, lobeEnd) {
  u = constrain(u, 0, 1);

  // Natural forward angle of barbs along the rachis
  let baseReach = f.barbReach * (1.0 - 0.55 * Math.pow(t0, 2.2));

  // Split perturbation: barbs near a split pull slightly away from the cleft
  let splitShift = 0;
  if (lobeStart !== undefined && lobeEnd !== undefined) {
    let distFromStart = t0 - lobeStart;
    let distToEnd = lobeEnd - t0;
    if (lobeStart > f.vaneStart + 0.02 && distFromStart < 0.045) {
      splitShift += 0.014 * Math.pow(1 - distFromStart / 0.045, 1.6);
    }
    if (lobeEnd < 0.98 && distToEnd < 0.045) {
      splitShift -= 0.012 * Math.pow(1 - distToEnd / 0.045, 1.6);
    }
  }

  let reach = baseReach + splitShift;
  // Curved forward trajectory of a single barb
  let tAlong = constrain(t0 + reach * (1.12 * u - 0.12 * u * u), 0, 0.9995);

  let sp = evalFeatherSpine(f, tAlong);
  let envW = getVaneEnvelopeWidth(f, tAlong, s);

  // Lateral distance from shaft center (accounting for shaft thickness)
  let shaftRadius = f.rachisBaseW * Math.pow(1 - t0 * 0.88, 1.4) * 0.5;
  let lateral = shaftRadius + (envW - shaftRadius) * Math.pow(Math.sin(u * Math.PI * 0.5), 0.82);

  // Slight arch curve of the barb
  let archLift = -s * envW * 0.06 * Math.sin(u * Math.PI);

  return {
    x: sp.x + sp.nx * (s * lateral + archLift),
    y: sp.y + sp.ny * (s * lateral + archLift),
    tAlong: tAlong
  };
}

// Nacre interference phase (0 to 1) across the feather vane (like the inside of an abalone shell)
function getNacrePhase(f, t0, s, u) {
  // Concentric shell-like wave across the vane + longitudinal shift toward feather tip
  let radialShell = Math.pow(Math.abs(u - 0.38) * 1.45, 1.35);
  let longWave = t0 * 1.65 + 0.22 * Math.sin(t0 * 14.0 + s * 1.2);
  let n = noise(f.id * 31 + t0 * 5.5, (s > 0 ? 10 : 20) + u * 3.2);
  let phase = (longWave * 0.58 - radialShell * 0.48 + n * 0.55 + f.phaseOffset) % 1.0;
  if (phase < 0) phase += 1.0;
  return phase;
}

// Iridescent palette lookup for glazes and barbules
const IRID_GLAZES = [
  { name: "obsidian",   hex: "#080c12" },
  { name: "bottleDark", hex: "#083d2e" },
  { name: "bottle",     hex: "#11664c" },
  { name: "emerald",    hex: "#1f8c67" },
  { name: "tealDark",   hex: "#0a4c54" },
  { name: "peacock",    hex: "#157e87" },
  { name: "cyanSheen",  hex: "#2fb3b8" },
  { name: "violetDark", hex: "#2d1942" },
  { name: "violet",     hex: "#522b78" },
  { name: "amethyst",   hex: "#7a429e" },
  { name: "bronzeDark", hex: "#4d3417" },
  { name: "bronze",     hex: "#825923" },
  { name: "copperGold", hex: "#b37f38" }
];

// Map phase + position to specific glaze & barbule colors
function sampleIridescence(f, t0, s, u) {
  let phase = getNacrePhase(f, t0, s, u);
  // Edges and very base are darker melanin
  let edgeDarken = (u < 0.08 || u > 0.92 || t0 < 0.18);
  if (edgeDarken && random() < 0.65) {
    return { glazeIdx: 0, barbHex: "#090d14", sheenHex: "#122429" };
  }

  // Distal paddle (t0 > 0.62) favors violet, bronze, and peacock teal;
  // Mid shaft favors bottle green, peacock teal, and violet ripples.
  let p = (phase + (t0 > 0.62 ? 0.25 : 0.0)) % 1.0;

  if (p < 0.24) {
    // Bottle green zone
    return {
      glazeIdx: p < 0.12 ? 1 : 2,
      barbHex: p < 0.10 ? "#0c4a38" : (p < 0.18 ? "#157355" : "#22966e"),
      sheenHex: "#38b888"
    };
  } else if (p < 0.50) {
    // Peacock teal zone
    return {
      glazeIdx: p < 0.36 ? 4 : 5,
      barbHex: p < 0.34 ? "#0e5c66" : (p < 0.44 ? "#188a94" : "#2eb3bd"),
      sheenHex: "#5cd6de"
    };
  } else if (p < 0.76) {
    // Violet / plum nacre zone
    return {
      glazeIdx: p < 0.62 ? 7 : 8,
      barbHex: p < 0.60 ? "#381f52" : (p < 0.69 ? "#5c3185" : "#8048a8"),
      sheenHex: "#a66bc9"
    };
  } else {
    // Burnished bronze / gold zone
    return {
      glazeIdx: p < 0.88 ? 10 : 11,
      barbHex: p < 0.85 ? "#5c3e1b" : (p < 0.93 ? "#8c6128" : "#b8843c"),
      sheenHex: "#d6a45c"
    };
  }
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // Define the three fanned magpie tail feathers
  // Feather 3 is the longest central rectrix, cropped hard at the top-right border
  const feathers = [
    {
      id: 1, // Lower-right fanned feather
      p0: { x: 165, y: 968 },
      p1: { x: 445, y: 870 },
      p2: { x: 745, y: 762 },
      p3: { x: 1045, y: 655 },
      vaneStart: 0.11,
      wLeft: 62,   // Upper/inner vane
      wRight: 40,  // Lower/outer vane
      rachisBaseW: 6.2,
      barbReach: 0.082,
      phaseOffset: 0.12,
      splitsLeft: [0.33, 0.57, 0.79],
      splitsRight: [0.45, 0.72]
    },
    {
      id: 2, // Upper-left fanned feather
      p0: { x: 112, y: 932 },
      p1: { x: 332, y: 678 },
      p2: { x: 568, y: 410 },
      p3: { x: 818, y: 142 },
      vaneStart: 0.10,
      wLeft: 43,   // Upper/outer vane
      wRight: 66,  // Lower/inner vane
      rachisBaseW: 6.5,
      barbReach: 0.085,
      phaseOffset: 0.47,
      splitsLeft: [0.39, 0.66, 0.84],
      splitsRight: [0.29, 0.53, 0.76]
    },
    {
      id: 3, // Central longest primary rectrix — CROPPED HARD at top-right feather tip
      p0: { x: 135, y: 955 },
      p1: { x: 485, y: 675 },
      p2: { x: 880, y: 345 },
      p3: { x: 1278, y: 12 }, // Extends past x=1200 so the wide iridescent paddle is cropped hard
      vaneStart: 0.10,
      wLeft: 66,
      wRight: 64,
      rachisBaseW: 7.4,
      barbReach: 0.078,
      phaseOffset: 0.78,
      splitsLeft: [0.26, 0.49, 0.68, 0.85],
      splitsRight: [0.35, 0.60, 0.78]
    }
  ];

  // 1. Render the rough grey-blue charcoal mass wet slate step
  drawWetSlateStep();

  // 2. Render wet slate reflections & soft contact shadows beneath the feathers
  drawFeatherShadowsAndReflections(feathers);

  // 3. Render water beads resting on the slate (some partially tucked under feather edges)
  drawSlateWaterBeads(feathers, false);

  // 4. Render the three magpie feathers (glazes, barbules, rachis, hairline pen splits)
  for (let f of feathers) {
    drawMagpieFeather(f);
  }

  // 5. Render foreground water beads on the slate and crystalline droplets beaded on the feathers
  drawSlateWaterBeads(feathers, true);
  drawFeatherWaterBeads(feathers);

  noLoop();
}

// ============================================================================
// STAGE 1: WET SLATE STEP (CHARCOAL MASS & TWILIGHT WASHES)
// ============================================================================

function drawWetSlateStep() {
  // Deep dusky twilight slate ground
  background("#141921");

  // Step edge geometry: diagonal stone lip across the lower canvas
  function stepEdgeY(x) {
    return 985 + (x / 1200) * 115 + 14 * (noise(x * 0.006, 1.2) - 0.5);
  }

  // A. Batched watercolor & wash underlayers for wet slate tonal variation
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  const slateWashes = [
    { col: "#1a222d", op: 110, count: 6 },
    { col: "#222d3b", op: 95,  count: 6 },
    { col: "#151c26", op: 130, count: 5 },
    { col: "#273342", op: 80,  count: 5 },
    { col: "#1c2433", op: 90,  count: 4 }, // Dusky twilight violet-blue undertone
    { col: "#0c1016", op: 170, count: 4 }  // Deep wet pools
  ];

  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.7, 0.4);

  for (let batch of slateWashes) {
    brush.fill(batch.col, batch.op);
    for (let i = 0; i < batch.count; i++) {
      let cx = random(-80, 1280);
      let cy = random(-80, 1060);
      let rx = random(180, 420);
      let ry = random(90, 240);
      let tilt = 12 + random(-8, 8); // Foliated slate grain angle
      brush.beginShape(0.35);
      for (let a = 0; a < 360; a += 45) {
        let rad = 0.75 + 0.45 * noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a));
        let px = cx + (rx * rad * cos(a)) * cos(tilt) - (ry * rad * sin(a)) * sin(tilt);
        let py = cy + (rx * rad * cos(a)) * sin(tilt) + (ry * rad * sin(a)) * cos(tilt);
        brush.vertex(px, py);
      }
      brush.endShape(true);
    }
  }
  brush.noFill();

  // B. Rough grey-blue charcoal mass planes (foliated slate strata)
  const charcoalSlateTones = [
    { col: "#263240", str: 0.55, prec: 0.35 },
    { col: "#303f50", str: 0.45, prec: 0.40 },
    { col: "#1c2530", str: 0.65, prec: 0.30 },
    { col: "#3a4b5e", str: 0.35, prec: 0.45 },
    { col: "#151c24", str: 0.60, prec: 0.35 },
    { col: "#2b3647", str: 0.50, prec: 0.40 }
  ];

  for (let tier = 0; tier < charcoalSlateTones.length; tier++) {
    let tone = charcoalSlateTones[tier];
    brush.mass("charcoal", tone.col, {
      precision: tone.prec,
      strength: tone.str,
      gradient: 0.65,
      outline: false
    });

    let patchCount = 4;
    for (let i = 0; i < patchCount; i++) {
      let cx = ((i + 0.5) / patchCount) * 1240 - 20 + random(-90, 90);
      let cy = ((tier + 0.5) / charcoalSlateTones.length) * 980 + random(-80, 80);
      let w = random(220, 440);
      let h = random(85, 190);
      let ang = 11 + random(-6, 6);

      brush.beginShape(0.2);
      for (let k = 0; k < 7; k++) {
        let a = (k / 7) * 360;
        let rScale = 0.7 + 0.5 * noise(tier * 13 + i * 7 + k, cx * 0.005);
        let vx = cx + (w * 0.5 * rScale * cos(a)) * cos(ang) - (h * 0.5 * rScale * sin(a)) * sin(ang);
        let vy = cy + (w * 0.5 * rScale * cos(a)) * sin(ang) + (h * 0.5 * rScale * sin(a)) * cos(ang);
        brush.vertex(vx, vy);
      }
      brush.endShape(true);
    }
  }
  brush.noMass();

  // C. Step riser (dark drop-off below the slate step edge)
  brush.wash("#0a0d12", 215);
  brush.beginShape(0.1);
  brush.vertex(-40, stepEdgeY(-40) + 12);
  for (let x = 0; x <= 1240; x += 80) {
    brush.vertex(x, stepEdgeY(x) + 12 + 6 * (noise(x * 0.02, 9) - 0.5));
  }
  brush.vertex(1240, 1250);
  brush.vertex(-40, 1250);
  brush.endShape(true);
  brush.noWash();

  // Charcoal mass texture on the vertical step riser
  brush.mass("charcoal", "#121821", { precision: 0.3, strength: 0.6, gradient: 0.7, outline: false });
  brush.beginShape(0.1);
  brush.vertex(-20, stepEdgeY(-20) + 16);
  for (let x = 0; x <= 1220; x += 120) {
    brush.vertex(x, stepEdgeY(x) + 16);
  }
  brush.vertex(1220, 1230);
  brush.vertex(-20, 1230);
  brush.endShape(true);
  brush.noMass();

  // D. Chipped stone bevel highlight & cleavage fissures along the slate step
  for (let x = -20; x < 1200; x += 35) {
    let x2 = x + random(25, 55);
    let y1 = stepEdgeY(x);
    let y2 = stepEdgeY(x2);

    // Wet twilight gleam on the stone lip bevel
    brush.set("charcoal", random() < 0.5 ? "#495b6e" : "#384757", random(0.6, 1.3));
    brush.line(x, y1 - random(1, 4), x2, y2 - random(1, 4));

    // Deep cleft shadow immediately beneath the lip
    brush.set("charcoal", "#06080c", random(0.9, 1.8));
    brush.line(x, y1 + random(6, 12), x2, y2 + random(6, 12));
  }

  // E. Directional slate striations, micro-fissures, and charcoal grain
  for (let i = 0; i < 140; i++) {
    let sx = random(-40, 1220);
    let sy = random(-20, 1150);
    let len = random(35, 190);
    let ang = 11 + random(-7, 7);
    let col = random(["#12171f", "#1e2733", "#364657", "#485b6e", "#0d1117"]);
    let bName = random() < 0.65 ? "charcoal" : "2B";
    brush.set(bName, col, random(0.22, 0.55));
    brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
  }

  // Crisp stone cleavage cracks
  for (let c = 0; c < 14; c++) {
    let cx = random(40, 1160);
    let cy = random(40, 1020);
    let pts = [];
    let segs = floor(random(4, 8));
    let baseAng = random() < 0.75 ? (12 + random(-10, 10)) : (65 + random(-15, 15));
    for (let s = 0; s < segs; s++) {
      pts.push([cx, cy]);
      let step = random(18, 48);
      let a = baseAng + random(-18, 18);
      cx += cos(a) * step;
      cy += sin(a) * step;
    }
    brush.set("2B", "#0a0e14", random(0.25, 0.45));
    brush.spline(pts, 0.25);
    // Faint wet rim beside crack
    let offsetPts = pts.map(p => [p[0] + 1.5, p[1] - 1.5]);
    brush.set("2H", "#46586b", 0.2);
    brush.spline(offsetPts, 0.25);
  }

  // Subtle mineral spray stipple
  for (let i = 0; i < 35; i++) {
    let x = random(0, 1200);
    let y = random(0, 1180);
    brush.set("spray", random() < 0.5 ? "#3b4c5e" : "#10151d", random(0.4, 0.9));
    brush.line(x, y, x + random(20, 60), y + random(-10, 15));
  }
}

// ============================================================================
// STAGE 2: WET SLATE REFLECTIONS & CONTACT SHADOWS
// ============================================================================

function drawFeatherShadowsAndReflections(feathers) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // 1. Faint wet iridescent reflection aura on the damp slate
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.5, 0.2);

  const reflColors = ["#0c2b2e", "#1b1429", "#0c261f"];
  for (let idx = 0; idx < feathers.length; idx++) {
    let f = feathers[idx];
    brush.fill(reflColors[idx % reflColors.length], 32);
    brush.beginShape(0.3);
    for (let t = 0.14; t <= 0.96; t += 0.08) {
      let p = evalBarbPoint(f, t, -1, 0.9, 0.1, 1.0);
      brush.vertex(p.x + 12, p.y + 18);
    }
    for (let t = 0.96; t >= 0.14; t -= 0.08) {
      let p = evalBarbPoint(f, t, 1, 0.9, 0.1, 1.0);
      brush.vertex(p.x + 12, p.y + 18);
    }
    brush.endShape(true);
  }

  // 2. Deep, soft contact shadow beneath each feather (batched)
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.6, 0.4);
  brush.fill("#06080d", 145);

  for (let f of feathers) {
    brush.beginShape(0.25);
    for (let t = 0.02; t <= 0.98; t += 0.06) {
      let p = t < f.vaneStart ? evalFeatherSpine(f, t) : evalBarbPoint(f, t, -1, 0.88, 0.1, 1.0);
      brush.vertex(p.x + 7, p.y + 11);
    }
    for (let t = 0.98; t >= 0.02; t -= 0.06) {
      let p = t < f.vaneStart ? evalFeatherSpine(f, t) : evalBarbPoint(f, t, 1, 0.92, 0.1, 1.0);
      brush.vertex(p.x + 9, p.y + 13);
    }
    brush.endShape(true);
  }

  // 3. Tighter umbra shadow directly under the rachis and lower vane
  brush.fill("#030508", 175);
  for (let f of feathers) {
    brush.beginShape(0.2);
    for (let t = 0.0; t <= 0.96; t += 0.06) {
      let sp = evalFeatherSpine(f, t);
      brush.vertex(sp.x + 3, sp.y + 5);
    }
    for (let t = 0.96; t >= 0.0; t -= 0.06) {
      let p = t < f.vaneStart ? evalFeatherSpine(f, t) : evalBarbPoint(f, t, 1, 0.55, 0.1, 1.0);
      brush.vertex(p.x + 5, p.y + 8);
    }
    brush.endShape(true);
  }

  brush.noFill();
}

// ============================================================================
// STAGE 3: RENDER EACH MAGPIE TAIL FEATHER
// ============================================================================

function getVaneLobes(f, s) {
  let splits = s < 0 ? f.splitsLeft : f.splitsRight;
  let lobes = [];
  let cur = f.vaneStart;
  for (let sp of splits) {
    lobes.push({ start: cur, end: sp - 0.005 });
    cur = sp + 0.005;
  }
  lobes.push({ start: cur, end: 0.992 });
  return lobes;
}

function drawMagpieFeather(f) {
  // --------------------------------------------------------------------------
  // 1. VELVETY MELANIN UNDERPAINTING (Respecting the sharp V-splits!)
  // --------------------------------------------------------------------------
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  for (let s of [-1, 1]) {
    let lobes = getVaneLobes(f, s);
    for (let lobe of lobes) {
      // Solid obsidian-indigo wash so the slate texture is occluded inside intact lobes
      brush.wash("#06090f", 238);
      traceLobeShape(f, s, lobe.start, lobe.end, 0.0, 0.98);
      brush.noWash();

      // Soft watercolor base for rich velvety depth
      brush.fillBleed(0.15, "in");
      brush.fillTexture(0.55, 0.35);
      brush.fill("#090e17", 190);
      traceLobeShape(f, s, lobe.start, lobe.end, 0.02, 0.96);
      brush.noFill();
    }
  }

  // --------------------------------------------------------------------------
  // 2. TRANSLUCENT WATERCOLOUR GLAZES (Layered nacre shell ripples)
  // --------------------------------------------------------------------------
  // Collect glaze patches grouped by color index so we batch brush.fill() calls
  let glazeBatches = Array.from({ length: IRID_GLAZES.length }, () => []);

  for (let s of [-1, 1]) {
    let lobes = getVaneLobes(f, s);
    for (let lobe of lobes) {
      let span = lobe.end - lobe.start;
      let tSteps = max(2, floor(span / 0.065));
      let dt = span / tSteps;

      // Layer 1 & Layer 2 overlapping nacreous glaze bands across u and t
      const uBands = [
        { u0: 0.04, u1: 0.48, op: 72 },
        { u0: 0.24, u1: 0.78, op: 68 },
        { u0: 0.50, u1: 0.95, op: 64 },
        { u0: 0.15, u1: 0.86, op: 52 } // Broad unifying ripple glaze
      ];

      for (let i = 0; i < tSteps; i++) {
        let tA = lobe.start + i * dt;
        let tB = min(lobe.end, tA + dt * 1.25); // Slight overlap along shaft
        let tMid = (tA + tB) * 0.5;

        for (let b of uBands) {
          let uMid = (b.u0 + b.u1) * 0.5;
          let sample = sampleIridescence(f, tMid, s, uMid);
          if (sample.glazeIdx > 0) {
            glazeBatches[sample.glazeIdx].push({
              s: s,
              lobeStart: lobe.start,
              lobeEnd: lobe.end,
              tA: tA,
              tB: tB,
              u0: b.u0,
              u1: b.u1,
              op: b.op
            });
          }
        }
      }
    }
  }

  // Render batched translucent watercolor glazes
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.68, 0.42);

  for (let gIdx = 1; gIdx < IRID_GLAZES.length; gIdx++) {
    let patches = glazeBatches[gIdx];
    if (patches.length === 0) continue;

    brush.fill(IRID_GLAZES[gIdx].hex, 66);
    for (let p of patches) {
      let p00 = evalBarbPoint(f, p.tA, p.s, p.u0, p.lobeStart, p.lobeEnd);
      let p01 = evalBarbPoint(f, p.tA, p.s, (p.u0 + p.u1) * 0.5, p.lobeStart, p.lobeEnd);
      let p02 = evalBarbPoint(f, p.tA, p.s, p.u1, p.lobeStart, p.lobeEnd);
      let p12 = evalBarbPoint(f, p.tB, p.s, p.u1, p.lobeStart, p.lobeEnd);
      let p11 = evalBarbPoint(f, p.tB, p.s, (p.u0 + p.u1) * 0.5, p.lobeStart, p.lobeEnd);
      let p10 = evalBarbPoint(f, p.tB, p.s, p.u0, p.lobeStart, p.lobeEnd);

      brush.beginShape(0.32);
      brush.vertex(p00.x, p00.y);
      brush.vertex(p01.x, p01.y);
      brush.vertex(p02.x, p02.y);
      brush.vertex(p12.x, p12.y);
      brush.vertex(p11.x, p11.y);
      brush.vertex(p10.x, p10.y);
      brush.endShape(true);
    }
  }
  brush.noFill();

  // --------------------------------------------------------------------------
  // 3. BARBULE-BY-BARBULE IRIDESCENT FILAMENTS
  // --------------------------------------------------------------------------
  // Draw dense curved barbs where hue shifts along each barb from shaft to margin
  for (let s of [-1, 1]) {
    let lobes = getVaneLobes(f, s);
    for (let lobe of lobes) {
      // Step ~0.0042 gives ~210 barbs per vane side for hyper-dense silky texture
      let stepT = 0.0042;
      for (let t0 = lobe.start; t0 <= lobe.end; t0 += stepT) {
        let p0 = evalBarbPoint(f, t0, s, 0.0, lobe.start, lobe.end);
        let p1 = evalBarbPoint(f, t0, s, 0.25, lobe.start, lobe.end);
        let p2 = evalBarbPoint(f, t0, s, 0.52, lobe.start, lobe.end);
        let p3 = evalBarbPoint(f, t0, s, 0.78, lobe.start, lobe.end);
        let p4 = evalBarbPoint(f, t0, s, 1.0, lobe.start, lobe.end);

        // Segment 1: Inner barb (shaft to mid-belly)
        let cInner = sampleIridescence(f, t0, s, 0.22);
        brush.set("cpencil", cInner.barbHex, random(0.24, 0.38));
        brush.spline([[p0.x, p0.y], [p1.x, p1.y], [p2.x, p2.y]], 0.35);

        // Segment 2: Mid-to-outer barb (belly to margin — peak nacre shimmer)
        let cMid = sampleIridescence(f, t0, s, 0.58);
        brush.set("cpencil", cMid.barbHex, random(0.26, 0.42));
        brush.spline([[p1.x, p1.y], [p2.x, p2.y], [p3.x, p3.y]], 0.35);

        // Segment 3: Outer barb (margin transition)
        let cOuter = sampleIridescence(f, t0, s, 0.85);
        brush.set("2H", cOuter.barbHex, random(0.20, 0.32));
        brush.spline([[p2.x, p2.y], [p3.x, p3.y], [p4.x, p4.y]], 0.35);

        // High-order specular barbule glint on every 3rd barb
        if (floor((t0 - lobe.start) / stepT) % 3 === 0) {
          let uPeak = 0.32 + 0.38 * noise(f.id * 9 + t0 * 12, s > 0 ? 1 : 2);
          let g0 = evalBarbPoint(f, t0, s, max(0.08, uPeak - 0.14), lobe.start, lobe.end);
          let g1 = evalBarbPoint(f, t0, s, uPeak, lobe.start, lobe.end);
          let g2 = evalBarbPoint(f, t0, s, min(0.94, uPeak + 0.14), lobe.start, lobe.end);
          let cPeak = sampleIridescence(f, t0, s, uPeak);

          brush.set("rotring", cPeak.sheenHex, random(0.18, 0.28));
          brush.spline([[g0.x, g0.y], [g1.x, g1.y], [g2.x, g2.y]], 0.3);
        }

        // Cross-angled micro-barbules (interlocking hooklets that create structural color)
        if (floor((t0 - lobe.start) / stepT) % 4 === 0 && t0 + stepT * 3 <= lobe.end) {
          let uB = random(0.2, 0.78);
          let bStart = evalBarbPoint(f, t0, s, uB, lobe.start, lobe.end);
          let bEnd = evalBarbPoint(f, t0 + stepT * 2.8, s, min(0.95, uB + 0.08), lobe.start, lobe.end);
          let cBarbule = sampleIridescence(f, t0, s, uB);
          brush.set("2H", cBarbule.sheenHex, 0.18);
          brush.line(bStart.x, bStart.y, bEnd.x, bEnd.y);
        }
      }
    }
  }

  // --------------------------------------------------------------------------
  // 4. HAIRLINE PEN FOR SPLIT VANE EDGES, STRAY BARBS & MARGIN DEFINITION
  // --------------------------------------------------------------------------
  for (let s of [-1, 1]) {
    let lobes = getVaneLobes(f, s);
    for (let lIdx = 0; lIdx < lobes.length; lIdx++) {
      let lobe = lobes[lIdx];

      // A. Crisp hairline pen along the proximal split edge of the lobe
      if (lIdx > 0) {
        drawHairlineBarbEdge(f, lobe.start, s, lobe.start, lobe.end, "#04060a", 0.26);
        // Subtle iridescent rim just inside the split edge
        let cRim = sampleIridescence(f, lobe.start + 0.005, s, 0.6);
        drawHairlineBarbEdge(f, lobe.start + 0.003, s, lobe.start, lobe.end, cRim.sheenHex, 0.18);
      }

      // B. Crisp hairline pen along the distal split edge of the lobe
      if (lIdx < lobes.length - 1) {
        drawHairlineBarbEdge(f, lobe.end, s, lobe.start, lobe.end, "#04060a", 0.28);

        // 1 or 2 individual unzipped stray barbs inside the V-split gap!
        let tStray = (lobe.end + lobes[lIdx + 1].start) * 0.5;
        drawStraySplitBarb(f, tStray, s);
      }

      // C. Delicate hairline pen serrations along the outer vane margin
      let marginPts = [];
      for (let t = lobe.start; t <= lobe.end; t += 0.015) {
        let pm = evalBarbPoint(f, t, s, 1.0, lobe.start, lobe.end);
        marginPts.push([pm.x, pm.y]);
      }
      let pEnd = evalBarbPoint(f, lobe.end, s, 1.0, lobe.start, lobe.end);
      marginPts.push([pEnd.x, pEnd.y]);

      if (marginPts.length >= 3) {
        brush.set("rotring", "#05080d", 0.22);
        brush.spline(marginPts, 0.35);
      }

      // Individual fine barb tips projecting slightly at the vane edge
      for (let t = lobe.start; t <= lobe.end; t += 0.009) {
        let pIn = evalBarbPoint(f, t, s, 0.86, lobe.start, lobe.end);
        let pOut = evalBarbPoint(f, t, s, 1.015, lobe.start, lobe.end);
        brush.set("pen", "#06090f", random(0.16, 0.24));
        brush.line(pIn.x, pIn.y, pOut.x, pOut.y);
      }
    }
  }

  // --------------------------------------------------------------------------
  // 5. PLUMULACEOUS DOWNY BASE (Soft smoky afterfeather fluff near calamus)
  // --------------------------------------------------------------------------
  for (let s of [-1, 1]) {
    for (let t0 = 0.075; t0 <= 0.165; t0 += 0.004) {
      let sp = evalFeatherSpine(f, t0);
      let len = random(18, 42) * Math.sin(((t0 - 0.07) / 0.10) * Math.PI);
      let ang = atan2(sp.ty, sp.tx) + s * random(32, 68);
      let midX = sp.x + cos(ang) * len * 0.55 + random(-3, 3);
      let midY = sp.y + sin(ang) * len * 0.55 + random(-3, 3);
      let endX = sp.x + cos(ang - s * 12) * len;
      let endY = sp.y + sin(ang - s * 12) * len;

      let downCol = random(["#2d3845", "#435263", "#182029", "#5c6f82"]);
      brush.set("2H", downCol, random(0.16, 0.26));
      brush.spline([[sp.x, sp.y], [midX, midY], [endX, endY]], 0.45);
    }
  }

  // --------------------------------------------------------------------------
  // 6. HAIRLINE PEN RACHIS (Central Shaft & Hollow Calamus Quill)
  // --------------------------------------------------------------------------
  drawFeatherRachis(f);
}

function traceLobeShape(f, s, tStart, tEnd, uMin, uMax) {
  brush.beginShape(0.2);
  let steps = max(4, floor((tEnd - tStart) / 0.025));
  let dt = (tEnd - tStart) / steps;

  // Inner edge along shaft
  for (let i = 0; i <= steps; i++) {
    let t = tStart + i * dt;
    let p = evalBarbPoint(f, t, s, uMin, tStart, tEnd);
    brush.vertex(p.x, p.y);
  }
  // Distal split edge (from uMin to uMax)
  for (let u = 0.25; u <= uMax; u += 0.25) {
    let p = evalBarbPoint(f, tEnd, s, u, tStart, tEnd);
    brush.vertex(p.x, p.y);
  }
  // Outer vane margin (from tEnd back to tStart)
  for (let i = steps; i >= 0; i--) {
    let t = tStart + i * dt;
    let p = evalBarbPoint(f, t, s, uMax, tStart, tEnd);
    brush.vertex(p.x, p.y);
  }
  // Proximal split edge (from uMax back to uMin)
  for (let u = 0.75; u >= 0.25; u -= 0.25) {
    let p = evalBarbPoint(f, tStart, s, u, tStart, tEnd);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
}

function drawHairlineBarbEdge(f, t0, s, lobeStart, lobeEnd, col, weight) {
  let pts = [];
  for (let u = 0.0; u <= 1.0; u += 0.2) {
    let p = evalBarbPoint(f, t0, s, u, lobeStart, lobeEnd);
    pts.push([p.x, p.y]);
  }
  brush.set("rotring", col, weight);
  brush.spline(pts, 0.35);
}

function drawStraySplitBarb(f, t0, s) {
  let pts = [];
  for (let u = 0.0; u <= 1.02; u += 0.25) {
    // Stray barb sits slightly unaligned inside the V-cleft
    let p = evalBarbPoint(f, t0, s, u, t0 - 0.02, t0 + 0.02);
    let wave = (u > 0.3) ? (noise(f.id * 20 + t0 * 50, u * 4) - 0.5) * 4.5 : 0;
    pts.push([p.x + wave, p.y + wave]);
  }
  let cStray = sampleIridescence(f, t0, s, 0.65);
  brush.set("cpencil", cStray.barbHex, 0.24);
  brush.spline(pts, 0.4);
  brush.set("rotring", "#04060a", 0.20);
  brush.spline(pts, 0.4);
}

function drawFeatherRachis(f) {
  // Build tapering shaft polygon & hairline pen contours from t=0 (calamus) to t=1 (tip)
  let segs = 36;
  for (let i = 0; i < segs; i++) {
    let tA = i / segs;
    let tB = (i + 1) / segs;
    let tMid = (tA + tB) * 0.5;

    let spA = evalFeatherSpine(f, tA);
    let spM = evalFeatherSpine(f, tMid);
    let spB = evalFeatherSpine(f, tB);

    let wA = f.rachisBaseW * Math.pow(1 - tA * 0.90, 1.35);
    let wB = f.rachisBaseW * Math.pow(1 - tB * 0.90, 1.35);
    let wM = (wA + wB) * 0.5;

    // 1. Dark core of the rachis (translucent horn at calamus, jet obsidian along vane)
    let coreCol = tA < f.vaneStart ? "#232d38" : "#04060a";
    brush.set("pen", coreCol, max(0.22, wM * 0.42));
    brush.spline([[spA.x, spA.y], [spM.x, spM.y], [spB.x, spB.y]], 0.3);

    // 2. Hairline pen upper and lower edges of the rachis shaft
    let uAx = spA.x - spA.nx * wA * 0.48, uAy = spA.y - spA.ny * wA * 0.48;
    let uMx = spM.x - spM.nx * wM * 0.48, uMy = spM.y - spM.ny * wM * 0.48;
    let uBx = spB.x - spB.nx * wB * 0.48, uBy = spB.y - spB.ny * wB * 0.48;

    let lAx = spA.x + spA.nx * wA * 0.48, lAy = spA.y + spA.ny * wA * 0.48;
    let lMx = spM.x + spM.nx * wM * 0.48, lMy = spM.y + spM.ny * wM * 0.48;
    let lBx = spB.x + spB.nx * wB * 0.48, lBy = spB.y + spB.ny * wB * 0.48;

    brush.set("rotring", "#030508", max(0.18, 0.32 * (1 - tA * 0.6)));
    brush.spline([[uAx, uAy], [uMx, uMy], [uBx, uBy]], 0.3);
    brush.spline([[lAx, lAy], [lMx, lMy], [lBx, lBy]], 0.3);

    // 3. Specular twilight ridge along the top-left of the polished rachis
    let hAx = spA.x - spA.nx * wA * 0.22, hAy = spA.y - spA.ny * wA * 0.22;
    let hMx = spM.x - spM.nx * wM * 0.22, hMy = spM.y - spM.ny * wM * 0.22;
    let hBx = spB.x - spB.nx * wB * 0.22, hBy = spB.y - spB.ny * wB * 0.22;

    let specCol;
    if (tA < f.vaneStart) {
      specCol = "#9eb5c7"; // Translucent keratin quill gleam
    } else if (tA < 0.55) {
      specCol = "#528a94"; // Peacock-tinted specular ridge
    } else {
      specCol = "#75628a"; // Dusky violet-silver ridge toward tip
    }
    brush.set("rotring", specCol, max(0.16, 0.28 * (1 - tA * 0.65)));
    brush.spline([[hAx, hAy], [hMx, hMy], [hBx, hBy]], 0.3);
  }
}

// ============================================================================
// STAGE 4 & 5: BEADED WATER DROPLETS (ON SLATE & ON HYDROPHOBIC FEATHERS)
// ============================================================================

function isPointInsideAnyFeather(x, y, feathers) {
  for (let f of feathers) {
    // Quick bounding check along spine samples
    for (let t = 0.08; t <= 0.98; t += 0.045) {
      let sp = evalFeatherSpine(f, t);
      let dx = x - sp.x, dy = y - sp.y;
      let distSq = dx * dx + dy * dy;
      if (distSq < 4600) {
        return { inside: true, feather: f, t: t };
      }
    }
  }
  return { inside: false };
}

function drawSlateWaterBeads(feathers, foregroundPass) {
  // Generate deterministic water beads across the wet slate step
  let droplets = [];
  let numClusters = foregroundPass ? 22 : 16;

  for (let c = 0; c < numClusters; c++) {
    let cx = random(45, 1155);
    let cy = random(45, 1135);
    let chk = isPointInsideAnyFeather(cx, cy, feathers);
    if (chk.inside) continue;

    // Main droplet in cluster
    let rMain = random(6.5, 19.5);
    droplets.push({
      x: cx,
      y: cy,
      r: rMain,
      stretch: random(1.05, 1.32),
      ang: 12 + random(-25, 25),
      causticCol: random(["#446078", "#385266", "#2c6169", "#4f6d85"])
    });

    // Satellite micro-beads around main droplet
    let satCount = floor(random(2, 6));
    for (let s = 0; s < satCount; s++) {
      let sa = random(360);
      let sd = rMain + random(5, 28);
      let sx = cx + cos(sa) * sd;
      let sy = cy + sin(sa) * sd;
      if (!isPointInsideAnyFeather(sx, sy, feathers).inside) {
        droplets.push({
          x: sx,
          y: sy,
          r: random(2.0, 5.8),
          stretch: random(1.0, 1.18),
          ang: sa,
          causticCol: "#4a6780"
        });
      }
    }
  }

  renderDropletBatch(droplets, false);
}

function drawFeatherWaterBeads(feathers) {
  // High-contact-angle crystalline dew pearls beaded directly on the hydrophobic vanes
  let pearls = [];
  const pearlSpots = [
    { fIdx: 0, t: 0.28, s: -1, u: 0.45, r: 6.5 },
    { fIdx: 0, t: 0.30, s: -1, u: 0.58, r: 3.2 },
    { fIdx: 0, t: 0.52, s:  1, u: 0.50, r: 5.2 },
    { fIdx: 0, t: 0.68, s: -1, u: 0.38, r: 8.0 },
    { fIdx: 0, t: 0.70, s: -1, u: 0.55, r: 3.8 },
    { fIdx: 0, t: 0.86, s: -1, u: 0.48, r: 4.5 },

    { fIdx: 1, t: 0.24, s:  1, u: 0.42, r: 5.8 },
    { fIdx: 1, t: 0.45, s:  1, u: 0.55, r: 7.4 },
    { fIdx: 1, t: 0.47, s:  1, u: 0.35, r: 3.4 },
    { fIdx: 1, t: 0.62, s: -1, u: 0.52, r: 4.8 },
    { fIdx: 1, t: 0.79, s:  1, u: 0.46, r: 6.2 },

    { fIdx: 2, t: 0.21, s: -1, u: 0.48, r: 5.5 },
    { fIdx: 2, t: 0.38, s: -1, u: 0.42, r: 9.2 },
    { fIdx: 2, t: 0.40, s: -1, u: 0.60, r: 4.0 },
    { fIdx: 2, t: 0.49, s:  1, u: 0.45, r: 6.8 },
    { fIdx: 2, t: 0.66, s: -1, u: 0.52, r: 7.8 },
    { fIdx: 2, t: 0.73, s:  1, u: 0.38, r: 5.4 },
    { fIdx: 2, t: 0.84, s:  1, u: 0.54, r: 8.5 },
    { fIdx: 2, t: 0.86, s:  1, u: 0.36, r: 3.6 }
  ];

  for (let ps of pearlSpots) {
    let f = feathers[ps.fIdx];
    let pt = evalBarbPoint(f, ps.t, ps.s, ps.u, 0.1, 1.0);
    let irid = sampleIridescence(f, ps.t, ps.s, ps.u);
    pearls.push({
      x: pt.x,
      y: pt.y,
      r: ps.r,
      stretch: 1.04, // Spherical high surface tension on feather barbules
      ang: 25,
      causticCol: irid.sheenHex
    });
  }

  renderDropletBatch(pearls, true);
}

function renderDropletBatch(droplets, onFeather) {
  // Light source direction: upper-left (-130 deg); shadow & internal caustic: lower-right (+50 deg)
  let lx = cos(-130), ly = sin(-130);
  let sx = cos(50), sy = sin(50);

  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // 1. Batched cast shadows on the lower-right of each water bead
  brush.wash("#04060a", onFeather ? 210 : 175);
  for (let d of droplets) {
    if (d.r < 3.2) continue;
    drawOrganicBeadShape(
      d.x + sx * d.r * 0.38,
      d.y + sy * d.r * 0.38,
      d.r * 0.96,
      d.stretch,
      d.ang
    );
  }
  brush.noWash();

  // 2. Batched dark upper-left internal refraction
  brush.wash(onFeather ? "#050910" : "#0b1119", 185);
  for (let d of droplets) {
    if (d.r < 3.2) continue;
    drawOrganicBeadShape(
      d.x + lx * d.r * 0.12,
      d.y + ly * d.r * 0.12,
      d.r * 0.88,
      d.stretch,
      d.ang
    );
  }
  brush.noWash();

  // 3. Lower-right internal lens caustic (tinted by slate or magnified feather iridescence!)
  for (let d of droplets) {
    if (d.r < 3.8) continue;
    brush.wash(d.causticCol, onFeather ? 155 : 115);
    drawOrganicBeadShape(
      d.x + sx * d.r * 0.22,
      d.y + sy * d.r * 0.22,
      d.r * 0.62,
      d.stretch * 0.92,
      d.ang
    );
    brush.noWash();
  }

  // 4. Crisp meniscus rim, secondary bottom caustic arc, and brilliant twilight sky specular highlight
  for (let d of droplets) {
    // Dark meniscus ring
    let rimPts = [];
    for (let a = 0; a <= 360; a += 45) {
      let rx = d.r * d.stretch * cos(a);
      let ry = d.r * sin(a);
      let px = d.x + rx * cos(d.ang) - ry * sin(d.ang);
      let py = d.y + rx * sin(d.ang) + ry * cos(d.ang);
      rimPts.push([px, py]);
    }
    brush.set("rotring", "#05080d", d.r > 6 ? 0.28 : 0.20);
    brush.spline(rimPts, 0.45);

    // Luminous lower-right secondary reflection rim
    if (d.r > 3.5) {
      let caustPts = [];
      for (let a = 5; a <= 95; a += 30) {
        let rad = d.r * 0.78;
        caustPts.push([d.x + cos(a) * rad, d.y + sin(a) * rad]);
      }
      brush.set("rotring", onFeather ? d.causticCol : "#86adc7", d.r > 7 ? 0.32 : 0.22);
      brush.spline(caustPts, 0.4);
    }

    // Primary upper-left specular sky highlight
    let hx = d.x + lx * d.r * 0.46;
    let hy = d.y + ly * d.r * 0.46;

    if (d.r >= 5.0) {
      // Curved window/sky highlight on larger beads
      let hPts = [
        [hx - d.r * 0.20, hy + d.r * 0.16],
        [hx, hy],
        [hx + d.r * 0.22, hy - d.r * 0.12]
      ];
      brush.set("pen", "#d9eefc", 0.42);
      brush.spline(hPts, 0.35);
      brush.set("rotring", "#ffffff", 0.32);
      brush.line(hx - d.r * 0.08, hy + d.r * 0.05, hx + d.r * 0.10, hy - d.r * 0.05);

      // Tiny secondary pinpoint glint
      brush.set("rotring", "#ffffff", 0.24);
      brush.line(hx - d.r * 0.28, hy + d.r * 0.26, hx - d.r * 0.25, hy + d.r * 0.28);
    } else {
      // Crisp pinpoint glint on micro-beads
      brush.set("rotring", "#eef7ff", 0.26);
      brush.line(hx, hy, hx + 0.8, hy - 0.6);
    }
  }
}

function drawOrganicBeadShape(cx, cy, r, stretch, ang) {
  brush.beginShape(0.4);
  for (let a = 0; a < 360; a += 45) {
    let wob = 0.94 + 0.12 * noise(cx * 0.05 + cos(a), cy * 0.05 + sin(a));
    let rx = r * stretch * wob * cos(a);
    let ry = r * wob * sin(a);
    let px = cx + rx * cos(ang) - ry * sin(ang);
    let py = cy + rx * sin(ang) + ry * cos(ang);
    brush.vertex(px, py);
  }
  brush.endShape(true);
}

