function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // PALETTE: Letterpress Two-Ink System + Muted Earth Tones on Cream Cotton
  // =========================================================================
  const PAPER_BASE = "#f1e7d4";      // Thick cream cotton stock
  const PAPER_WARM = "#e6d8be";      // Muted earth cotton shadow / warm rag
  const PAPER_DEEP = "#d4c2a3";      // Deep blind-deboss trough tone
  const PAPER_UMBER = "#bfa886";     // Concentrated blind-deboss crease shadow
  const PAPER_HIGHLIGHT = "#fcf9f2"; // Sunlit crest of blind debossed paper

  // Ink 1: Letterpress Vermilion (muted earthy cinnabar / terracotta vermilion)
  const VERM_SOLID = "#c44522";      // Dense vermilion plate mass
  const VERM_SQUASH = "#8f270e";     // Ink-squash halo at edge of vermilion plate
  const VERM_MID = "#d45a33";        // Halftone vermilion midtone
  const VERM_EARTH = "#a65433";      // Earthy kraft-vermilion undertone

  // Ink 2: Heavy Carbon Black (dense warm lampblack / soot)
  const BLACK_SOLID = "#1b1815";     // Solid carbon black ink mass
  const BLACK_SQUASH = "#0c0a09";    // Dense ink-squash bead at black plate boundary
  const BLACK_CHAR = "#2b2520";      // Engraved carbon black halftone line
  const BLACK_EARTH = "#433930";     // Warm diluted earth-black for fine engraving

  // Overprint tone (where carbon black and vermilion plates mix)
  const OVERPRINT = "#2e1a12";

  // Misregistration offset for the Vermilion plate (shifts down-left)
  const MIS_X = -7.5;
  const MIS_Y = 5.5;

  // =========================================================================
  // 1. THICK CREAM COTTON STOCK & BLIND PLATE MARK
  // =========================================================================
  background(PAPER_BASE);
  noStroke();
  brush.noField();

