  // Draws a physical blind-debossed crease in the thick cotton paper
  // (paired recessed shadow trough + raised sunlit paper ridge + micro-bevel)
  function drawBlindCrease(pts, strength = 1.0, lightFromTopRight = true) {
    let ox = lightFromTopRight ? -1.8 * strength : 1.8 * strength;
    let oy = lightFromTopRight ? 1.8 * strength : -1.8 * strength;

    let shadowPts = pts.map(p => [p[0] - ox * 0.5, p[1] - oy * 0.5, random(0.6, 1.1)]);
    let ridgePts  = pts.map(p => [p[0] + ox * 0.7, p[1] + oy * 0.7, random(0.7, 1.2)]);
    let corePts   = pts.map(p => [p[0], p[1], random(0.8, 1.2)]);

    // Wide soft paper depression
    brush.set("deboss_chisel", PAPER_DEEP, 1.6 * strength);
    if (pts.length > 2) brush.spline(shadowPts, 0.35);
    else brush.line(shadowPts[0][0], shadowPts[0][1], shadowPts[1][0], shadowPts[1][1]);

    // Deeper core valley
    brush.set("burin", PAPER_UMBER, 0.85 * strength);
    if (pts.length > 2) brush.spline(corePts, 0.35);
    else brush.line(corePts[0][0], corePts[0][1], corePts[1][0], corePts[1][1]);

    // Crisp sunlit cotton ridge beside the trough
    brush.set("deboss_chisel", PAPER_HIGHLIGHT, 1.35 * strength);
    if (pts.length > 2) brush.spline(ridgePts, 0.35);
    else brush.line(ridgePts[0][0], ridgePts[0][1], ridgePts[1][0], ridgePts[1][1]);

    // Fine perpendicular bevel ticks inside the debossed trough
    brush.set("burin", PAPER_DEEP, 0.45 * strength);
    for (let i = 0; i < pts.length - 1; i++) {
      let p1 = pts[i], p2 = pts[i + 1];
      let d = dist(p1[0], p1[1], p2[0], p2[1]);
      let steps = floor(d / 6);
      let ang = atan2(p2[1] - p1[1], p2[0] - p1[0]) + 90;
      for (let s = 1; s < steps; s++) {
        if (random() < 0.65) {
          let t = s / steps;
          let mx = lerp(p1[0], p2[0], t);
          let my = lerp(p1[1], p2[1], t);
          let bw = random(1.8, 3.8) * strength;
          brush.line(mx, my, mx + cos(ang) * bw, my + sin(ang) * bw);
        }
      }
    }
  }

  // Draws a solid letterpress ink plate with ink-squash halo at the rim
  // and a subtle blind-impression halo outside the edge
  function drawLetterpressPlate(pts, fillCol, fillOpacity, squashCol, squashWeight = 1.0, hatchCfg = null) {
    let poly = new brush.Polygon(pts);

    // 1. Blind debossed paper halo just outside the ink block
    let cx = 0, cy = 0;
    for (let p of pts) { cx += p[0]; cy += p[1]; }
    cx /= pts.length; cy /= pts.length;
    let outerPts = pts.map(p => {
      let dx = p[0] - cx, dy = p[1] - cy;
      let len = sqrt(dx * dx + dy * dy) || 1;
      return [p[0] + (dx / len) * 2.2, p[1] + (dy / len) * 2.2, 0.8];
    });
    outerPts.push(outerPts[0]);
    brush.set("deboss_chisel", PAPER_HIGHLIGHT, 0.95);
    brush.spline(outerPts, 0.2);

    // 2. Solid ink wash + mottled letterpress ink fill
    if (fillOpacity > 0) {
      poly.wash(fillCol, fillOpacity);
    }

    // 3. Optional engraved halftone hatch inside the plate
    if (hatchCfg) {
      brush.hatchStyle(hatchCfg.brush || "burin", hatchCfg.color || squashCol, hatchCfg.weight || 0.7);
      poly.hatch(hatchCfg.dist, hatchCfg.angle, {
        rand: hatchCfg.rand || 0.03,
        continuous: false,
        gradient: hatchCfg.gradient || 0
      });
      brush.noHatch();
    }

    // 4. Ink-squash rim (squeezed ink bead around the perimeter of the block)
    if (squashWeight > 0) {
      poly.draw("squash_rim", squashCol, squashWeight);
      // Crisp inner-edge capillary line
      poly.draw("burin", squashCol, squashWeight * 0.55);
    }
  }

  function drawRegistrationMark(x, y, mx, my, vCol, kCol) {
    // Vermilion target (shifted by misregistration)
    brush.set("burin", vCol, 0.55);
    brush.line(x - 12 + mx, y + my, x + 12 + mx, y + my);
    brush.line(x + mx, y - 12 + my, x + mx, y + 12 + my);
    brush.circle(x + mx, y + my, 6, 0.05);

    // Carbon black target (key plate)
    brush.set("burin", kCol, 0.6);
    brush.line(x - 12, y, x + 12, y);
    brush.line(x, y - 12, x, y + 12);
    brush.circle(x, y, 6, 0.05);
  }

