      brush.noHatch();

      brush.hatchStyle("burin", BLACK_CHAR, 0.68);
      poly.hatch(3.6, f.ang + 52, { rand: 0.02 });
      brush.noHatch();

      poly.draw("squash_rim", BLACK_SQUASH, 0.95);
    } else if (f.tone === 4) {
      // Tone 4: Solid Carbon Black letterpress plate with ink-squash halo
      drawLetterpressPlate(
        f.pts,
        BLACK_SOLID, 228, BLACK_SQUASH, 1.25,
        { brush: "burin", color: BLACK_SQUASH, weight: 0.85, dist: 2.2, angle: f.ang }
      );
    }
  }

  // Render the overhanging upper mouth canopy (which casts shadow onto Orange #1)
  let canopyPoly = new brush.Polygon(upperMouthCanopy);
  canopyPoly.wash(PAPER_WARM, 215);
  brush.hatchStyle("burin", BLACK_CHAR, 0.62);
  canopyPoly.hatch(4.4, -28, { rand: 0.025, gradient: 0.3 });
  brush.noHatch();
  canopyPoly.draw("squash_rim", BLACK_CHAR, 0.75);

  // =========================================================================
  // 7. BLIND DEBOSSED CREASES & WRINKLES ACROSS THE BAG AND MARGIN
  // =========================================================================
  // Primary structural folds & subsidiary crinkle networks rendered as physical
  // blind-debossed valleys and sunlit cotton ridges
  const blindCreaseLines = [
    // Major crown & gusset folds
    [V.M_topPeak, V.U_buck1, V.G_tuck1, V.G_valley1, V.B_fold1],
    [V.U_ridge1, V.U_buck1, V.U_buck2, V.U_buck3, V.E_upperMid],
    [V.U_ridge2, V.U_buck2, V.G_tuck2, V.G_valley2, V.G_low2, V.B_fold2],
    [V.U_ridge3, V.U_buck3, V.G_tuck3, V.G_valley3, V.G_low3, V.B_fold3],
    [V.M_topRight, V.M_midRight, V.G_valley1, V.G_low1, V.B_fold1],
    [V.G_tuck1, V.G_tuck2, V.G_tuck3, V.E_upperMid],
    [V.G_valley1, V.G_valley2, V.G_valley3, V.E_center],
    [V.G_low1, V.G_low2, V.G_low3, V.E_lowerMid],

    // Diagonal buckle wrinkles across the paper wall
    [[672, 540], [728, 592], [798, 565], [855, 610]],
    [[782, 488], [812, 535], [875, 512], [922, 548]],
    [[895, 475], [932, 522], [992, 508], [1038, 545]],
    [[790, 725], [862, 745], [912, 718], [978, 755]],
    [[758, 835], [825, 815], [888, 858], [952, 825]],
    [[668, 938], [735, 902], [812, 945], [895, 912]],
    [[1065, 555], [1095, 635], [1072, 715], [1105, 795], [1075, 868]],

    // Subtle blind-debossed table & paper stress creases extending slightly past the bag
    [[648, 520], [762, 482], [888, 468], [1012, 492], [1082, 525]],
    [[715, 510], [745, 492], [805, 498]],
    [[840, 480], [878, 495], [945, 482]]
  ];

  for (let cl of blindCreaseLines) {
    drawBlindCrease(cl, random(0.85, 1.35), true);
  }

  // Secondary micro-crinkles (crow's-foot paper buckles at fold vertices)
  const vertexNodes = [
    V.U_buck1, V.U_buck2, V.U_buck3,
    V.G_tuck1, V.G_tuck2, V.G_tuck3,
    V.G_low1, V.G_low2, V.B_fold1, V.B_fold2
  ];
  for (let node of vertexNodes) {
    let rays = floor(random(4, 7));
    for (let r = 0; r < rays; r++) {
      let ang = random(360);
      let len = random(18, 48);
      let midX = node[0] + cos(ang) * len * 0.5 + random(-5, 5);
      let midY = node[1] + sin(ang) * len * 0.5 + random(-5, 5);
      let endX = node[0] + cos(ang) * len;
      let endY = node[1] + sin(ang) * len;
      drawBlindCrease([node, [midX, midY], [endX, endY]], random(0.55, 0.9), true);
    }
  }

  // =========================================================================
  // 8. SERRATED (PINKED) GROCERY BAG MOUTH & HYPERREAL PAPER FIBRE TEARS
  // =========================================================================
  // Draw the iconic zig-zag sawtooth pinked edge along the grocery bag's mouth rim
  function drawSerratedBagLip(pts, toothSize = 7.5, isLit = true) {
    let sawPts = [];
    for (let i = 0; i < pts.length - 1; i++) {
      let p1 = pts[i], p2 = pts[i + 1];
      let d = dist(p1[0], p1[1], p2[0], p2[1]);
      let steps = max(2, floor(d / toothSize));
      let ang = atan2(p2[1] - p1[1], p2[0] - p1[0]);
      let perp = ang - 90;

      for (let s = 0; s < steps; s++) {
        let t1 = s / steps;
        let t2 = (s + 0.5) / steps;
        let bx = lerp(p1[0], p2[0], t1);
        let by = lerp(p1[1], p2[1], t1);
        let tx = lerp(p1[0], p2[0], t2) + cos(perp) * (toothSize * 0.68);
        let ty = lerp(p1[1], p2[1], t2) + sin(perp) * (toothSize * 0.68);
        sawPts.push([bx, by]);
        sawPts.push([tx, ty]);
      }
    }
    sawPts.push(pts[pts.length - 1]);

    // 1. Misregistered vermilion ghost along the serrated teeth
    brush.set("burin", VERM_SOLID, 0.68);
    for (let i = 0; i < sawPts.length - 1; i++) {
      brush.line(
        sawPts[i][0] + MIS_X * 0.65, sawPts[i][1] + MIS_Y * 0.65,
        sawPts[i + 1][0] + MIS_X * 0.65, sawPts[i + 1][1] + MIS_Y * 0.65
      );
    }

    // 2. Blind debossed paper highlight along the sawtooth edge
    brush.set("deboss_chisel", PAPER_HIGHLIGHT, isLit ? 1.3 : 0.85);
    for (let i = 0; i < sawPts.length - 1; i++) {
      brush.line(sawPts[i][0] - 1.2, sawPts[i][1] - 1.2, sawPts[i + 1][0] - 1.2, sawPts[i + 1][1] - 1.2);
    }

    // 3. Crisp Carbon Black engraved sawtooth edge + tiny torn kraft paper fibers
    brush.set("burin", BLACK_SOLID, 0.85);
    for (let i = 0; i < sawPts.length - 1; i++) {
      brush.line(sawPts[i][0], sawPts[i][1], sawPts[i + 1][0], sawPts[i + 1][1]);

      // Hyperreal microscopic paper fiber tears fraying from tooth peaks
      if (i % 2 === 1) {
        let tip = sawPts[i];
        let fCount = floor(random(2, 5));
        for (let f = 0; f < fCount; f++) {
          let fa = random(150, 240);
          let fl = random(3.5, 11);
          brush.set("cotton_fiber", f % 2 === 0 ? PAPER_HIGHLIGHT : BLACK_CHAR, 0.55);
          brush.line(tip[0], tip[1], tip[0] + cos(fa) * fl, tip[1] + sin(fa) * fl);
        }
      }
    }
  }

  // Upper overhanging serrated lip
  drawSerratedBagLip([V.M_farLeft, V.M_topLeft, V.M_topPeak, V.M_topRight, V.M_midRight], 7.5, true);
  // Inner lower serrated lip
  drawSerratedBagLip([V.M_midRight, V.M_botRight, V.M_botMid, V.M_botLeft, V.M_farLeft], 7.5, false);

  // Additional hyperreal torn paper fibers & surface scuffs along sharp bag fold ridges
  function drawPaperFibreTears(p1, p2, density = 0.35) {
    let d = dist(p1[0], p1[1], p2[0], p2[1]);
    let steps = floor(d / 3.5);
    let ang = atan2(p2[1] - p1[1], p2[0] - p1[0]);
    for (let i = 0; i <= steps; i++) {
      if (random() < density) {
        let t = i / steps;
        let x = lerp(p1[0], p2[0], t);
        let y = lerp(p1[1], p2[1], t);
        let tearAng = ang + random(-65, 65);
        let tearLen = random(4, 15);
        // White torn fiber gap breaking across the ink
        brush.set("burin", PAPER_HIGHLIGHT, random(0.6, 1.1));
        brush.line(x, y, x + cos(tearAng) * tearLen, y + sin(tearAng) * tearLen);
        // Fine dark fiber shadow beside the tear
        brush.set("burin", BLACK_CHAR, 0.45);
        brush.line(x + 1, y + 1, x + 1 + cos(tearAng) * (tearLen * 0.8), y + 1 + sin(tearAng) * (tearLen * 0.8));
      }
    }
  }

  drawPaperFibreTears(V.M_midRight, V.G_valley1, 0.55);
  drawPaperFibreTears(V.G_valley1, V.G_valley2, 0.45);
  drawPaperFibreTears(V.G_tuck1, V.G_tuck2, 0.5);
  drawPaperFibreTears(V.B_fold1, V.B_fold2, 0.55);
  drawPaperFibreTears(V.B_fold2, V.B_fold3, 0.45);
  drawPaperFibreTears(V.M_topRight, V.M_midRight, 0.6);

  // =========================================================================
  // 9. FOREGROUND ORANGES (#2 AND #3) — HYPERREAL LETTERPRESS & ENGRAVING
  // =========================================================================
  renderHyperrealOrange(oranges[1]);
  renderHyperrealOrange(oranges[2]);

  // =========================================================================
  // HYPERREAL ORANGE RENDERER (Two-Ink Misregistered Plates + Engraved Peel Pores)
  // =========================================================================
  function renderHyperrealOrange(o) {
    const cx = o.cx;
    const cy = o.cy;
    const r  = o.r;

    // Light direction: from upper-left/top-front (highlight offset at (-0.34*r, -0.36*r))
    const hlX = cx - r * 0.34;
    const hlY = cy - r * 0.36;

    // -----------------------------------------------------------------------
    // STEP A: Blind Debossed Paper Halo around the Orange Sphere
    // -----------------------------------------------------------------------
    brush.set("deboss_chisel", PAPER_HIGHLIGHT, 1.5);
    brush.arc(cx - 2, cy - 2, r + 3.5, 0, 360);
    brush.set("burin", PAPER_UMBER, 0.85);
    brush.arc(cx + 1.5, cy + 1.5, r + 2, 0, 360);

    // -----------------------------------------------------------------------
    // STEP B: PLATE 1 — VERMILION INK PLATE (Shifted by MIS_X, MIS_Y)
    // -----------------------------------------------------------------------
    const vcx = cx + MIS_X;
    const vcy = cy + MIS_Y;

    // 1. Base circular vermilion body (leaving an uninked cotton highlight window)
    let vCirclePts = [];
    for (let a = 0; a < 360; a += 8) {
      let rad = r + random(-0.6, 0.6);
      vCirclePts.push([vcx + cos(a) * rad, vcy + sin(a) * rad]);
    }
    let vPoly = new brush.Polygon(vCirclePts);
    vPoly.wash(VERM_MID, 175);

    // 2. Dense solid Vermilion mass in the main body & shadow crescent (with ink squash)
    let vCrescentPts = [];
    for (let a = -55; a <= 215; a += 8) {
      vCrescentPts.push([vcx + cos(a) * r, vcy + sin(a) * r]);
    }
    for (let a = 215; a >= -55; a -= 10) {
      // Inner boundary curves around the upper-left highlight zone
      let innerR = r * 0.42;
      let ix = (vcx - r * 0.25) + cos(a) * innerR;
      let iy = (vcy - r * 0.25) + sin(a) * innerR;
      vCrescentPts.push([ix, iy]);
    }
    let vCrescentPoly = new brush.Polygon(vCrescentPts);
    vCrescentPoly.wash(VERM_SOLID, 225);
    // Letterpress ink-squash halo around the vermilion plate perimeter!
    vPoly.draw("squash_rim", VERM_SQUASH, 1.45);
    vPoly.draw("burin", VERM_SQUASH, 0.85);

    // 3. Re-open the pure cream cotton specular highlight window on the upper-left
    let specPts = [];
    for (let a = 0; a < 360; a += 15) {
      let sr = r * 0.31 * (1 + 0.12 * cos(a * 2));
      specPts.push([hlX + MIS_X * 0.4 + cos(a) * sr, hlY + MIS_Y * 0.4 + sin(a) * sr]);
    }
    let specPoly = new brush.Polygon(specPts);
    specPoly.wash(PAPER_BASE, 235);

    // 4. Spherical engraved halftone contours in Vermilion ink
    // Latitude rings centered on the light-axis pole so lines wrap 3D around the fruit
    brush.set("burin", VERM_SQUASH, 0.62);
    for (let ring = 0.18; ring <= 0.98; ring += 0.032) {
      let ringPts = [];
      for (let a = 0; a <= 360; a += 10) {
        // Interpolate center from highlight pole (hlX, hlY) to sphere center (vcx, vcy)
        let rcx = lerp(hlX + MIS_X, vcx, ring);
        let rcy = lerp(hlY + MIS_Y, vcy, ring);
        let rr  = ring * r;
        let px  = rcx + cos(a) * rr;
        let py  = rcy + sin(a) * rr;

        // Clip inside the vermilion sphere
        if (dist(px, py, vcx, vcy) < r - 1.5) {
          // Leave broken gaps in the highlight zone
          let dHl = dist(px, py, hlX + MIS_X, hlY + MIS_Y);
          if (dHl > r * 0.24 || random() < 0.25) {
            let pWeight = map(dHl, r * 0.2, r * 1.2, 0.3, 1.25, true);
            ringPts.push([px, py, pWeight]);
          } else if (ringPts.length > 2) {
            brush.spline(ringPts, 0.3);
            ringPts = [];
          } else {
            ringPts = [];
          }
        }
      }
      if (ringPts.length > 2) {
        brush.spline(ringPts, 0.3);
      }
    }

    // -----------------------------------------------------------------------
    // STEP C: PLATE 2 — CARBON BLACK KEY PLATE (Registered at cx, cy)
    // -----------------------------------------------------------------------
    // 1. Solid Carbon Black crescent in the core terminator shadow (with ink squash)
    // Leaves a narrow reflected-light rim along the very bottom-right edge!
    let kCorePts = [];
    for (let a = -28; a <= 168; a += 8) {
      let outerR = r * 0.91; // Inset slightly from limb for reflected light!
      kCorePts.push([cx + cos(a) * outerR, cy + sin(a) * outerR]);
    }
    for (let a = 168; a >= -28; a -= 8) {
      let innerR = r * 0.56;
      let tx = (cx - r * 0.08) + cos(a) * innerR;
      let ty = (cy - r * 0.08) + sin(a) * innerR;
      kCorePts.push([tx, ty]);
    }
    let kCorePoly = new brush.Polygon(kCorePts);
    kCorePoly.wash(BLACK_SOLID, 215);
    brush.hatchStyle("burin", BLACK_SQUASH, 0.9);
    kCorePoly.hatch(2.2, 38, { rand: 0.02 });
    brush.noHatch();
    // Pronounced letterpress ink-squash halo at the boundary of the black core plate
    kCorePoly.draw("squash_rim", BLACK_SQUASH, 1.15);

    // If Orange #1 is inside the bag mouth, cast a deep canopy shadow across its upper-right hemisphere
    if (o.inBagMouth) {
      let mouthShadowPts = [];
      for (let a = -85; a <= 42; a += 8) {
        mouthShadowPts.push([cx + cos(a) * r, cy + sin(a) * r]);
      }
      for (let a = 42; a >= -85; a -= 10) {
        mouthShadowPts.push([cx + cos(a) * (r * 0.48), cy + sin(a) * (r * 0.48)]);
      }
      let msPoly = new brush.Polygon(mouthShadowPts);
      msPoly.wash(BLACK_SOLID, 225);
      msPoly.draw("squash_rim", BLACK_SQUASH, 1.1);
    }

    // 2. Wood-engraved Carbon Black halftone lines wrapping spherically (meridians + latitudes)
    for (let ring = 0.34; ring <= 0.99; ring += 0.026) {
      let segPts = [];
      for (let a = -75; a <= 215; a += 7) {
        let rcx = lerp(hlX, cx, ring);
        let rcy = lerp(hlY, cy, ring);
        let rr  = ring * r;
        let px  = rcx + cos(a) * rr;
        let py  = rcy + sin(a) * rr;

        let dCenter = dist(px, py, cx, cy);
        let dHl     = dist(px, py, hlX, hlY);

        // Calculate spherical illumination (0 = dark terminator, 1 = bright highlight)
        let lum = 1.0 - constrain(dHl / (r * 1.38), 0, 1);

        if (dCenter < r - 1.0 && lum < 0.72) {
          // Small gap modulation to simulate engraved line breaks around peel bumps
          if (noise(px * 0.08, py * 0.08) > lum * 0.82) {
            let pr = map(lum, 0, 0.72, 1.35, 0.2, true);
            segPts.push([px, py, pr]);
          } else {
            if (segPts.length > 1) {
              brush.set("burin", BLACK_SOLID, 0.68);
              brush.spline(segPts, 0.25);
            }
            segPts = [];
          }
        } else {
          if (segPts.length > 1) {
            brush.set("burin", BLACK_SOLID, 0.68);
            brush.spline(segPts, 0.25);
          }
          segPts = [];
        }
      }
      if (segPts.length > 1) {
        brush.set("burin", BLACK_SOLID, 0.68);
        brush.spline(segPts, 0.25);
      }
    }

    // Cross-hatched meridional engraving lines from the stem calyx pole
    let numMeridians = 44;
    for (let m = 0; m < numMeridians; m++) {
      let baseAng = (m / numMeridians) * 360;
      let mPts = [];
      for (let t = 0.14; t <= 0.98; t += 0.06) {
        // Curve meridians across the sphere from calyx toward opposite pole
        let curX = lerp(o.calyxX, cx + (cx - o.calyxX) * 0.45, t);
        let curY = lerp(o.calyxY, cy + (cy - o.calyxY) * 0.45, t);
        let rad  = sin(t * 180) * r * 0.96;
        let px   = curX + cos(baseAng) * rad;
        let py   = curY + sin(baseAng) * rad;

        if (dist(px, py, cx, cy) < r - 2) {
          let dHl = dist(px, py, hlX, hlY);
          let lum = 1.0 - constrain(dHl / (r * 1.35), 0, 1);
          if (lum < 0.62 && random() > lum * 0.9) {
            mPts.push([px, py, map(lum, 0, 0.62, 1.15, 0.2)]);
          } else {
            if (mPts.length > 1) {
              brush.set("burin", BLACK_CHAR, 0.55);
              brush.spline(mPts, 0.3);
            }
            mPts = [];
          }
        }
      }
      if (mPts.length > 1) {
        brush.set("burin", BLACK_CHAR, 0.55);
        brush.spline(mPts, 0.3);
      }
    }

    // Outer Carbon Black key-plate contour with ink squash along the shadow hemisphere
    brush.set("squash_rim", BLACK_SQUASH, 1.35);
    brush.arc(cx, cy, r, -45, 195);
    brush.set("burin", BLACK_CHAR, 0.72);
    brush.arc(cx, cy, r, 185, 325);

    // -----------------------------------------------------------------------
    // STEP D: HYPERREAL PEEL PORE DIMPLES (Sebaceous Oil Glands)
    // -----------------------------------------------------------------------
    // Generate ~320 Fibonacci-spiral points across the hemisphere, foreshortened
    // toward the limb, rendered as engraved micro-craters in Vermilion, Black & Cream
    const numPores = 330;
    const goldenAngle = 137.50776;

    for (let i = 1; i < numPores; i++) {
      let frac = i / numPores;
      // Concentrate slightly toward mid-sphere and limb
      let rho = sqrt(frac) * (r - 4.5);
      let theta = i * goldenAngle;

      let px = cx + cos(theta) * rho + random(-1.8, 1.8);
      let py = cy + sin(theta) * rho + random(-1.8, 1.8);

      // Skip inside the stem calyx button
      if (dist(px, py, o.calyxX, o.calyxY) < o.calyxRx * 1.25) continue;

      let dCenter = dist(px, py, cx, cy);
      if (dCenter >= r - 3.5) continue;

      let dHl = dist(px, py, hlX, hlY);
      let lum = 1.0 - constrain(dHl / (r * 1.38), 0, 1);

      // Pore radius foreshortens near the edge of the sphere
      let foreshorten = sqrt(max(0.15, 1 - sq(dCenter / r)));
      let poreR = random(1.4, 2.7) * (0.55 + 0.45 * foreshorten);

      if (lum > 0.76) {
        // In the bright highlight zone: delicate vermilion & blind-deboss pinprick pores
        if (random() < 0.72) {
          brush.set("burin", VERM_SOLID, 0.55);
          brush.arc(px + MIS_X * 0.45, py + MIS_Y * 0.45, poreR, -40, 155);
          brush.set("burin", PAPER_UMBER, 0.45);
          brush.arc(px, py, poreR * 0.85, 120, 310);
        }
      } else if (lum > 0.36) {
        // Midtone zone: crisp engraved pore dimple!
        // Dark crescent on the side facing the light (inner wall of the dimple),
        // plus uninked cream cotton catchlight on the opposite lip!
        let lightAng = atan2(py - hlY, px - hlX);
        let arcStart = lightAng + 110;
        let arcEnd   = lightAng + 285;

        // Vermilion pore crescent (slightly misregistered)
        brush.set("burin", VERM_SQUASH, 0.68);
        brush.arc(px + MIS_X * 0.3, py + MIS_Y * 0.3, poreR * 1.05, arcStart, arcEnd);

        // Carbon Black burin pore crescent
        brush.set("burin", BLACK_SOLID, map(lum, 0.36, 0.76, 0.82, 0.45));
        brush.arc(px, py, poreR, arcStart, arcEnd);

        // Tiny uninked cream cotton rim catchlight on the far lip of the dimple
        brush.set("burin", PAPER_HIGHLIGHT, 0.65);
        brush.arc(px + cos(lightAng) * 0.8, py + sin(lightAng) * 0.8, poreR * 0.8, lightAng - 65, lightAng + 65);
      } else {
        // Shadow & terminator zone: pores appear as tiny vermilion & cream glints
        // breaking through the dense carbon-black engraving!
        let lightAng = atan2(py - hlY, px - hlX);
        brush.set("burin", VERM_MID, 0.72);
        brush.arc(px, py, poreR, lightAng - 75, lightAng + 75);
        if (random() < 0.45) {
          brush.set("burin", PAPER_BASE, 0.55);
          brush.line(px, py, px + cos(lightAng) * 1.6, py + sin(lightAng) * 1.6);
        }
        brush.set("burin", BLACK_SQUASH, 0.85);
        brush.arc(px, py, poreR * 1.1, lightAng + 95, lightAng + 265);
      }
    }

    // -----------------------------------------------------------------------
    // STEP E: THE STEM CALYX SCAR (Woody Rosette & Radiating Peel Pleats)
    // -----------------------------------------------------------------------
    const kx = o.calyxX;
    const ky = o.calyxY;
    const krx = o.calyxRx;
    const kry = o.calyxRy;
    const kang = o.calyxAng;

    // 1. Recessed circular collar around the calyx
    let calPts = [];
    for (let a = 0; a < 360; a += 20) {
      let lx = cos(a) * krx;
      let ly = sin(a) * kry;
      let gx = kx + lx * cos(kang) - ly * sin(kang);
      let gy = ky + lx * sin(kang) + ly * cos(kang);
      calPts.push([gx, gy]);
    }
    let calPoly = new brush.Polygon(calPts);
    calPoly.wash(PAPER_DEEP, 225);
    calPoly.draw("squash_rim", BLACK_SOLID, 0.95);

    // 2. Five-pointed woody star button inside the calyx
    let starPts = [];
    for (let i = 0; i < 10; i++) {
      let a = i * 36;
      let radScale = (i % 2 === 0) ? 0.82 : 0.38;
      let lx = cos(a) * krx * radScale;
      let ly = sin(a) * kry * radScale;
      let gx = kx + lx * cos(kang) - ly * sin(kang);
      let gy = ky + lx * sin(kang) + ly * cos(kang);
      starPts.push([gx, gy]);
    }
    let starPoly = new brush.Polygon(starPts);
    starPoly.wash(BLACK_EARTH, 215);
    starPoly.draw("burin", BLACK_SQUASH, 0.85);

    // Central woody pith highlight dot
    brush.set("deboss_chisel", PAPER_HIGHLIGHT, 1.1);
    brush.circle(kx - 1.5, ky - 1.5, 2.8, 0.15);
    brush.set("burin", BLACK_SOLID, 0.75);
    brush.circle(kx, ky, 3.2, 0.15);

    // 3. Radiating puckered peel pleats around the calyx button
    for (let i = 0; i < 22; i++) {
      let a = (i / 22) * 360 + random(-5, 5);
      let r1 = 1.05;
      let r2 = random(1.65, 2.55);
      let x1 = kx + (cos(a) * krx * r1) * cos(kang) - (sin(a) * kry * r1) * sin(kang);
      let y1 = ky + (cos(a) * krx * r1) * sin(kang) + (sin(a) * kry * r1) * cos(kang);
      let x2 = kx + (cos(a) * krx * r2) * cos(kang) - (sin(a) * kry * r2) * sin(kang);
      let y2 = ky + (cos(a) * krx * r2) * sin(kang) + (sin(a) * kry * r2) * cos(kang);

      if (dist(x2, y2, cx, cy) < r - 3) {
        brush.set("burin", BLACK_SOLID, 0.68);
        brush.line(x1, y1, x2, y2);
        brush.set("burin", PAPER_HIGHLIGHT, 0.55);
        brush.line(x1 + 1.2, y1 - 1.2, x2 + 1.2, y2 - 1.2);
      }
    }
  }

  // =========================================================================
  // 10. FINAL LETTERPRESS OVERLAY: LOWER BAG LIP OVERLAPPING ORANGE #1 & CRUMBS
  // =========================================================================
  // The lower-right corner of the grocery bag's mouth fold slightly overlaps
  // the bottom-right edge of Orange #1, locking it physically inside the bag
  const lowerLipOverlap = [
    [682, 868], V.M_botRight, V.B_fold1, [765, 922], [652, 952], V.M_botMid
  ];
  let lipPoly = new brush.Polygon(lowerLipOverlap);
  lipPoly.wash(PAPER_DEEP, 210);
  brush.hatchStyle("burin", BLACK_SOLID, 0.78);
  lipPoly.hatch(2.8, -18, { rand: 0.02 });
  brush.noHatch();
  lipPoly.draw("squash_rim", BLACK_SQUASH, 1.15);
  drawSerratedBagLip([[682, 868], V.M_botMid, V.M_botLeft], 7.0, false);

  // Tiny scattered debris on the cotton table surface (dried citrus stem fleck & paper shards)
  const crumbs = [
    { x: 538, y: 982, sz: 5.5 },
    { x: 365, y: 955, sz: 4.2 },
    { x: 332, y: 895, sz: 3.5 },
    { x: 585, y: 1015, sz: 6.0 },
    { x: 158, y: 862, sz: 3.8 }
  ];
  for (let c of crumbs) {
    // Vermilion misregistered speck
    brush.set("squash_rim", VERM_SOLID, 0.85);
    brush.line(c.x + MIS_X * 0.5, c.y + MIS_Y * 0.5, c.x + c.sz + MIS_X * 0.5, c.y + 1.5 + MIS_Y * 0.5);
    // Carbon black speck + tiny cast shadow
    brush.set("squash_rim", BLACK_SOLID, 0.95);
    brush.line(c.x, c.y, c.x + c.sz, c.y + 1.5);
    brush.set("burin", PAPER_HIGHLIGHT, 0.65);
    brush.line(c.x, c.y - 1.2, c.x + c.sz * 0.7, c.y - 0.5);
  }

  noLoop();
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(4271);

  // Custom fine chisel brush for refracted mirage slats
  brush.add("mirage_slat", {
    type: "custom",
    weight: 3.5,
    scatter: 0.12,
    opacity: 42,
    spacing: 0.45,
    pressure: [0.3, 1.2, 0.3],
    tip: (_m) => {
      _m.rect(-3, -0.4, 6, 0.8);
    },
    rotate: "none",
    markerTip: false,
    noise: 0.35
  });

  // Custom razor pencil for hyperreal chrome & visor core
  brush.add("razor_core", {
