    grain: 18,
    opacity: 210,
    spacing: 0.18,
    pressure: [0.7, 1.15, 0.6],
    noise: 0.15
  });
}

// Deterministic horizontal refraction offset simulating superheated desert strata
function getRefractionDX(y) {
  let n = noise(y * 0.035, 14.2) - 0.5;
  let fault = 0;
  // Discrete atmospheric shear bands
  if (y > 328 && y < 342) fault = 14;
  else if (y > 412 && y < 426) fault = -18;
  else if (y > 488 && y < 504) fault = 24;
  else if (y > 522 && y < 548) fault = -32;
  else if (y > 555 && y < 578) fault = 28;

  if (y > 578) {
    let depth = (y - 578) / 380;
    let wave = sin((y - 578) * 3.4) * (18 + depth * 55);
    let subWave = cos((y - 578) * 8.5) * (8 + depth * 22);
    return wave + subWave + n * 35;
  }
  return fault + n * 8;
}

// Helper for drawing broken, horizontally refracted watercolour bands
function drawRefractedBand(x, y, w, h, skew, jitter) {
  let j = jitter || 2.5;
  brush.beginShape(0.08);
  brush.vertex(x + random(-j, j), y + random(-j * 0.3, j * 0.3));
  brush.vertex(x + w * 0.35, y - random(0, j * 0.4));
  brush.vertex(x + w + skew + random(-j, j), y + random(-j * 0.3, j * 0.3));
  brush.vertex(x + w + skew * 0.5 + random(-j, j), y + h + random(-j * 0.3, j * 0.3));
  brush.vertex(x + w * 0.6, y + h + random(0, j * 0.4));
  brush.vertex(x - skew * 0.5 + random(-j, j), y + h + random(-j * 0.3, j * 0.3));
  brush.endShape(true);
}

