  // 2. TREMBLING SALT FLAT CRUST & ATMOSPHERIC REFRACTION FAULT LINES
  // =========================================================================
  // Faint foreshortened salt polygons in the foreground glare
  for (let row = 0; row < 11; row++) {
    let t = row / 10;
    let y = lerp(640, 1175, pow(t, 1.35));
    let nextY = lerp(640, 1175, pow((row + 1) / 10, 1.35));
    let spanW = lerp(75, 190, t);
    let count = floor(1200 / spanW) + 2;

    for (let i = -1; i < count; i++) {
      // Leave the central mirage pool liquid and un-crusted
      let xCenter = i * spanW + (row % 2) * (spanW * 0.5);
      if (y < 910 && abs(xCenter - cx) < lerp(360, 160, (y - 640) / 270)) continue;
      if (random() < 0.35) continue;

      let x1 = xCenter - spanW * 0.45 + random(-12, 12);
      let x2 = xCenter + spanW * 0.45 + random(-12, 12);
      let xm = xCenter + random(-15, 15);
