    if (random() < 0.55) {
      y = horizonY + randomGaussian(0, 95);
    }
    let dx = getRefractionDX(y);
    let len = random(45, 280);
    let x = random(30, 1170 - len) + dx * 0.5;

    let col = "#e6c367";
    let bName = "2H";
    let w = random(0.2, 0.45);

    if (y < horizonY - 40) {
      col = random(["#8eb7d9", "#b0d0e8", "#e8d396"]);
    } else if (abs(y - horizonY) < 48) {
      col = random(["#b84b20", "#8f3310", "#d97a3e", "#f0cb69"]);
      bName = random(["cpencil", "2H", "mirage_slat"]);
      w = random(0.25, 0.65);
    } else if (y > horizonY + 30 && y < 910 && abs(x + len * 0.5 - cx) < 420) {
      col = random(["#13448a", "#2564b3", "#5894d6", "#b84b20", "#f5d77f"]);
      bName = random(["cpencil", "mirage_slat"]);
      w = random(0.3, 0.7);
    }

    brush.set(bName, col, w);
    brush.line(x, y, x + len, y + random(-0.8, 0.8));
  }

  // =========================================================================
  // 3. UPSIDE-DOWN MIRAGE REFLECTION & WAVERING LEG RIBBONS (y = 576..955)
  // =========================================================================
  const mirrorY = 578;

  // Scanline ribbon synthesis for the inverted rider, smearing legs into wavering ribbons
  for (let y = mirrorY; y <= 950; y += 2.2) {
    let depth = (y - mirrorY) / (950 - mirrorY); // 0 at contact patch -> 1 at bottom of helmet reflection
    let waveDX = getRefractionDX(y);

    // Occasional refracted gap where blinding glare or cobalt water cuts through
    if (sin(y * 7.1) > 0.78 && depth > 0.15) continue;

