      brush.line(leftRibbonX - ribbonHalfW, y, leftRibbonX + ribbonHalfW, y);
      brush.line(rightRibbonX - ribbonHalfW, y, rightRibbonX + ribbonHalfW, y);

      // Scorched sienna & cobalt fraying on the ribbon edges
      if (random() < 0.65) {
        let edgeCol = random(["#b84b20", "#1c58ab", "#d4743b", "#4584cc"]);
        brush.set("2H", edgeCol, 0.4);
        brush.line(leftRibbonX - ribbonHalfW - random(6, 26), y, leftRibbonX + ribbonHalfW + random(6, 26), y);
        brush.line(rightRibbonX - ribbonHalfW - random(6, 26), y, rightRibbonX + ribbonHalfW + random(6, 26), y);
      }

      // Specular boot buckle / leather highlight smears near top of reflection
