        brush.set("razor_core", "#fbf8ee", 0.55);
        brush.line(leftRibbonX - 5, y, leftRibbonX + 6, y);
        brush.line(rightRibbonX - 6, y, rightRibbonX + 5, y);
      }
    }

    // 3B. Inverted Front Tire, Forks & Engine Core (y = 578..785)
    if (y < 785) {
      let bikeT = (y - mirrorY) / 207;
      let centerWave = cx + waveDX * (0.25 + bikeT * 0.55);

      // Tire & Fender reflection (y = 578..695)
