        brush.line(centerWave - tireHalfW, y, centerWave + tireHalfW, y);
      }

      // Twin Chrome Forks & Exhaust Headers reflection (y = 610..775)
      if (y > 605) {
        let forkSpread = 33 + sin(y * 6) * 5;
        brush.set("cpencil", random(["#fffef9", "#7ab0de", "#13448a", "#c95b27"]), 0.65);
        brush.line(centerWave - forkSpread - 7, y, centerWave - forkSpread + 7, y);
        brush.line(centerWave + forkSpread - 7, y, centerWave + forkSpread + 7, y);
      }
    }

    // 3C. Inverted Chrome Headlamp Glare Column (y = 720..810)
