    }

    // 3E. Inverted Helmet & Cobalt Visor Reflection (y = 835..935)
    if (y > 835 && y < 935) {
      let helmT = map(y, 835, 935, -1, 1);
      let helmW = sqrt(max(0, 1 - helmT * helmT)) * 36 + random(-4, 8);
