  }

  // Liquid horizon glare & ripple slits cutting across the cobalt mirage pool
  for (let i = 0; i < 65; i++) {
    let ry = random(576, 920);
    let rx = cx + randomGaussian(0, 160);
    let rw = random(25, 130);
