  // =========================================================================
  // 4. WATERCOLOUR & DRY-PIGMENT UNDERPAINTING OF THE MOTORCYCLIST (y = 258..582)
  // =========================================================================
  brush.noStroke();
  brush.noHatch();
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.45, 0.35);

  // Dark espresso/charcoal core silhouette washes (Jacket, Tank, Tire, Boots)
  brush.fill("#221d1a", 165);
  // Rider torso & shoulders
  brush.beginShape(0.15);
  brush.vertex(564, 306);
  brush.vertex(504, 334);
  brush.vertex(488, 368);
  brush.vertex(528, 384);
  brush.vertex(542, 428);
