  brush.vertex(636, 306);
  brush.endShape(true);

  // Left thigh, knee & boot mass
  brush.beginShape(0.12);
  brush.vertex(544, 412);
  brush.vertex(516, 438);
  brush.vertex(514, 482);
  brush.vertex(522, 558);
  brush.vertex(550, 562);
  brush.vertex(556, 485);
  brush.vertex(564, 440);
  brush.endShape(true);

  // Right thigh, knee & boot mass
  brush.beginShape(0.12);
  brush.vertex(656, 412);
  brush.vertex(684, 438);
  brush.vertex(686, 482);
  brush.vertex(678, 558);
  brush.vertex(650, 562);
  brush.vertex(644, 485);
  brush.vertex(636, 440);
  brush.endShape(true);

  // Engine cradle & front tire dark core
  brush.rect(558, 420, 84, 96, "corner");
  brush.rect(577, 456, 46, 124, "corner");

  // Helmet shell underpainting
  brush.fill("#1c1917", 185);
  brush.circle(cx, 298, 35, 0.08);

  // Scorched sienna & Naples yellow ground-bounce reflections on leather & engine
  brush.fill("#b84b20", 110);
  brush.rect(516, 462, 34, 36, "corner");
  brush.rect(650, 462, 34, 36, "corner");
  brush.rect(544, 455, 22, 58, "corner");
  brush.rect(634, 455, 22, 58, "corner");

  // Cobalt visor & tank reflection glazes
  brush.fill("#1852a3", 150);
