  // =========================================================================
  // 5. FRAYING HEAT RIPPLES AT THE OUTER EDGES OF THE RIDER & MACHINE
  // =========================================================================
  // Before locking in the needle-sharp core, fray the outer contours into horizontal ripples
  for (let y = 262; y <= 576; y += 2.0) {
    let leftEdge = 0;
    let rightEdge = 0;

    if (y < 312) {
      // Helmet top/sides
