      leftEdge = 468;
      rightEdge = 732;
    } else if (y < 425) {
      // Torso / fuel tank
      leftEdge = 536;
      rightEdge = 664;
    } else if (y < 495) {
      // Knees & exhaust pipes
      leftEdge = 514;
      rightEdge = 686;
    } else {
      // Boots & footpegs
      leftEdge = 518;
      rightEdge = 682;
    }

    let shift = getRefractionDX(y) * 0.45;
    let frayLenL = random(14, 68) * (1 + 0.6 * abs(sin(y * 4.5)));
    let frayLenR = random(14, 68) * (1 + 0.6 * abs(cos(y * 4.5)));

