  // =========================================================================
  // 6. HYPERREAL COLOURED-PENCIL & ROTRING CORE: MOTORCYCLE & RIDER
  // =========================================================================

  // --- 6A. FRONT TIRE, TREAD & FENDER (Core x = 577..623, y = 450..582) ---
  for (let y = 458; y <= 580; y += 1.4) {
