  brush.set("razor_core", "#ffffff", 0.65);
  brush.line(cx - 8, 325, cx + 8, 325);
  brush.set("rotring", "#0d0c0b", 0.6);
  brush.line(cx - 7, 327, cx + 7, 327);

  // =========================================================================
  // 7. FINAL OPTICAL REFRACTION SLICES & TREMBLING GLARE INCIDENTS
  // =========================================================================
  // Delicate horizontal refraction shear lines cutting right across the outer edges
  const shearYList = [294, 336, 371, 419, 488, 534, 558, 576];
  for (let sy of shearYList) {
    let shift = (sy % 2 === 0 ? 1 : -1) * random(14, 28);
    brush.set("razor_core", "#fbf8ee", 0.72);
    brush.line(cx - 175 + shift, sy, cx - 32, sy);
    brush.line(cx + 32, sy, cx + 175 + shift, sy);

    brush.set("razor_core", random(["#b84b20", "#1c58ab"]), 0.48);
    brush.line(cx - 195 + shift, sy + 1.4, cx - 45, sy + 1.4);
    brush.line(cx + 45, sy + 1.4, cx + 195 + shift, sy + 1.4);
  }

  // Subtle sun-bleached salt dust & shimmer stipple across the horizon boundary
  brush.set("spray", "#fbf8ee", 0.65);
  for (let i = 0; i < 18; i++) {
    let sx = random(80, 1120);
    let sy = horizonY + random(-35, 65);
    if (abs(sx - cx) < 95 && sy < 560) continue; // Keep rider core razor-sharp
    brush.line(sx, sy, sx + random(30, 90), sy);
  }

  noLoop();
}

// Monumental Hyperrealism in p5.brush
// Subject: Broad shoulder & upper back in a steamy bathhouse with healed irezumi
// (climbing koi, waterfall, wind bars & peonies under glistening porous skin)

let silhouettePts = [];
let customFieldReady = false;

async function setup() {
