  });

  // Custom vector field for rising bathhouse steam & anatomical contours
  brush.addField("steam_rise", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let sw = sin(ny * 260 + nx * 140 + t * 10) * 28;
        let curl = (noise(nx * 3.2, ny * 3.2, 0.7) - 0.5) * 65;
        field[col][row] = -90 + sw + curl;
      }
    }
    return field;
  });

  buildSilhouettePolygon();
  background("#e8e4df");
}

// ============================================================================
// SAFE STATE HELPERS FOR P5.BRUSH
// ============================================================================
function useStroke(name, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, weight);
}

function useWatercolor(col, opacity = 80, bleed = 0.22, tex = 0.42, border = 0.22) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
}

function useWash(col, opacity = 80) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, opacity);
}

function drawShapePoly(pts, curvature = 0.28, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// ============================================================================
// 3D ANATOMICAL SURFACE & SILHOUETTE GEOMETRY
// ============================================================================
function buildSilhouettePolygon() {
  // Monumental tight crop of upper back, neck, broad right trapezius, deltoid & arm
  const ctrl = [
    [-40, 240],
    [70, 202],
    [195, 162],
    [295, 122],
    [332, 65],
    [345, -30],
    [460, -45],
    [568, -30],
    [578, 52],
    [594, 102],
    [665, 146],
    [785, 186],
    [915, 224],
    [1015, 268],
    [1084, 338],
    [1122, 430],
    [1130, 535],
    [1112, 635],
    [1096, 705], // Deltoid insertion notch
    [1112, 815], // Tricep lateral swell
    [1106, 965],
    [1086, 1110],
    [1072, 1235],
    [500, 1250],
    [-45, 1250]
  ];

  silhouettePts = [];
  // Interpolate smooth upper/right anatomical contour (indices 0..22)
  for (let i = 0; i < 22; i++) {
    let p0 = ctrl[max(0, i - 1)];
    let p1 = ctrl[i];
    let p2 = ctrl[i + 1];
    let p3 = ctrl[min(22, i + 2)];
    let steps = 12;
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let x = catmullRom(p0[0], p1[0], p2[0], p3[0], t);
      let y = catmullRom(p0[1], p1[1], p2[1], p3[1], t);
      silhouettePts.push([x, y]);
    }
  }
  silhouettePts.push(ctrl[22]);
  silhouettePts.push(ctrl[23]);
  silhouettePts.push(ctrl[24]);
}

function catmullRom(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  return 0.5 * (
    (2 * p1) +
    (-p0 + p2) * t +
    (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 +
    (-p0 + 3 * p1 - 3 * p2 + p3) * t3
  );
}

function sstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function distToSegment(px, py, x1, y1, x2, y2) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let l2 = dx * dx + dy * dy;
  if (l2 === 0) return dist(px, py, x1, y1);
  let t = constrain(((px - x1) * dx + (py - y1) * dy) / l2, 0, 1);
  return dist(px, py, x1 + t * dx, y1 + t * dy);
}

function isInsideBody(x, y) {
  // Ray casting against silhouette polygon
  let inside = false;
  for (let i = 0, j = silhouettePts.length - 1; i < silhouettePts.length; j = i++) {
    let xi = silhouettePts[i][0], yi = silhouettePts[i][1];
    let xj = silhouettePts[j][0], yj = silhouettePts[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / (yj - yi + 0.00001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function distToSkinEdge(x, y) {
  // Minimum distance to visible skin-to-air boundary (excluding bottom/left offscreen edges)
  let minD = 9999;
  let limit = silhouettePts.length - 3;
  for (let i = 0; i < limit; i++) {
    let p = silhouettePts[i];
    if (p[1] < -10 || p[1] > 1210 || p[0] < -10) continue;
    let d = dist(x, y, p[0], p[1]);
    if (d < minD) minD = d;
  }
  return minD;
}

function getSpineX(y) {
  // Subtle S-curve of the median spinal furrow from nape (C7) down thoracic/lumbar spine
  return 468 + 18 * sin((y - 90) * 0.19) - 14 * ((y - 550) / 650);
}

function getRawBodyHeight(x, y) {
  let sx = getSpineX(y);
  let ds = x - sx;

  // 1. Broad barrel arch of the upper back and ribcage
  let centerShift = sx + 75;
  let arch = 1.0 - pow((x - centerShift) / 660, 2) * 0.72 - pow((y - 480) / 980, 2) * 0.18;

  // Roll off smoothly toward the physical silhouette of shoulder, arm, and trapezius
  let dEdge = distToSkinEdge(x, y);
  let edgeRoll = pow(constrain(dEdge / 155, 0.02, 1.0), 0.52);
  let h = arch * (0.32 + 0.68 * edgeRoll);

  // 2. Median spinal furrow (deepens through thoracic spine)
  let grooveDepth = 0.145 * sstep(80, 260, y) * (0.75 + 0.25 * sin(y * 0.15));
  h -= grooveDepth * exp(-(ds * ds) / (2 * 33 * 33));

  // 3. C7 (vertebra prominens) & T1 subtle bony bumps at base of neck
  h += 0.048 * exp(-(ds * ds) / 480 - pow(y - 126, 2) / 420);
  h += 0.032 * exp(-(ds * ds) / 520 - pow(y - 168, 2) / 460);

  // 4. Erector spinae / paraspinal muscular columns flanking the spine
  let erectorEnv = sstep(140, 340, y);
  h += 0.068 * erectorEnv * exp(-pow(ds - 64, 2) / 2300);
  h += 0.060 * erectorEnv * exp(-pow(ds + 58, 2) / 2200);

  // 5. Right Scapula (Shoulder blade) - tilted muscular plane & scapular spine
  let rx = x - 735;
  let ry = y - 455;
  let angR = -14;
  let uR = rx * cos(angR) - ry * sin(angR);
  let vR = rx * sin(angR) + ry * cos(angR);
  h += 0.165 * exp(-pow(uR / 175, 2) - pow(vR / 195, 2));

  // Spine of the right scapula (prominent ridge from medial border to acromion)
  let dScapSpineR = distToSegment(x, y, 575, 332, 975, 258);
  h += 0.088 * exp(-pow(dScapSpineR / 42, 2));

  // Medial border step of right scapula (subtle anatomical depression between spine & blade)
  let dMedialR = distToSegment(x, y, 578, 330, 618, 635);
  h -= 0.038 * exp(-pow(dMedialR / 26, 2));

  // Teres major / infraspinatus lateral swell
  h += 0.075 * exp(-pow((x - 865) / 110, 2) - pow((y - 545) / 145, 2));

  // 6. Left Scapula (turning away into left bathhouse mist)
  let lx = x - 210;
  let ly = y - 465;
  let angL = 13;
  let uL = lx * cos(angL) - ly * sin(angL);
  let vL = lx * sin(angL) + ly * cos(angL);
  h += 0.125 * exp(-pow(uL / 165, 2) - pow(vL / 190, 2));
  let dScapSpineL = distToSegment(x, y, 368, 338, 40, 285);
  h += 0.062 * exp(-pow(dScapSpineL / 42, 2));

  // 7. Right Posterior & Lateral Deltoid (Monumental shoulder cap)
  let dx = x - 998;
  let dy = y - 438;
  h += 0.235 * exp(-pow(dx / 138, 2) - pow(dy / 185, 2));

  // Deltoid-infraspinatus cleft (anatomical groove where posterior deltoid meets back)
  let dDeltCleft = distToSegment(x, y, 895, 345, 1088, 675);
  h -= 0.062 * exp(-pow(dDeltCleft / 25, 2));

  // 8. Tricep lateral head below deltoid insertion
  h += 0.115 * exp(-pow((x - 1025) / 105, 2) - pow((y - 880) / 240, 2));

  // 9. Trapezius hood (nape to acromion & down thoracic spine)
  let dTrapR = distToSegment(x, y, 485, 85, 925, 240);
  h += 0.105 * exp(-pow(dTrapR / 78, 2));
  let dTrapL = distToSegment(x, y, 445, 85, 110, 210);
  h += 0.085 * exp(-pow(dTrapL / 75, 2));

  return h;
}

function getAnatomy(x, y) {
  let eps = 4.0;
  let h = getRawBodyHeight(x, y);
  let hx = getRawBodyHeight(x + eps, y);
  let hy = getRawBodyHeight(x, y + eps);
  let dzdx = (hx - h) / eps;
  let dzdy = (hy - h) / eps;

  // Surface normal N
  let nx = -dzdx * 290;
  let ny = -dzdy * 290;
  let nz = 1.0;
  let len = sqrt(nx * nx + ny * ny + nz * nz) || 1;
  nx /= len;
  ny /= len;
  nz /= len;

  // Primary bathhouse skylight (upper right front)
  let l1x = 0.40, l1y = -0.52, l1z = 0.754;
  let diff = constrain(nx * l1x + ny * l1y + nz * l1z, 0, 1);

  // Secondary warm-mist bounce light (left/below)
  let l2x = -0.45, l2y = 0.28, l2z = 0.847;
  let bounce = constrain(nx * l2x + ny * l2y + nz * l2z, 0, 1);

  // Half-vector wet skin specular reflection
  let hxVec = l1x, hyVec = l1y, hzVec = l1z + 1.0;
  let hLen = sqrt(hxVec * hxVec + hyVec * hyVec + hzVec * hzVec);
  hxVec /= hLen; hyVec /= hLen; hzVec /= hLen;
  let ndoth = constrain(nx * hxVec + ny * hyVec + nz * hzVec, 0, 1);
  let specBroad = pow(ndoth, 11);
  let specSharp = pow(ndoth, 34);

  // Fresnel rim light along wet shoulder/trapezius edge
  let rim = pow(constrain(1.0 - nz, 0, 1), 2.2) * constrain((x - 500) / 600, 0, 1);

  return {
    h, dzdx, dzdy, nx, ny, nz,
    diff, bounce, specBroad, specSharp, rim
  };
}

// Warps any 2D tattoo coordinate over the 3D muscle topography
function warpTattooPt(x, y) {
  let a = getAnatomy(x, y);
  let dEdge = distToSkinEdge(x, y);
  // Foreshortening pulls pigment inward near the curved silhouette of deltoid/trapezius
  let edgePull = (1.0 - sstep(15, 130, dEdge)) * 22;
  let wx = x + a.dzdx * 4600 - a.nx * edgePull;
  let wy = y + a.dzdy * 4600 - a.ny * edgePull;
  return [wx, wy, a];
}

// Checks whether a point is inside the tattooed region (respecting mikiri borders)
function isInsideTattoo(x, y) {
  if (!isInsideBody(x, y)) return false;
  let dEdge = distToSkinEdge(x, y);
  if (dEdge < 8) return false;

  // 1. Nape of neck untattooed opening (classic munewari / collar mikiri curve)
  let neckDist = pow((x - 455) / 145, 2) + pow((y - 25) / 140, 2);
  if (neckDist < 1.0) return false;

  // 2. Lower right arm / lateral tricep botan-giri (scalloped sleeve border)
  let armCut = pow((x - 1145) / 215, 2) + pow((y - 980) / 310, 2);
  if (armCut < 1.0) return false;

  return true;
}

// Modulates tattoo pigment color by skin lighting & subsurface epidermal depth
function subsurfaceColor(hexCol, x, y, depthBoost = 0) {
  let c = color(hexCol);
  let a = getAnatomy(x, y);
  let r = red(c), g = green(c), b = blue(c);

  // Epidermis warms and desaturates underlying ink slightly;
  // Lit areas lift toward warm alabaster-peach (#f4dfd3), shadows shift toward cool violet-slate (#595469)
  let lightAmt = constrain(a.diff * 0.85 + a.bounce * 0.25, 0, 1);
  let shadowAmt = constrain(1.0 - lightAmt, 0, 1);

  // Epidermal veil blend (healed ink sits ~1mm under translucent skin)
  let veil = 0.22 + depthBoost + a.specBroad * 0.22;
  r = lerp(r, 242, veil * lightAmt);
  g = lerp(g, 218, veil * lightAmt);
  b = lerp(b, 205, veil * lightAmt);

  // Shadow cooling
  r = lerp(r, 68, shadowAmt * 0.36);
  g = lerp(g, 64, shadowAmt * 0.36);
  b = lerp(b, 84, shadowAmt * 0.32);

  return color(constrain(r, 0, 255), constrain(g, 0, 255), constrain(b, 0, 255));
}

// ============================================================================
// KOI CARP PARAMETRIC GEOMETRY (CLIMBING THE WATERFALL)
// ============================================================================
const koiSpineCtrl = [
  [735, 225], // Pre-snout tangent
  [702, 278], // t=0.0: Snout rising toward waterfall crest on upper right scapula
  [648, 378], // t=0.2: Head & gill plates
  [558, 525], // t=0.4: Broad muscular shoulder crossing medial scapula
  [482, 705], // t=0.6: Midsection flexing across the human spinal furrow
  [538, 888], // t=0.8: Caudal peduncle curving back right
  [642, 1038], // t=1.0: Tail base
  [725, 1145]  // Post-tail tangent
];

function getKoiSpine(t) {
  t = constrain(t, 0, 1);
  let segs = 5;
  let scaled = t * segs;
  let idx = min(segs - 1, floor(scaled));
  let lt = scaled - idx;

  let p0 = koiSpineCtrl[idx];
  let p1 = koiSpineCtrl[idx + 1];
  let p2 = koiSpineCtrl[idx + 2];
  let p3 = koiSpineCtrl[idx + 3];

  let x = catmullRom(p0[0], p1[0], p2[0], p3[0], lt);
  let y = catmullRom(p0[1], p1[1], p2[1], p3[1], lt);

  // Tangent via small delta
  let dt = 0.01;
  let tNext = min(1, t + dt);
  let scaledN = tNext * segs;
  let idxN = min(segs - 1, floor(scaledN));
  let ltN = scaledN - idxN;
  let nx = catmullRom(koiSpineCtrl[idxN][0], koiSpineCtrl[idxN + 1][0], koiSpineCtrl[idxN + 2][0], koiSpineCtrl[idxN + 3][0], ltN);
  let ny = catmullRom(koiSpineCtrl[idxN][1], koiSpineCtrl[idxN + 1][1], koiSpineCtrl[idxN + 2][1], koiSpineCtrl[idxN + 3][1], ltN);

  let tx = nx - x;
  let ty = ny - y;
  let len = sqrt(tx * tx + ty * ty) || 1;
  tx /= len;
  ty /= len;

  // Normal vector pointing right/outward from spine
  let normX = -ty;
  let normY = tx;

  // Koi half-width profile along body
  let w;
  if (t < 0.16) {
    // Snout to gill cover
    w = lerp(32, 98, pow(t / 0.16, 0.72));
  } else if (t < 0.42) {
    // Gill cover to broadest belly
    let u = (t - 0.16) / 0.26;
    w = 98 + 16 * sin(u * 180);
  } else if (t < 0.86) {
    // Taper to caudal peduncle
    let u = (t - 0.42) / 0.44;
    w = lerp(102, 38, pow(u, 0.88));
  } else {
    // Tail flare
    let u = (t - 0.86) / 0.14;
    w = lerp(38, 62, u);
  }

  return { x, y, tx, ty, nx: normX, ny: normY, w };
}

// Maps (t along spine, u across width [-1..1]) to 3D muscle-warped canvas coordinates
function getKoiPoint(t, u) {
  let sp = getKoiSpine(t);
  // Slight 3D cylindrical foreshortening on the fish itself
  let cylU = sin(constrain(u, -1, 1) * 90);
  let px = sp.x + sp.nx * sp.w * cylU;
  let py = sp.y + sp.ny * sp.w * cylU;
  return warpTattooPt(px, py);
}

// Determines scale coloration (Kohaku vermilion-coral patches vs pastel indigo/jade-pearl)
function getKoiScalePalette(t, u) {
  let n = noise(t * 4.5 + 1.2, u * 2.4 + 3.7);
  // Classic Kohaku/Sanke bold vermilion markings on shoulder, flank, and tail wrist
  let patch1 = (t > 0.16 && t < 0.46 && u > -0.65 && u < 0.85 && n > 0.34);
  let patch2 = (t > 0.54 && t < 0.78 && u > -0.85 && u < 0.35 && n > 0.36);
  let patch3 = (t > 0.02 && t < 0.15 && abs(u) < 0.55);

  if (patch1 || patch2 || patch3) {
    return {
      type: "vermilion",
      base: "#c8524b",
      mid: "#e27f75",
      rim: "#f6bdb4",
      line: "#6e2e2c"
    };
  } else if (n > 0.63) {
    // Soft jade-celadon & golden-pearl scales catching waterfall reflection
    return {
      type: "jade",
      base: "#487870",
      mid: "#78aba2",
      rim: "#cbe3de",
      line: "#2b4a46"
    };
  } else {
    // Healed sumi-indigo & pearlescent white scales
    return {
      type: "indigo",
      base: "#384b61",
      mid: "#6e849c",
      rim: "#d5e0eb",
      line: "#233040"
    };
  }
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================
function draw() {
  translate(-width / 2, -height / 2);

  // 1. Bathhouse background & soft architectural haze
  drawBathhouseBackground();

  // 2. Monumental sculptural skin base washes (anatomical lighting & subsurface tones)
  drawAnatomicalSkinBase();

  // 3. Irezumi Tattoo Layer A: Mikiri borders & Bokashi Wind Bars (Gakubori)
  drawMikiriAndWindBars();

  // 4. Irezumi Tattoo Layer B: Crashing Waterfall (Taki) & Hokusai Finger Waves
  drawWaterfallAndWaves();

  // 5. Irezumi Tattoo Layer C: Peonies (Botan) & Serrated Jade Leaves (Botan-ba)
  drawAllPeonies();

  // 6. Irezumi Tattoo Layer D: The Climbing Carp (Nobori-Goi) - Fins, Scales, Head
  drawClimbingKoi();

  // 7. Epidermal Integration: Subsurface skin glazes, pores & Langer's lines OVER tattoo
  drawEpidermalVeilAndPores();

  // 8. Glistening Wet Skin Sheen along muscular crests
  drawWetSkinSpecularSheen();

  // 9. Sweat Beads & Trickling Rivulets with pin-sharp highlights
  drawSweatBeadsAndTrickles();

  // 10. Rising Bathhouse Steam veiling the lower back & blurring frame edges
  drawBathhouseSteam();

  noLoop();
}

// ============================================================================
// LAYER 1: BATHHOUSE BACKGROUND
// ============================================================================
function drawBathhouseBackground() {
  // Soft pastel grey-blue & warm mist washes in upper corners and right margin
  const bgWashes = [
    { col: "#cfd6df", op: 85, pts: [[-30, -30], [390, -30], [360, 270], [-30, 290]] },
    { col: "#bfc8d4", op: 75, pts: [[540, -30], [1230, -30], [1230, 420], [920, 270], [560, 130]] },
    { col: "#b4becb", op: 70, pts: [[1040, 260], [1230, 260], [1230, 1230], [1050, 1230]] },
    { col: "#dce1e7", op: 90, pts: [[640, -20], [1180, -20], [1160, 280], [720, 190]] }
  ];

  for (let w of bgWashes) {
    useWatercolor(w.col, w.op, 0.38, 0.45, 0.15);
    drawShapePoly(w.pts, 0.25, true);
  }

  // Subtle blurred bathhouse tile/hinoki wood horizontals in the steamy distance
  useStroke("charcoal", "#9da7b5", 0.9);
  for (let y = 35; y < 230; y += 48) {
    brush.line(600, y, 1190, y + 8);
    if (y < 200) brush.line(10, y + 15, 325, y + 10);
  }
  for (let x = 680; x < 1180; x += 95) {
    brush.line(x, 0, x - 6, 260);
  }
}

// ============================================================================
// LAYER 2: ANATOMICAL SKIN BASE WASHES
