// ============================================================================
// LAYER 3: MIKIRI BORDERS & BOKASHI WIND BARS (GAKUBORI)
// ============================================================================
function drawMikiriAndWindBars() {
  // Define 8 sweeping traditional Japanese wind bars & cloud-scroll arcs across back & shoulder
  const windBars = [
    // 1. Upper left trapezius mikiri wind bar framing the neck
    {
      arc: [[45, 235], [165, 195], [285, 165], [385, 168], [455, 205]],
      normalDir: 1, width: 78, darkCol: "#2d3a4d", midCol: "#566a82", lightCol: "#8a9eb3"
    },
    // 2. Left scapula diagonal wind bar above left peony
    {
      arc: [[-10, 385], [135, 335], [295, 315], [445, 345], [555, 405]],
      normalDir: 1, width: 88, darkCol: "#283548", midCol: "#4f637a", lightCol: "#8498ad"
    },
    // 3. Mid-left flank wind bar sweeping beneath left peony toward spine
    {
      arc: [[-10, 665], [140, 635], [305, 630], [455, 675]],
      normalDir: 1, width: 92, darkCol: "#263244", midCol: "#4c5f76", lightCol: "#7e92a8"
    },
    // 4. Lower left back wind bar framing waterfall base
    {
      arc: [[15, 920], [175, 875], [335, 885], [465, 955]],
      normalDir: 1, width: 95, darkCol: "#253042", midCol: "#495b73", lightCol: "#7a8ea3"
    },
    // 5. Upper right trapezius mikiri border arc
    {
      arc: [[555, 155], [685, 165], [825, 205], [955, 268]],
      normalDir: 1, width: 76, darkCol: "#303e52", midCol: "#5b7088", lightCol: "#91a5ba"
    },
    // 6. Right deltoid upper cloud-bar curving over shoulder dome above right peony
    {
      arc: [[795, 275], [925, 275], [1035, 325], [1105, 425]],
      normalDir: 1, width: 72, darkCol: "#2e3c50", midCol: "#576c84", lightCol: "#8ca0b5"
    },
    // 7. Right deltoid lower botan-giri (peony-cut sleeve border)
    {
      arc: [[765, 655], [895, 615], [1005, 615], [1088, 655]],
      normalDir: -1, width: 82, darkCol: "#2b384b", midCol: "#52667e", lightCol: "#869ab0"
    },
    // 8. Lower right flank wind bar below lower peony
    {
      arc: [[685, 985], [815, 955], [925, 975], [1015, 1045]],
      normalDir: -1, width: 86, darkCol: "#293648", midCol: "#4e6279", lightCol: "#8195ab"
    }
  ];

  // Batch render the 3 graded bokashi watercolor steps for all wind bars
  for (let pass = 0; pass < 3; pass++) {
    for (let wb of windBars) {
      let frac = pass === 0 ? 1.0 : (pass === 1 ? 0.65 : 0.35);
      let colHex = pass === 0 ? wb.lightCol : (pass === 1 ? wb.midCol : wb.darkCol);
      let op = pass === 0 ? 48 : (pass === 1 ? 58 : 68);

      let upperPts = [];
      let lowerPts = [];
      let samples = 18;
      for (let i = 0; i <= samples; i++) {
        let t = i / samples;
        let p = samplePolyline(wb.arc, t);
        let tang = samplePolylineTangent(wb.arc, t);
        let nx = -tang[1] * wb.normalDir;
        let ny = tang[0] * wb.normalDir;

        let p0 = warpTattooPt(p[0], p[1]);
        let p1 = warpTattooPt(p[0] + nx * wb.width * frac, p[1] + ny * wb.width * frac);
        upperPts.push([p0[0], p0[1]]);
        lowerPts.unshift([p1[0], p1[1]]);
      }

      let midPt = wb.arc[floor(wb.arc.length / 2)];
      let subCol = subsurfaceColor(colHex, midPt[0], midPt[1], 0.05);
      useWatercolor(subCol, op, 0.26, 0.42, 0.18);
      drawShapePoly(upperPts.concat(lowerPts), 0.25, true);
    }
  }

  // Fine directional bokashi shading striae + healed black outlines along wind bars
  for (let wb of windBars) {
    let samples = 44;
    let spineWarped = [];
    for (let i = 0; i <= samples; i++) {
      let t = i / samples;
      let p = samplePolyline(wb.arc, t);
      let tang = samplePolylineTangent(wb.arc, t);
      let nx = -tang[1] * wb.normalDir;
      let ny = tang[0] * wb.normalDir;

      let wp0 = warpTattooPt(p[0], p[1]);
      spineWarped.push([wp0[0], wp0[1]]);

      // Graded bokashi needle shading lines perpendicular/angled to the bar
      let len = wb.width * (0.55 + 0.35 * noise(i * 0.3, wb.width));
      let wp1 = warpTattooPt(p[0] + (nx * 0.88 + tang[0] * 0.35) * len, p[1] + (ny * 0.88 + tang[1] * 0.35) * len);
      let shadeCol = subsurfaceColor(wb.darkCol, p[0], p[1], 0.02);
      useStroke("cpencil", shadeCol, 0.85);
      brush.line(wp0[0], wp0[1], wp1[0], wp1[1]);
    }

    // Healed ink outline: soft subcutaneous halo + crisp healed sumi line
    let midPt = wb.arc[1];
    useStroke("healed_ink", subsurfaceColor("#3d4f66", midPt[0], midPt[1], 0.04), 1.55);
    brush.spline(spineWarped, 0.35);

    useStroke("pen", subsurfaceColor("#1f2937", midPt[0], midPt[1], 0.0), 1.15);
    brush.spline(spineWarped, 0.35);
  }
}

function samplePolyline(pts, t) {
  let n = pts.length - 1;
  let st = constrain(t, 0, 1) * n;
  let idx = min(n - 1, floor(st));
  let f = st - idx;
  let p0 = pts[ max(0, idx - 1) ];
  let p1 = pts[idx];
  let p2 = pts[idx + 1];
  let p3 = pts[ min(n, idx + 2) ];
  return [
    catmullRom(p0[0], p1[0], p2[0], p3[0], f),
    catmullRom(p0[1], p1[1], p2[1], p3[1], f)
  ];
}

function samplePolylineTangent(pts, t) {
  let pA = samplePolyline(pts, max(0, t - 0.02));
  let pB = samplePolyline(pts, min(1, t + 0.02));
  let dx = pB[0] - pA[0];
  let dy = pB[1] - pA[1];
  let l = sqrt(dx * dx + dy * dy) || 1;
  return [dx / l, dy / l];
}

// ============================================================================
// LAYER 4: WATERFALL (TAKI) & JAPANESE FINGER WAVES (NAMI)
// ============================================================================
function drawWaterfallAndWaves() {
  // Waterfall courses diagonally from upper right scapula (780, 180) across spine to lower back (460, 1180)
  const numStreams = 28;
  const streamPaths = [];

  for (let s = 0; s < numStreams; s++) {
    let u = s / (numStreams - 1); // 0..1 across width of waterfall
    let pts = [];
    let steps = 26;
    for (let i = 0; i <= steps; i++) {
      let v = i / steps; // 0..1 top to bottom
      // Centerline of waterfall
      let cx = lerp(775, 495, v) + 42 * sin(v * 220 - 25);
      let cy = lerp(175, 1175, v);
      let halfW = lerp(115, 195, v) + 25 * sin(v * 300);

      let offset = (u - 0.5) * 2 * halfW;
      // Streams part slightly around the climbing koi body
      let koiSp = getKoiSpine(constrain((v - 0.08) / 0.82, 0, 1));
      let dKoi = dist(cx + offset, cy, koiSp.x, koiSp.y);
      if (dKoi < koiSp.w * 1.25) {
        let push = (koiSp.w * 1.25 - dKoi) * 0.45 * (offset >= 0 ? 1 : -1);
        offset += push;
      }

      let wx = cx + offset + 12 * sin(v * 540 + s * 32);
      let wy = cy + 6 * cos(v * 420 + s * 25);
      let wp = warpTattooPt(wx, wy);
      pts.push([wp[0], wp[1], wx, wy]);
    }
    streamPaths.push(pts);
  }

  // 4A. Watercolor washes of jade-celadon & indigo-blue along the waterfall ribbons
  for (let s = 0; s < numStreams - 3; s += 3) {
    let ribbon = [];
    let sA = streamPaths[s];
    let sB = streamPaths[s + 3];
    for (let i = 0; i < sA.length; i += 2) ribbon.push([sA[i][0], sA[i][1]]);
    for (let i = sB.length - 1; i >= 0; i -= 2) ribbon.push([sB[i][0], sB[i][1]]);

    let isJade = (s % 6 === 0);
    let baseHex = isJade ? "#5b948b" : "#4b6782";
    let midP = sA[floor(sA.length / 2)];
    let wCol = subsurfaceColor(baseHex, midP[2], midP[3], 0.04);
    useWatercolor(wCol, isJade ? 52 : 48, 0.28, 0.42, 0.16);
    drawShapePoly(ribbon, 0.25, true);
  }

  // Deeper jade & sumi-indigo water pockets in the torrent
  for (let s = 1; s < numStreams - 2; s += 5) {
    let ribbon = [];
    let sA = streamPaths[s];
    let sB = streamPaths[s + 2];
    for (let i = 4; i < sA.length - 4; i += 2) ribbon.push([sA[i][0], sA[i][1]]);
    for (let i = sB.length - 5; i >= 4; i -= 2) ribbon.push([sB[i][0], sB[i][1]]);

    let midP = sA[12];
    let wCol = subsurfaceColor(s % 2 === 0 ? "#38665e" : "#2f4359", midP[2], midP[3], 0.02);
    useWatercolor(wCol, 56, 0.25, 0.45, 0.20);
    drawShapePoly(ribbon, 0.25, true);
  }

  // 4B. Crashing Waterfall Stream Lines (healed sumi-indigo & deep jade pen/pencil)
  for (let s = 0; s < numStreams; s++) {
    let path = streamPaths[s];
    let isBold = (s % 3 === 0);
    // Break stream into rhythmic segments like woodblock/irezumi waterfall lines
    let seg = [];
    for (let i = 0; i < path.length; i++) {
      let p = path[i];
      if (!isInsideTattoo(p[2], p[3])) {
        if (seg.length >= 3) drawWaterStreamSegment(seg, isBold, s);
        seg = [];
        continue;
      }
      seg.push([p[0], p[1], p[2], p[3]]);
      if (seg.length === 8 && (i + s) % 5 === 0) {
        drawWaterStreamSegment(seg, isBold, s);
        seg = [[p[0], p[1], p[2], p[3]]];
      }
    }
    if (seg.length >= 3) drawWaterStreamSegment(seg, isBold, s);
  }

  // 4C. Traditional Japanese Finger Waves (Nami-gashira) & Foam Scrolls
  const waveClusters = [
    { cx: 435, cy: 365, r: 95, dir: -35, count: 6 },  // Left of koi head
    { cx: 815, cy: 555, r: 105, dir: 155, count: 7 }, // Right of koi shoulder
    { cx: 385, cy: 765, r: 110, dir: -20, count: 7 }, // Left of koi midsection
    { cx: 745, cy: 965, r: 115, dir: 140, count: 7 }, // Right of koi tail
    { cx: 475, cy: 1095, r: 105, dir: -45, count: 6 } // Base of waterfall
  ];

  for (let wc of waveClusters) {
    drawFingerWaveCluster(wc.cx, wc.cy, wc.r, wc.dir, wc.count);
  }
}

function drawWaterStreamSegment(seg, isBold, idx) {
  let mid = seg[floor(seg.length / 2)];
  let pts2D = seg.map(p => [p[0], p[1]]);
  if (isBold) {
    useStroke("healed_ink", subsurfaceColor("#3b5266", mid[2], mid[3], 0.04), 1.35);
    brush.spline(pts2D, 0.35);
    useStroke("pen", subsurfaceColor("#202d3d", mid[2], mid[3], 0.0), 0.95);
    brush.spline(pts2D, 0.35);
  } else {
    let colHex = (idx % 2 === 0) ? "#3b6b63" : "#435970";
    useStroke("cpencil", subsurfaceColor(colHex, mid[2], mid[3], 0.02), 0.85);
    brush.spline(pts2D, 0.35);
  }
}

function drawFingerWaveCluster(cx, cy, radius, baseAngle, numFingers) {
  for (let i = 0; i < numFingers; i++) {
    let u = (i / (numFingers - 1)) - 0.5;
    let ang = baseAngle + u * 68;
    let rad = radius * (0.72 + 0.28 * cos(u * 140));

    // Build curved wave crest ending in a curled Hokusai/irezumi claw tip
    let spine = [];
    let leftEdge = [];
    let rightEdge = [];
    let steps = 12;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let curlAng = ang + pow(t, 1.7) * 115 * (u >= 0 ? 1 : -1);
      let stepLen = (rad / steps) * (1.0 - 0.35 * t);
      let prev = s === 0 ? [cx + u * 55, cy + u * 25] : spine[s - 1];
      let px = prev[0] + cos(curlAng) * stepLen;
      let py = prev[1] + sin(curlAng) * stepLen;
      spine.push([px, py]);

      let w = (1.0 - pow(t, 0.85)) * 18 + 2.0;
      let nx = -sin(curlAng);
      let ny = cos(curlAng);
      let wpL = warpTattooPt(px + nx * w, py + ny * w);
      let wpR = warpTattooPt(px - nx * w, py - ny * w);
      leftEdge.push([wpL[0], wpL[1]]);
      rightEdge.unshift([wpR[0], wpR[1]]);
    }

    // Jade-seafoam & pastel pearl wash inside the wave finger
    let poly = leftEdge.concat(rightEdge);
    let fillCol = subsurfaceColor(i % 2 === 0 ? "#82b5ac" : "#b8d6d0", cx, cy, 0.05);
    useWatercolor(fillCol, 58, 0.20, 0.35, 0.18);
    drawShapePoly(poly, 0.3, true);

    // Healed sumi outline around the curled wave finger
    useStroke("healed_ink", subsurfaceColor("#3d5266", cx, cy, 0.03), 1.3);
    brush.spline(leftEdge, 0.35);
    brush.spline(rightEdge, 0.35);

    useStroke("pen", subsurfaceColor("#202c3b", cx, cy, 0.0), 0.95);
    brush.spline(leftEdge, 0.35);
    brush.spline(rightEdge, 0.35);

    // Tiny foam droplets (shibuki) at wave tips
    let tip = leftEdge[leftEdge.length - 1];
    useStroke("pen", subsurfaceColor("#233040", cx, cy, 0.0), 0.85);
    brush.circle(tip[0] + random(-14, 14), tip[1] + random(-14, 14), random(4, 8), 0.25);
  }
}

// ============================================================================
// LAYER 5: TRADITIONAL PEONIES (BOTAN) & JADE LEAVES (BOTAN-BA)
// ============================================================================
function drawAllPeonies() {
  const peonies = [
    // 1. Monumental Right Deltoid Peony (wrapping over the rounded shoulder cap)
    {
      cx: 955, cy: 435, r: 128, rot: -18,
      darkCol: "#b54342", midCol: "#dc746e", lightCol: "#f4b4ad", underCol: "#fae0dc",
      leafAngles: [-145, -95, -35, 30, 95, 150]
    },
    // 2. Left Scapula Peony (nestled amid wind bars and waterfall mist)
    {
      cx: 265, cy: 495, r: 122, rot: 14,
      darkCol: "#bd4b48", midCol: "#e07e76", lightCol: "#f5bbb3", underCol: "#fbe3df",
      leafAngles: [-160, -110, -45, 25, 80, 145]
    },
    // 3. Lower Right Back Peony (beside the koi's sweeping tail)
    {
      cx: 855, cy: 815, r: 118, rot: -8,
      darkCol: "#b04248", midCol: "#d87379", lightCol: "#f2b2b6", underCol: "#f9dfe1",
      leafAngles: [-135, -75, -15, 45, 115, 170]
    }
  ];

  // First draw all serrated jade peony leaves behind the blooms
  for (let p of peonies) {
    for (let lang of p.leafAngles) {
      drawJadePeonyLeaf(p.cx, p.cy, p.r * 0.72, p.r * 0.92, lang + p.rot);
    }
  }

  // Then draw the layered ruffled peony blooms
  for (let p of peonies) {
    drawSinglePeony(p);
  }
}

function drawJadePeonyLeaf(cx, cy, startDist, leafLen, angleDeg) {
  let bx = cx + cos(angleDeg) * startDist;
  let by = cy + sin(angleDeg) * startDist;

  // Each traditional peony leaf cluster has a main central blade and two smaller side lobes
  const lobes = [
    { angOff: 0, lenMul: 1.0, wid: 34 },
    { angOff: -34, lenMul: 0.72, wid: 24 },
    { angOff: 34, lenMul: 0.72, wid: 24 }
  ];

  for (let lb of lobes) {
    let a = angleDeg + lb.angOff;
    let len = leafLen * lb.lenMul;
    let wid = lb.wid;

    let leftPts = [];
    let rightPts = [];
    let ribPts = [];
    let steps = 10;

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let curveA = a + sin(t * 180) * 10;
      let px = bx + cos(curveA) * (len * t);
      let py = by + sin(curveA) * (len * t);
      let nx = -sin(curveA);
      let ny = cos(curveA);

      // Serrated leaf margin envelope
      let env = sin(t * 180) * wid * (1.0 - 0.25 * t);
      let serration = (i > 2 && i < steps && i % 2 === 1) ? 1.24 : 0.92;
      let w = env * serration;

      let wpRib = warpTattooPt(px, py);
      let wpL = warpTattooPt(px + nx * w, py + ny * w);
      let wpR = warpTattooPt(px - nx * w, py - ny * w);

      ribPts.push([wpRib[0], wpRib[1]]);
      leftPts.push([wpL[0], wpL[1]]);
      rightPts.unshift([wpR[0], wpR[1]]);
    }

    let poly = leftPts.concat(rightPts);
    let midX = bx + cos(a) * len * 0.5;
    let midY = by + sin(a) * len * 0.5;

    // Graded jade-celadon bokashi watercolor washes
    useWatercolor(subsurfaceColor("#6ca69c", midX, midY, 0.04), 66, 0.22, 0.40, 0.18);
    drawShapePoly(poly, 0.22, true);

    // Darker jade base wash
    let basePoly = leftPts.slice(0, 6).concat(rightPts.slice(rightPts.length - 6));
    useWatercolor(subsurfaceColor("#376960", bx, by, 0.02), 62, 0.25, 0.42, 0.20);
    drawShapePoly(basePoly, 0.25, true);

    // Healed sumi outline & leaf venation
    useStroke("healed_ink", subsurfaceColor("#2f4a46", midX, midY, 0.03), 1.3);
    drawShapePoly(poly, 0.22, true);

    useStroke("pen", subsurfaceColor("#1c2e2c", midX, midY, 0.0), 0.95);
    drawShapePoly(poly, 0.22, true);
    brush.spline(ribPts, 0.3);

    // Lateral leaf veins
    useStroke("cpencil", subsurfaceColor("#243d3a", midX, midY, 0.02), 0.8);
    for (let v = 2; v < steps - 1; v += 2) {
      brush.line(ribPts[v][0], ribPts[v][1], leftPts[v + 1][0], leftPts[v + 1][1]);
      brush.line(ribPts[v][0], ribPts[v][1], rightPts[steps - v - 1][0], rightPts[steps - v - 1][1]);
    }
  }
}

function drawSinglePeony(p) {
  // 4 concentric rings of ruffled petals from outer skirt to inner cupped heart
  const rings = [
    { count: 9, rIn: p.r * 0.18, rOut: p.r * 1.02, span: 46, foldChance: 0.45 },
    { count: 8, rIn: p.r * 0.14, rOut: p.r * 0.78, span: 48, foldChance: 0.55 },
    { count: 7, rIn: p.r * 0.10, rOut: p.r * 0.54, span: 52, foldChance: 0.65 },
    { count: 5, rIn: p.r * 0.05, rOut: p.r * 0.34, span: 62, foldChance: 0.35 }
  ];

  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let rg = rings[rIdx];
    for (let i = 0; i < rg.count; i++) {
      let baseAng = p.rot + (i * 360 / rg.count) + rIdx * 23 + random(-6, 6);
      drawPeonyPetal(
        p.cx, p.cy, baseAng, rg.rIn, rg.rOut * random(0.92, 1.06),
        rg.span, p, (i + rIdx) % 2 === 0
      );
    }
  }

  // Golden-coral peony stamen center (shibe)
  let cWp = warpTattooPt(p.cx, p.cy);
  useWatercolor(subsurfaceColor("#e69d56", p.cx, p.cy, 0.04), 78, 0.22, 0.38, 0.2);
  brush.circle(cWp[0], cWp[1], p.r * 0.16, 0.35);

  for (let s = 0; s < 26; s++) {
    let a = s * (360 / 26) + random(-5, 5);
    let len = p.r * random(0.11, 0.23);
    let p0 = warpTattooPt(p.cx + cos(a) * 5, p.cy + sin(a) * 5);
    let p1 = warpTattooPt(p.cx + cos(a) * len, p.cy + sin(a) * len);
    useStroke("pen", subsurfaceColor("#6e2c26", p.cx, p.cy, 0.0), 0.75);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    useStroke("marker", subsurfaceColor("#f5c77e", p.cx, p.cy, 0.06), 0.9);
    brush.circle(p1[0], p1[1], 2.5, 0.2);
  }
}

function drawPeonyPetal(cx, cy, ang, rIn, rOut, spanDeg, pal, hasFold) {
  let pts = [];
  let halfSpan = spanDeg * 0.5;

  // Base left & right anchor
  let bL = warpTattooPt(cx + cos(ang - halfSpan * 0.45) * rIn, cy + sin(ang - halfSpan * 0.45) * rIn);
  pts.push([bL[0], bL[1]]);

  // Left edge flaring out
  let mL = warpTattooPt(cx + cos(ang - halfSpan * 0.92) * ((rIn + rOut) * 0.52), cy + sin(ang - halfSpan * 0.92) * ((rIn + rOut) * 0.52));
  pts.push([mL[0], mL[1]]);

  // Ruffled outer margin with organic notches (characteristic of traditional botan)
  let rimSteps = 9;
  let rimPts = [];
  for (let s = 0; s <= rimSteps; s++) {
    let u = (s / rimSteps) - 0.5;
    let a = ang + u * spanDeg;
    let ruffle = 1.0 + 0.09 * sin(s * 135) - 0.06 * (s === 4 ? 1 : 0);
    let r = rOut * (0.94 + 0.08 * cos(u * 160)) * ruffle;
    let wp = warpTattooPt(cx + cos(a) * r, cy + sin(a) * r);
    pts.push([wp[0], wp[1]]);
    rimPts.push([wp[0], wp[1]]);
  }

  // Right edge tapering back to base
  let mR = warpTattooPt(cx + cos(ang + halfSpan * 0.92) * ((rIn + rOut) * 0.52), cy + sin(ang + halfSpan * 0.92) * ((rIn + rOut) * 0.52));
  pts.push([mR[0], mR[1]]);

  let bR = warpTattooPt(cx + cos(ang + halfSpan * 0.45) * rIn, cy + sin(ang + halfSpan * 0.45) * rIn);
  pts.push([bR[0], bR[1]]);

  let midX = cx + cos(ang) * ((rIn + rOut) * 0.5);
  let midY = cy + sin(ang) * ((rIn + rOut) * 0.5);

  // 1. Light pastel blush outer wash
  useWatercolor(subsurfaceColor(pal.lightCol, midX, midY, 0.04), 68, 0.20, 0.36, 0.16);
  drawShapePoly(pts, 0.26, true);

  // 2. Mid vermilion-coral bokashi wash (inner 70% of petal)
  let midPoly = [bL, mL, rimPts[2], rimPts[4], rimPts[6], mR, bR];
  useWatercolor(subsurfaceColor(pal.midCol, midX, midY, 0.03), 62, 0.24, 0.40, 0.18);
  drawShapePoly(midPoly, 0.28, true);

  // 3. Deep crimson-vermilion pocket at petal root
  let rMid = (rIn + rOut) * 0.42;
  let rootTip = warpTattooPt(cx + cos(ang) * rMid, cy + sin(ang) * rMid);
  let rootPoly = [bL, mL, rootTip, mR, bR];
  useWatercolor(subsurfaceColor(pal.darkCol, cx, cy, 0.02), 64, 0.25, 0.42, 0.20);
  drawShapePoly(rootPoly, 0.28, true);

  // 4. Fine radial bokashi contour striae inside the petal
  useStroke("cpencil", subsurfaceColor(pal.darkCol, midX, midY, 0.02), 0.75);
  for (let s = 1; s < rimSteps; s += 2) {
    let u = (s / rimSteps) - 0.5;
    let a = ang + u * spanDeg * 0.82;
    let p0 = warpTattooPt(cx + cos(a) * (rIn * 1.15), cy + sin(a) * (rIn * 1.15));
    let p1 = warpTattooPt(cx + cos(a) * (rOut * 0.78), cy + sin(a) * (rOut * 0.78));
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // 5. Optional folded-over petal lip (ura-jiro pale underside)
  if (hasFold) {
    let foldPts = [];
    for (let s = 2; s <= 7; s++) foldPts.push(rimPts[s]);
    for (let s = 7; s >= 2; s--) {
      let u = (s / rimSteps) - 0.5;
      let a = ang + u * spanDeg;
      let wpIn = warpTattooPt(cx + cos(a) * (rOut * 0.81), cy + sin(a) * (rOut * 0.81));
      foldPts.push([wpIn[0], wpIn[1]]);
    }
    useWatercolor(subsurfaceColor(pal.underCol, midX, midY, 0.06), 76, 0.14, 0.30, 0.14);
    drawShapePoly(foldPts, 0.24, true);

    useStroke("pen", subsurfaceColor("#29232c", midX, midY, 0.0), 0.85);
    drawShapePoly(foldPts, 0.24, true);
  }

  // 6. Healed ink petal outline
  useStroke("healed_ink", subsurfaceColor("#453542", midX, midY, 0.04), 1.3);
  drawShapePoly(pts, 0.26, true);

  useStroke("pen", subsurfaceColor("#241d26", midX, midY, 0.0), 0.95);
  drawShapePoly(pts, 0.26, true);
}

// ============================================================================
// LAYER 6: THE CLIMBING CARP (NOBORI-GOI)
// ============================================================================
function drawClimbingKoi() {
  // 6A. Pectoral, Ventral & Caudal (Tail) Fins (drawn behind body)
  drawKoiFinsBehind();

  // 6B. Koi Body Base Wash & Cylindrical Shading
  let leftBody = [];
  let rightBody = [];
  for (let i = 0; i <= 32; i++) {
    let t = i / 32;
    let pL = getKoiPoint(t, -1.0);
    let pR = getKoiPoint(t, 1.0);
    leftBody.push([pL[0], pL[1]]);
    rightBody.unshift([pR[0], pR[1]]);
  }
  let fullBodyPoly = leftBody.concat(rightBody);
  useWatercolor(subsurfaceColor("#dce3e8", 550, 580, 0.05), 78, 0.18, 0.35, 0.16);
  drawShapePoly(fullBodyPoly, 0.25, true);

  // 6C. Overlapping Koi Scales (Uroko) from tail wrist (t=0.86) up to gill line (t=0.17)
  // Drawing from tail to head ensures authentic anatomical overlap!
  const numRows = 19;
  for (let r = numRows - 1; r >= 0; r--) {
    let tCenter = map(r, 0, numRows - 1, 0.175, 0.845);
    let dt = 0.044;
    let colsInRow = (r % 2 === 0) ? 7 : 8;

    for (let c = 0; c < colsInRow; c++) {
      let uCenter = map(c + 0.5, 0, colsInRow, -0.92, 0.92);
      let du = 1.95 / colsInRow;
      drawSingleKoiScale(tCenter, uCenter, dt, du);
    }
  }

  // 6D. Sculpted Koi Head, Gill Covers, Fierce Eyes & Streaming Barbels
  drawKoiHeadAndWhiskers();

  // 6E. Koi Body Outer Contour (bold healed sumi outline)
  useStroke("healed_ink", subsurfaceColor("#334457", 560, 560, 0.04), 1.85);
  brush.spline(leftBody, 0.35);
  brush.spline(rightBody, 0.35);

  useStroke("pen", subsurfaceColor("#1c2633", 560, 560, 0.0), 1.35);
  brush.spline(leftBody, 0.35);
  brush.spline(rightBody, 0.35);

  // 6F. Ripple Dorsal Fin along the Koi's Spine Crest (drawn on top of scales)
  drawKoiDorsalFin();
}

function drawSingleKoiScale(tC, uC, dt, du) {
  // Shield/crescent scale polygon in (t, u) space
  const localOffsets = [
    [-dt * 0.55, -du * 0.52],
    [0.0, -du * 0.72],
    [dt * 0.62, -du * 0.48],
    [dt * 0.88, 0.0],
    [dt * 0.62, du * 0.48],
    [0.0, du * 0.72],
    [-dt * 0.55, du * 0.52]
  ];

  let poly = [];
  for (let off of localOffsets) {
    let wp = getKoiPoint(constrain(tC + off[0], 0.15, 0.88), constrain(uC + off[1], -0.98, 0.98));
    poly.push([wp[0], wp[1]]);
  }

  let centerWp = getKoiPoint(tC, uC);
  let cx = centerWp[0], cy = centerWp[1];
  let pal = getKoiScalePalette(tC, uC);

  // 1. Outer pale crescent rim wash
  useWatercolor(subsurfaceColor(pal.rim, cx, cy, 0.05), 68, 0.15, 0.32, 0.14);
  drawShapePoly(poly, 0.32, true);

  // 2. Inner bokashi scale pocket (deep vermilion, jade, or sumi-indigo)
  let innerPoly = [];
  for (let off of localOffsets) {
    let wp = getKoiPoint(constrain(tC + off[0] * 0.68 - dt * 0.12, 0.15, 0.88), constrain(uC + off[1] * 0.70, -0.98, 0.98));
    innerPoly.push([wp[0], wp[1]]);
  }
  useWatercolor(subsurfaceColor(pal.mid, cx, cy, 0.03), 66, 0.20, 0.38, 0.18);
  drawShapePoly(innerPoly, 0.30, true);

  // 3. Fine radiating scale ridges (radii)
  let rootWp = getKoiPoint(max(0.15, tC - dt * 0.35), uC);
  useStroke("cpencil", subsurfaceColor(pal.base, cx, cy, 0.02), 0.75);
  for (let k = 1; k <= 5; k++) {
    brush.line(rootWp[0], rootWp[1], poly[k][0], poly[k][1]);
  }

  // 4. Exposed trailing arc outline of the scale in healed sumi ink
  let arcPts = [poly[1], poly[2], poly[3], poly[4], poly[5]];
  useStroke("healed_ink", subsurfaceColor("#3a4b5e", cx, cy, 0.04), 1.25);
  brush.spline(arcPts, 0.35);

  useStroke("pen", subsurfaceColor("#1e2836", cx, cy, 0.0), 0.92);
  brush.spline(arcPts, 0.35);
}

function drawKoiFinsBehind() {
  // 1. Left & Right Pectoral Fins (broad wing-like fans)
  drawFanFin(0.22, -0.92, -145, -75, 165, 14, true);
  drawFanFin(0.23, 0.92, -5, 65, 160, 14, false);

  // 2. Left & Right Ventral / Pelvic Fins
  drawFanFin(0.56, -0.90, -155, -105, 115, 9, true);
  drawFanFin(0.57, 0.90, 20, 75, 115, 9, false);

  // 3. Grand Bifurcated Caudal (Tail) Fin
  drawKoiTailFin();
}

function drawFanFin(tAnchor, uAnchor, angStart, angEnd, finRadius, numRays, isLeft) {
  let anchor = getKoiPoint(tAnchor, uAnchor);
  let ax = anchor[0], ay = anchor[1];

  let rimPts = [];
  let rayTips = [];
  for (let i = 0; i <= numRays; i++) {
    let f = i / numRays;
    let a = lerp(angStart, angEnd, f);
    let r = finRadius * (0.65 + 0.35 * sin(f * 180)) * (0.94 + 0.06 * sin(i * 120));
    let wp = warpTattooPt(ax + cos(a) * r, ay + sin(a) * r);
    rimPts.push([wp[0], wp[1]]);
    rayTips.push([wp[0], wp[1], a, r]);
  }

  let base2 = getKoiPoint(tAnchor + 0.08, uAnchor * 0.88);
  let poly = [[ax, ay]].concat(rimPts).concat([[base2[0], base2[1]]]);

  // Translucent jade-pearl & vermilion-blush membrane wash
  useWatercolor(subsurfaceColor("#c8d9d7", ax, ay, 0.05), 64, 0.22, 0.36, 0.16);
  drawShapePoly(poly, 0.28, true);

  // Deep indigo & coral bokashi at fin base
  let basePoly = [[ax, ay], rimPts[2], rimPts[floor(numRays / 2)], rimPts[numRays - 2], [base2[0], base2[1]]];
  useWatercolor(subsurfaceColor(isLeft ? "#486178" : "#cf6b62", ax, ay, 0.03), 58, 0.26, 0.40, 0.18);
  drawShapePoly(basePoly, 0.30, true);

  // Fin rays (curved bony spines)
  for (let i = 0; i <= numRays; i++) {
    let tip = rayTips[i];
    let f = i / numRays;
    let bPt = [lerp(ax, base2[0], f * 0.7), lerp(ay, base2[1], f * 0.7)];
    let midPt = warpTattooPt(
      (bPt[0] + tip[0]) * 0.5 + cos(tip[2] + (isLeft ? -18 : 18)) * 16,
      (bPt[1] + tip[1]) * 0.5 + sin(tip[2] + (isLeft ? -18 : 18)) * 16
    );
    useStroke("pen", subsurfaceColor("#243140", ax, ay, 0.0), i === 0 || i === numRays ? 1.15 : 0.78);
    brush.spline([bPt, [midPt[0], midPt[1]], [tip[0], tip[1]]], 0.35);
  }

  // Scalloped outer fin margin
  useStroke("healed_ink", subsurfaceColor("#37495c", ax, ay, 0.04), 1.3);
  brush.spline(rimPts, 0.35);
  useStroke("pen", subsurfaceColor("#1f2a38", ax, ay, 0.0), 0.95);
  brush.spline(rimPts, 0.35);
}

function drawKoiTailFin() {
  let wristL = getKoiPoint(0.84, -0.85);
  let wristC = getKoiPoint(0.92, 0.0);
  let wristR = getKoiPoint(0.84, 0.85);

  // Left and Right sweeping tail lobes
  const lobes = [
    { base1: wristL, base2: wristC, a0: 145, a1: 82, rad: 185, rays: 12 },
    { base1: wristC, base2: wristR, a0: 72, a1: 12, rad: 195, rays: 12 }
  ];

  for (let lb of lobes) {
    let rimPts = [];
    for (let i = 0; i <= lb.rays; i++) {
      let f = i / lb.rays;
      let a = lerp(lb.a0, lb.a1, f);
      let r = lb.rad * (0.68 + 0.36 * sin(f * 180));
      let bx = lerp(lb.base1[0], lb.base2[0], f);
      let by = lerp(lb.base1[1], lb.base2[1], f);
      let wp = warpTattooPt(bx + cos(a) * r, by + sin(a) * r);
      rimPts.push([wp[0], wp[1], bx, by]);
    }

    let poly = [[lb.base1[0], lb.base1[1]]].concat(rimPts.map(p => [p[0], p[1]])).concat([[lb.base2[0], lb.base2[1]]]);
    useWatercolor(subsurfaceColor("#cad8df", wristC[0], wristC[1], 0.05), 62, 0.24, 0.38, 0.16);
    drawShapePoly(poly, 0.28, true);

    // Vermilion & indigo tail base bokashi
    let innerPoly = [[lb.base1[0], lb.base1[1]], [rimPts[3][0], rimPts[3][1]], [rimPts[8][0], rimPts[8][1]], [lb.base2[0], lb.base2[1]]];
    useWatercolor(subsurfaceColor("#d46d63", wristC[0], wristC[1], 0.03), 55, 0.26, 0.40, 0.18);
    drawShapePoly(innerPoly, 0.28, true);

    for (let i = 0; i <= lb.rays; i++) {
      let p = rimPts[i];
      useStroke("pen", subsurfaceColor("#243140", p[0], p[1], 0.0), 0.8);
      brush.line(p[2], p[3], p[0], p[1]);
    }

    useStroke("healed_ink", subsurfaceColor("#36485c", wristC[0], wristC[1], 0.04), 1.35);
    brush.spline(rimPts.map(p => [p[0], p[1]]), 0.35);
    useStroke("pen", subsurfaceColor("#1f2a38", wristC[0], wristC[1], 0.0), 0.98);
    brush.spline(rimPts.map(p => [p[0], p[1]]), 0.35);
  }
}

function drawKoiHeadAndWhiskers() {
  // Sculpted head & gill covers (t from 0.0 to 0.175)
  let headPts = [];
  for (let i = 0; i <= 10; i++) {
    let t = map(i, 0, 10, 0.175, 0.0);
    let p = getKoiPoint(t, -1.0);
    headPts.push([p[0], p[1]]);
  }
  let snout = getKoiPoint(0.0, 0.0);
  headPts.push([snout[0], snout[1]]);
  for (let i = 0; i <= 10; i++) {
    let t = map(i, 0, 10, 0.0, 0.175);
    let p = getKoiPoint(t, 1.0);
    headPts.push([p[0], p[1]]);
  }
  // Curved gill plate arch (operculum)
  for (let i = 6; i >= 0; i--) {
    let u = map(i, 0, 6, -0.95, 0.95);
    let p = getKoiPoint(0.175 - 0.022 * cos(u * 90), u);
    headPts.push([p[0], p[1]]);
  }

  let hCenter = getKoiPoint(0.09, 0.0);
  useWatercolor(subsurfaceColor("#dde5eb", hCenter[0], hCenter[1], 0.05), 76, 0.18, 0.34, 0.16);
  drawShapePoly(headPts, 0.28, true);

  // Classic Kohaku vermilion crown marking (Tancho / Maruten) on the forehead
  let crownPts = [];
  for (let a = 0; a < 360; a += 30) {
    let t = 0.085 + cos(a) * 0.055;
    let u = sin(a) * 0.52;
    let wp = getKoiPoint(t, u);
    crownPts.push([wp[0], wp[1]]);
  }
  useWatercolor(subsurfaceColor("#cf544c", hCenter[0], hCenter[1], 0.03), 74, 0.22, 0.38, 0.18);
  drawShapePoly(crownPts, 0.35, true);

  // Gill plate contour lines & cranial plates
  let gillArc1 = [], gillArc2 = [];
  for (let i = 0; i <= 10; i++) {
    let u = map(i, 0, 10, -0.96, 0.96);
    let p1 = getKoiPoint(0.172 - 0.022 * cos(u * 90), u);
    let p2 = getKoiPoint(0.142 - 0.018 * cos(u * 90), u * 0.92);
    gillArc1.push([p1[0], p1[1]]);
    gillArc2.push([p2[0], p2[1]]);
  }
  useStroke("healed_ink", subsurfaceColor("#35475b", hCenter[0], hCenter[1], 0.04), 1.45);
  brush.spline(gillArc1, 0.35);
  brush.spline(gillArc2, 0.35);

  useStroke("pen", subsurfaceColor("#1d2736", hCenter[0], hCenter[1], 0.0), 1.05);
  brush.spline(gillArc1, 0.35);
  brush.spline(gillArc2, 0.35);

  // Fierce traditional Koi Eyes on left and right side of head
  const eyeSides = [-0.74, 0.74];
  for (let side of eyeSides) {
    let ep = getKoiPoint(0.068, side);
    useWash(subsurfaceColor("#f2d085", ep[0], ep[1], 0.04), 195);
    brush.circle(ep[0], ep[1], 11, 0.2);

    useWash(subsurfaceColor("#1b2430", ep[0], ep[1], 0.0), 225);
    brush.circle(ep[0], ep[1], 6, 0.15);

    useStroke("pen", subsurfaceColor("#1a2330", ep[0], ep[1], 0.0), 1.05);
    brush.circle(ep[0], ep[1], 11.5, 0.2);
  }

  // Two long streaming Koi Whiskers (Barbels) curling gracefully into the waterfall
  const whiskers = [
    [
      getKoiPoint(0.015, -0.52),
      warpTattooPt(635, 235),
      warpTattooPt(565, 215),
      warpTattooPt(505, 245),
      warpTattooPt(465, 220)
    ],
    [
      getKoiPoint(0.015, 0.52),
      warpTattooPt(755, 285),
      warpTattooPt(825, 275),
      warpTattooPt(875, 315),
      warpTattooPt(915, 295)
    ]
  ];

  for (let w of whiskers) {
    let pts = w.map(p => [p[0], p[1]]);
    useStroke("healed_ink", subsurfaceColor("#45576b", pts[1][0], pts[1][1], 0.04), 1.6);
    brush.spline(pts, 0.4);
    useStroke("pen", subsurfaceColor("#202a38", pts[1][0], pts[1][1], 0.0), 1.15);
    brush.spline(pts, 0.4);
  }
}

function drawKoiDorsalFin() {
  // Undulating dorsal fin ribbon running along the koi's spine from t=0.25 to t=0.77
  let basePts = [];
  let crestPts = [];
  let steps = 18;

  for (let i = 0; i <= steps; i++) {
    let f = i / steps;
    let t = lerp(0.25, 0.77, f);
    let b = getKoiPoint(t, -0.06);
    // Fin arches upward/left in 3/4 view with dynamic wave
    let crestOffset = -0.52 - 0.18 * sin(f * 360) * sin(f * 180);
    let c = getKoiPoint(t - 0.015, crestOffset);
    basePts.push([b[0], b[1]]);
    crestPts.push([c[0], c[1]]);
  }

  let poly = basePts.concat(crestPts.slice().reverse());
  useWatercolor(subsurfaceColor("#6f8d9c", basePts[9][0], basePts[9][1], 0.04), 68, 0.20, 0.36, 0.16);
  drawShapePoly(poly, 0.28, true);

  // Dark indigo base shading along spine attachment
  useStroke("healed_ink", subsurfaceColor("#29384a", basePts[9][0], basePts[9][1], 0.03), 1.75);
  brush.spline(basePts, 0.35);

  // Spiny dorsal rays
  useStroke("pen", subsurfaceColor("#1e2836", basePts[9][0], basePts[9][1], 0.0), 0.9);
  for (let i = 0; i <= steps; i++) {
    brush.line(basePts[i][0], basePts[i][1], crestPts[i][0], crestPts[i][1]);
  }

  // Dorsal crest outline
  useStroke("healed_ink", subsurfaceColor("#36485c", basePts[9][0], basePts[9][1], 0.04), 1.45);
  brush.spline(crestPts, 0.35);
  useStroke("pen", subsurfaceColor("#1c2633", basePts[9][0], basePts[9][1], 0.0), 1.1);
  brush.spline(crestPts, 0.35);
}

// ============================================================================
// LAYER 7: EPIDERMAL VEIL, SUBSURFACE SCATTERING & SKIN PORES OVER TATTOO
// ============================================================================
function drawEpidermalVeilAndPores() {
  // 7A. Translucent epidermal glazes unifying tattoo pigment with 3D muscle lighting
  // Warm lit skin crowns (upper right scapula, deltoid dome, trapezius crest)
  const litEpidermis = [
    [[575, 135], [785, 195], [965, 265], [915, 425], [615, 385]],
    [[935, 295], [1075, 345], [1110, 495], [1015, 595], [915, 465]],
    [[615, 375], [845, 385], [865, 595], [615, 575]]
  ];
  useWatercolor("#fae6d9", 46, 0.34, 0.32, 0.12);
  for (let poly of litEpidermis) drawShapePoly(poly, 0.38, true);

  // Cool bathhouse shadow glazes sinking the spinal furrow, left flank & lower back
  const shadowEpidermis = [
    [[442, 160], [505, 160], [518, 560], [492, 1180], [435, 1180], [455, 560]],
    [[-20, 235], [245, 185], [275, 620], [265, 1180], [-20, 1180]],
    [[885, 355], [930, 365], [1095, 680], [1080, 1180], [995, 1180], [1015, 705]]
  ];
  useWatercolor("#6b667d", 44, 0.35, 0.40, 0.16);
  for (let poly of shadowEpidermis) drawShapePoly(poly, 0.35, true);

  // 7B. Anatomical Skin Grain, Langer's Lines & Sebaceous Pores across Back & Shoulder
  // Because pores sit in the epidermis, they break up and stipple the tattoo ink underneath!
  for (let y = 75; y < 1140; y += 22) {
    for (let x = 25; x < 1115; x += 22) {
      let jx = x + random(-9, 9);
      let jy = y + random(-9, 9);
      if (!isInsideBody(jx, jy)) continue;

      let a = getAnatomy(jx, jy);
      // Contour direction tangent to muscle slope
      let tangAng = atan2(a.dzdx, -a.dzdy) + random(-12, 12);
      let segLen = random(9, 18);

      // Subtle epidermal cross-contour micro-lines (Langer's lines)
      if (random() < 0.58) {
        let poreCol = a.diff > 0.52 ? "#e8cabe" : "#7c7487";
        useStroke("2H", poreCol, 0.55);
        brush.line(
          jx - cos(tangAng) * segLen * 0.5,
          jy - sin(tangAng) * segLen * 0.5,
          jx + cos(tangAng) * segLen * 0.5,
          jy + sin(tangAng) * segLen * 0.5
        );
      }

      // Pore stipple clusters sinking into skin and over tattoo pigment
      if (random() < 0.72) {
        let pCol = a.specBroad > 0.25 ? "#f7e3d7" : (a.diff > 0.45 ? "#b88f84" : "#595466");
        useStroke("pore_stipple", pCol, random(0.65, 1.15));
        brush.line(jx, jy, jx + cos(tangAng) * 5, jy + sin(tangAng) * 5);
      }
    }
  }
}

