// LAYER 9: SWEAT BEADS & TRICKLES WITH PIN-SHARP HIGHLIGHTS
// ============================================================================
function drawSweatBeadsAndTrickles() {
  // 9A. Trickling sweat rivulets running down the spinal groove, scapula & deltoid
  const rivulets = [
    [[472, 165], [478, 245], [484, 335], [480, 425], [486, 515]],
    [[488, 595], [482, 685], [476, 775], [472, 865]],
    [[745, 225], [738, 295], [744, 375], [736, 455]],
    [[1015, 345], [1024, 425], [1018, 515], [1008, 595]],
    [[625, 385], [618, 465], [622, 555], [614, 645]],
    [[295, 245], [288, 325], [292, 405]]
  ];

  for (let riv of rivulets) {
    let shPts = riv.map(p => [p[0] - 2.2, p[1] + 2.0]);
    let hiPts = riv.map(p => [p[0] + 1.5, p[1] - 1.0]);

    useStroke("2B", "#313645", 0.75);
    brush.spline(shPts, 0.4);

    useStroke("specular_pin", "#ffffff", 0.85);
    brush.spline(hiPts, 0.4);
  }

  // 9B. 175 Hyperrealistic 3D Sweat Beads across the glistening shoulder & back
  const beads = [];

  // Cluster along the end of each rivulet
  for (let riv of rivulets) {
    let tip = riv[riv.length - 1];
    beads.push({ x: tip[0], y: tip[1] + 5, r: random(6.5, 9.5) });
  }

  // Distribute sweat beads naturally across upper back, deltoid, trapezius, spine & scapulae
  for (let i = 0; i < 170; i++) {
    // Bias toward upper back, shoulder cap, scapula & spinal furrow
    let bx = random(95, 1095);
    let by = random(95, 1060);
    if (!isInsideBody(bx, by)) continue;
    if (distToSkinEdge(bx, by) < 18) continue;

    // Avoid overlapping existing beads
    let ok = true;
    for (let b of beads) {
      if (dist(bx, by, b.x, b.y) < (b.r + 12)) {
        ok = false;
        break;
      }
    }
    if (!ok) continue;

    let a = getAnatomy(bx, by);
    // Larger beads congregate on high-sweat zones (spine groove, upper scapula, deltoid)
    let r = random(2.6, 6.2);
    if (abs(bx - getSpineX(by)) < 55 || a.specBroad > 0.35) {
      r *= random(1.1, 1.45);
    }
    beads.push({ x: bx, y: by, r: r });
  }

  // Render each sweat bead as a 5-part optical water lens:
  // 1. Cast shadow crescent on bottom-left (away from upper-right skylight)
  // 2. Dark upper-right internal meniscus rim
  // 3. Refracted glowing caustic belly on lower-left interior
  // 4. Pin-sharp pure white primary specular highlight on upper-right dome
  // 5. Secondary micro-glint on lower-left rim for larger drops
  for (let b of beads) {
    let x = b.x, y = b.y, r = b.r;

    // 1. Cast shadow crescent underneath/bottom-left
    useWash("#222533", 125);
    brush.circle(x - r * 0.32, y + r * 0.42, r * 0.92, 0.18);

    // 2. Dark upper meniscus rim
    useStroke("pen", "#2d3545", constrain(r * 0.16, 0.55, 1.15));
    brush.arc(x, y, r, -110, 45);

    // 3. Refracted caustic lower-left belly (glowing warm peach or cool jade/coral)
    let causticCol = (x > 520 && y < 780) ? "#ffe8dc" : "#e3eff2";
    useWash(causticCol, 155);
    brush.circle(x - r * 0.18, y + r * 0.18, r * 0.58, 0.15);

    // 4. Pin-sharp pure white primary specular highlight on upper-right dome
    let hx = x + r * 0.28;
    let hy = y - r * 0.28;
    useWash("#ffffff", 250);
    brush.circle(hx, hy, max(1.6, r * 0.28), 0.05);

    useStroke("specular_pin", "#ffffff", constrain(r * 0.22, 0.75, 1.45));
    brush.line(hx - r * 0.12, hy - r * 0.08, hx + r * 0.14, hy + r * 0.10);

    // 5. Secondary lower-left rim micro-reflection on larger beads
    if (r > 4.6) {
      useStroke("specular_pin", "#f5f9ff", 0.68);
      brush.line(x - r * 0.38, y + r * 0.32, x - r * 0.22, y + r * 0.42);
    }
  }
}

