// Hyperrealist Drum-Recorder Trace: Shivering Black Coffee on a Fold-Down Train Table

const CUP_CX = 555;
const CUP_TOP_CY = 415;
const CUP_LIQ_CY = 448;
const CUP_BOT_CY = 792;
const ASPECT = 0.61;

const RIM_OUT_A = 252, RIM_OUT_B = RIM_OUT_A * ASPECT;
const RIM_IN_A  = 236, RIM_IN_B  = RIM_IN_A  * ASPECT;
const LIQ_A     = 230, LIQ_B     = LIQ_A     * ASPECT;
const TOP_WALL_A = 242, TOP_WALL_B = TOP_WALL_A * ASPECT;
const BOT_WALL_A = 154, BOT_WALL_B = BOT_WALL_A * ASPECT;

const REC_CX = 642, REC_CY = 764;
const REC_A = 180, REC_B = REC_A * 0.625;

async function setup() {
