// Smoothstep utility
function sstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

// Solve whether (x, y) lies on the visible front frustum wall of the paper cup
function solveCupWall(x, y) {
  let yMin = CUP_TOP_CY + 6;
  let yMax = CUP_BOT_CY + BOT_WALL_B + 2;
  if (y < yMin || y > yMax) return null;

  let dySpan = CUP_BOT_CY - (CUP_TOP_CY + 8);
  let t = constrain((y - (CUP_TOP_CY + 18)) / dySpan, 0, 1);

  for (let i = 0; i < 5; i++) {
    let a = lerp(TOP_WALL_A, BOT_WALL_A, t);
    let b = a * ASPECT;
    let cy = lerp(CUP_TOP_CY + 8, CUP_BOT_CY, t);
    let u = (x - CUP_CX) / a;
    if (abs(u) > 1.03) {
      // Nudge t toward valid range if close
      t = constrain((y - cy) / dySpan + t, 0, 1);
      continue;
    }
    let uClamped = constrain(u, -1, 1);
    let root = sqrt(max(0, 1 - uClamped * uClamped));
    let yPred = cy + b * root;
    let dYdt = dySpan + (BOT_WALL_A - TOP_WALL_A) * ASPECT * (root + (uClamped * uClamped) / max(0.15, root));
    t -= (yPred - y) / max(80, dYdt);
  }

  if (t < -0.015 || t > 1.008) return null;
  let tc = constrain(t, 0, 1);
  let a = lerp(TOP_WALL_A, BOT_WALL_A, tc);
  let b = a * ASPECT;
  let cy = lerp(CUP_TOP_CY + 8, CUP_BOT_CY, tc);
  let u = (x - CUP_CX) / a;
  if (abs(u) > 1.0) return null;

  let ySurf = cy + b * sqrt(max(0, 1 - u * u));
  if (abs(y - ySurf) > 9.0 && (t < 0 || t > 1)) return null;

  return { u: u, t: tc, a: a, b: b };
}

// Evaluate hyperrealist scene properties at (x, y):
// Returns { D: darkness [0..1], waveY: vertical displacement, glare: spike intensity [0..1], region: id, freqBoost: float }
function evaluateScene(x, y) {
  let D = 0.06;
  let waveY = 0.0;
  let glare = 0.0;
  let region = 0; // 0: tabletop, 1: seat/bg, 2: cup wall/rim, 3: coffee liquid
  let freqBoost = 1.0;

  // 1. Fold-down train table boundary (top & bottom edges, rounded industrial corners)
  let dxTable = (x - 600) / 520;
  let tableTopY = 212 + 10 * dxTable * dxTable;
  if (abs(dxTable) > 0.84) {
    let cornerT = (abs(dxTable) - 0.84) / 0.22;
    tableTopY += 68 * cornerT * cornerT;
  }
  let tableBotY = 1054 - 6 * dxTable * dxTable;

  if (y < tableTopY) {
    region = 1;
    let gapDist = tableTopY - y;
    if (gapDist < 26) {
      // Deep recess gap behind the fold-down table
      D = lerp(0.76, 0.84, sin((gapDist / 26) * PI));
      freqBoost = 1.35;
    } else {
      // Seat-back panel & rotary table latch housing
      D = 0.31 + 0.08 * sstep(0, 520, abs(x - 600));
      // Subtle horizontal seat-back molding ribs
      D += 0.05 * sin(y * 0.22);
      // Recessed twist-latch at (600, 128)
      let lx = (x - 600) / 56;
      let ly = (y - 128) / 38;
      let lr = sqrt(lx * lx + ly * ly);
      if (lr < 1.08) {
        if (lr > 0.90) {
          D = (ly < 0) ? 0.68 : 0.16; // Bevel ring
        } else {
          D = 0.56 + 0.12 * ly; // Dark latch well
          // Vertical metallic latch knob
          if (abs(lx) < 0.24 && abs(ly) < 0.72) {
            D = 0.14 + 0.22 * sstep(-0.24, 0.24, lx);
          }
        }
      }
    }
  } else if (y > tableBotY) {
    region = 1;
    let lipDist = y - tableBotY;
    if (lipDist < 16) {
      // Front edge thickness of the plastic tray table
      D = 0.38 + 0.14 * (lipDist / 16);
    } else {
      // Dark shadow beneath the fold-down table
      D = 0.72 * exp(-(lipDist - 16) * 0.012) + 0.22;
      freqBoost = 1.25;
    }
  } else {
    // On the pale buff fold-down tabletop
    region = 0;
    // Subtle diagonal window illumination gradient across tabletop
    let lightDiag = ((x - 250) * 0.65 + (y - 300) * 0.75) / 900;
    D = 0.045 + 0.055 * constrain(lightDiag, 0, 1);

    // Molded raised spill-lip along the back edge of the table
    let dTop = y - tableTopY;
    if (dTop < 22) {
      if (dTop < 8) D = 0.02; // Bright top ridge
      else D = lerp(0.24, D, (dTop - 8) / 14); // Inner bevel shadow
    }
    // Molded spill-lip along the front edge of the table
    let dBot = tableBotY - y;
    if (dBot < 22) {
      if (dBot < 8) D = 0.025;
      else D = lerp(0.22, D, (dBot - 8) / 14);
    }

    // Shallow circular molded cup recess on the train table (cup has jittered slightly left of it)
    let rx = (x - REC_CX) / REC_A;
    let ry = (y - REC_CY) / REC_B;
    let rr = sqrt(rx * rx + ry * ry);
    if (rr < 1.06) {
      let lightDot = -0.68 * rx - 0.73 * ry; // Positive when facing upper-left window light
      if (rr > 0.94 && rr <= 1.01) {
        // Sloped step of the recessed ring
        if (lightDot < 0) {
          // Upper-left lip casts a crisp step shadow
          D += 0.28 * (-lightDot) * sin(((rr - 0.94) / 0.07) * PI);
        } else {
          // Lower-right lip catches bright window light
          D = max(0.015, D - 0.05 * lightDot);
        }
      } else if (rr > 1.01 && rr < 1.06) {
        // Subtle outer molding ridge
        D += 0.09 * sin(((rr - 1.01) / 0.05) * PI);
      } else if (rr <= 0.94) {
        // Flat floor of the recess + standing vibration rings on tabletop
        D += 0.032;
        waveY += 0.35 * sin(rr * 38.0);
      }
    }

    // Cast shadow of the paper cup stretching to the right and slightly down
    let shDx = x - (CUP_CX + 18);
    let shDy = y - (CUP_BOT_CY - 4);
    // Rotate into shadow axis (approx +11 degrees)
    let ca = cos(0.19), sa = sin(0.19);
    let su = (shDx * ca + shDy * sa);
    let sv = (-shDx * sa + shDy * ca);
    if (su > -130 && su < 520) {
      let tSh = constrain((su + 80) / 540, 0, 1);
      let halfW = lerp(BOT_WALL_B * 0.96, BOT_WALL_B * 1.48, tSh);
      let edgeSoft = lerp(10, 68, tSh);
      let distV = abs(sv);
      let capEnd = su > 340 ? (su - 340) / 130 : 0;
      let effR = sqrt( pow(distV / halfW, 2) + capEnd * capEnd );
      if (effR < 1.35) {
        let shMask = 1.0 - sstep(0.75, 1.0 + edgeSoft / 160, effR);
        // Intense dark contact shadow right under the cup base
        let baseU = (x - CUP_CX) / BOT_WALL_A;
        let baseV = (y - CUP_BOT_CY) / BOT_WALL_B;
        let baseR = sqrt(baseU * baseU + baseV * baseV);
        let contact = (baseR >= 0.95 && baseR < 1.12 && y > CUP_BOT_CY)
                      ? 0.42 * exp(-pow((baseR - 1.01) / 0.045, 2)) : 0;
        let umbra = lerp(0.58, 0.16, pow(tSh, 0.75)) * shMask + contact;
        D = max(D, min(0.88, D + umbra));
        freqBoost = max(freqBoost, 1.0 + 0.35 * shMask);
      }
    }
  }

  // 2. Check Top Rim & Cup Interior (Coffee Liquid + Inner Paper Wall)
  let uRimOut = (x - CUP_CX) / RIM_OUT_A;
  let vRimOut = (y - CUP_TOP_CY) / RIM_OUT_B;
  let rRimOut = sqrt(uRimOut * uRimOut + vRimOut * vRimOut);

  let uRimIn = (x - CUP_CX) / RIM_IN_A;
  let vRimIn = (y - CUP_TOP_CY) / RIM_IN_B;
  let rRimIn = sqrt(uRimIn * uRimIn + vRimIn * vRimIn);

  if (rRimIn < 1.0) {
    // Inside the cup opening! Check if on the black coffee surface or inner back wall
    let uLiq = (x - CUP_CX) / LIQ_A;
    let vLiq = (y - CUP_LIQ_CY) / LIQ_B;
    let rLiq = sqrt(uLiq * uLiq + vLiq * vLiq);

    if (rLiq < 1.0) {
      // THE SHIVERING BLACK COFFEE SURFACE
      region = 3;
      freqBoost = 1.65;

      // Concentric capillary standing waves (primary Bessel-like center + slight off-center harmonic beat)
      let u1 = uLiq - 0.015, v1 = vLiq + 0.01;
      let r1 = sqrt(u1 * u1 + v1 * v1);
      let u2 = uLiq + 0.085, v2 = vLiq - 0.045;
      let r2 = sqrt(u2 * u2 + v2 * v2);

      // 8.5 concentric ripple rings from center to meniscus
      let k1 = 8.5 * TWO_PI;
      let k2 = 6.2 * TWO_PI;
      let env1 = (0.62 / sqrt(r1 + 0.08)) * (1.0 - 0.25 * r1) + 0.38 * r1 * r1;
      let env2 = 0.26 * (1.0 - 0.4 * r2);

      let phase1 = k1 * r1 - 0.65;
      let phase2 = k2 * r2 + 0.90;
      let waveH = env1 * cos(phase1) + env2 * cos(phase2) + 0.14 * cos(17.0 * TWO_PI * r1);

      // Radial derivative (wave slope) for 3D optical normal calculation
      let dWdr1 = -env1 * k1 * sin(phase1) - 0.14 * 17.0 * TWO_PI * sin(17.0 * TWO_PI * r1);
      let dWdr2 = -env2 * k2 * sin(phase2);
      let gx = (r1 > 0.001 ? dWdr1 * (u1 / r1) : 0) + (r2 > 0.001 ? dWdr2 * (u2 / r2) : 0);
      let gy = (r1 > 0.001 ? dWdr1 * (v1 / r1) : 0) + (r2 > 0.001 ? dWdr2 * (v2 / r2) : 0);

      // Meniscus upward curl near rLiq -> 1
      let meniscus = sstep(0.91, 1.0, rLiq);
      waveY = -waveH * 2.85 * (1.0 - 0.65 * meniscus);

      // Optical reflection of the train window on the rippled surface
      // Slope component facing the upper-left train window
      let slopeToWindow = (-0.52 * gx - 0.85 * gy) / 48.0;
      let crestFactor = sstep(-0.15, 0.68, cos(phase1) + 0.28 * cos(phase2));

      // Train window reflection geometry projected across the liquid ellipse
      let winU = uLiq + 0.26 * vLiq;
      let winV = vLiq - 0.12 * uLiq;

      // Main window pane (upper-left to center) split by a narrow window mullion bar
      let inMainPane = (winU > -0.84 && winU < 0.44 && winV > -0.84 && winV < 0.56);
      let paneFade = sstep(-0.84, -0.68, winU) * (1.0 - sstep(0.24, 0.44, winU))
                   * sstep(-0.84, -0.66, winV) * (1.0 - sstep(0.36, 0.56, winV));
      // Window frame transom bar cutting across winV ~ -0.14
      let mullionBar = 1.0 - 0.88 * exp(-pow((winV + 0.14) / 0.055, 2));
      let verticalBar = 1.0 - 0.82 * exp(-pow((winU + 0.22) / 0.045, 2));
      let windowMask = inMainPane ? paneFade * mullionBar * verticalBar : 0.0;

      // Secondary rim glare on the opposite concentric wave faces & central bullseye glints
      let centerGlint = exp(-r1 * 4.2) * sstep(0.25, 0.85, cos(phase1));
      let rimArcGlint = sstep(0.68, 0.92, rLiq) * (1.0 - sstep(0.94, 0.99, rLiq))
                      * sstep(0.1, 0.8, uLiq * 0.7 + vLiq * 0.7) * sstep(0.15, 0.75, -cos(phase1));

      // Combine window mask with concentric ripple crest slope
      let rawGlare = windowMask * sstep(0.08, 0.65, slopeToWindow + 0.45 * crestFactor)
                   + 0.65 * centerGlint
                   + 0.72 * rimArcGlint;

      // Sharp meniscus highlight line along the liquid edge
      let menAngle = atan2(vLiq, uLiq);
      let menHighlight = meniscus * (1.0 - sstep(0.97, 1.0, rLiq))
                       * (0.55 * pow(max(0, cos(menAngle - 0.6)), 3) + 0.45 * pow(max(0, cos(menAngle + 2.3)), 3));
      rawGlare = constrain(rawGlare + menHighlight, 0, 1);

      glare = pow(rawGlare, 0.85);

      // Base coffee tone: deep dark trembling ink (0.90..0.97) modulated by 3D wave troughs/crests
      let baseCoffeeD = 0.91 - 0.19 * crestFactor - 0.07 * clampSlope(slopeToWindow);
      // In dark meniscus shadow right against the paper wall
      if (rLiq > 0.95) baseCoffeeD = max(baseCoffeeD, 0.94);

      // Where window glare hits a ripple crest, darkness drops sharply so the pale ground gleams through
      // while the primary line spikes violently!
      D = lerp(constrain(baseCoffeeD, 0.62, 0.97), 0.03, pow(glare, 1.15));

    } else {
      // INNER PAPER WALL OF THE CUP (visible crescent at the back above the coffee meniscus)
      region = 2;
      // Left inside wall is shaded by the cup's left lip; right inside wall catches direct window light
      let innerShade = lerp(0.58, 0.09, sstep(-0.75, 0.55, uRimIn));
      // Darken slightly toward the far right inner curve
      if (uRimIn > 0.60) innerShade += 0.22 * ((uRimIn - 0.60) / 0.40);
      // Dark coffee meniscus stain right above rLiq == 1.0
      let distToLiq = rLiq - 1.0;
      if (distToLiq < 0.055) {
        innerShade = lerp(0.84, innerShade, distToLiq / 0.055);
      }
      // Subtle shadow right under the inner rolled lip (rRimIn -> 1.0)
      if (rRimIn > 0.94) {
        innerShade = lerp(innerShade, 0.48, (rRimIn - 0.94) / 0.06);
      }
      D = innerShade;
    }
  } else if (rRimOut <= 1.0) {
    // THE ROLLED PAPER RIM (3D Torus lip)
    region = 2;
    let tubeT = (rRimOut - 1.0) / max(0.01, rRimOut - rRimIn) * 2.0 + 1.0; // -1 at inner edge, +1 at outer edge
    // Top of the rolled torus is around tubeT = -0.15
    let topHighlight = exp(-pow((tubeT + 0.18) / 0.48, 2));
    let rimBase = lerp(0.11, 0.34, sstep(-0.8, 0.8, uRimOut));
    D = lerp(rimBase + 0.28, 0.025 + 0.08 * sstep(-0.6, 0.7, uRimOut), topHighlight);
    // Crisp dark underside on the outer overhang of the rolled rim (especially on the front lip vRimOut > 0)
    if (tubeT > 0.45) {
      let lipShadow = ((tubeT - 0.45) / 0.55) * (0.35 + 0.32 * max(0, vRimOut));
      D = min(0.82, D + lipShadow);
    }
    waveY = -1.1 * topHighlight;
  } else {
    // 3. Check Outer Paper Cup Body (Frustum Wall)
    let wall = solveCupWall(x, y);
    if (wall !== null) {
      region = 2;
      let u = wall.u;
      let t = wall.t;

      // Cylindrical Phong + Ambient + Bounce-light shading across u in [-1, 1]
      // Window light comes from left-front (u ~ -0.62)
      let cylShade;
      if (u < -0.58) {
        // Turning away toward far-left silhouette edge
        cylShade = lerp(0.32, 0.065, sstep(-1.0, -0.58, u));
      } else if (u < 0.48) {
        // Sweep from bright lit left side across front into core shadow on right
        cylShade = lerp(0.065, 0.68, sstep(-0.58, 0.48, u));
      } else if (u < 0.88) {
        // Core shadow easing into cool bounce light from the pale tabletop
        cylShade = lerp(0.68, 0.32, sstep(0.48, 0.88, u));
      } else {
        // Crisp silhouette edge darkening on the far right
        cylShade = lerp(0.32, 0.62, sstep(0.88, 1.0, u));
      }

      // Vertical gradient (slightly deeper tone toward the base)
      cylShade += 0.05 * t;

      // Crisp overhang shadow cast by the rolled rim onto the top of the cup wall
      let yFrontRim = CUP_TOP_CY + RIM_OUT_B * sqrt(max(0, 1 - pow(constrain((x - CUP_CX) / RIM_OUT_A, -1, 1), 2)));
      let dUnderRim = y - yFrontRim;
      if (dUnderRim >= 0 && dUnderRim < 15) {
        let rimCast = (1.0 - dUnderRim / 15);
        cylShade = lerp(cylShade, 0.78, pow(rimCast, 1.5));
      }

      // Hyperrealist overlapped cardboard vertical seam at u = -0.44
      let dSeam = u - (-0.44);
      if (abs(dSeam) < 0.022) {
        if (dSeam < 0) cylShade = max(0.02, cylShade - 0.06); // Tiny catchlight on seam step
        else cylShade = min(0.85, cylShade + 0.26 * (1.0 - dSeam / 0.022)); // Crisp micro-shadow
        waveY += (dSeam > 0 ? 0.9 : -0.6);
      }

      // Bottom recessed cardboard chime ring (t in [0.955..1.0])
      if (t > 0.955) {
        let chimeT = (t - 0.955) / 0.045;
        if (chimeT < 0.35) cylShade += 0.22; // Crimp groove
        else if (chimeT < 0.75) cylShade -= 0.06; // Bottom chime ridge
        else cylShade = max(cylShade, 0.86); // Contact occlusion at table
      }

      D = constrain(cylShade, 0.03, 0.88);
      freqBoost = 1.15;
    }
  }

  return { D: D, waveY: waveY, glare: glare, region: region, freqBoost: freqBoost };
}

function clampSlope(s) {
  return constrain(s, -1, 1);
}

// Helper to flush a sequence of [x, y, pressure] points as a continuous horizontal brush trace
function drawHorizontalTrace(pts, brushName, col, weightMult) {
  if (pts.length < 2) return;
  brush.set(brushName, col, weightMult);
  // Draw in chunks of 45 points with zero curvature so sharp seismograph spikes stay razor-sharp
  const CHUNK = 45;
  for (let i = 0; i < pts.length - 1; i += CHUNK - 1) {
    let slice = pts.slice(i, min(pts.length, i + CHUNK));
    if (slice.length >= 2) {
      brush.spline(slice, 0);
    }
  }
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();
  brush.noFill();
  brush.noHatch();

  // Pale cool clinical buff drum-recorder paper ground
  background("#e8e7df");

  const X_MIN = 56;
  const X_MAX = 1144;
  const Y_MIN = 60;
  const Y_MAX = 1140;
  const ROW_STEP = 6.75; // 160 primary scanlines

  // Cool clinical ink palette
  const INK_PRIMARY = "#12171f"; // Deep cool Prussian-carbon black
  const INK_DENSE   = "#0d1218"; // Pitch carbon black for liquid core & deep occlusion
  const INK_SUB1    = "#1d2631"; // Cool dark slate-black for secondary density traces
  const INK_SUB2    = "#2c3947"; // Cool graphite-slate for delicate midtone & glare harmonics
  const INK_MARGIN  = "#5a6673"; // Clinical recorder margin ticks

  let numRows = floor((Y_MAX - Y_MIN) / ROW_STEP);

  // Sub-channel offsets & activation thresholds within each horizontal scan band
  const CHANNELS = [
    { dy:  0.00, thresh: -1.00, brush: "stylus_primary", col: INK_PRIMARY, w: 1.00 }, // Primary continuous trace
    { dy:  3.35, thresh:  0.19, brush: "stylus_fine",    col: INK_SUB1,    w: 0.92 }, // Secondary midtone trace
    { dy: -1.70, thresh:  0.38, brush: "stylus_fine",    col: INK_SUB2,    w: 0.88 }, // Tertiary shadow trace
    { dy:  1.70, thresh:  0.56, brush: "stylus_primary", col: INK_PRIMARY, w: 0.96 }, // Deep shadow/coffee trace
    { dy:  5.05, thresh:  0.74, brush: "stylus_dense",   col: INK_DENSE,   w: 1.08 }  // Pitch-black coffee core trace
  ];

  // Sample grid along X (every 3px for high-frequency fidelity; 2px inside the cup region)
  for (let r = 0; r <= numRows; r++) {
    let baseY = Y_MIN + r * ROW_STEP;

    // Clinical drum-recorder calibration ticks at left and right margins every 5th row
    if (r % 5 === 0) {
      let tickLen = (r % 10 === 0) ? 10 : 5;
      brush.set("stylus_fine", INK_MARGIN, 0.75);
      brush.line(X_MIN - 6 - tickLen, baseY, X_MIN - 6, baseY);
      brush.line(X_MAX + 6, baseY, X_MAX + 6 + tickLen, baseY);
    }

    // Pre-sample scene along X for this row band so we can compute edge derivatives (AC-coupled stylus kick)
    let xCoords = [];
    let cx = X_MIN;
    while (cx <= X_MAX) {
      xCoords.push(cx);
      // Finer horizontal sampling across the cup & coffee horizontal span
      let inCupSpan = (cx > 280 && cx < 860 && baseY > 250 && baseY < 900);
      cx += inCupSpan ? 2.2 : 3.8;
    }
    if (xCoords[xCoords.length - 1] < X_MAX) xCoords.push(X_MAX);

    let nPts = xCoords.length;
    let samples = new Array(nPts);
    for (let i = 0; i < nPts; i++) {
      samples[i] = evaluateScene(xCoords[i], baseY);
    }

    // Smooth darkness envelope slightly for sub-channel activation (except across crisp object boundaries)
    let smoothD = new Float32Array(nPts);
    for (let i = 0; i < nPts; i++) {
      let s0 = samples[i];
      let sum = s0.D * 2.0, wt = 2.0;
      for (let k = -3; k <= 3; k++) {
        if (k === 0) continue;
        let idx = constrain(i + k, 0, nPts - 1);
        // Only average across matching regions so cup rim and silhouette stay razor-sharp
        if (samples[idx].region === s0.region) {
          sum += samples[idx].D;
          wt += 1.0;
        }
      }
      smoothD[i] = sum / wt;
    }

    // Render each channel in the row band
    for (let c = 0; c < CHANNELS.length; c++) {
      let ch = CHANNELS[c];
      let yChan = baseY + ch.dy;
      if (yChan < Y_MIN - 2 || yChan > Y_MAX + 2) continue;

      let phaseRow1 = r * 1.93 + c * 2.41;
      let phaseRow2 = r * 3.17 - c * 1.57;
      let dither = 0.032 * sin(r * 2.7 + c * 1.9);

      let currentRun = [];

      for (let i = 0; i < nPts; i++) {
        let x = xCoords[i];
        let sc = samples[i];
        let dVal = smoothD[i] + dither * (sc.region === 0 ? 0.3 : 1.0);

        // Channel 0 is always active; Channel 1 also activates on violent glare spikes for harmonic echo
        let active = (c === 0) ||
                     (dVal > ch.thresh) ||
                     (c === 1 && sc.glare > 0.28);

        if (active) {
          // Edge derivative kick (simulates mechanical stylus inertia crossing sharp tonal boundaries)
          let dPrev = samples[max(0, i - 1)].D;
          let dNext = samples[min(nPts - 1, i + 1)].D;
          let edgeKick = (dNext - dPrev) * 1.85;

          // 1. Calm mechanical baseline tremor (always present, subtle on tabletop)
          let nVal = noise(x * 0.035, yChan * 0.08 + c * 10) - 0.5;
          let calmTremor = 0.32 * sin(x * 0.09 + phaseRow1)
                         + 0.20 * cos(x * 0.23 + phaseRow2)
                         + 0.42 * nVal;

          // 2. High-frequency tonal jitter (trembles tightly in dark coffee & deep shadows)
          let dEff = constrain((sc.D - 0.07) / 0.90, 0, 1);
          let toneAmp = 3.15 * pow(dEff, 1.30);
          if (sc.region === 3) {
            // Extra tight, agitated tremor inside the cup's dark liquid
            toneAmp = max(toneAmp, 3.55 * pow(dEff, 1.05));
          }

          let w1 = 1.25 * sc.freqBoost;
          let w2 = 2.35 * sc.freqBoost;
          let highFreq = 0.62 * sin(x * w1 + phaseRow1)
                       + 0.38 * cos(x * w2 + phaseRow2)
                       + 0.35 * (noise(x * 0.28, yChan * 0.22 + c * 7) - 0.5);

          let dyJitter = calmTremor + toneAmp * highFreq + edgeKick;

          // 3. Violent seismograph spikes where a concentric coffee ripple catches window glare
          let dySpike = 0.0;
          if (sc.glare > 0.06) {
            let g = sc.glare;
            // High-Q resonant mechanical needle whipping violently across glare crests
            let carrier = sin(x * 1.58 + r * 2.15 + c * 1.1)
                        * pow(abs(sin(x * 0.74 - r * 1.35)), 0.65)
                        + 0.48 * cos(x * 2.85 + r * 0.85);
            let spikeScale = (c === 0) ? 26.5 : 14.0;
            // Upward-biased sharp clinical spikes with downward ringing overshoot
            let asymBias = -6.5 * pow(g, 1.6) * abs(sin(x * 1.15 + r * 0.9));
            dySpike = pow(g, 1.25) * spikeScale * carrier + asymBias;
          }

          let yFinal = yChan + sc.waveY + dyJitter + dySpike;

          // Modulate stylus pressure with darkness and spike energy
          let press = 0.78 + 0.42 * dEff + 0.35 * sc.glare;
          currentRun.push([x, yFinal, constrain(press, 0.65, 1.30)]);
        } else {
          if (currentRun.length >= 3) {
            // Taper entry and exit pressures of sub-channel horizontal segments
            currentRun[0][2] *= 0.65;
            currentRun[currentRun.length - 1][2] *= 0.65;
            drawHorizontalTrace(currentRun, ch.brush, ch.col, ch.w);
          }
          currentRun = [];
        }
      }

      if (currentRun.length >= 3) {
        if (c > 0) {
          currentRun[0][2] *= 0.65;
          currentRun[currentRun.length - 1][2] *= 0.65;
        }
        drawHorizontalTrace(currentRun, ch.brush, ch.col, ch.w);
      }
    }
  }

  // A single thin red-ink baseline running straight across the lower third
  const RED_Y = 826;
  let redPts = [];
  for (let x = X_MIN - 14; x <= X_MAX + 14; x += 6) {
    // Taut, razor-straight clinical reference datum with microscopic mechanical tension
    let microTension = 0.14 * sin(x * 0.045) + 0.12 * (noise(x * 0.05, 99.4) - 0.5);
    redPts.push([x, RED_Y + microTension, 1.0]);
  }
  drawHorizontalTrace(redPts, "stylus_red", "#b8222a", 1.0);
  // Ultra-crisp core pass for authentic red recorder ink saturation
  drawHorizontalTrace(redPts, "stylus_fine", "#8e151c", 0.72);

  noLoop();
}

// Hyperrealist Dinghy Sail — Meteorological Flow-Field Streamlines in Coloured Pencil
// p5.js 2.x + p5.brush (WEBGL, 1200x1200)

const BATTENS = [
  { v: 0.22, uStart: 0.48, width: 0.013, amp: 0.095 },
  { v: 0.45, uStart: 0.36, width: 0.014, amp: 0.105 },
  { v: 0.68, uStart: 0.24, width: 0.014, amp: 0.100 },
  { v: 0.86, uStart: 0.02, width: 0.012, amp: 0.085 } // Full-length top batten
];

// Muted earth-mineral colour ramp: Ultramarine (windward) -> Lilac (belly) -> Warm Coral (leech)
const STREAM_STOPS = [
  { u: 0.00, sh: [24, 41, 76],   mid: [43, 66, 110],  hi: [88, 110, 150] }, // Deep mineral ultramarine
  { u: 0.18, sh: [42, 59, 97],   mid: [67, 87, 128],  hi: [116, 133, 168] }, // Slate ultramarine
  { u: 0.38, sh: [78, 66, 98],   mid: [115, 99, 134], hi: [162, 146, 176] }, // Mineral violet-lilac
  { u: 0.56, sh: [108, 76, 94],  mid: [148, 112, 128],hi: [190, 158, 169] }, // Dusty mauve-lilac
  { u: 0.76, sh: [138, 78, 68],  mid: [182, 112, 96], hi: [216, 154, 136] }, // Warm clay-coral
  { u: 1.00, sh: [152, 68, 50],  mid: [204, 114, 86], hi: [228, 158, 126] }  // Sunlit terracotta coral
];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(4271);

  // Custom ultra-fine coloured pencil for crisp dense streamlines
  brush.add("fine_cpencil", {
    type: "default",
    weight: 0.9,
    scatter: 0.35,
    sharpness: 0.72,
    grain: 9,
    opacity: 195,
    spacing: 0.12,
    pressure: [0.65, 1.0, 0.65],
    noise: 0.45
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // ---------------------------------------------------------------------------
