// =============================================================================
// GEOMETRY & AERODYNAMIC PHYSICS OF THE SAIL
// =============================================================================

function mastCenter(v) {
  let t = constrain(v, -0.25, 1.05);
  let tc = constrain(t, 0, 1);
  // Mast rises from bottom-left (cockpit view) and bends slightly to leeward
  let x = 266 + (486 - 266) * t - 38 * Math.sin(Math.PI * tc);
  let y = 1022 - (1022 - 72) * Math.pow(tc, 0.96);
  if (t < 0) {
    x = 266 + (486 - 266) * t * 0.82;
    y = 1022 - (1022 - 72) * t;
  }
  let r = lerp(16.5, 7.2, constrain((t + 0.2) / 1.2, 0, 1));
  return { x, y, r };
}

function luffAttach(v) {
  let m = mastCenter(v);
  return {
    x: m.x + m.r * 0.82,
    y: m.y + 1.5
  };
}

function leechEdge(v) {
  let vc = constrain(v, 0, 1);
  // Base line from Clew (1122, 892) to Leech Headboard (522, 78)
  let bx = lerp(1122, 522, Math.pow(vc, 1.07));
  let by = lerp(892, 78, Math.pow(vc, 0.92));

  // Generous dinghy mainsail roach supported by 4 battens
  let roach = 196 * Math.pow(Math.sin(Math.PI * vc), 0.80);

  // Subtle inward scalloping in the slack leech bays between batten tips
  let bStops = [0.0, 0.22, 0.45, 0.68, 0.86, 1.0];
  let scallop = 0;
  for (let i = 0; i < bStops.length - 1; i++) {
    if (vc >= bStops[i] && vc <= bStops[i + 1]) {
      let lt = (vc - bStops[i]) / (bStops[i + 1] - bStops[i]);
      scallop = -10.5 * Math.sin(Math.PI * lt);
      break;
    }
  }

  let nx = 0.815, ny = -0.579;
  return {
    x: bx + (roach + scallop) * nx,
    y: by + (roach + scallop) * ny
  };
}

// Warps streamline parameter s in [0, 1] into sail vertical coordinate v(u, s)
// so lines pack tightly in the high-tension belly & over battens, and loosen in the slack leech
function streamlineV(u, s) {
  let sc = constrain(s, 0.001, 0.999);
  let v = sc;

  // 1. Entry upwash & fluttering luff wave deflection (u in [0, 0.18])
  let flutterEnvU = u * Math.exp(-u / 0.052) * 7.2;
  let flutterEnvV = Math.pow(Math.sin(Math.PI * sc), 0.85);
  let flutterDeflect = 0.0095 * flutterEnvU * flutterEnvV * Math.cos(sc * Math.PI * 7.5 - 0.5);
  v += flutterDeflect;

  // 2. High-tension belly pinch (lines converge toward the diagonal gust tension axis)
  let tensionBell = Math.sin(Math.PI * constrain(u / 0.72, 0, 1));
  let tensionAxis = 0.56 - 0.20 * u; // diagonal from mid-luff toward lower-middle leech
  let dvAxis = sc - tensionAxis;
  v -= 0.055 * tensionBell * dvAxis * Math.exp(-dvAxis * dvAxis / 0.14);

  // 3. Batten ridge compression & slack leech bay expansion
  for (let i = 0; i < BATTENS.length; i++) {
    let b = BATTENS[i];
    let uActive = constrain((u - (b.uStart - 0.08)) / 0.16, 0, 1);
    let distV = sc - b.v;
    let band = 0.095;
    if (Math.abs(distV) < band && uActive > 0) {
      // Pulls streamlines tightly onto the batten pocket ridge
      let pull = -0.019 * Math.sin((distV / band) * Math.PI) * uActive * (0.65 + 0.55 * u);
      v += pull;
    }
  }

  // 4. Slack leech divergence and subtle trailing-edge flutter (u > 0.65)
  if (u > 0.62) {
    let leechT = Math.pow((u - 0.62) / 0.38, 1.35);
    let bStops = [0.0, 0.22, 0.45, 0.68, 0.86, 1.0];
    for (let i = 0; i < bStops.length - 1; i++) {
      if (sc >= bStops[i] && sc <= bStops[i + 1]) {
        let lt = (sc - bStops[i]) / (bStops[i + 1] - bStops[i]);
        // Fan apart inside each slack bay between battens
        v += 0.011 * leechT * Math.sin(2 * Math.PI * lt);
        break;
      }
    }
  }

  return constrain(v, 0.001, 0.999);
}

// Computes raw 3D height/camber components at (u, v)
function sailElevation(u, v) {
  let uc = constrain(u, 0, 1);
  let vc = constrain(v, 0, 1);

  // 1. Main aerodynamic gust belly (NACA-style high-lift section peaking at u ~ 0.33)
  let draftU = 3.28 * Math.pow(uc, 0.71) * Math.pow(1 - uc, 1.42);
  let footArch = 0.34 * Math.pow(1 - vc, 2.4);
  let bellyV = footArch + 0.96 * Math.pow(Math.sin(Math.PI * vc), 0.72);
  let mainCamber = draftU * bellyV;

  // 2. Luff flutter (4.5 harmonic ripples along the windward entry u in [0, 0.20])
  let flU = uc * Math.exp(-uc / 0.046) * 7.5;
  let flV = Math.pow(Math.sin(Math.PI * vc), 0.82);
  let waveV = Math.sin(vc * Math.PI * 7.5 - 0.5) * 0.72 + Math.cos(vc * Math.PI * 13.0 + 0.7) * 0.28;
  let waveU = Math.sin(uc * Math.PI / 0.085 - vc * Math.PI * 4.5);
  let flutter = flU * flV * (waveV * 0.78 + waveU * 0.22) * 0.24;

  // 3. Battens pressing through the cloth
  let battenLift = 0;
  let battenTipDimple = 0;
  for (let i = 0; i < BATTENS.length; i++) {
    let b = BATTENS[i];
    let dv = (vc - b.v) / b.width;
    if (Math.abs(dv) < 4.0) {
      let uOn = 1 / (1 + Math.exp(-(uc - b.uStart) / 0.018));
      let ridge = Math.exp(-dv * dv * 0.85);
      battenLift += b.amp * ridge * uOn * (0.7 + 0.3 * Math.sin(Math.PI * uc));

      // Localized tension dimple/crease right at the inner batten pocket tip
      let duTip = (uc - b.uStart) / 0.028;
      if (Math.abs(duTip) < 2.5 && b.uStart > 0.1) {
        battenTipDimple += 0.032 * Math.exp(-duTip * duTip - dv * dv * 0.6) * Math.cos(duTip * 2.2);
      }
    }
  }

  // 4. Slack leech bay fall-off between battens (u > 0.68)
  let slackDrop = 0;
  if (uc > 0.65) {
    let lt = Math.pow((uc - 0.65) / 0.35, 1.45);
    let bStops = [0.0, 0.22, 0.45, 0.68, 0.86, 1.0];
    for (let i = 0; i < bStops.length - 1; i++) {
      if (vc >= bStops[i] && vc <= bStops[i + 1]) {
        let bayT = (vc - bStops[i]) / (bStops[i + 1] - bStops[i]);
        let bayBell = Math.sin(Math.PI * bayT);
        let ripple = Math.sin(bayT * Math.PI * 3.0 + uc * 14.0) * 0.25;
        slackDrop = -0.075 * lt * bayBell * (1.0 - 0.3 * ripple);
        break;
      }
    }
  }

  // 5. Subtle radial corner tension rays from Clew (1,0) and Tack (0,0)
  let dClew = Math.hypot(1 - uc, vc);
  let angClew = Math.atan2(vc, 1 - uc);
  let clewCrease = 0.018 * Math.exp(-dClew / 0.32) * Math.sin(angClew * 16.0) * Math.sin(Math.PI * uc);

  let dTack = Math.hypot(uc, vc);
  let angTack = Math.atan2(vc, uc);
  let tackCrease = 0.016 * Math.exp(-dTack / 0.28) * Math.sin(angTack * 14.0) * Math.sin(Math.PI * (1 - uc));

  let totalZ = mainCamber + flutter + battenLift + battenTipDimple + slackDrop + clewCrease + tackCrease;

  // Fabric tension metric in [0, 1]
  let tension = constrain(
    0.35 +
    0.55 * draftU * Math.sin(Math.PI * vc) +
    battenLift * 4.5 +
    0.35 * Math.exp(-dClew / 0.25) +
    0.35 * Math.exp(-dTack / 0.25) +
    slackDrop * 3.2,
    0.05, 1.0
  );

  return { totalZ, mainCamber, flutter, battenLift, slackDrop, tension };
}

// Projects (u, v) to 2D canvas coordinates + computes 3D lighting from surface normal
function sailPoint(u, v, computeLight = true) {
  let L = luffAttach(v);
  let R = leechEdge(v);

  let baseX = lerp(L.x, R.x, u);
  let baseY = lerp(L.y, R.y, u);

  let elev = sailElevation(u, v);
  let z = elev.totalZ;

  // Looking up from the cockpit below:
  // Swelling belly arches dramatically UPWARD (-y) and forward/outward in x
  let dx = (-36 * (1 - u) + 26 * u) * z - 18 * elev.flutter;
  let dy = -142 * z - 24 * Math.pow(Math.sin(Math.PI * u), 0.85) * Math.pow(1 - v, 2.2);

  let x = baseX + dx;
  let y = baseY + dy;

  let light = 0.62;
  if (computeLight) {
    let eps = 0.004;
    let zU = sailElevation(min(1, u + eps), v).totalZ;
    let zV = sailElevation(u, min(1, v + eps)).totalZ;
    let dzdu = (zU - z) / eps;
    let dzdv = (zV - z) / eps;

    // Raking sunlight from upper-left-front sculpting the 3D relief
    // -dzdu > 0 means facing windward/left; -dzdv > 0 means facing upward toward the sun
    let shade = 0.60 - 0.29 * dzdu + 0.34 * dzdv + 0.14 * elev.mainCamber;
    light = constrain(shade, 0.04, 0.99);
  }

  return {
    x, y,
    z,
    light,
    tension: elev.tension,
    flutter: elev.flutter,
    battenLift: elev.battenLift
  };
}

// Interpolates the Ultramarine -> Lilac -> Warm Coral palette modulated by 3D light
function getStreamlineColor(u, light, jitter = 0) {
  let uc = constrain(u + jitter * 0.03, 0, 1);
  let s0 = STREAM_STOPS[0];
  let s1 = STREAM_STOPS[STREAM_STOPS.length - 1];

  for (let i = 0; i < STREAM_STOPS.length - 1; i++) {
    if (uc >= STREAM_STOPS[i].u && uc <= STREAM_STOPS[i + 1].u) {
      s0 = STREAM_STOPS[i];
      s1 = STREAM_STOPS[i + 1];
      break;
    }
  }

  let t = (uc - s0.u) / max(0.0001, s1.u - s0.u);
  let shR = lerp(s0.sh[0], s1.sh[0], t);
  let shG = lerp(s0.sh[1], s1.sh[1], t);
  let shB = lerp(s0.sh[2], s1.sh[2], t);

  let mdR = lerp(s0.mid[0], s1.mid[0], t);
  let mdG = lerp(s0.mid[1], s1.mid[1], t);
  let mdB = lerp(s0.mid[2], s1.mid[2], t);

  let hiR = lerp(s0.hi[0], s1.hi[0], t);
  let hiG = lerp(s0.hi[1], s1.hi[1], t);
  let hiB = lerp(s0.hi[2], s1.hi[2], t);

  let r, g, b;
  let lc = constrain(light, 0, 1);
  if (lc < 0.52) {
    let lt = lc / 0.52;
    r = lerp(shR, mdR, lt);
    g = lerp(shG, mdG, lt);
    b = lerp(shB, mdB, lt);
  } else {
    let lt = (lc - 0.52) / 0.48;
    r = lerp(mdR, hiR, lt);
    g = lerp(mdG, hiG, lt);
    b = lerp(mdB, hiB, lt);
  }

  return color(constrain(r, 0, 255), constrain(g, 0, 255), constrain(b, 0, 255));
}

// =============================================================================
// LAYER 1 & 2: ATMOSPHERIC GROUND & METEOROLOGICAL CHART GRID
// =============================================================================

function drawAtmosphericGround() {
  brush.noStroke();

  // Soft mineral-earth sky washes
  brush.fill("#cfd5db", 32);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.55, 0.2);
  brush.rect(40, 40, 620, 760, "corner");

  brush.fill("#dccbb8", 36);
  brush.fillBleed(0.45, "out");
  brush.rect(520, 340, 640, 820, "corner");

  brush.fill("#d4c5b4", 26);
  brush.fillBleed(0.38, "out");
  brush.circle(880, 260, 340, 0.25);

  brush.noFill();

  // Subtle archival paper grain via ultra-light hatch
  brush.noStroke();
  brush.hatchStyle("2H", "#d6cbb9", 0.32);
  brush.hatch(14, 28, { rand: 0.12 });
  brush.rect(25, 25, 1150, 1150, "corner");
  brush.noHatch();
}

function drawMeteorologicalChartGrid() {
  // Polar wind-rose circles and radial bearings centered near the masthead & tack
  let head = mastCenter(1.0);
  let tack = mastCenter(0.0);

  brush.set("2H", "#b8ad9d", 0.32);
  let radii = [160, 320, 500, 700, 920];
  for (let r of radii) {
    brush.arc(head.x, head.y, r, 10, 172);
  }

  brush.set("2H", "#c2b7a6", 0.28);
  for (let ang = 15; ang <= 165; ang += 15) {
    let x1 = head.x + 95 * cos(ang);
    let y1 = head.y + 95 * sin(ang);
    let x2 = head.x + 960 * cos(ang);
    let y2 = head.y + 960 * sin(ang);
    brush.line(x1, y1, constrain(x2, 30, 1170), constrain(y2, 30, 1170));
  }

  // Synoptic background isobars sweeping across the sky
  brush.set("rotring", "#a99d8d", 0.28);
  for (let k = 0; k < 9; k++) {
    let pts = [];
    let yBase = 110 + k * 125;
    for (let s = 0; s <= 12; s++) {
      let x = 35 + (s / 12) * 1130;
      let y = yBase - 85 * Math.sin((s / 12) * Math.PI + k * 0.22) + 28 * Math.cos(s * 0.6 - k);
      pts.push([x, constrain(y, 32, 1168), 0.5]);
    }
    brush.spline(pts, 0.5);

    // Small meteorological tick marks along every second isobar
    if (k % 2 === 0) {
      for (let s = 1; s < 12; s += 2) {
        let p = pts[s];
        brush.line(p[0], p[1] - 5, p[0] + 3, p[1] + 5);
      }
    }
  }

  // Secondary polar arcs around the tack / gooseneck
  brush.set("2H", "#b5a999", 0.28);
  for (let r of [140, 260, 400]) {
    brush.arc(tack.x, tack.y, r, -82, 22);
  }
}

// =============================================================================
// LAYER 3: SPARSER SKY FLOW-FIELD STREAMLINES
// =============================================================================

function skyTrajectoryPoint(uSky, sSky) {
  // uSky in [0, 1] flows from windward left to leeward right across the 1200x1200 frame
  // sSky in [0, 1] spans from bottom to top of the sky
  let x = lerp(28, 1172, uSky);
  let yBase = lerp(1165, 35, sSky);

  // Aerodynamic upwash & deflection around the high-lift dinghy sail dome
  let sailCenterX = lerp(330, 760, sSky * 0.8 + 0.1);
  let sailCenterY = lerp(960, 140, sSky);
  let dx = (x - sailCenterX) / 420;
  let dy = (yBase - sailCenterY) / 480;
  let dist2 = dx * dx + dy * dy;

  // Upwash ahead of the luff and arching acceleration over the head/leech
  let arch = -115 * Math.sin(Math.PI * uSky) * Math.exp(-dist2 * 0.65);
  let wave = 22 * Math.sin(uSky * Math.PI * 2.4 - sSky * 3.2) +
             12 * Math.cos(uSky * Math.PI * 4.5 + sSky * 5.0);

  let y = yBase + arch + wave * (0.4 + 0.6 * uSky);
  return {
    x: constrain(x, 26, 1174),
    y: constrain(y, 26, 1174)
  };
}

function drawSkyStreamlines() {
  // Generate ~155 sparser sky streamlines with synoptic clustering
  let numSkyLines = 155;
  let skySeeds = [];
  for (let i = 0; i < numSkyLines; i++) {
    let t = i / (numSkyLines - 1);
    // Cluster slightly into synoptic wind bands
    let warped = t + 0.016 * Math.sin(t * Math.PI * 10);
    skySeeds.push(constrain(warped, 0.005, 0.995));
  }

  let numSegs = 6;
  let ptsPerSeg = 4;
  let totalSteps = numSegs * ptsPerSeg;

  for (let idx = 0; idx < skySeeds.length; idx++) {
    let s = skySeeds[idx];
    let jitter = random(-0.4, 0.4);
    let isPrimary = (idx % 6 === 0);

    let allPts = [];
    for (let k = 0; k <= totalSteps; k++) {
      let u = k / totalSteps;
      let p = skyTrajectoryPoint(u, s);
      allPts.push({ x: p.x, y: p.y, u });
    }

    for (let seg = 0; seg < numSegs; seg++) {
      let i0 = seg * ptsPerSeg;
      let segPts = [];
      for (let j = 0; j <= ptsPerSeg; j++) {
        let pt = allPts[i0 + j];
        let press = 0.65 + 0.35 * Math.sin((j / ptsPerSeg) * Math.PI);
        segPts.push([pt.x, pt.y, press]);
      }

      let uMid = (seg + 0.5) / numSegs;
      let skyLight = 0.60 + 0.16 * Math.sin(s * Math.PI + uMid * 2.0);
      let col = getStreamlineColor(uMid, skyLight, jitter);

      let bName = isPrimary ? "fine_cpencil" : "2H";
      let w = isPrimary ? 0.56 : 0.38;
      brush.set(bName, col, w);
      brush.spline(segPts, 0.5);

      // Occasional meteorological wind barbs in the open sky outside the sail
      if (isPrimary && (seg === 0 || seg === 5) && idx % 12 === 0) {
        let pA = allPts[i0 + 2];
        let pB = allPts[i0 + 3];
        let ang = atan2(pB.y - pA.y, pB.x - pA.x);
        let barbLen = 14;
        let bx = pA.x + barbLen * cos(ang - 125);
        let by = pA.y + barbLen * sin(ang - 125);
        brush.set("rotring", col, 0.32);
        brush.line(pA.x, pA.y, bx, by);
        // Second feather on barb
        let pA2 = { x: lerp(pA.x, pB.x, 0.45), y: lerp(pA.y, pB.y, 0.45) };
        brush.line(pA2.x, pA2.y, pA2.x + 9 * cos(ang - 125), pA2.y + 9 * sin(ang - 125));
      }
    }
  }
}

// =============================================================================
// LAYER 4: THE WHITE DINGHY SAIL BASE LUMINOSITY & 3D VOLUME
// =============================================================================

function buildSailBoundaryPolygon() {
  let pts = [];
  // Luff from Tack (v=0) to Head (v=1)
  for (let i = 0; i <= 40; i++) {
    let v = i / 40;
    let p = sailPoint(0, v, false);
    pts.push([p.x, p.y]);
  }
  // Headboard to Leech (v=1, u=0..1)
  for (let i = 1; i <= 8; i++) {
    let u = i / 8;
    let p = sailPoint(u, 1, false);
    pts.push([p.x, p.y]);
  }
  // Leech from Head (v=1) down to Clew (v=0)
  for (let i = 39; i >= 0; i--) {
    let v = i / 40;
    let p = sailPoint(1, v, false);
    pts.push([p.x, p.y]);
  }
  // Foot from Clew (u=1) back to Tack (u=0)
  for (let i = 24; i >= 1; i--) {
    let u = i / 25;
    let p = sailPoint(u, 0, false);
    pts.push([p.x, p.y]);
  }
  return pts;
}

function buildSailPatchPolygon(u0, u1, v0, v1, steps = 12) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let p = sailPoint(lerp(u0, u1, i / steps), v0, false);
    pts.push([p.x, p.y]);
  }
  for (let i = 1; i <= steps; i++) {
    let p = sailPoint(u1, lerp(v0, v1, i / steps), false);
    pts.push([p.x, p.y]);
  }
  for (let i = steps - 1; i >= 0; i--) {
    let p = sailPoint(lerp(u0, u1, i / steps), v1, false);
    pts.push([p.x, p.y]);
  }
  for (let i = steps - 1; i >= 1; i--) {
    let p = sailPoint(u0, lerp(v0, v1, i / steps), false);
    pts.push([p.x, p.y]);
  }
  return pts;
}

function drawSailBaseLuminosity() {
  brush.noStroke();

  // 1. Crisp warm-white cloth wash across the entire sail silhouette
  let sailPoly = new brush.Polygon(buildSailBoundaryPolygon());
  sailPoly.wash("#f8f5ed", 232);

  // 2. Brilliant sunlit white-ivory highlight over the swollen gust dome
  let domePoly = new brush.Polygon(buildSailPatchPolygon(0.14, 0.62, 0.18, 0.84, 14));
  domePoly.fill("#fdfcf8", 165, 0.28, 0.25);

  // 3. Cool mineral shadow wash in the fluttering luff trough (u in [0.01, 0.14])
  let luffTroughPoly = new brush.Polygon(buildSailPatchPolygon(0.01, 0.14, 0.08, 0.90, 14));
  luffTroughPoly.fill("#cad2de", 62, 0.25, 0.35);

  // 4. Warm earth-stone shadow wash in the slack leech & lower foot pocket
  let leechShadePoly = new brush.Polygon(buildSailPatchPolygon(0.68, 0.99, 0.05, 0.85, 12));
  leechShadePoly.fill("#e2d6c5", 64, 0.28, 0.35);

  // 5. Semi-translucent Mylar visibility window tint (shows faint sky tone)
  let winPoly = new brush.Polygon(buildSailPatchPolygon(0.20, 0.45, 0.16, 0.28, 10));
  winPoly.fill("#dce0e3", 78, 0.12, 0.20);
}

// =============================================================================
// LAYER 5: CONTINUOUS SAIL STREAMLINES (THE CORE COLOURED-PENCIL FLOW FIELD)
// =============================================================================

function drawSingleSailStreamline(sSeed, uStart, uEnd, weightMult = 1.0, passType = "main") {
  let numSegs = 7;
  let ptsPerSeg = 4;

  // Adjust segment count for partial tension streamlines
  let span = uEnd - uStart;
  if (span < 0.85) {
    numSegs = max(3, floor(span * 7));
  }
  let totalSteps = numSegs * ptsPerSeg;

  let pts = [];
  for (let k = 0; k <= totalSteps; k++) {
    let u = lerp(uStart, uEnd, k / totalSteps);
    let v = streamlineV(u, sSeed);
    let sp = sailPoint(u, v, true);
    pts.push({
      x: sp.x,
      y: sp.y,
      u,
      v,
      light: sp.light,
      tension: sp.tension,
      battenLift: sp.battenLift
    });
  }

  let colorJitter = random(-0.35, 0.35);

  for (let seg = 0; seg < numSegs; seg++) {
    let i0 = seg * ptsPerSeg;
    let midPt = pts[i0 + 2];

    // Skip occasional segments on the brightest sunlit dome during secondary passes
    // so the luminous white Dacron cloth gleams through the pencil texture
    if (passType === "tension" && midPt.light > 0.84 && random() < 0.45) {
      continue;
    }

    let splinePts = [];
    for (let j = 0; j <= ptsPerSeg; j++) {
      let p = pts[i0 + j];
      // Taper pressure gracefully at ends of partial tension streamlines
      let env = 1.0;
      if (uEnd < 0.98 && p.u > uEnd - 0.15) {
        env = constrain((uEnd - p.u) / 0.15, 0.15, 1.0);
      }
      if (uStart > 0.02 && p.u < uStart + 0.12) {
        env = min(env, constrain((p.u - uStart) / 0.12, 0.15, 1.0));
      }
      // Heavier pressure in shadowed hollows & high-tension batten ridges
      let shadePress = 0.55 + 0.65 * (1.0 - p.light) + 0.30 * p.tension;
      splinePts.push([p.x, p.y, shadePress * env]);
    }

    let col = getStreamlineColor(midPt.u, midPt.light, colorJitter);

    // Modulate brush choice & weight by 3D illumination and local tension
    let darkFactor = 1.0 - midPt.light;
    let w = (0.34 + 0.46 * darkFactor + 0.18 * midPt.tension) * weightMult;
    let bName = (darkFactor > 0.48 || midPt.battenLift > 0.03) ? "fine_cpencil" : "2H";
    if (passType === "shadow" && darkFactor > 0.52) {
      bName = "cpencil";
    }

    brush.set(bName, col, w);
    brush.spline(splinePts, 0.55);
  }
}

function drawSailStreamlines() {
  // -------------------------------------------------------------------------
  // PASS A: 350 Full-Chord Continuous Streamlines (u = 0 -> 1)
  //         Every line runs uninterrupted from windward luff to trailing leech
  // -------------------------------------------------------------------------
  let numFull = 350;
  for (let i = 0; i < numFull; i++) {
    let s = (i + 0.5) / numFull;
    // Slight organic hand-drawn jitter in seed spacing
    let sJit = constrain(s + random(-0.0008, 0.0008), 0.002, 0.998);
    drawSingleSailStreamline(sJit, 0.0, 1.0, 0.95, "main");
  }

  // -------------------------------------------------------------------------
  // PASS B: High-Tension Packing Streamlines (u = 0 -> 0.62..0.82)
  //         Interleaved in the strained gust belly, luff flutter & batten corridors,
  //         feathering out before the slack leech so the leech loosens naturally!
  // -------------------------------------------------------------------------
  let numTension = 190;
  for (let i = 0; i < numTension; i++) {
    let t = (i + 0.5) / numTension;
    // Concentrate in the main gust belly (s in [0.12, 0.88])
    let s = lerp(0.06, 0.94, t);
    let uEnd = 0.58 + 0.24 * Math.sin(Math.PI * s) + random(-0.06, 0.06);
    // Extend further along the 4 batten ridges
    for (let b of BATTENS) {
      if (Math.abs(s - b.v) < 0.032) {
        uEnd = 0.96;
      }
    }
    drawSingleSailStreamline(s, 0.0, constrain(uEnd, 0.45, 0.98), 0.78, "tension");
  }

  // -------------------------------------------------------------------------
  // PASS C: Luff Flutter Trough & Corner Tension Deepening
  //         Extra tightly-packed ultramarine streamlines in the fluttering entry
  // -------------------------------------------------------------------------
  for (let i = 0; i < 85; i++) {
    let s = lerp(0.04, 0.95, i / 84);
    let uSpan = 0.22 + 0.12 * Math.sin(s * Math.PI * 7.5 - 0.5);
    drawSingleSailStreamline(s, 0.0, uSpan, 0.85, "shadow");
  }

  // -------------------------------------------------------------------------
  // PASS D: Sunlit White Coloured-Pencil Highlights Over the Swollen Belly
  //         Enhances the crisp white Dacron sheen on the high-camber crown
  // -------------------------------------------------------------------------
  for (let i = 0; i < 75; i++) {
    let s = lerp(0.18, 0.84, i / 74);
    let pts = [];
    for (let k = 0; k <= 8; k++) {
      let u = lerp(0.16, 0.54, k / 8);
      let v = streamlineV(u, s);
      let sp = sailPoint(u, v, true);
      pts.push([sp.x, sp.y, 0.4 + 0.6 * sp.light]);
    }
    brush.set("fine_cpencil", "#fcfaf4", 0.45);
    brush.spline(pts, 0.5);
  }

  // -------------------------------------------------------------------------
  // PASS E: Trailing-Edge Leech Wake & Vortex Curls Peeling Into the Sky
  // -------------------------------------------------------------------------
  for (let i = 0; i < 58; i++) {
    let s = lerp(0.03, 0.97, i / 57);
    let vLeech = streamlineV(1.0, s);
    let p0 = sailPoint(0.92, vLeech, true);
    let p1 = sailPoint(1.00, vLeech, true);

    let dx = p1.x - p0.x;
    let dy = p1.y - p0.y;
    let len = max(1, Math.hypot(dx, dy));
    let ux = dx / len, uy = dy / len;

    let wakePts = [[p1.x, p1.y, 0.85]];
    let curlDir = Math.sin(s * Math.PI * 9.0);
    for (let step = 1; step <= 4; step++) {
      let dist = step * random(16, 26);
      let bend = step * step * 2.8 * curlDir;
      let wx = p1.x + ux * dist - uy * bend;
      let wy = p1.y + uy * dist + ux * bend;
      wakePts.push([constrain(wx, 30, 1170), constrain(wy, 30, 1170), 0.85 - step * 0.18]);
    }
    let col = getStreamlineColor(1.0, p1.light, random(-0.2, 0.2));
    brush.set("2H", col, 0.36);
    brush.spline(wakePts, 0.55);
  }
}

// =============================================================================
// LAYER 6: BATTENS PRESSING THROUGH CLOTH, SEAMS, WINDOW & ISOBARS
// =============================================================================

function drawBattenDetails() {
  for (let i = 0; i < BATTENS.length; i++) {
    let b = BATTENS[i];
    let steps = 24;

    // 1. Upper sunlit lip of the batten pocket pressing through the Dacron
    let upperPts = [];
    // 2. Center crown highlight of the batten rod
    let crownPts = [];
    // 3. Lower cast-shadow crease under the batten pocket
    let lowerPts = [];
    let lowerShadowPts = [];

    for (let k = 0; k <= steps; k++) {
      let u = lerp(b.uStart, 1.0, k / steps);
      let pUp = sailPoint(u, b.v + b.width * 0.95, false);
      let pCr = sailPoint(u, b.v, false);
      let pLo = sailPoint(u, b.v - b.width * 0.95, false);
      let pSh = sailPoint(u, b.v - b.width * 1.45, false);

      let press = 0.5 + 0.5 * Math.sin((k / steps) * Math.PI);
      upperPts.push([pUp.x, pUp.y, press]);
      crownPts.push([pCr.x, pCr.y, press]);
      lowerPts.push([pLo.x, pLo.y, press * 1.15]);
      lowerShadowPts.push([pSh.x, pSh.y, press * 0.9]);
    }

    // Draw sunlit crown & upper pocket stitch line
    brush.set("fine_cpencil", "#fdfbf5", 0.65);
    brush.spline(crownPts, 0.5);

    brush.set("2H", "#8d7684", 0.38);
    brush.spline(upperPts, 0.5);

    // Draw deep embossed shadow along underside of batten pocket (color-graded in halves)
    let half = floor(steps / 2);
    let colIn = getStreamlineColor(lerp(b.uStart, 1.0, 0.25), 0.16, 0);
    let colOut = getStreamlineColor(lerp(b.uStart, 1.0, 0.78), 0.18, 0);

    brush.set("fine_cpencil", colIn, 0.78);
    brush.spline(lowerPts.slice(0, half + 2), 0.5);
    brush.set("fine_cpencil", colOut, 0.82);
    brush.spline(lowerPts.slice(half), 0.5);

    brush.set("2H", "#5d4854", 0.42);
    brush.spline(lowerShadowPts, 0.5);

    // Cross-contour stitch ticks along the batten pocket edges
    brush.set("rotring", "#6e5853", 0.24);
    for (let k = 1; k < steps; k += 2) {
      let p1 = upperPts[k];
      let p2 = lowerPts[k];
      brush.line(p1[0], p1[1], lerp(p1[0], p2[0], 0.22), lerp(p1[1], p2[1], 0.22));
      brush.line(p2[0], p2[1], lerp(p2[0], p1[0], 0.22), lerp(p2[1], p1[1], 0.22));
    }

    // 4. Inner batten-pocket receptacle cap & radiating cloth tension wrinkles
    if (b.uStart > 0.1) {
      let capU0 = b.uStart - 0.012;
      let capU1 = b.uStart + 0.025;
      let capV0 = b.v - b.width * 1.15;
      let capV1 = b.v + b.width * 1.15;
      let capPoly = new brush.Polygon(buildSailPatchPolygon(capU0, capU1, capV0, capV1, 4));
      capPoly.fill("#cfc3b4", 95, 0.08, 0.2);

      let c0 = sailPoint(capU0, capV0, false);
      let c1 = sailPoint(capU1, capV0, false);
      let c2 = sailPoint(capU1, capV1, false);
      let c3 = sailPoint(capU0, capV1, false);
      brush.set("rotring", "#54433a", 0.32);
      brush.line(c0.x, c0.y, c1.x, c1.y);
      brush.line(c1.x, c1.y, c2.x, c2.y);
      brush.line(c2.x, c2.y, c3.x, c3.y);
      brush.line(c3.x, c3.y, c0.x, c0.y);

      // Short radial stress wrinkles fanning forward from the stiff batten tip into soft cloth
      for (let r = -3; r <= 3; r++) {
        let ang = r * 18;
        let wPts = [];
        for (let s = 0; s <= 4; s++) {
          let wu = capU0 - (s / 4) * 0.075 * cos(ang);
          let wv = b.v + (s / 4) * 0.038 * sin(ang);
          let wp = sailPoint(wu, wv, true);
          wPts.push([wp.x, wp.y, 0.85 - s * 0.16]);
        }
        let wCol = getStreamlineColor(capU0 - 0.03, 0.28, 0);
        brush.set("fine_cpencil", wCol, 0.46);
        brush.spline(wPts, 0.45);
      }
    }

    // 5. Outer leech batten tension cap at u = 1.0
    let lCap0 = sailPoint(0.975, b.v - b.width * 1.1, false);
    let lCap1 = sailPoint(1.000, b.v - b.width * 1.1, false);
    let lCap2 = sailPoint(1.000, b.v + b.width * 1.1, false);
    let lCap3 = sailPoint(0.975, b.v + b.width * 1.1, false);
    brush.set("rotring", "#6b473b", 0.34);
    brush.line(lCap0.x, lCap0.y, lCap1.x, lCap1.y);
    brush.line(lCap1.x, lCap1.y, lCap2.x, lCap2.y);
    brush.line(lCap2.x, lCap2.y, lCap3.x, lCap3.y);
    brush.line(lCap3.x, lCap3.y, lCap0.x, lCap0.y);
  }
}

function drawSailPanelSeamsAndWindow(isOverlay) {
  // 1. Horizontal/radial Dacron panel seams curving over the 3D sail belly
  let seamVs = [0.14, 0.33, 0.56, 0.77, 0.92];
  for (let sv of seamVs) {
    let seamPts = [];
    for (let k = 0; k <= 24; k++) {
      let u = k / 24;
      let vCurve = sv + 0.015 * Math.sin(Math.PI * u);
      let p = sailPoint(u, vCurve, false);
      seamPts.push([p.x, p.y, 0.65]);
    }
    brush.set("2H", isOverlay ? "#7d6d63" : "#b8ada0", isOverlay ? 0.30 : 0.36);
    brush.spline(seamPts, 0.5);

    if (isOverlay) {
      // Delicate zigzag sailmaker stitching along the panel overlap
      brush.set("rotring", "#8c776b", 0.20);
      for (let k = 1; k < 24; k++) {
        let pA = sailPoint((k - 0.5) / 24, sv + 0.015 * Math.sin(Math.PI * ((k - 0.5) / 24)) - 0.004, false);
        let pB = sailPoint(k / 24, sv + 0.015 * Math.sin(Math.PI * (k / 24)) + 0.004, false);
        brush.line(pA.x, pA.y, pB.x, pB.y);
      }
    }
  }

  // 2. Framed Mylar visibility window in the lower belly (u in [0.20, 0.45], v in [0.16, 0.28])
  let u0 = 0.20, u1 = 0.45, v0 = 0.16, v1 = 0.28;
  let winEdge = buildSailPatchPolygon(u0, u1, v0, v1, 10);
  winEdge.push(winEdge[0]);

  brush.set(isOverlay ? "rotring" : "HB", isOverlay ? "#59483e" : "#9c8d7e", isOverlay ? 0.36 : 0.52);
  brush.spline(winEdge.map(pt => [pt[0], pt[1], 0.75]), 0.25);

  if (isOverlay) {
    // Inner window tape border
    let winInner = buildSailPatchPolygon(u0 + 0.012, u1 - 0.012, v0 + 0.008, v1 - 0.008, 10);
    winInner.push(winInner[0]);
    brush.set("2H", "#786558", 0.28);
    brush.spline(winInner.map(pt => [pt[0], pt[1], 0.65]), 0.25);

    // Specular diagonal sheen lines across the curved Mylar window film
    brush.set("fine_cpencil", "#fcfaf5", 0.45);
    for (let g = 0; g < 5; g++) {
      let gu0 = u0 + 0.03 + g * 0.035;
      let gp1 = sailPoint(gu0, v0 + 0.01, false);
      let gp2 = sailPoint(gu0 + 0.04, v1 - 0.01, false);
      brush.line(gp1.x, gp1.y, gp2.x, gp2.y);
    }
  }

  // 3. Starburst radial corner reinforcement patches at Tack, Clew, and Head
  if (isOverlay) {
    drawCornerReinforcementPatch(0.0, 0.0, 0.16, 0.14, 0, 82);     // Tack
    drawCornerReinforcementPatch(1.0, 0.0, -0.18, 0.15, 105, 175); // Clew
    drawCornerReinforcementPatch(0.0, 1.0, 0.18, -0.13, -78, -8);  // Head
  }
}

function drawCornerReinforcementPatch(uCorner, vCorner, duMax, dvMax, aStart, aEnd) {
  brush.set("rotring", "#695548", 0.26);
  // Radial tension rays
  for (let i = 0; i <= 7; i++) {
    let t = i / 7;
    let rayPts = [];
    for (let s = 0; s <= 6; s++) {
      let r = s / 6;
      let u = constrain(uCorner + duMax * r * cos(lerp(aStart, aEnd, t)), 0, 1);
      let v = constrain(vCorner + abs(dvMax) * Math.sign(dvMax) * r * sin(lerp(aStart, aEnd, t)), 0, 1);
      let p = sailPoint(u, v, false);
      rayPts.push([p.x, p.y, 0.7]);
    }
    brush.spline(rayPts, 0.4);
  }
  // Concentric reinforcement ply arcs
  for (let ring of [0.38, 0.68, 1.0]) {
    let arcPts = [];
    for (let i = 0; i <= 10; i++) {
      let t = i / 10;
      let u = constrain(uCorner + duMax * ring * cos(lerp(aStart, aEnd, t)), 0, 1);
      let v = constrain(vCorner + abs(dvMax) * Math.sign(dvMax) * ring * sin(lerp(aStart, aEnd, t)), 0, 1);
      let p = sailPoint(u, v, false);
      arcPts.push([p.x, p.y, 0.7]);
    }
    brush.spline(arcPts, 0.45);
  }
}

function drawClothIsobarsAndTelltales() {
  // 1. Meteorological Isobars / Pressure Contours directly on the swollen sail cloth
  //    ("The image reads like a meteorological chart that has become cloth")
  let isobarLevels = [0.22, 0.36, 0.50, 0.64, 0.78];
  for (let idx = 0; idx < isobarLevels.length; idx++) {
    let rad = isobarLevels[idx];
    let isoPts = [];
    let steps = 36;
    for (let k = 0; k <= steps; k++) {
      let ang = (k / steps) * 360;
      let u = 0.35 + rad * 0.48 * cos(ang);
      let v = 0.48 + rad * 0.52 * sin(ang);
      if (u >= 0.01 && u <= 0.99 && v >= 0.01 && v <= 0.99) {
        let p = sailPoint(u, v, false);
        isoPts.push({ x: p.x, y: p.y, u, v });
      }
    }
    if (isoPts.length > 5) {
      let col = (idx % 2 === 0) ? "#5c4a42" : "#445473";
      brush.set("rotring", col, 0.28);
      let sp = isoPts.map(pt => [pt.x, pt.y, 0.65]);
      brush.spline(sp, 0.5);

      // Tiny calibration ticks along the cloth isobars
      for (let k = 0; k < isoPts.length - 1; k += 4) {
        let pA = isoPts[k];
        let pB = isoPts[k + 1];
        let nx = -(pB.y - pA.y), ny = pB.x - pA.x;
        let nl = max(0.001, Math.hypot(nx, ny));
        brush.line(pA.x, pA.y, pA.x + (nx / nl) * 5, pA.y + (ny / nl) * 5);
      }
    }
  }

  // 2. Streaming aerodynamic wool telltales along the Luff entry and Leech batten tips
  let luffTellVs = [0.26, 0.48, 0.68, 0.84];
  for (let tv of luffTellVs) {
    let pBase = sailPoint(0.08, tv, false);
    // Small circular fabric patch holding the telltale
    brush.set("rotring", "#8c4332", 0.32);
    brush.circle(pBase.x, pBase.y, 4.5, 0.15);

    // Windward telltale (ultramarine, lifting slightly in the gust flutter)
    let wPts = [];
    for (let s = 0; s <= 5; s++) {
      let p = sailPoint(0.08 + s * 0.022, tv + 0.006 * Math.sin(s * 1.1), false);
      wPts.push([p.x, p.y - s * 1.5, 0.9 - s * 0.1]);
    }
    brush.set("cpencil", "#1d3566", 0.68);
    brush.spline(wPts, 0.5);

    // Leeward telltale (terracotta-coral, streaming along the airflow)
    let lPts = [];
    for (let s = 0; s <= 5; s++) {
      let p = sailPoint(0.08 + s * 0.024, tv - 0.004 * s, false);
      lPts.push([p.x, p.y + 3, 0.85 - s * 0.1]);
    }
    brush.set("cpencil", "#b84a35", 0.65);
    brush.spline(lPts, 0.5);
  }

  // Leech telltales streaming off the batten tips into the sky
  for (let b of BATTENS) {
    let pTip = sailPoint(1.0, b.v, false);
    let tPts = [[pTip.x, pTip.y, 0.9]];
    for (let s = 1; s <= 5; s++) {
      tPts.push([
        pTip.x + s * 11,
        pTip.y - s * 4 + 4 * Math.sin(s * 1.3 + b.v * 10),
        0.9 - s * 0.12
      ]);
    }
    brush.set("cpencil", "#c45138", 0.68);
    brush.spline(tPts, 0.55);
  }

  // Crisp leech and foot boltrope / edge binding
  let leechBind = [];
  for (let k = 0; k <= 45; k++) {
    let p = sailPoint(1.0, k / 45, false);
    leechBind.push([p.x, p.y, 0.75]);
  }
  brush.set("fine_cpencil", "#a6533e", 0.55);
  brush.spline(leechBind, 0.5);

  let footBind = [];
  for (let k = 0; k <= 30; k++) {
    let p = sailPoint(k / 30, 0.0, false);
    footBind.push([p.x, p.y, 0.8]);
  }
  brush.set("fine_cpencil", "#59483e", 0.62);
  brush.spline(footBind, 0.5);
}

// =============================================================================
// LAYER 7: FORESHORTENED MAST, BOOM, GOOSENECK & RIGGING FROM BELOW
// =============================================================================

function drawMastBoomAndRigging() {
  // ---------------------------------------------------------------------------
  // 1. THE MAST (Sweeping up from bottom-left (220, 1200) to Head (486, 72))
  // ---------------------------------------------------------------------------
  let mastLeft = [];
  let mastRight = [];
  let mastSteps = 45;

  for (let i = 0; i <= mastSteps; i++) {
    let v = lerp(-0.19, 1.01, i / mastSteps);
    let m = mastCenter(v);
    let mNext = mastCenter(v + 0.01);
    let tx = mNext.x - m.x, ty = mNext.y - m.y;
    let tl = max(0.001, Math.hypot(tx, ty));
    let nx = -ty / tl, ny = tx / tl;

    mastLeft.push([m.x + nx * m.r, m.y + ny * m.r]);
    mastRight.push([m.x - nx * m.r, m.y - ny * m.r]);
  }

  let mastPolyPts = mastLeft.concat(mastRight.slice().reverse());
  let mastPoly = new brush.Polygon(mastPolyPts);
  mastPoly.wash("#4a3d33", 240);

  // Longitudinal coloured-pencil shading lines along the cylindrical mast spar
  for (let f = -0.92; f <= 0.92; f += 0.14) {
    let sparPts = [];
    for (let i = 0; i <= 26; i++) {
      let v = lerp(-0.19, 1.01, i / 26);
      let m = mastCenter(v);
      let mNext = mastCenter(v + 0.01);
      let tx = mNext.x - m.x, ty = mNext.y - m.y;
      let tl = max(0.001, Math.hypot(tx, ty));
      let nx = -ty / tl, ny = tx / tl;

      sparPts.push([m.x + nx * m.r * f, m.y + ny * m.r * f, 0.8]);
    }
    // Windward face catches warm ochre/parchment highlight; leeward side has deep umber core shadow
    let col = "#2b221c";
    let w = 0.65;
    if (f > 0.35 && f < 0.78) {
      col = "#d9cdb8";
      w = 0.52;
    } else if (f > -0.15 && f <= 0.35) {
      col = "#7a6654";
      w = 0.55;
    } else if (f <= -0.45) {
      col = "#1f1915";
      w = 0.78;
    }
    brush.set("cpencil", col, w);
    brush.spline(sparPts, 0.5);
  }

  // Circumferential contour bands & luff track groove along the mast
  brush.set("rotring", "#1f1814", 0.35);
  for (let i = 0; i <= mastSteps; i += 2) {
    let pL = mastLeft[i];
    let pR = mastRight[i];
    brush.line(pL[0], pL[1], pR[0], pR[1]);
  }

  // ---------------------------------------------------------------------------
  // 2. THE BOOM (Foreshortened from Gooseneck (252, 1044) to Clew (1148, 898))
  // ---------------------------------------------------------------------------
  let gNeck = mastCenter(-0.02);
  let bx0 = gNeck.x + 8, by0 = gNeck.y;
  let bx1 = 1148, by1 = 898;
  let boomH0 = 26, boomH1 = 17;

  // Under-sail foot shadow gap between arched loose foot and straight boom
  let gapPts = [];
  for (let k = 0; k <= 24; k++) {
    let u = k / 24;
    let pFoot = sailPoint(u, 0, false);
    gapPts.push([pFoot.x, pFoot.y]);
  }
  gapPts.push([bx1 - 22, by1 - 4]);
  gapPts.push([bx0 + 18, by0 - 4]);
  let gapPoly = new brush.Polygon(gapPts);
  gapPoly.fill("#9c9082", 52, 0.15, 0.25);

  // Boom spar polygon
  let boomPolyPts = [
    [bx0, by0 - boomH0 * 0.45],
    [bx1, by1 - boomH1 * 0.45],
    [bx1, by1 + boomH1 * 0.55],
    [bx0, by0 + boomH0 * 0.55]
  ];
  let boomPoly = new brush.Polygon(boomPolyPts);
  boomPoly.wash("#45382e", 242);

  // Boom longitudinal pencil shading (seen from underneath)
  for (let f = -0.42; f <= 0.52; f += 0.09) {
    let yA = by0 + boomH0 * f;
    let yB = by1 + boomH1 * f;
    let col = "#241d18";
    let w = 0.68;
    if (f < -0.18) {
      col = "#ccbda8"; // Upper rim catching reflected light from the white sail foot
      w = 0.50;
    } else if (f < 0.12) {
      col = "#6e5a49";
      w = 0.58;
    }
    brush.set("cpencil", col, w);
    brush.line(bx0, yA, bx1, yB);
  }

  // Boom outline, gooseneck fitting, outhaul block at clew & tack cringle
  brush.set("rotring", "#1c1612", 0.42);
  brush.line(bx0, by0 - boomH0 * 0.45, bx1, by1 - boomH1 * 0.45);
  brush.line(bx0, by0 + boomH0 * 0.55, bx1, by1 + boomH1 * 0.55);
  brush.line(bx1, by1 - boomH1 * 0.45, bx1, by1 + boomH1 * 0.55);

  // Gooseneck bracket & Cunningham cringle at Tack
  let pTack = sailPoint(0, 0, false);
  brush.set("cpencil", "#2a211b", 0.9);
  brush.line(gNeck.x - 6, gNeck.y - 14, bx0 + 18, by0 + 12);
  brush.line(gNeck.x - 6, gNeck.y + 14, bx0 + 18, by0 - 10);
  brush.set("rotring", "#876b52", 0.45);
  brush.circle(pTack.x + 8, pTack.y - 8, 6.5, 0.1);
  brush.line(pTack.x + 8, pTack.y - 2, bx0 + 14, by0 + 25);

  // Outhaul strap & Clew cringle at right end of boom
  let pClew = sailPoint(1, 0, false);
  brush.set("rotring", "#876b52", 0.48);
  brush.circle(pClew.x - 10, pClew.y - 6, 7, 0.1);
  brush.set("cpencil", "#2b221c", 0.85);
  brush.line(pClew.x - 8, pClew.y, bx1 - 14, by1);
  brush.line(pClew.x - 4, pClew.y - 4, bx1 - 6, by1 - 2);

  // Headboard plate & Halyard shackle at top of sail
  let pHeadL = sailPoint(0, 1, false);
  let pHeadR = sailPoint(1, 1, false);
  brush.set("rotring", "#3b2f26", 0.45);
  brush.line(pHeadL.x, pHeadL.y, pHeadR.x, pHeadR.y);
  brush.circle(lerp(pHeadL.x, pHeadR.x, 0.35), lerp(pHeadL.y, pHeadR.y, 0.35) + 8, 5, 0.1);

  // ---------------------------------------------------------------------------
  // 3. BOOM VANG & MAINSHEET TACKLE ANGLING INTO THE LOWER FRAME
  // ---------------------------------------------------------------------------
  // Boom Vang (kicking strap) from lower mast to boom at 30% length
  let vangBoomX = lerp(bx0, bx1, 0.28);
  let vangBoomY = lerp(by0, by1, 0.28) + 8;
  let vangMast = mastCenter(-0.16);

  for (let d = -3; d <= 3; d += 2) {
    brush.set("cpencil", d === -1 ? "#a89680" : "#332820", 0.58);
    brush.line(vangMast.x + 10, vangMast.y + d * 2, vangBoomX, vangBoomY + d);
  }
  // Vang purchase cascade block
  let vMidX = lerp(vangMast.x + 10, vangBoomX, 0.52);
  let vMidY = lerp(vangMast.y, vangBoomY, 0.52);
  brush.set("rotring", "#241c17", 0.42);
  brush.circle(vMidX, vMidY, 7, 0.1);

  // Mainsheet tackle dropping from mid-boom (u ~ 0.62) down toward cockpit bottom
  let sheetBoomX = lerp(bx0, bx1, 0.62);
  let sheetBoomY = lerp(by0, by1, 0.62) + 9;
  brush.set("rotring", "#2b221c", 0.48);
  brush.circle(sheetBoomX, sheetBoomY + 8, 8, 0.1);

  // Three-part mainsheet falls angling down out of the bottom edge
  let sheetLines = [
    [sheetBoomX - 6, sheetBoomY + 14, sheetBoomX - 85, 1190],
    [sheetBoomX,     sheetBoomY + 15, sheetBoomX - 52, 1190],
    [sheetBoomX + 6, sheetBoomY + 14, sheetBoomX - 18, 1190]
  ];
  for (let sl of sheetLines) {
    brush.set("cpencil", "#4a3b30", 0.55);
    brush.line(sl[0], sl[1], sl[2], sl[3]);
    brush.set("2H", "#bfb19c", 0.28);
    brush.line(sl[0] + 1.5, sl[1], sl[2] + 1.5, sl[3]);
  }
}

// =============================================================================
// LAYER 8: METEOROLOGICAL CHART CALIBRATION BORDER & SCALE TICKS
// =============================================================================

function drawChartCalibrationBorder() {
  let m = 24;
  let w = 1200 - m * 2;
  let h = 1200 - m * 2;

  // Outer & inner technical chart ruling in fine sepia rotring
  brush.set("rotring", "#7a6b5c", 0.38);
  brush.noFill();
  brush.rect(m, m, w, h, "corner");

  brush.set("rotring", "#9c8d7c", 0.26);
  brush.rect(m + 8, m + 8, w - 16, h - 16, "corner");

  // Degree / scale graduation ticks along all 4 margins
  brush.set("rotring", "#857566", 0.28);
  for (let pos = m + 20; pos <= 1200 - m - 20; pos += 20) {
    let tickLen = (pos % 100 === 4) ? 8 : 4.5;
    // Top & bottom ticks
    brush.line(pos, m, pos, m + tickLen);
    brush.line(pos, 1200 - m, pos, 1200 - m - tickLen);
    // Left & right ticks
    brush.line(m, pos, m + tickLen, pos);
    brush.line(1200 - m, pos, 1200 - m - tickLen, pos);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(2);
  angleMode(DEGREES);
  randomSeed(7319);
  noiseSeed(7319);
}

function smin(a, b, k) {
  let h = Math.max(0, Math.min(1, 0.5 + 0.5 * (b - a) / k));
  return b * (1 - h) + a * h - k * h * (1 - h);
}

function drawPoly(pts, curvature = 0.45) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm storm-lit rag paper ground (allows watercolor bellies to glow from within)
  background("#e8d9c8");

  // Subtle atmospheric storm-light gradient across the paper ground
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Warm amber storm leak from the left
  brush.fill("#f5e2c8", 75);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.45, 0.2);
  brush.circle(180, 480, 680, 0.2);

  // Deeper bruised tone toward the right side of the ceiling
  brush.fill("#c9b6ad", 65);
  brush.fillBleed(0.45, "out");
  brush.circle(1050, 680, 720, 0.2);
  brush.noFill();

  // Late-storm warm color families: bruised mauve, copper, sickly olive, dusky rose, warm umber-rose
  const PALETTES = [
    {
      name: "copper",
      rim: "#f5b06b",
      glow: "#e07e3c",
      mid: "#b54e26",
      deep: "#732917",
      dark: "#3b140d",
      shadow: "#24161a",
      spec: "#fff3e0"
    },
    {
      name: "mauve",
      rim: "#d9a6a4",
      glow: "#a8748c",
      mid: "#784b68",
      deep: "#4a2a44",
      dark: "#291528",
      shadow: "#1f1726",
      spec: "#fae9e8"
    },
    {
      name: "olive",
      rim: "#ded078",
      glow: "#b0a44d",
      mid: "#807934",
      deep: "#4f4b1d",
      dark: "#2b290f",
      shadow: "#1e2017",
      spec: "#f9f4dc"
    },
    {
      name: "rose",
      rim: "#f0b2a1",
      glow: "#cf7474",
      mid: "#9e4952",
      deep: "#632531",
      dark: "#361119",
      shadow: "#26161e",
      spec: "#ffefe8"
    },
    {
      name: "umberRose",
      rim: "#ebb88d",
      glow: "#c48464",
      mid: "#915647",
      deep: "#59302b",
      dark: "#301816",
      shadow: "#23181c",
      spec: "#fceede"
    }
  ];

  // Primary late-storm light direction (leaking strongly from left / upper-left)
  const lightAng = -0.38; // radians (~ -22 deg)
  const lx = -Math.cos(lightAng); // -0.928 (light sits to the left)
  const ly = -Math.sin(lightAng); // +0.371 (slightly upper-left)

  // ---------------------------------------------------------------------------
  // 1. GENERATE CROWDED BALLOON PACKING (Soft-body ceiling compression)
  // ---------------------------------------------------------------------------
  let balloons = [];
  let rowSpacing = 232;
  let colSpacing = 258;
  let idCounter = 0;

  for (let r = -1; r <= 5; r++) {
    for (let c = -1; c <= 5; c++) {
      let xOff = (r % 2 !== 0) ? colSpacing * 0.5 : 0;
      let bx = c * colSpacing + xOff + random(-34, 34) + 60;
      let by = r * rowSpacing + random(-34, 34) + 50;

      if (bx < -140 || bx > 1340 || by < -140 || by > 1340) continue;

      let rad = random(168, 228);
      // Slight variation in hanging depth (z: higher value = hangs slightly lower toward viewer)
      let z = random(-0.4, 0.6);
      let palIdx = (r * 3 + c * 2 + Math.floor(random(5))) % PALETTES.length;
      if (palIdx < 0) palIdx += PALETTES.length;

      balloons.push({
        id: idCounter++,
        x: bx,
        y: by,
        R: rad,
        z: z,
        palIdx: palIdx,
        pal: PALETTES[palIdx],
        seed: random(1000),
        knotOffMag: random(10, 32),
        knotOffAng: random(Math.PI * 2),
        nozzleAng: random(Math.PI * 2),
        radii: []
      });
    }
  }

  // Relax centers so balloons pack tightly with realistic mutual compression
  for (let iter = 0; iter < 65; iter++) {
    for (let i = 0; i < balloons.length; i++) {
      for (let j = i + 1; j < balloons.length; j++) {
        let bi = balloons[i];
        let bj = balloons[j];
        let dx = bj.x - bi.x;
        let dy = bj.y - bi.y;
        let d = Math.hypot(dx, dy) || 1;
        let target = (bi.R + bj.R) * 0.81;

        if (d < target) {
          let push = (target - d) * 0.28;
          let nx = dx / d;
          let ny = dy / d;
          bi.x -= nx * push;
          bi.y -= ny * push;
          bj.x += nx * push;
          bj.y += ny * push;
        } else if (d < target * 1.18) {
          // Mild cohesion so no wide ceiling gaps open up
          let pull = (d - target) * 0.03;
          let nx = dx / d;
          let ny = dy / d;
          bi.x += nx * pull;
          bi.y += ny * pull;
          bj.x -= nx * pull;
          bj.y -= ny * pull;
        }
      }
    }
  }

  // Precompute deformed lobe radii for each balloon (72 angular bins)
  const N_BINS = 72;
  for (let i = 0; i < balloons.length; i++) {
    let bi = balloons[i];
    bi.radii = new Array(N_BINS);

    for (let k = 0; k < N_BINS; k++) {
      let th = (k / N_BINS) * Math.PI * 2;
      // Subtle organic latex bulge
      let r = bi.R * (
        1.0 +
        0.022 * Math.sin(3 * th + bi.seed) +
        0.015 * Math.cos(2 * th - bi.seed * 1.7)
      );

      // Compress against neighboring balloons using smooth-min power boundaries
      for (let j = 0; j < balloons.length; j++) {
        if (i === j) continue;
        let bj = balloons[j];
        let dx = bj.x - bi.x;
        let dy = bj.y - bi.y;
        let D = Math.hypot(dx, dy);
        if (D > (bi.R + bj.R) * 1.35) continue;

        let angIJ = Math.atan2(dy, dx);
        let ca = Math.cos(th - angIJ);
        if (ca > 0.08) {
          let wDist = (D * D + bi.R * bi.R - bj.R * bj.R) / (2 * D);
          wDist = Math.max(0.34 * D, Math.min(0.66 * D, wDist));
          // Lower-hanging balloons slightly overlap higher neighbors
          wDist += (bi.z - bj.z) * 11.0;
          let seamGap = 2.8;
          let bound = (wDist - seamGap) / Math.pow(ca, 0.74);
          r = smin(r, bound, 28.0);
        }
      }
      bi.radii[k] = Math.max(45, r);
    }

    // Smooth angular array slightly
    let smoothed = new Array(N_BINS);
    for (let k = 0; k < N_BINS; k++) {
      let prev = bi.radii[(k - 1 + N_BINS) % N_BINS];
      let curr = bi.radii[k];
      let next = bi.radii[(k + 1) % N_BINS];
      smoothed[k] = prev * 0.22 + curr * 0.56 + next * 0.22;
    }
    bi.radii = smoothed;

    // Helper method to sample radius at any angle
    bi.getRadiusAt = function (ang) {
      let norm = ang % (Math.PI * 2);
      if (norm < 0) norm += Math.PI * 2;
      let fIdx = (norm / (Math.PI * 2)) * N_BINS;
      let i0 = Math.floor(fIdx) % N_BINS;
      let i1 = (i0 + 1) % N_BINS;
      let frac = fIdx - Math.floor(fIdx);
      return this.radii[i0] * (1 - frac) + this.radii[i1] * frac;
    };

    // Compute light intensity factor (stronger on left side of canvas)
    let screenLight = map(bi.x, -50, 1250, 1.08, 0.62, true);
    bi.lightStrength = screenLight;
  }

  // Helper to build a polygon for balloon b with radial scale and offset
  function getBalloonPoly(b, nPts, scaleFn, offsetX = 0, offsetY = 0) {
    let pts = [];
    for (let k = 0; k < nPts; k++) {
      let th = (k / nPts) * Math.PI * 2;
      let baseR = b.getRadiusAt(th);
      let r = scaleFn(th, baseR);
      pts.push([
        b.x + offsetX + Math.cos(th) * r,
        b.y + offsetY + Math.sin(th) * r
      ]);
    }
    return pts;
  }

  // ---------------------------------------------------------------------------
  // 2. COMPUTE INTERSTITIAL CEILING CREVICES (Triple junctions & contact seams)
  // ---------------------------------------------------------------------------
  let junctions = [];
  let seams = [];

  // Find pairwise contact seams
  for (let i = 0; i < balloons.length; i++) {
    for (let j = i + 1; j < balloons.length; j++) {
      let bi = balloons[i];
      let bj = balloons[j];
      let dx = bj.x - bi.x;
      let dy = bj.y - bi.y;
      let D = Math.hypot(dx, dy);
      if (D > (bi.R + bj.R) * 1.08) continue;

      let wDist = (D * D + bi.R * bi.R - bj.R * bj.R) / (2 * D);
      wDist = Math.max(0.35 * D, Math.min(0.65 * D, wDist));
      let mx = bi.x + (dx / D) * wDist;
      let my = bi.y + (dy / D) * wDist;

      if (mx < -120 || mx > 1320 || my < -120 || my > 1320) continue;

      // Verify no third balloon obliterates the seam midpoint
      let occluded = false;
      for (let m = 0; m < balloons.length; m++) {
        if (m === i || m === j) continue;
        let bm = balloons[m];
        let dm = Math.hypot(mx - bm.x, my - bm.y);
        let angM = Math.atan2(my - bm.y, mx - bm.x);
        if (dm < bm.getRadiusAt(angM) - 10) {
          occluded = true;
          break;
        }
      }
      if (!occluded) {
        let tang = Math.atan2(dy, dx) + Math.PI * 0.5;
        let angIJ = Math.atan2(dy, dx);
        let angJI = angIJ + Math.PI;
        let rI = bi.getRadiusAt(angIJ);
        let rJ = bj.getRadiusAt(angJI);
        let gapHalf = Math.max(5, (D - rI - rJ) * 0.5 + 9);
        seams.push({
          mx: mx,
          my: my,
          tang: tang,
          norm: angIJ,
          len: Math.min(bi.R, bj.R) * 0.58,
          thick: gapHalf,
          bi: bi,
          bj: bj
        });
      }
    }
  }

  // Find triple junctions where 3 balloons meet
  for (let i = 0; i < balloons.length; i++) {
    for (let j = i + 1; j < balloons.length; j++) {
      let bi = balloons[i];
      let bj = balloons[j];
      if (Math.hypot(bj.x - bi.x, bj.y - bi.y) > (bi.R + bj.R) * 1.25) continue;

      for (let k = j + 1; k < balloons.length; k++) {
        let bk = balloons[k];
        if (Math.hypot(bk.x - bi.x, bk.y - bi.y) > (bi.R + bk.R) * 1.25) continue;
        if (Math.hypot(bk.x - bj.x, bk.y - bj.y) > (bj.R + bk.R) * 1.25) continue;

        // Solve power center of (bi, bj, bk)
        let A1 = 2 * (bj.x - bi.x);
        let B1 = 2 * (bj.y - bi.y);
        let C1 = (bj.x * bj.x + bj.y * bj.y - bj.R * bj.R) - (bi.x * bi.x + bi.y * bi.y - bi.R * bi.R);

        let A2 = 2 * (bk.x - bi.x);
        let B2 = 2 * (bk.y - bi.y);
        let C2 = (bk.x * bk.x + bk.y * bk.y - bk.R * bk.R) - (bi.x * bi.x + bi.y * bi.y - bi.R * bi.R);

        let det = A1 * B2 - A2 * B1;
        if (Math.abs(det) < 1e-4) continue;

        let vx = (C1 * B2 - C2 * B1) / det;
        let vy = (A1 * C2 - A2 * C1) / det;

        if (vx < -100 || vx > 1300 || vy < -100 || vy > 1300) continue;

        // Check that no 4th balloon covers this junction
        let pDist = (vx - bi.x) ** 2 + (vy - bi.y) ** 2 - bi.R * bi.R;
        let valid = true;
        for (let m = 0; m < balloons.length; m++) {
          if (m === i || m === j || m === k) continue;
          let bm = balloons[m];
          let pm = (vx - bm.x) ** 2 + (vy - bm.y) ** 2 - bm.R * bm.R;
          if (pm < pDist - 2200) {
            valid = false;
            break;
          }
        }

        if (valid) {
          // Raycast 18 directions from (vx, vy) to trace concave star crevice
          let outerPts = [];
          let innerPts = [];
          let triplet = [bi, bj, bk];
          let nRays = 18;
          for (let r = 0; r < nRays; r++) {
            let phi = (r / nRays) * Math.PI * 2;
            let cPhi = Math.cos(phi);
            let sPhi = Math.sin(phi);
            let hitD = 78;

            for (let step = 2; step <= 82; step += 3.5) {
              let px = vx + cPhi * step;
              let py = vy + sPhi * step;
              let insideAny = false;
              for (let t = 0; t < 3; t++) {
                let bt = triplet[t];
                let dCenter = Math.hypot(px - bt.x, py - bt.y);
                let angC = Math.atan2(py - bt.y, px - bt.x);
                if (dCenter < bt.getRadiusAt(angC) - 2) {
                  insideAny = true;
                  break;
                }
              }
              if (insideAny) {
                hitD = step;
                break;
              }
            }
            let dOuter = Math.min(82, hitD + 14);
            let dInner = Math.min(62, Math.max(6, hitD + 3));
            outerPts.push([vx + cPhi * dOuter, vy + sPhi * dOuter]);
            innerPts.push([vx + cPhi * dInner, vy + sPhi * dInner]);
          }
          junctions.push({ vx, vy, outerPts, innerPts });
        }
      }
    }
  }

  // ---------------------------------------------------------------------------
  // 3. STAGE 1: SOFT WATERCOLOR UNDERSIDES (Batched by palette for speed & glow)
  // ---------------------------------------------------------------------------
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  for (let pIdx = 0; pIdx < PALETTES.length; pIdx++) {
    let pal = PALETTES[pIdx];
    let group = balloons.filter(b => b.palIdx === pIdx);

    // Pass A: Full pouched belly base wash
    brush.fill(pal.mid, 98);
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.68, 0.42);
    for (let b of group) {
      let pts = getBalloonPoly(b, 18, (th, r) => r * 0.985);
      drawPoly(pts, 0.48);
    }

    // Pass B: Deep shadow bowl on side turned away from storm light
    brush.fill(pal.deep, 118);
    brush.fillBleed(0.26, "in");
    brush.fillTexture(0.72, 0.48);
    for (let b of group) {
      let shX = -lx * b.R * 0.14;
      let shY = -ly * b.R * 0.14;
      let pts = getBalloonPoly(b, 18, (th, r) => {
        let dotL = Math.cos(th) * lx + Math.sin(th) * ly;
        // Shrink on the lit side so the shadow wash crescents around the right/bottom
        let factor = map(dotL, -1, 1, 0.96, 0.56);
        return r * factor;
      }, shX, shY);
      drawPoly(pts, 0.48);
    }

    // Pass C: Late-storm warm leaking light glow on the lit belly swell
    brush.fill(pal.glow, 96);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.58, 0.32);
    for (let b of group) {
      let litX = lx * b.R * 0.22;
      let litY = ly * b.R * 0.22;
      let pts = getBalloonPoly(b, 16, (th, r) => {
        let dotL = Math.cos(th) * lx + Math.sin(th) * ly;
        let factor = map(dotL, -1, 1, 0.34, 0.68) * b.lightStrength;
        return r * factor;
      }, litX, litY);
      drawPoly(pts, 0.5);
    }

    // Pass D: Luminous amber/rose rim backscatter & thick unstretched knot spot
    brush.fill(pal.rim, 88);
    brush.fillBleed(0.24, "out");
    brush.fillTexture(0.5, 0.28);
    for (let b of group) {
      let litX = lx * b.R * 0.34;
      let litY = ly * b.R * 0.34;
      let pts = getBalloonPoly(b, 14, (th, r) => {
        let dotL = Math.cos(th) * lx + Math.sin(th) * ly;
        let factor = map(dotL, -1, 1, 0.18, 0.44) * b.lightStrength;
        return r * factor;
      }, litX, litY);
      drawPoly(pts, 0.5);
    }
  }
  brush.noFill();

  // ---------------------------------------------------------------------------
  // 4. STAGE 2: CHARCOAL MASS IN DEEP SLATE SHADOWS BETWEEN THE LOBES
  // ---------------------------------------------------------------------------
  brush.noStroke();
  brush.noFill();
  brush.noHatch();

  // 4A. Shadow-side charcoal mass crescents hugging each balloon's dark rim
  for (let pIdx = 0; pIdx < PALETTES.length; pIdx++) {
    let pal = PALETTES[pIdx];
    let group = balloons.filter(b => b.palIdx === pIdx);
    brush.mass("charcoal", pal.shadow, {
      precision: 0.35,
      strength: 0.55,
      gradient: 0.72,
      outline: false
    });

    for (let b of group) {
      // Build a crescent along the shadow rim (facing away from light)
      let crescentPts = [];
      let nSteps = 10;
      let centerAng = lightAng + Math.PI; // opposite of light
      let span = Math.PI * 0.78;

      // Outer edge along balloon rim
      for (let s = 0; s <= nSteps; s++) {
        let th = centerAng - span + (s / nSteps) * (span * 2);
        let r = b.getRadiusAt(th) * 1.01;
        crescentPts.push([b.x + Math.cos(th) * r, b.y + Math.sin(th) * r]);
      }
      // Inner edge tapering smoothly
      for (let s = nSteps; s >= 0; s--) {
        let th = centerAng - span + (s / nSteps) * (span * 2);
        let u = (s / nSteps) * 2 - 1; // -1 to 1
        let depth = (1 - u * u) * 0.24; // deepest in middle of shadow crescent
        let r = b.getRadiusAt(th) * (1.0 - depth);
        crescentPts.push([b.x + Math.cos(th) * r, b.y + Math.sin(th) * r]);
      }
      drawPoly(crescentPts, 0.35);
    }
  }
  brush.noMass();

  // 4B. Deep slate foundational wash inside triple junctions & seams so zero bright paper leaks in voids
  brush.wash("#191521", 215);
  for (let junc of junctions) {
    drawPoly(junc.innerPts, 0.35);
  }
  for (let sm of seams) {
    let ct = Math.cos(sm.tang);
    let st = Math.sin(sm.tang);
    let cn = Math.cos(sm.norm);
    let sn = Math.sin(sm.norm);
    let L = sm.len * 0.72;
    let W = sm.thick * 0.65;
    let spindle = [
      [sm.mx - ct * L, sm.my - st * L],
      [sm.mx - ct * L * 0.35 + cn * W, sm.my - st * L * 0.35 + sn * W],
      [sm.mx + cn * W * 1.15, sm.my + sn * W * 1.15],
      [sm.mx + ct * L * 0.35 + cn * W, sm.my + st * L * 0.35 + sn * W],
      [sm.mx + ct * L, sm.my + st * L],
      [sm.mx + ct * L * 0.35 - cn * W, sm.my + st * L * 0.35 - sn * W],
      [sm.mx - cn * W * 1.15, sm.my - sn * W * 1.15],
      [sm.mx - ct * L * 0.35 - cn * W, sm.my - st * L * 0.35 - sn * W]
    ];
    drawPoly(spindle, 0.4);
  }
  brush.noWash();

  // 4C. Charcoal mass along pairwise compression seams
  brush.mass("charcoal", "#241e2b", {
    precision: 0.32,
    strength: 0.78,
    gradient: 0.45,
    outline: true
  });
  for (let sm of seams) {
    let ct = Math.cos(sm.tang);
    let st = Math.sin(sm.tang);
    let cn = Math.cos(sm.norm);
    let sn = Math.sin(sm.norm);
    let L = sm.len * 0.85;
    let W = sm.thick * 0.95;
    let spindle = [
      [sm.mx - ct * L, sm.my - st * L],
      [sm.mx - ct * L * 0.4 + cn * W, sm.my - st * L * 0.4 + sn * W],
      [sm.mx + cn * W * 1.25, sm.my + sn * W * 1.25],
      [sm.mx + ct * L * 0.4 + cn * W, sm.my + st * L * 0.4 + sn * W],
      [sm.mx + ct * L, sm.my + st * L],
      [sm.mx + ct * L * 0.4 - cn * W, sm.my + st * L * 0.4 - sn * W],
      [sm.mx - cn * W * 1.25, sm.my - sn * W * 1.25],
      [sm.mx - ct * L * 0.4 - cn * W, sm.my - st * L * 0.4 - sn * W]
    ];
    drawPoly(spindle, 0.4);
  }

  // 4D. Outer slate charcoal mass in triple-junction crevices (feathers onto lobe bellies)
  brush.mass("charcoal", "#282230", {
    precision: 0.28,
    strength: 0.82,
    gradient: 0.35,
    outline: true
  });
  for (let junc of junctions) {
    drawPoly(junc.outerPts, 0.38);
  }

  // 4E. Deepest pitch-slate charcoal core inside the triple-junction pockets
  brush.mass("charcoal", "#14111a", {
    precision: 0.48,
    strength: 0.95,
    gradient: 0.2,
    outline: true
  });
  for (let junc of junctions) {
    drawPoly(junc.innerPts, 0.35);
  }
  brush.noMass();

  // ---------------------------------------------------------------------------
  // 5. STAGE 3: LATEX FORM MODELING, SPECULAR WINDOWS & CREVICE CHARCOAL WORK
  // ---------------------------------------------------------------------------

  // Sort balloons from highest (tucked up) to lowest (hanging closer) for natural overlap
  let sortedBalloons = [...balloons].sort((a, b) => a.z - b.z);

  for (let b of sortedBalloons) {
    let pal = b.pal;

    // 5A. Curved cross-contour form shading around the pouched rim
    brush.set("charcoal", pal.shadow, 0.72);
    let nArcs = 26;
    for (let a = 0; a < nArcs; a++) {
      let th0 = (a / nArcs) * Math.PI * 2 + random(-0.05, 0.05);
      let dotL = Math.cos(th0) * lx + Math.sin(th0) * ly;
      // More charcoal form strokes on the shadow side and pinched rim
      if (dotL > 0.45 && random() < 0.55) continue;

      let span = random(0.18, 0.36);
      let rFrac = random(0.86, 0.99);
      let arcPts = [];
      for (let s = 0; s <= 4; s++) {
        let th = th0 + ((s / 4) - 0.5) * span;
        let r = b.getRadiusAt(th) * rFrac;
        let p = s === 2 ? 1.15 : 0.45;
        arcPts.push([b.x + Math.cos(th) * r, b.y + Math.sin(th) * r, p]);
      }
      brush.spline(arcPts, 0.5);
    }

    // Fine colored-pencil cross-contour modeling transitioning from shadow into mid-belly
    brush.set("cpencil", pal.deep, 0.55);
    for (let a = 0; a < 22; a++) {
      let th0 = (a / 22) * Math.PI * 2 + random(-0.08, 0.08);
      let rOuter = b.getRadiusAt(th0) * 0.96;
      let rInner = b.getRadiusAt(th0) * random(0.68, 0.84);
      let curveBend = random(-0.12, 0.12);
      let pts = [];
      for (let s = 0; s <= 3; s++) {
        let t = s / 3;
        let r = lerp(rOuter, rInner, t);
        let th = th0 + Math.sin(t * Math.PI) * curveBend;
        pts.push([b.x + Math.cos(th) * r, b.y + Math.sin(th) * r, (1 - t) * 0.9 + 0.2]);
      }
      brush.spline(pts, 0.45);
    }

    // 5B. Internal transmitted bounce light along the shadow-side rim
    brush.set("cpencil", pal.rim, 0.5);
    for (let a = 0; a < 9; a++) {
      let th0 = lightAng + Math.PI + random(-0.85, 0.85);
      let span = random(0.14, 0.26);
      let rFrac = random(0.84, 0.91);
      let pts = [];
      for (let s = 0; s <= 3; s++) {
        let th = th0 + ((s / 3) - 0.5) * span;
        let r = b.getRadiusAt(th) * rFrac;
        pts.push([b.x + Math.cos(th) * r, b.y + Math.sin(th) * r, s === 1 || s === 2 ? 0.85 : 0.3]);
      }
      brush.spline(pts, 0.5);
    }

    // 5C. Warped Storm-Window Specular Reflection on the lit swell of the balloon
    let specAng = lightAng + Math.PI + random(-0.14, 0.14); // direction from center toward light
    let specR = b.getRadiusAt(specAng) * 0.52;
    let sx = b.x + Math.cos(specAng) * specR;
    let sy = b.y + Math.sin(specAng) * specR;
    let tangAng = specAng + Math.PI * 0.5;

    // Build 4 warped window panes following the spherical curvature of the balloon
    let paneW = b.R * 0.11 * b.lightStrength;
    let paneH = b.R * 0.065 * b.lightStrength;
    if (paneW > 9) {
      brush.noStroke();
      let washAlpha = Math.floor(105 * b.lightStrength);
      brush.wash(pal.spec, washAlpha);

      for (let row = -1; row <= 0; row++) {
        for (let col = -1; col <= 0; col++) {
          let u0 = col * 1.15 + 0.1;
          let u1 = (col + 1) * 1.15 - 0.1;
          let v0 = row * 1.18 + 0.1;
          let v1 = (row + 1) * 1.18 - 0.1;

          let corners = [
            [u0, v0],
            [u1, v0],
            [u1, v1],
            [u0, v1]
          ].map(([u, v]) => {
            let a = specAng + (u * paneW) / Math.max(60, specR);
            let rad = specR + v * paneH;
            return [b.x + Math.cos(a) * rad, b.y + Math.sin(a) * rad];
          });
          drawPoly(corners, 0.25);
        }
      }
      brush.noWash();

      // Crisp colored-pencil sheen strokes across the warped window panes
      brush.set("cpencil", "#fffaf0", 0.48 * b.lightStrength);
      for (let s = -4; s <= 4; s++) {
        if (Math.abs(s) <= 0.6) continue; // leave window mullion gap
        let a0 = specAng - (paneW * 1.05) / Math.max(60, specR);
        let a1 = specAng + (paneW * 1.05) / Math.max(60, specR);
        let rad = specR + (s / 4) * paneH * 1.05;
        let pts = [];
        for (let k = 0; k <= 3; k++) {
          let a = lerp(a0, a1, k / 3);
          pts.push([b.x + Math.cos(a) * rad, b.y + Math.sin(a) * rad, k === 1 || k === 2 ? 0.95 : 0.35]);
        }
        brush.spline(pts, 0.4);
      }
    }
  }

  // Reinforce deep contact seams between lobes with heavy charcoal strokes
  brush.set("charcoal", "#120e17", 1.15);
  for (let sm of seams) {
    let ct = Math.cos(sm.tang);
    let st = Math.sin(sm.tang);
    let L = sm.len * 0.78;
    let pts = [
      [sm.mx - ct * L, sm.my - st * L, 0.35],
      [sm.mx - ct * L * 0.3, sm.my - st * L * 0.3, 1.25],
      [sm.mx + ct * L * 0.3, sm.my + st * L * 0.3, 1.25],
      [sm.mx + ct * L, sm.my + st * L, 0.35]
    ];
    brush.spline(pts, 0.45);
  }

  // ---------------------------------------------------------------------------
  // 6. STAGE 4: HYPERREAL LATEX KNOTS & TINY KNOT PUCKERS
  // ---------------------------------------------------------------------------
  for (let b of sortedBalloons) {
    let pal = b.pal;
    let kx = b.x + Math.cos(b.knotOffAng) * b.knotOffMag;
    let ky = b.y + Math.sin(b.knotOffAng) * b.knotOffMag;
    b.kx = kx;
    b.ky = ky;

    // 6A. Thicker, darker unstretched latex halo around the navel
    brush.noStroke();
    brush.wash(pal.deep, 145);
    brush.circle(kx, ky, 22, 0.35);
    brush.wash(pal.dark, 155);
    brush.circle(kx, ky, 12, 0.3);
    brush.noWash();

    // 6B. Radial tension puckers (micro-pleats pulled taut around the tied knot)
    let nPuckers = 26;
    for (let p = 0; p < nPuckers; p++) {
      let ang = (p / nPuckers) * Math.PI * 2 + random(-0.06, 0.06);
      let innerR = random(5.5, 9.5);
      let outerR = random(19, 39);
      // Slight torsional twist from tying the neck
      let twist = random(0.08, 0.22);

      let pPts = [];
      let hPts = [];
      for (let s = 0; s <= 3; s++) {
        let t = s / 3;
        let r = lerp(innerR, outerR, t);
        let a = ang + t * twist;
        let pr = s === 1 ? 1.1 : (1 - t) * 0.8 + 0.15;
        pPts.push([kx + Math.cos(a) * r, ky + Math.sin(a) * r, pr]);
        // Adjacent highlight ridge on the storm-lit side of the pleat
        let aH = a + 0.045;
        hPts.push([kx + Math.cos(aH) * r, ky + Math.sin(aH) * r, pr * 0.8]);
      }

      brush.set("2H", pal.dark, 0.34);
      brush.spline(pPts, 0.45);

      if (p % 2 === 0) {
        brush.set("cpencil", pal.rim, 0.28);
        brush.spline(hPts, 0.45);
      }
    }

    // 6C. The tied knot twist (overhand rubber bulge) & flared nozzle lip
    let nAng = b.nozzleAng;
    let cn = Math.cos(nAng);
    let sn = Math.sin(nAng);
    let pnX = -sn;
    let pnY = cn;

    // Deep crevice shadow directly under the knot twist and nozzle ear
    brush.noStroke();
    brush.wash("#120d14", 210);
    let knotShadowPts = [];
    for (let s = 0; s < 10; s++) {
      let a = (s / 10) * Math.PI * 2;
      let rx = 11 * Math.cos(a);
      let ry = 7.5 * Math.sin(a);
      knotShadowPts.push([
        kx + 2.5 + rx * cn - ry * sn,
        ky + 2.5 + rx * sn + ry * cn
      ]);
    }
    drawPoly(knotShadowPts, 0.45);

    // Twisted knot body
    brush.wash(pal.dark, 225);
    let knotBodyPts = [];
    for (let s = 0; s < 10; s++) {
      let a = (s / 10) * Math.PI * 2;
      let rx = 9.5 * Math.cos(a);
      let ry = 6.2 * Math.sin(a);
      knotBodyPts.push([
        kx + rx * cn - ry * sn,
        ky + rx * sn + ry * cn
      ]);
    }
    drawPoly(knotBodyPts, 0.45);

    // Flared nozzle neck & rolled rubber lip jutting out to one side
    let lipCx = kx + cn * 13.5;
    let lipCy = ky + sn * 13.5;
    brush.wash(pal.deep, 220);
    let lipOuterPts = [];
    for (let s = 0; s < 10; s++) {
      let a = (s / 10) * Math.PI * 2;
      let rx = 5.2 * Math.cos(a);
      let ry = 8.4 * Math.sin(a);
      lipOuterPts.push([
        lipCx + rx * cn - ry * sn,
        lipCy + rx * sn + ry * cn
      ]);
    }
    drawPoly(lipOuterPts, 0.48);

    // Dark hollow inside the nozzle mouth
    brush.wash("#120c12", 235);
    brush.circle(lipCx + cn * 1.2, lipCy + sn * 1.2, 3.6, 0.25);
    brush.noWash();

    // Crisp pencil & ink definition on the knot folds and rolled lip ring
    brush.set("rotring", "#140d12", 0.36);
    brush.spline([
      [kx - pnX * 7, ky - pnY * 7, 0.4],
      [kx + cn * 3, ky + sn * 3, 1.1],
      [kx + pnX * 7, ky + pnY * 7, 0.4]
    ], 0.45);

    // Translucent rim highlight on the rolled rubber lip and knot ridge
    brush.set("cpencil", pal.rim, 0.42);
    let lipHiPts = [];
    for (let s = -2; s <= 2; s++) {
      let a = (s / 2) * 1.1;
      let rx = 4.8 * Math.cos(a);
      let ry = 7.8 * Math.sin(a);
      lipHiPts.push([
        lipCx + rx * cn - ry * sn,
        lipCy + rx * sn + ry * cn,
        s === 0 ? 1.0 : 0.4
      ]);
    }
    brush.spline(lipHiPts, 0.45);
  }

  // ---------------------------------------------------------------------------
  // 7. STAGE 5: STATIC-CLUNG HAIRS & MICRO-LINT SPECKS
  // ---------------------------------------------------------------------------
  for (let b of sortedBalloons) {
    let pal = b.pal;
    let nHairs = Math.floor(random(3, 5.5));

    for (let h = 0; h < nHairs; h++) {
      let startAng = random(Math.PI * 2);
      let startR = b.getRadiusAt(startAng) * random(0.22, 0.86);
      let hx = b.x + Math.cos(startAng) * startR;
      let hy = b.y + Math.sin(startAng) * startR;

      let hairLen = random(48, 128);
      let dir = random(Math.PI * 2);
      let curlRate = random(-0.028, 0.028);
      let sCurve = random(-0.018, 0.018);

      let nSegs = 6;
      let stepL = hairLen / nSegs;
      let hairPts = [];
      let shadPts = [];
      let glintPts = [];

      let cx = hx;
      let cy = hy;
      for (let s = 0; s <= nSegs; s++) {
        let t = s / nSegs;
        let press = Math.sin(t * Math.PI) * 0.75 + 0.2;
        // Shadow is offset away from storm light (to the right/down)
        let shOff = 1.8 + 1.4 * Math.sin(t * Math.PI);
        hairPts.push([cx, cy, press]);
        shadPts.push([cx - lx * shOff, cy - ly * shOff, press * 0.75]);

        if (s >= 2 && s <= 4) {
          glintPts.push([cx + lx * 0.8, cy + ly * 0.8, press * 0.7]);
        }

        dir += curlRate * stepL + Math.sin(t * Math.PI * 2) * sCurve * stepL;
        cx += Math.cos(dir) * stepL;
        cy += Math.sin(dir) * stepL;
      }

      // Soft contact shadow on the latex skin
      brush.set("HB", pal.shadow, 0.26);
      brush.spline(shadPts, 0.5);

      // Razor-sharp static hair filament
      let hairCol = random() < 0.65 ? "#1c1417" : "#382119";
      brush.set("rotring", hairCol, random(0.2, 0.28));
      brush.spline(hairPts, 0.5);

      // Subtle warm glint where the hair catches the storm light
      if (b.lightStrength > 0.78 && glintPts.length >= 3) {
        brush.set("cpencil", pal.rim, 0.2);
        brush.spline(glintPts, 0.5);
      }
    }

    // Tiny static dust specks & short lint fibers in the raking light zone
    for (let d = 0; d < 8; d++) {
      let dAng = lightAng + Math.PI + random(-1.1, 1.1);
      let dR = b.getRadiusAt(dAng) * random(0.28, 0.88);
      let dx = b.x + Math.cos(dAng) * dR;
      let dy = b.y + Math.sin(dAng) * dR;
      let fAng = random(Math.PI * 2);
      let fLen = random(2.5, 6.5);

      brush.set("2H", pal.spec, 0.24);
      brush.line(dx, dy, dx + Math.cos(fAng) * fLen, dy + Math.sin(fAng) * fLen);
    }
  }

  // ---------------------------------------------------------------------------
  // 8. STAGE 6: TRAILING CURLED RIBBONS IN SHARP PENCIL
  // ---------------------------------------------------------------------------
  for (let b of sortedBalloons) {
    let kx = b.kx;
    let ky = b.ky;
    if (kx < -40 || kx > 1240 || ky < -40 || ky > 1240) continue;

    // Each ribbon hangs down from the knot toward the viewer, curling in 3D helices
    let mainDir = Math.PI * 0.5 + random(-0.95, 0.95); // generally drifting downward/sideways
    let totalSteps = 38;
    let stepDist = random(4.8, 7.6);
    let nCurls = random(2.6, 4.8);
    let twistFreq = nCurls * Math.PI * 2;
    let phase0 = random(Math.PI * 2);
    let chirality = random() < 0.5 ? 1 : -1;

    let spine = [];
    let sx = kx;
    let sy = ky;
    let curAng = mainDir;

    for (let s = 0; s <= totalSteps; s++) {
      let t = s / totalSteps;
      // Perspective foreshortening: curls & width grow as ribbon drops closer to viewer
      let persp = 1.0 + 1.45 * Math.pow(t, 1.2);
      let curlPhase = phase0 + chirality * t * twistFreq;

      // Helical trajectory offset
      let loopAmp = (5.5 + 15.0 * t) * persp * 0.42;
      let px = sx + Math.cos(curlPhase) * loopAmp;
      let py = sy + Math.sin(curlPhase) * loopAmp * 0.72;

      // Apparent ribbon width modulated by 3D twist turnover
      let baseW = (2.6 + 4.8 * t);
      let twistVal = Math.sin(curlPhase * 0.85 + 0.6);
      let wProj = baseW * twistVal;

      spine.push({
        x: px,
        y: py,
        t: t,
        wProj: wProj,
        twistVal: twistVal,
        curlPhase: curlPhase
      });

      curAng += Math.sin(t * Math.PI * 2.5 + b.seed) * 0.06;
      sx += Math.cos(curAng) * stepDist;
      sy += Math.sin(curAng) * stepDist;
    }

    // Compute ribbon normals and the two physical edges (EdgeA & EdgeB)
    let edgeA = [];
    let edgeB = [];
    let shadSpine = [];

    for (let s = 0; s < spine.length; s++) {
      let pCurr = spine[s];
      let pNext = spine[Math.min(spine.length - 1, s + 1)];
      let pPrev = spine[Math.max(0, s - 1)];
      let tx = pNext.x - pPrev.x;
      let ty = pNext.y - pPrev.y;
      let tLen = Math.hypot(tx, ty) || 1;
      let nx = -ty / tLen;
      let ny = tx / tLen;

      pCurr.nx = nx;
      pCurr.ny = ny;

      let hw = pCurr.wProj * 0.5;
      let ax = pCurr.x + nx * hw;
      let ay = pCurr.y + ny * hw;
      let bx = pCurr.x - nx * hw;
      let by = pCurr.y - ny * hw;

      let edgePress = 0.45 + 0.65 * pCurr.t;
      edgeA.push([ax, ay, edgePress]);
      edgeB.push([bx, by, edgePress]);

      // Cast shadow on the balloon belly near the upper part of the ribbon (t < 0.55)
      if (pCurr.t < 0.58) {
        let shDist = 4.0 + pCurr.t * 26.0;
        shadSpine.push([
          pCurr.x - lx * shDist,
          pCurr.y - ly * shDist,
          (1 - pCurr.t / 0.58) * 0.85
        ]);
      }
    }

    // 8A. Soft shadow cast by the upper ribbon onto the balloon belly
    if (shadSpine.length >= 4) {
      brush.set("charcoal", b.pal.shadow, 0.48);
      brush.spline(shadSpine, 0.45);
    }

    // 8B. Sharp pencil tonal shading across the flat ribbon strip between EdgeA and EdgeB
    for (let s = 0; s < spine.length - 1; s++) {
      let p0 = spine[s];
      let p1 = spine[s + 1];
      let a0 = edgeA[s];
      let b0 = edgeB[s];
      let a1 = edgeA[s + 1];
      let b1 = edgeB[s + 1];

      // Normal of ribbon face in 3D determines whether it catches storm light or turns dark
      let faceLight = p0.twistVal * (p0.nx * lx + p0.ny * ly);
      let absTwist = Math.abs(p0.twistVal);

      // Fill ribbon band with crisp cross-strokes / longitudinal graphite strokes
      let nFillLines = 3;
      for (let f = 0; f <= nFillLines; f++) {
        let u = f / nFillLines;
        let x0 = lerp(a0[0], b0[0], u);
        let y0 = lerp(a0[1], b0[1], u);
        let x1 = lerp(a1[0], b1[0], u);
        let y1 = lerp(a1[1], b1[1], u);

        if (absTwist < 0.32) {
          // Dark pinch right at the ribbon twist turnover
          brush.set("2H", "#19151c", 0.36);
        } else if (faceLight > 0.12) {
          // Specular storm-lit ribbon face (warm cream/silver pencil sheen)
          brush.set("cpencil", "#f7ecde", 0.42);
        } else if (faceLight > -0.15) {
          // Midtone warm grey graphite
          brush.set("HB", "#6e6166", 0.34);
        } else {
          // Dark shaded underside of the ribbon curl
          brush.set("HB", "#2b242c", 0.38);
        }
        brush.line(x0, y0, x1, y1);
      }
    }

    // 8C. Crisp, continuous sharp pencil edges along both sides of the curled ribbon
    brush.set("2H", "#17131a", 0.42);
    brush.spline(edgeA, 0.45);

    brush.set("HB", "#241e28", 0.38);
    brush.spline(edgeB, 0.45);

    // Extra sharp highlight edge along the lower curls closest to the viewer
    let lowerHighlight = edgeA.slice(Math.floor(edgeA.length * 0.45)).map(pt => [
      pt[0] + lx * 0.9,
      pt[1] + ly * 0.9,
      pt[2] * 0.85
    ]);
    if (lowerHighlight.length >= 4) {
      brush.set("cpencil", "#fff8ee", 0.34);
      brush.spline(lowerHighlight, 0.45);
    }
  }

  noLoop();
}

// Hyperreal Full-Face Motorcycle Helmet — Candy-Apple Lacquer vs. Cyan Curvature Mesh
// Rendered entirely with p5.brush in WEBGL

const SEED = 4271;

// Helmet parametric grid resolution
const NU = 72; // azimuthal columns around [-PI, PI]
const NV = 46; // longitudinal rows from crown [0] to neck rim [1]

// Camera & projection parameters
const YAW = 27 * (Math.PI / 180);   // 3/4 view angled toward viewer's right
const PITCH = 9 * (Math.PI / 180);  // slight downward aggressive tilt
const ROLL = -2.5 * (Math.PI / 180);
const CAM_DIST = 1650;
const FOCAL = 1420;
const CX = 605;
const CY = 585;

let grid = [];
let seamCol = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Register custom brushes for airbrushing and razor-thin luminous pen work
  brush.add("airbrushSoft", {
    type: "spray",
    weight: 16,
    scatter: 3.8,
    opacity: 16,
    spacing: 0.45,
    pressure: [0.4, 1.2, 0.4],
    rotate: "random"
  });

  brush.add("flakeSpray", {
    type: "spray",
    weight: 6,
    scatter: 2.2,
    opacity: 28,
    spacing: 0.7,
    pressure: [0.6, 1.0, 0.6],
    rotate: "random"
  });

  brush.add("laserCyan", {
    type: "default",
    weight: 0.45,
    scatter: 0.02,
    sharpness: 0.95,
    grain: 2,
    opacity: 225,
    spacing: 0.15,
    pressure: [0.85, 1.0, 0.85],
    noise: 0.08
  });

  brush.add("razorGlint", {
    type: "default",
    weight: 0.65,
    scatter: 0.01,
    sharpness: 0.98,
    grain: 1,
    opacity: 250,
    spacing: 0.12,
    pressure: [0.3, 1.3, 0.3],
    noise: 0.05
  });

  buildHelmetMesh();
}

// ============================================================================
// 1. 3D PARAMETRIC HELMET GEOMETRY & CURVATURE ENGINE
// ============================================================================

function visorBounds(u) {
  let au = Math.abs(u);
  // Top brow edge of visor opening
  let vTop = 0.305 + 0.028 * Math.pow(au / 1.16, 1.8);
  // Bottom cheek/nose edge of visor opening (rises at nose bridge u=0, dips at cheek, rises to pivot)
  let noseGuard = -0.036 * Math.exp(-Math.pow(u / 0.25, 2));
  let templeSweep = -0.082 * Math.pow(Math.max(0, (au - 0.52) / 0.64), 1.7);
  let vBot = 0.618 + noseGuard + templeSweep;
  return { vTop, vBot };
}

function isInsideVisor(u, v) {
  if (Math.abs(u) > 1.15) return false;
  let { vTop, vBot } = visorBounds(u);
  return v >= vTop && v <= vBot;
}

function evalHelmet3D(u, v, surfaceMode = "auto") {
  // u in [-PI, PI], u = 0 is front nose, u > 0 is viewer-right side, u < 0 is viewer-left side
  // v in [0, 1], v = 0 is top crown pole, v = 1 is bottom neck gasket rim
  let au = Math.abs(u);
  let theta = v * 0.85 * Math.PI;
  let sinT = Math.sin(theta);
  let cosT = Math.cos(theta);

  // Radial envelope from crown to neck roll
  let rEnv = sinT
    + 0.25 * Math.pow(Math.max(0, v - 0.42), 1.15)
    - 0.17 * Math.pow(Math.max(0, v - 0.85) / 0.15, 2.0);
  rEnv = Math.max(0.001, rEnv);

  // Vertical Y coordinate (negative is up, positive is down)
  let yBase = -345 * cosT;
  let chinDrop = 82 * Math.pow(v, 1.35) * Math.exp(-Math.pow(u / 1.18, 2));
  let napeLift = -58 * Math.pow(v, 1.25) * Math.pow(Math.sin(u * 0.5), 4);
  let jawCurve = 16 * Math.pow(v, 1.8) * Math.exp(-Math.pow((au - 0.82) / 0.42, 2));
  let y = yBase + chinDrop + napeLift + jawCurve;

  // Jawline aerodynamic character ridge
  let vRidge = 0.81 - 0.085 * Math.min(1.2, au / 1.45);
  let jawRidge = 23 * Math.exp(-Math.pow((v - vRidge) / 0.048, 2))
    * Math.pow(Math.sin(Math.min(Math.PI, au * 0.82)), 1.4);

  // Crown aerodynamic twin ribs
  let crownRib = 9.5 * Math.exp(-Math.pow((v - 0.20) / 0.085, 2))
    * Math.exp(-Math.pow((au - 0.36) / 0.12, 2));

  // Rear aerodynamic wake spoiler (at back |u| > 1.65, v in [0.18, 0.58])
  let uBack = Math.PI - au;
  let spoilerV = Math.exp(-Math.pow((v - 0.37) / 0.14, 2)) * (v > 0.12 && v < 0.62 ? 1 : 0);
  let spoilerU = Math.exp(-Math.pow(uBack / 0.72, 2))
    + 0.48 * Math.exp(-Math.pow((uBack - 0.46) / 0.14, 2));
  let aeroSpoiler = 54 * spoilerV * spoilerU;

  // Chin bar forward prow and lower aero splitter lip
  let chinProw = 48 * Math.exp(-Math.pow((v - 0.77) / 0.14, 2))
    * Math.exp(-Math.pow(u / 0.76, 2));
  let chinSplitter = 17 * Math.exp(-Math.pow((v - 0.915) / 0.036, 2))
    * Math.exp(-Math.pow(u / 0.54, 2));

  // Chin central vent recess
  let chinVentRecess = -9 * Math.exp(-Math.pow((v - 0.735) / 0.042, 2))
    * Math.exp(-Math.pow(u / 0.21, 2));

  // Eye-port / Visor transition
  let { vTop, vBot } = visorBounds(u);
  let inVisorU = au <= 1.15;
  let inVisor = inVisorU && v >= vTop && v <= vBot;

  // Smooth step into eye-port recess for shell vs flush curve for visor
  let visorBulge = 0;
  if (inVisorU) {
    // Rim gasket lip around eye-port
    let dTop = Math.abs(v - vTop);
    let dBot = Math.abs(v - vBot);
    let lipBump = 5.5 * (Math.exp(-Math.pow(dTop / 0.014, 2)) + Math.exp(-Math.pow(dBot / 0.015, 2)));
    if (inVisor) {
      if (surfaceMode === "shellRecess") {
        visorBulge = -18;
      } else {
        // Flush spherical-toric polycarbonate shield with slight step inside gasket
        let vNorm = (v - vTop) / Math.max(0.01, vBot - vTop);
        let shieldArch = 5.0 * Math.sin(vNorm * Math.PI) * Math.cos(u * 0.65);
        visorBulge = -3.5 + shieldArch;
      }
    } else {
      visorBulge = lipBump;
    }
  }

  // Circular mechanical visor pivot boss on left/right temples (|u| ~ 1.13, v ~ 0.45)
  let dPiv = Math.hypot((au - 1.12) * 1.05, (v - 0.448) * 2.4);
  let pivotBoss = 0;
  if (dPiv < 0.22) {
    let rNorm = dPiv / 0.22;
    pivotBoss = 8.5 * Math.cos(rNorm * Math.PI * 0.5)
      + 3.0 * Math.sin(rNorm * Math.PI * 3.0) * (1 - rNorm);
  }

  // Bottom rubber neck gasket collar flare
  let neckGasket = 7.5 * Math.exp(-Math.pow((v - 0.955) / 0.032, 2));

  // Combine radii in X (width) and Z (front-back length)
  let rx = 310 * rEnv + jawRidge + crownRib * 0.6 + visorBulge * 0.65 + pivotBoss + neckGasket;
  let frontFactor = Math.cos(u) >= 0 ? 368 : 386;
  let rz = frontFactor * rEnv + chinProw + chinSplitter + chinVentRecess
    + aeroSpoiler + crownRib + visorBulge + neckGasket * 0.8;

  let x = rx * Math.sin(u);
  let z = rz * Math.cos(u);

  return { x, y, z, inVisor, vTop, vBot, dPiv, jawRidge, aeroSpoiler, crownRib };
}

function project3D(p) {
  // Yaw around Y
  let cy = Math.cos(YAW), sy = Math.sin(YAW);
  let x1 = p.x * cy + p.z * sy;
  let y1 = p.y;
  let z1 = -p.x * sy + p.z * cy;

  // Pitch around X
  let cp = Math.cos(PITCH), sp = Math.sin(PITCH);
  let x2 = x1;
  let y2 = y1 * cp - z1 * sp;
  let z2 = y1 * sp + z1 * cp;

  // Roll around Z
  let cr = Math.cos(ROLL), sr = Math.sin(ROLL);
  let x3 = x2 * cr - y2 * sr;
  let y3 = x2 * sr + y2 * cr;
  let z3 = z2;

  let scale = FOCAL / Math.max(200, CAM_DIST - z3);
  return {
    px: CX + x3 * scale,
    py: CY + y3 * scale,
    wx: x3,
    wy: y3,
    wz: z3,
    scale
  };
}

function computePointData(u, v) {
  let p0 = evalHelmet3D(u, v);
  let proj = project3D(p0);

  // Finite difference surface normal in camera space
  let eps = 0.008;
  let pu = project3D(evalHelmet3D(u + eps, v));
  let pv = project3D(evalHelmet3D(u, Math.min(1, v + eps)));

  let tx = pu.wx - proj.wx, ty = pu.wy - proj.wy, tz = pu.wz - proj.wz;
  let bx = pv.wx - proj.wx, by = pv.wy - proj.wy, bz = pv.wz - proj.wz;

  // Cross product B x T points outward
  let nx = by * tz - bz * ty;
  let ny = bz * tx - bx * tz;
  let nz = bx * ty - by * tx;
  let nLen = Math.hypot(nx, ny, nz) || 1;
  nx /= nLen; ny /= nLen; nz /= nLen;

  // Curvature metric from geometric features so the mesh densifies at sharp bends
  let au = Math.abs(u);
  let { vTop, vBot } = p0;
  let eyeLipCurv = Math.max(
    Math.exp(-Math.pow((v - vTop) / 0.026, 2)),
    Math.exp(-Math.pow((v - vBot) / 0.026, 2))
  ) * (au < 1.18 ? 1.0 : 0.0);

  let vRidge = 0.81 - 0.085 * Math.min(1.2, au / 1.45);
  let jawCurv = Math.exp(-Math.pow((v - vRidge) / 0.045, 2)) * (au > 0.25 && au < 2.2 ? 0.95 : 0.3);
  let spoilerCurv = (p0.aeroSpoiler / 54.0) * 1.15;
  let pivotCurv = p0.dPiv < 0.24 ? Math.pow(1 - p0.dPiv / 0.24, 0.7) * 1.2 : 0;
  let crownCurv = (p0.crownRib / 9.5) * 0.85;
  let chinCurv = Math.exp(-Math.pow((v - 0.76) / 0.09, 2)) * Math.exp(-Math.pow(u / 0.42, 2)) * 0.85
    + Math.exp(-Math.pow((v - 0.915) / 0.035, 2)) * 0.9;
  let silhouetteCurv = Math.exp(-Math.pow(nz / 0.26, 2)) * 0.65;

  let curvature = constrain(
    Math.max(eyeLipCurv, jawCurv, spoilerCurv, pivotCurv, crownCurv, chinCurv, silhouetteCurv),
    0, 1.2
  );

  return {
    u, v,
    px: proj.px,
    py: proj.py,
    wx: proj.wx,
    wy: proj.wy,
    wz: proj.wz,
    nx, ny, nz,
    inVisor: p0.inVisor,
    vTop, vBot,
    dPiv: p0.dPiv,
    curvature
  };
}

function buildHelmetMesh() {
  grid = [];
  for (let i = 0; i <= NU; i++) {
    let u = -Math.PI + (i / NU) * (2 * Math.PI);
    let col = [];
    for (let j = 0; j <= NV; j++) {
      let v = Math.pow(j / NV, 1.02); // slight concentration near crown
      col.push(computePointData(u, v));
    }
    grid.push(col);
  }

  // Build the ragged render seam column index seamCol[j] for each longitudinal row j
  // u = 0 is index NU/2 = 36. Seam hovers around i = 31..35 (u ~ -0.45..-0.10, canvas x ~ 515..595)
  seamCol = [];
  let baseCol = Math.floor(NU * 0.455); // ~33
  let currentOffset = 0;
  for (let j = 0; j <= NV; j++) {
    if (j % 2 === 0) {
      let step = Math.floor(random(-2.8, 3.2));
      currentOffset = constrain(currentOffset + step, -4, 4);
    }
    // Create a few dramatic jagged render-bucket steps mid-visor and mid-cheek
    let bucketJolt = 0;
    if (j >= 14 && j <= 17) bucketJolt = 3;
    if (j >= 21 && j <= 24) bucketJolt = -3;
    if (j >= 31 && j <= 33) bucketJolt = 2;
    seamCol[j] = baseCol + currentOffset + bucketJolt;
  }
}

// Helper to draw a polygon cleanly with brush.beginShape
function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// ============================================================================
// 2. MAIN DRAW PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Deep Slate Studio Backdrop
  drawDeepSlateBackground();

  // 2. Back-Facing Interior / Rear Shell Wireframe (seen through left half)
  drawBackfaceWireframe();

  // 3. Hyperreal Right Half: Base Lacquer, Airbrushed Gradients, Decals, Vents & Neck Roll
  drawHyperrealShellRight();

  // 4. Hyperreal Right Half: Mirrored Smoke Visor Reflecting a Garage Door
  drawHyperrealVisorRight();

  // 5. Scuffed Racing Decals & Track Abrasion on Rendered Shell
  drawScuffedDecalsAndVents();

  // 6. Razor-Edged Specular Glints & Clearcoat Reflections
  drawRazorSpecularGlints();

  // 7. Ragged Render Seam & Mid-Calculation Polygon Buckets
  drawRaggedSeamTransition();

  // 8. Cyan Fine-Pen Polygon Mesh & Curvature Isolines (Left Half)
  drawCyanWireframeMeshLeft();

  // 9. Atmospheric Micro-Incidents & Floating Render Diagnostics
  drawFinalPolish();

  noLoop();
}

// ============================================================================
// 3. DEEP SLATE BACKGROUND
// ============================================================================

function drawDeepSlateBackground() {
  background("#0b1017");

  brush.noStroke();
  // Deep slate radial & diagonal studio washes
  brush.wash("#121b26", 190);
  brush.rect(0, 0, width, height);

  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.25);

  // Subtle cool Prussian-slate aura behind left wireframe half
  brush.fill("#112838", 95);
  brush.circle(430, 580, 420, 0.2);

  // Subtle dark crimson-slate warm bounce behind right hyperreal half
  brush.fill("#22121d", 85);
  brush.circle(760, 590, 390, 0.2);

  // Deep slate-charcoal vignette corners
  const corners = [
    [[0, 0], [520, 0], [220, 320], [0, 480]],
    [[680, 0], [1200, 0], [1200, 480], [960, 300]],
    [[0, 720], [260, 880], [520, 1200], [0, 1200]],
    [[940, 880], [1200, 700], [1200, 1200], [680, 1200]]
  ];
  brush.fill("#06090e", 150);
  for (let c of corners) drawPoly(c, 0.1);
  brush.noFill();
  brush.noWash();

  // Cast ambient shadow floating far below helmet on slate floor plane
  brush.noStroke();
  brush.fillBleed(0.5, "out");
  brush.fill("#04070b", 170);
  brush.circle(590, 1085, 240, 0.35);
  brush.noFill();

  // Subtle atmospheric airbrush grain across background
  brush.set("airbrushSoft", "#1b2a3b", 1.8);
  for (let i = 0; i < 28; i++) {
    let x1 = random(160, 1040);
    let y1 = random(160, 1020);
    let ang = random(-25, 25);
    brush.line(x1, y1, x1 + cos(ang) * 180, y1 + sin(ang) * 180);
  }
}

// ============================================================================
// 4. BACK-FACING WIREFRAME (GHOSTED REAR SHELL ON LEFT HALF)
// ============================================================================

function drawBackfaceWireframe() {
  // Draw faint deep-teal wireframe of the back-facing interior shell and neck opening
  // where visible on the left half of the canvas
  brush.noFill();
  brush.noWash();
  brush.set("rotring", "#093b4d", 0.26);

  for (let i = 0; i < NU; i += 2) {
    for (let j = 2; j < NV - 1; j += 2) {
      let p00 = grid[i][j];
      let p10 = grid[(i + 2) % NU][j];
      let p01 = grid[i][j + 2];
      // Back-facing points that project to the left of the ragged seam
      if (p00.nz < -0.05 && p10.nz < -0.05 && p01.nz < -0.05) {
        let seamX = grid[seamCol[j]][j].px;
        if (p00.px < seamX - 15 && p10.px < seamX - 15) {
          brush.line(p00.px, p00.py, p10.px, p10.py);
          brush.line(p00.px, p00.py, p01.px, p01.py);
        }
      }
    }
  }

  // Interior neck opening structural ring visible at bottom-left
  brush.set("rotring", "#0e546b", 0.32);
  let jNeck = NV - 1;
  for (let i = 0; i < NU; i++) {
    let pA = grid[i][jNeck];
    let pB = grid[(i + 1) % NU][jNeck];
    let seamX = grid[seamCol[jNeck]][jNeck].px;
    if (pA.px < seamX && pB.px < seamX && pA.nz < 0.1) {
      brush.line(pA.px, pA.py, pB.px, pB.py);
    }
  }
}

// ============================================================================
// 5. HYPERREAL RIGHT HALF: CANDY-APPLE RED LACQUER & AIRBRUSHED GRADIENTS
// ============================================================================

function getCandyLacquerColor(p) {
  // Compute studio lighting & automotive clearcoat reflections from 3D normal
  let nx = p.nx, ny = p.ny, nz = p.nz;

  // Primary softbox above-right-front
  let lx1 = 0.38, ly1 = -0.62, lz1 = 0.68;
  let ndl1 = Math.max(0, nx * lx1 + ny * ly1 + nz * lz1);

  // Warm secondary fill from front-left-below (subsurface metallic bounce)
  let lx2 = -0.35, ly2 = 0.25, lz2 = 0.88;
  let ndl2 = Math.max(0, nx * lx2 + ny * ly2 + nz * lz2);

  // Studio floor horizon reflection band (glossy clearcoat effect)
  let reflY = ny * 0.85 - nz * 0.25;
  let horizonDark = Math.exp(-Math.pow((reflY - 0.16) / 0.16, 2));

  // Rim / grazing Fresnel darkening (candy-apple depth at edges)
  let fresnel = Math.pow(constrain(nz, 0, 1), 0.65);

  // Rim bounce light on far right silhouette (nx > 0.72)
  let rightRim = Math.pow(Math.max(0, nx - 0.55) / 0.45, 2.0) * (1 - nz * 0.6);

  // Cool cyan bounce near the wireframe seam
  let seamBounce = Math.exp(-Math.pow((p.u + 0.22) / 0.22, 2)) * 0.35;

  let tone = (ndl1 * 0.78 + ndl2 * 0.38) * fresnel * (1 - 0.52 * horizonDark);

  // Quantize into rich candy-apple lacquer palette buckets for fast batched washing
  if (p.v > 0.915) {
    // Molded rubber neck roll / base gasket
    if (ndl1 > 0.55) return "#3d4957";
    if (ndl1 > 0.30) return "#222a34";
    return "#10151c";
  }

  // Eye-port rubber gasket rim
  let dTop = Math.abs(p.v - p.vTop);
  let dBot = Math.abs(p.v - p.vBot);
  if (Math.abs(p.u) <= 1.16 && (dTop < 0.018 || dBot < 0.020) && !p.inVisor) {
    return ndl1 > 0.48 ? "#3a4554" : "#141a22";
  }

  if (rightRim > 0.35) return "#7a1632";
  if (seamBounce > 0.22 && tone < 0.35) return "#4a1228";

  if (tone < 0.14) return "#210007"; // deepest oxblood shadow
  if (tone < 0.24) return "#3d000d"; // dark mahogany crimson
  if (tone < 0.35) return "#630015"; // deep burgundy lacquer
  if (tone < 0.46) return "#8f001d"; // rich ruby base
  if (tone < 0.57) return "#b80224"; // candy-apple red midtone
  if (tone < 0.68) return "#dc072c"; // vivid candy-apple red
  if (tone < 0.79) return "#f71935"; // sunlit scarlet
  if (tone < 0.89) return "#ff3d33"; // hot vermilion subsurface bounce
  return "#ff6b4a";                  // incandescent orange-red highlight
}

function drawHyperrealShellRight() {
  brush.noStroke();
  brush.noFill();

  // Batch quads by color bucket for fast, crisp polygon coverage right up to seamCol[j]
  let colorBuckets = {};

  for (let j = 0; j < NV; j++) {
    let sCol = seamCol[j];
    for (let i = sCol; i < NU; i++) {
      let p00 = grid[i][j];
      let p10 = grid[i + 1][j];
      let p11 = grid[i + 1][j + 1];
      let p01 = grid[i][j + 1];

      // Only front-facing shell quads (visor handled in next pass)
      if (p00.nz < -0.08 && p10.nz < -0.08) continue;
      if (p00.inVisor && p10.inVisor && p11.inVisor && p01.inVisor) continue;

      let colHex = getCandyLacquerColor(p00);
      if (!colorBuckets[colHex]) colorBuckets[colHex] = [];
      colorBuckets[colHex].push([
        [p00.px, p00.py],
        [p10.px, p10.py],
        [p11.px, p11.py],
        [p01.px, p01.py]
      ]);
    }
  }

  // 1. Solid opaque base pass for every quad on the rendered half
  for (let hex in colorBuckets) {
    brush.wash(hex, 250);
    let quads = colorBuckets[hex];
    for (let q of quads) {
      drawPoly(q, 0.02);
    }
  }
  brush.noWash();

  // 2. Watercolor glaze passes for deep translucent candy-apple richness
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.45, 0.2);

  // Upper crown & brow ruby glaze
  let crownPts = [];
  for (let j = 2; j <= 13; j++) {
    let i = Math.max(seamCol[j], 34);
    crownPts.push([grid[i][j].px, grid[i][j].py]);
  }
  for (let j = 13; j >= 2; j--) {
    let i = 49;
    crownPts.push([grid[i][j].px, grid[i][j].py]);
  }
  brush.fill("#d90429", 115);
  drawPoly(crownPts, 0.15);

  // Cheek & chin bar deep crimson glaze
  let cheekPts = [];
  for (let j = 28; j <= 41; j++) {
    let i = Math.max(seamCol[j], 34);
    cheekPts.push([grid[i][j].px, grid[i][j].py]);
  }
  for (let j = 41; j >= 28; j--) {
    let i = 50;
    cheekPts.push([grid[i][j].px, grid[i][j].py]);
  }
  brush.fill("#9e0020", 120);
  drawPoly(cheekPts, 0.15);
  brush.noFill();

  // 3. Soft Airbrushed Spray Gradients & Metallic Basecoat Flake
  // Group strokes by color so we minimize brush state changes
  const sprayPasses = [
    { brushName: "airbrushSoft", color: "#2b0009", weight: 1.6, minT: 0.0, maxT: 0.28, step: 2 },
    { brushName: "airbrushSoft", color: "#9e0020", weight: 1.5, minT: 0.25, maxT: 0.52, step: 2 },
    { brushName: "airbrushSoft", color: "#e6092b", weight: 1.4, minT: 0.48, maxT: 0.72, step: 1 },
    { brushName: "airbrushSoft", color: "#ff3b30", weight: 1.25, minT: 0.68, maxT: 0.88, step: 1 },
    { brushName: "airbrushSoft", color: "#ff7b47", weight: 1.0, minT: 0.82, maxT: 1.05, step: 1 },
    { brushName: "flakeSpray", color: "#ff2a4b", weight: 0.9, minT: 0.52, maxT: 0.85, step: 2 },
    { brushName: "flakeSpray", color: "#ff9e66", weight: 0.75, minT: 0.74, maxT: 1.0, step: 2 }
  ];

  for (let sp of sprayPasses) {
    brush.set(sp.brushName, sp.color, sp.weight);
    for (let j = 2; j < NV - 3; j += sp.step) {
      let sCol = seamCol[j] + 1;
      for (let i = sCol; i < NU - 1; i += sp.step) {
        let pA = grid[i][j];
        let pB = grid[i + 1][j];
        if (pA.nz < 0.05 || pA.inVisor || pB.inVisor) continue;

        let ndl = Math.max(0, pA.nx * 0.38 - pA.ny * 0.62 + pA.nz * 0.68);
        if (ndl >= sp.minT && ndl <= sp.maxT) {
          brush.line(pA.px, pA.py, pB.px, pB.py);
        }
      }
    }
  }

  // Smooth contour shading strokes along the jawline aero ridge & crown ribs
  brush.set("cpencil", "#ff5a36", 1.1);
  for (let j = 30; j <= 36; j++) {
    let sCol = Math.max(seamCol[j] + 1, 35);
    for (let i = sCol; i <= 47; i++) {
      let pA = grid[i][j];
      let pB = grid[i + 1][j];
      if (pA.nz > 0.15 && pA.curvature > 0.55) {
        brush.line(pA.px, pA.py, pB.px, pB.py);
      }
    }
  }

  // Dark oxblood shadow contour beneath the jawline ridge
  brush.set("cpencil", "#1a0006", 1.4);
  for (let j = 35; j <= 39; j++) {
    let sCol = Math.max(seamCol[j] + 1, 35);
    for (let i = sCol; i <= 49; i++) {
      let pA = grid[i][j];
      let pB = grid[i + 1][j];
      if (pA.nz > 0.1) {
        brush.line(pA.px, pA.py, pB.px, pB.py);
      }
    }
  }
}

// ============================================================================
// 6. HYPERREAL MIRRORED SMOKE VISOR REFLECTING A GARAGE DOOR
// ============================================================================

function getVisorReflectionColor(p) {
  // Normalized visor coordinates:
  // vNorm in [0, 1] from top brow edge to bottom cheek edge
  // u in [-1.15, 1.15] across visor width
  let vNorm = constrain((p.v - p.vTop) / Math.max(0.01, p.vBot - p.vTop), 0, 1);

  // Spherical mirror warp from surface normal
  let uRefl = p.u + p.nx * 0.22;
  let vRefl = vNorm + (p.ny + 0.12) * 0.14;

  // Grazing smoked polycarbonate Fresnel rim darkening on far right (u > 0.78)
  if (p.u > 0.88) return "#0b1017";
  if (p.u > 0.78 && (vNorm < 0.12 || vNorm > 0.88)) return "#101822";

  // Top rubber seal & smoked visor upper bevel
  if (vNorm < 0.045 || vNorm > 0.955) return "#090d13";

  // 1. Garage Ceiling & Overhead Fluorescent Shop Light (vRefl in [0.04, 0.19])
  if (vRefl < 0.19) {
    // Glowing overhead LED shop tube reflection
    if (vRefl > 0.085 && vRefl < 0.135 && uRefl > -0.25 && uRefl < 0.72) {
      return "#e6f9ff";
    }
    if (vRefl > 0.065 && vRefl < 0.155 && uRefl > -0.32 && uRefl < 0.78) {
      return "#3b7ea1";
    }
    return "#0f1722";
  }

  // 2. Sectional Roll-Up Garage Door (vRefl in [0.19, 0.73], uRefl in [-0.30, 0.84])
  if (vRefl >= 0.19 && vRefl <= 0.73) {
    // Right garage door frame jamb & steel track
    if (uRefl > 0.82) return "#16202b";
    if (uRefl > 0.76) return "#2c3d4f";

    // Horizontal seam grooves between the 4 sectional garage door panels
    const seams = [0.315, 0.450, 0.585];
    for (let s of seams) {
      if (Math.abs(vRefl - s) < 0.013) return "#0d141d"; // dark panel joint shadow
      if (vRefl >= s + 0.013 && vRefl < s + 0.026) return "#cfe8f7"; // bright metallic lip glint
    }

    // Garage door upper window panes in Panel 2 (vRefl in [0.34, 0.43])
    if (vRefl >= 0.34 && vRefl <= 0.43) {
      let inWin1 = uRefl > -0.18 && uRefl < 0.08;
      let inWin2 = uRefl > 0.15 && uRefl < 0.42;
      let inWin3 = uRefl > 0.49 && uRefl < 0.71;
      if (inWin1 || inWin2 || inWin3) {
        return vRefl < 0.385 ? "#caf0f8" : "#ffffff"; // bright sky reflection in door windows
      }
    }

    // Metallic sectional door panels catching outdoor sky + warm bounce light
    if (vRefl < 0.315) return "#41586e"; // top panel
    if (vRefl < 0.450) return "#58748f"; // window panel frame
    if (vRefl < 0.585) return "#7998b5"; // lower-mid panel
    return "#9eb9d1";                    // bottom panel catching driveway bounce
  }

  // 3. Blazing Sunlit Threshold Gap Under Garage Door (vRefl in [0.73, 0.81])
  if (vRefl > 0.73 && vRefl <= 0.81 && uRefl < 0.78) {
    if (vRefl < 0.765) return "#fff8e8"; // hot daylight concrete strip
    return "#f4a261";                    // warm golden driveway reflection
  }

  // 4. Polished Dark Concrete Garage Floor (vRefl > 0.81)
  if (uRefl > 0.15 && uRefl < 0.62 && vRefl < 0.89) {
    return "#3d4e61"; // floor reflection of open doorway light
  }
  return "#18222e";
}

function drawHyperrealVisorRight() {
  brush.noStroke();
  brush.noFill();

  let visorBuckets = {};

  for (let j = 0; j < NV; j++) {
    let sCol = seamCol[j];
    for (let i = sCol; i < NU; i++) {
      let p00 = grid[i][j];
      let p10 = grid[i + 1][j];
      let p11 = grid[i + 1][j + 1];
      let p01 = grid[i][j + 1];

      if (p00.nz < -0.05) continue;
      if (!(p00.inVisor || p10.inVisor || p11.inVisor || p01.inVisor)) continue;

      let colHex = getVisorReflectionColor(p00);
      if (!visorBuckets[colHex]) visorBuckets[colHex] = [];
      visorBuckets[colHex].push([
        [p00.px, p00.py],
        [p10.px, p10.py],
        [p11.px, p11.py],
        [p01.px, p01.py]
      ]);
    }
  }

  for (let hex in visorBuckets) {
    brush.wash(hex, 250);
    for (let q of visorBuckets[hex]) {
      drawPoly(q, 0.02);
    }
  }
  brush.noWash();

  // Airbrushed smoke-mirror gradient & sunlit garage floor bloom across visor
  const visorSprays = [
    { color: "#0b111a", weight: 1.5, vMin: 0.0, vMax: 0.22 },
    { color: "#749bc2", weight: 1.2, vMin: 0.32, vMax: 0.68 },
    { color: "#ffd166", weight: 1.1, vMin: 0.68, vMax: 0.82 },
    { color: "#141f2c", weight: 1.4, vMin: 0.82, vMax: 1.0 }
  ];

  for (let vs of visorSprays) {
    brush.set("airbrushSoft", vs.color, vs.weight);
    for (let j = 13; j <= 28; j++) {
      let sCol = Math.max(seamCol[j] + 1, 34);
      for (let i = sCol; i <= 48; i++) {
        let pA = grid[i][j];
        let pB = grid[i + 1][j];
        if (!pA.inVisor || !pB.inVisor || pA.nz < 0.05) continue;
        let vNorm = (pA.v - pA.vTop) / Math.max(0.01, pA.vBot - pA.vTop);
        if (vNorm >= vs.vMin && vNorm <= vs.vMax) {
          brush.line(pA.px, pA.py, pB.px, pB.py);
        }
      }
    }
  }

  // Crisp horizontal garage door panel joints, embossed rectangles & window mullions on visor
  const panelV = [0.31, 0.44, 0.57, 0.70, 0.77];
  for (let idx = 0; idx < panelV.length; idx++) {
    let pv = panelV[idx];
    let shadowPts = [];
    let highlightPts = [];
    for (let i = 34; i <= 46; i++) {
      let u = -Math.PI + (i / NU) * (2 * Math.PI);
      let { vTop, vBot } = visorBounds(u);
      let vTarget = vTop + pv * (vBot - vTop);
      let jApprox = Math.round(Math.pow(vTarget, 1 / 1.02) * NV);
      if (i < seamCol[constrain(jApprox, 0, NV)]) continue;

      let pS = computePointData(u, vTarget - p0Offset(u));
      let pH = computePointData(u, vTarget - p0Offset(u) + 0.0045);
      if (pS.nz > 0.1) {
        shadowPts.push([pS.px, pS.py]);
        highlightPts.push([pH.px, pH.py]);
      }
    }
    if (shadowPts.length > 2) {
      brush.set("rotring", "#070b10", 0.55);
      brush.spline(shadowPts, 0.35);
      brush.set("razorGlint", idx === 4 ? "#fff3b0" : "#e0f4ff", 0.5);
      brush.spline(highlightPts, 0.35);
    }
  }

  // Vertical garage door stile lines & stamped panel embossments reflected in visor
  const stileU = [0.05, 0.34, 0.62, 0.79];
  brush.set("rotring", "#1d2d3d", 0.42);
  for (let su of stileU) {
    let { vTop, vBot } = visorBounds(su);
    let pTop = computePointData(su, vTop + 0.22 * (vBot - vTop));
    let pBot = computePointData(su, vTop + 0.72 * (vBot - vTop));
    if (pTop.nz > 0.15) {
      brush.line(pTop.px, pTop.py, pBot.px, pBot.py);
    }
  }

  // Visor optical polycarbonate top/bottom edge bevel highlight
  let topLip = [], botLip = [];
  for (let i = 35; i <= 48; i++) {
    let u = -Math.PI + (i / NU) * (2 * Math.PI);
    let { vTop, vBot } = visorBounds(u);
    let pT = computePointData(u, vTop + 0.004);
    let pB = computePointData(u, vBot - 0.004);
    if (pT.nz > 0.08) topLip.push([pT.px, pT.py]);
    if (pB.nz > 0.08) botLip.push([pB.px, pB.py]);
  }
  brush.set("razorGlint", "#90e0ef", 0.55);
  if (topLip.length > 2) brush.spline(topLip, 0.3);
  brush.set("razorGlint", "#caf0f8", 0.65);
  if (botLip.length > 2) brush.spline(botLip, 0.3);

  // Eccentric anodized tear-off post on right side of visor (u ~ 0.90)
  let pPin = computePointData(0.88, 0.48);
  if (pPin.nz > 0.1) {
    brush.noStroke();
    brush.wash("#141b24", 245);
    brush.circle(pPin.px, pPin.py, 9, 0.1);
    brush.wash("#e9c46a", 245);
    brush.circle(pPin.px - 1.5, pPin.py - 1, 5.2, 0.1);
    brush.noWash();
    brush.set("razorGlint", "#ffffff", 0.55);
    brush.circle(pPin.px - 2.5, pPin.py - 2.5, 2.2, 0.05);
  }
}

function p0Offset(u) {
  return 0.015 * Math.sin(u * 1.4);
}

// ============================================================================
// 7. SCUFFED RACING DECALS, MOLDED VENTS & ABRASION WEAR
// ============================================================================

function drawUVQuadStrip(uMin, uMax, vMinFn, vMaxFn, colorHex, opacity = 245) {
  let pts = [];
  let steps = 14;
  for (let k = 0; k <= steps; k++) {
    let u = uMin + (k / steps) * (uMax - uMin);
    let v = vMinFn(u);
    let iApprox = constrain(Math.round(((u + Math.PI) / (2 * Math.PI)) * NU), 0, NU);
    let jApprox = constrain(Math.round(Math.pow(v, 1 / 1.02) * NV), 0, NV);
    let uSeam = -Math.PI + (seamCol[jApprox] / NU) * (2 * Math.PI);
    let uClamped = Math.max(u, uSeam);
    let p = computePointData(uClamped, vMinFn(uClamped));
    if (p.nz > 0.05) pts.push([p.px, p.py]);
  }
  for (let k = steps; k >= 0; k--) {
    let u = uMin + (k / steps) * (uMax - uMin);
    let v = vMaxFn(u);
    let jApprox = constrain(Math.round(Math.pow(v, 1 / 1.02) * NV), 0, NV);
    let uSeam = -Math.PI + (seamCol[jApprox] / NU) * (2 * Math.PI);
    let uClamped = Math.max(u, uSeam);
    let p = computePointData(uClamped, vMaxFn(uClamped));
    if (p.nz > 0.05) pts.push([p.px, p.py]);
  }
  if (pts.length >= 4) {
    brush.noStroke();
    brush.wash(colorHex, opacity);
    drawPoly(pts, 0.08);
    brush.noWash();
  }
}

