function drawRazorSpecularGlints() {
  // 1. Primary Studio Softbox Ribbon curving down the Upper Crown & Brow (u in [0.22, 0.40])
  brush.set("airbrushSoft", "#ff8fa3", 1.1);
  for (let v = 0.06; v <= 0.27; v += 0.02) {
    let p1 = computePointData(0.24, v);
    let p2 = computePointData(0.40, v + 0.01);
    brush.line(p1.px, p1.py, p2.px, p2.py);
  }

  // Razor-sharp white softbox reflection strip on crown
  drawUVQuadStrip(
    0.26, 0.36,
    (u) => 0.065 + (u - 0.26) * 0.15,
    (u) => 0.235 + (u - 0.26) * 0.12,
    "#ffffff", 240
  );
  // Crisp cyan-white edge accent on the crown glint
  let crownGlintEdge = [];
  for (let v = 0.065; v <= 0.24; v += 0.025) {
    let p = computePointData(0.26, v);
    crownGlintEdge.push([p.px, p.py]);
  }
  brush.set("razorGlint", "#ffffff", 0.75);
  brush.spline(crownGlintEdge, 0.35);

  // 2. Continuation of Studio Softbox Ribbon across the Mirrored Smoke Visor (u in [0.24, 0.36])
  drawUVQuadStrip(
    0.25, 0.33,
    () => 0.325,
    () => 0.565,
    "#ffffff", 215
  );

  // 3. Razor Specular Glint along the Sculpted Jawline / Cheek Aero Crease
  let jawGlint = [];
  let jawHalo = [];
  for (let u = 0.08; u <= 0.92; u += 0.06) {
    let vRidge = 0.81 - 0.085 * Math.min(1.2, u / 1.45) - 0.008;
    let p = computePointData(u, vRidge);
    let pH = computePointData(u, vRidge - 0.012);
    if (p.nz > 0.15) {
      jawGlint.push([p.px, p.py]);
      jawHalo.push([pH.px, pH.py]);
    }
  }
  brush.set("airbrushSoft", "#ff758f", 0.9);
  if (jawHalo.length > 2) brush.spline(jawHalo, 0.35);
  brush.set("razorGlint", "#ffffff", 0.85);
  if (jawGlint.length > 2) brush.spline(jawGlint, 0.35);

  // 4. Eye-Port Lower Sill & Chin Prow Razor Highlights
  let sillGlint = [];
  for (let u = 0.02; u <= 0.82; u += 0.06) {
    let { vBot } = visorBounds(u);
    let p = computePointData(u, vBot + 0.022);
    if (p.nz > 0.15) sillGlint.push([p.px, p.py]);
  }
  brush.set("razorGlint", "#ffe5ec", 0.7);
  if (sillGlint.length > 2) brush.spline(sillGlint, 0.35);

  // Crown aero rib razor highlight (u ~ 0.37, v in [0.10, 0.27])
  let ribGlint = [];
  for (let v = 0.10; v <= 0.27; v += 0.025) {
    let p = computePointData(0.37, v);
    ribGlint.push([p.px, p.py]);
  }
  brush.set("razorGlint", "#ffffff", 0.65);
  brush.spline(ribGlint, 0.35);

  // Far-right grazing rim highlight (cool studio rim light on red lacquer)
  let rimPts = [];
  for (let j = 6; j <= 38; j += 2) {
    for (let i = 45; i < NU; i++) {
      let p = grid[i][j];
      if (p.nz > 0.06 && p.nz < 0.26 && p.nx > 0.65) {
        rimPts.push([p.px, p.py]);
        break;
      }
    }
  }
  if (rimPts.length > 3) {
    brush.set("razorGlint", "#caf0f8", 0.55);
    brush.spline(rimPts, 0.3);
  }
}

// ============================================================================
// 9. RAGGED RENDER SEAM & MID-CALCULATION POLYGON BUCKETS
// ============================================================================

function drawRaggedSeamTransition() {
  // 1. Soft cyan-magenta energy glow along the active rasterization frontier
  brush.set("airbrushSoft", "#00b4d8", 1.3);
  for (let j = 2; j < NV - 2; j += 2) {
    let sc = seamCol[j];
    let pA = grid[sc][j];
    let pB = grid[sc][j + 2];
    if (pA.nz > 0.05) {
      brush.line(pA.px, pA.py, pB.px, pB.py);
    }
  }

  // 2. Partially calculated triangles & isolated render buckets straddling the seam
  for (let j = 1; j < NV - 1; j++) {
    let sc = seamCol[j];

    // Scan a 5-column transition band around seamCol[j]
    for (let di = -3; di <= 1; di++) {
      let i = sc + di;
      if (i < 2 || i >= NU - 1) continue;

      let p00 = grid[i][j];
      let p10 = grid[i + 1][j];
      let p11 = grid[i + 1][j + 1];
      let p01 = grid[i][j + 1];
      if (p00.nz < 0.02) continue;

      let triRight = [[p10.px, p10.py], [p11.px, p11.py], [p01.px, p01.py]];
      let triLeft = [[p00.px, p00.py], [p10.px, p10.py], [p01.px, p01.py]];

      if (di === 0) {
        // Right on the seam: fill the right triangle with flat faceted lacquer/visor color,
        // leave the left triangle as exposed cyan shader mesh
        let flatCol = p00.inVisor ? getVisorReflectionColor(p00) : getCandyLacquerColor(p00);
        brush.noStroke();
        brush.wash(flatCol, 240);
        drawPoly(triRight, 0);
        brush.noWash();

        // Translucent cyan shader pass on the left triangle
        brush.noStroke();
        brush.wash("#00b4d8", 65);
        drawPoly(triLeft, 0);
        brush.noWash();
      } else if (di === -1 && (j * 7 + i * 3) % 3 === 0) {
        // Isolated mid-render triangle just to the left of the seam
        let bucketCol = p00.inVisor ? "#1e3a52" : ((j % 2 === 0) ? "#9e0020" : "#0077b6");
        brush.noStroke();
        brush.wash(bucketCol, 175);
        drawPoly(triRight, 0);
        brush.noWash();
      } else if (di === -2 && (j * 5 + i) % 5 === 0) {
        // Ghosted wireframe pre-pass quad further left
        brush.noStroke();
        brush.wash("#00f5ff", 42);
        drawPoly([[p00.px, p00.py], [p10.px, p10.py], [p11.px, p11.py], [p01.px, p01.py]], 0);
        brush.noWash();
      } else if (di === 1 && (j % 3 === 0)) {
        // Overlay crisp wireframe triangulation onto the first rendered column (shader wireframe overlay)
        brush.set("laserCyan", "#72efdd", 0.35);
        brush.line(p00.px, p00.py, p10.px, p10.py);
        brush.line(p10.px, p10.py, p01.px, p01.py);
        brush.line(p00.px, p00.py, p01.px, p01.py);
      }
    }
  }

  // 3. Incandescent stepped seam boundary contour line
  brush.set("razorGlint", "#caf0f8", 0.55);
  for (let j = 1; j < NV - 1; j++) {
    let sc0 = seamCol[j];
    let sc1 = seamCol[j + 1];
    let pA = grid[sc0][j];
    let pB = grid[sc0][j + 1];
    if (pA.nz > 0.02 && pB.nz > 0.02) {
      brush.line(pA.px, pA.py, pB.px, pB.py);
      if (sc1 !== sc0) {
        let pStep = grid[sc1][j + 1];
        brush.line(pB.px, pB.py, pStep.px, pStep.py);
      }
    }
  }
}

// ============================================================================
// 10. CYAN FINE-PEN POLYGON MESH & CURVATURE ISOLINES (LEFT HALF)
// ============================================================================

function drawCyanWireframeMeshLeft() {
  // 1. Progressive surface dissolution: subtle deep-teal inner shell backing near seam
  // that dissolves completely into transparent wireframe toward the left
  brush.noStroke();
  for (let j = 1; j < NV - 1; j++) {
    let sc = seamCol[j];
    for (let i = Math.max(1, sc - 7); i < sc; i++) {
      let p00 = grid[i][j];
      let p10 = grid[i + 1][j];
      let p11 = grid[i + 1][j + 1];
      let p01 = grid[i][j + 1];
      if (p00.nz < 0.0) continue;

      let distFromSeam = sc - i;
      let alpha = map(distFromSeam, 1, 7, 90, 12);
      let tintHex = p00.inVisor ? "#0d2838" : "#1a1426";
      brush.wash(tintHex, alpha);
      drawPoly([[p00.px, p00.py], [p10.px, p10.py], [p11.px, p11.py], [p01.px, p01.py]], 0);
    }
  }
  brush.noWash();

  // 2. Luminous cyan atmospheric glow along high-curvature bands (spoiler, pivot, jawline, eyeport)
  brush.set("airbrushSoft", "#0096c7", 1.25);
  for (let j = 1; j < NV - 1; j += 2) {
    let sc = seamCol[j];
    for (let i = 1; i < sc; i += 2) {
      let p = grid[i][j];
      let pNext = grid[i + 1][j];
      if (p.nz > -0.05 && p.curvature > 0.58) {
        brush.line(p.px, p.py, pNext.px, pNext.py);
      }
    }
  }

  // 3. Collect wireframe segments into 4 luminous hairline-pen batches by curvature/importance
  // Batch 0: Deep Teal-Cyan (#0077b6) — outer/grazing & low-curvature base mesh
  // Batch 1: Electric Cyan (#00b4d8) — primary triangulated quad mesh
  // Batch 2: Luminous Aqua-Cyan (#00f5ff) — curvature-subdivided quads & isolines
  // Batch 3: Incandescent Ice-Cyan (#caf0f8) — sharpest ridges, visor pivot & silhouette creases
  let batches = [[], [], [], []];
  let vertexNodes = [];

  function addSeg(bIdx, x1, y1, x2, y2) {
    batches[bIdx].push([x1, y1, x2, y2]);
  }

  for (let j = 0; j < NV; j++) {
    let sc = seamCol[j];
    for (let i = 0; i < sc; i++) {
      let p00 = grid[i][j];
      let p10 = grid[i + 1][j];
      let p11 = grid[i + 1][j + 1];
      let p01 = grid[i][j + 1];

      // Cull back-facing cells (already drawn in ghosted backface pass)
      if (p00.nz < -0.04 && p10.nz < -0.04 && p11.nz < -0.04) continue;

      // Determine adaptive subdivision level from 3D surface curvature
      let maxCurv = Math.max(p00.curvature, p10.curvature, p11.curvature, p01.curvature);
      let sub = 1;
      if (maxCurv > 0.72) sub = 3;      // 3x3 = 9 sub-quads = 18 triangles where shell bends sharply!
      else if (maxCurv > 0.42) sub = 2; // 2x2 = 4 sub-quads = 8 triangles in medium curvature

      // Base quad boundary edges
      let baseBatch = maxCurv > 0.65 ? 2 : (p00.nz < 0.22 ? 0 : 1);
      addSeg(baseBatch, p00.px, p00.py, p10.px, p10.py);
      addSeg(baseBatch, p00.px, p00.py, p01.px, p01.py);
      if (i === sc - 1) addSeg(2, p10.px, p10.py, p11.px, p11.py);
      if (j === NV - 1) addSeg(2, p01.px, p01.py, p11.px, p11.py);

      // Subdivide cell and triangulate quads
      for (let sx = 0; sx < sub; sx++) {
        for (let sy = 0; sy < sub; sy++) {
          let uA = sx / sub, uB = (sx + 1) / sub;
          let vA = sy / sub, vB = (sy + 1) / sub;

          let q00 = bilerpPt(p00, p10, p11, p01, uA, vA);
          let q10 = bilerpPt(p00, p10, p11, p01, uB, vA);
          let q11 = bilerpPt(p00, p10, p11, p01, uB, vB);
          let q01 = bilerpPt(p00, p10, p11, p01, uA, vB);

          let subBatch = sub === 3 ? (maxCurv > 0.88 ? 3 : 2) : (sub === 2 ? 2 : 1);

          // Internal sub-quad grid lines (curvature isolines)
          if (sx > 0) addSeg(subBatch, q00[0], q00[1], q01[0], q01[1]);
          if (sy > 0) addSeg(subBatch, q00[0], q00[1], q10[0], q10[1]);

          // Diagonal triangulation line inside every sub-quad
          let diagBatch = sub === 3 ? 2 : (sub === 2 ? 1 : 0);
          if ((i + j + sx + sy) % 2 === 0) {
            addSeg(diagBatch, q00[0], q00[1], q11[0], q11[1]);
          } else {
            addSeg(diagBatch, q10[0], q10[1], q01[0], q01[1]);
          }
        }
      }

      // Record high-curvature vertex nodes for luminous micro-ticks
      if (maxCurv > 0.78 && (i + j) % 2 === 0) {
        vertexNodes.push([p00.px, p00.py]);
      }
    }
  }

  // Execute batched hairline pen strokes
  const batchStyles = [
    { brush: "rotring", color: "#0077b6", weight: 0.25 },
    { brush: "laserCyan", color: "#00b4d8", weight: 0.30 },
    { brush: "laserCyan", color: "#00f5ff", weight: 0.35 },
    { brush: "razorGlint", color: "#caf0f8", weight: 0.42 }
  ];

  for (let b = 0; b < 4; b++) {
    let st = batchStyles[b];
    brush.set(st.brush, st.color, st.weight);
    let segs = batches[b];
    for (let k = 0; k < segs.length; k++) {
      let s = segs[k];
      brush.line(s[0], s[1], s[2], s[3]);
    }
  }

  // 4. Continuous Curvature Isolines tracing the major sculptural creases on the Left Half
  drawCurvatureIsolinesLeft();

  // 5. High-Density Mechanical Wireframe for the Left Visor Pivot Pod (u ~ -1.12, v ~ 0.448)
  drawVisorPivotWireframe();

  // 6. Luminous Vertex Node Ticks at Sharp Curvature Maxima
  brush.set("razorGlint", "#ffffff", 0.45);
  for (let k = 0; k < vertexNodes.length; k++) {
    let vx = vertexNodes[k][0], vy = vertexNodes[k][1];
    brush.line(vx - 1.8, vy, vx + 1.8, vy);
    brush.line(vx, vy - 1.8, vx, vy + 1.8);
  }
}

function bilerpPt(p00, p10, p11, p01, tx, ty) {
  let xTop = p00.px + (p10.px - p00.px) * tx;
  let yTop = p00.py + (p10.py - p00.py) * tx;
  let xBot = p01.px + (p11.px - p01.px) * tx;
  let yBot = p01.py + (p11.py - p01.py) * tx;
  return [xTop + (xBot - xTop) * ty, yTop + (yBot - yTop) * ty];
}

function drawCurvatureIsolinesLeft() {
  // Trace smooth continuous isolines along the jawline crease, eye-port perimeter,
  // crown aero rib, rear wake spoiler ridge, and bottom neck gasket
  brush.set("razorGlint", "#80ffdb", 0.44);

  // A. Eye-port top brow & bottom sill recessed contour isolines on left half
  for (let offset of [-0.012, 0.0, 0.012]) {
    let topPts = [], botPts = [];
    for (let u = -1.14; u <= -0.15; u += 0.04) {
      let { vTop, vBot } = visorBounds(u);
      let jTop = constrain(Math.round(Math.pow(vTop, 1 / 1.02) * NV), 0, NV);
      let uSeamTop = -Math.PI + (seamCol[jTop] / NU) * (2 * Math.PI);
      if (u < uSeamTop) {
        let pT = computePointData(u, vTop + offset);
        if (pT.nz > 0.0) topPts.push([pT.px, pT.py]);
      }

      let jBot = constrain(Math.round(Math.pow(vBot, 1 / 1.02) * NV), 0, NV);
      let uSeamBot = -Math.PI + (seamCol[jBot] / NU) * (2 * Math.PI);
      if (u < uSeamBot) {
        let pB = computePointData(u, vBot + offset);
        if (pB.nz > 0.0) botPts.push([pB.px, pB.py]);
      }
    }
    if (topPts.length > 3) brush.spline(topPts, 0.35);
    if (botPts.length > 3) brush.spline(botPts, 0.35);
  }

  // B. Jawline aerodynamic crease isolines sweeping from chin seam to rear spoiler
  for (let dv of [-0.016, -0.005, 0.006, 0.018]) {
    let jawPts = [];
    for (let u = -2.25; u <= -0.18; u += 0.05) {
      let au = Math.abs(u);
      let vRidge = 0.81 - 0.085 * Math.min(1.2, au / 1.45) + dv;
      let jApprox = constrain(Math.round(Math.pow(vRidge, 1 / 1.02) * NV), 0, NV);
      let uSeam = -Math.PI + (seamCol[jApprox] / NU) * (2 * Math.PI);
      if (u >= uSeam) continue;
      let p = computePointData(u, vRidge);
      if (p.nz > -0.02) jawPts.push([p.px, p.py]);
    }
    if (jawPts.length > 3) {
      brush.set("razorGlint", dv === -0.005 ? "#ffffff" : "#00f5ff", dv === -0.005 ? 0.50 : 0.36);
      brush.spline(jawPts, 0.35);
    }
  }

  // C. Rear Aerodynamic Wake Spoiler Fin Isolines (high curvature at u in [-2.65, -1.65])
  for (let vSpoil = 0.20; vSpoil <= 0.54; vSpoil += 0.028) {
    let spPts = [];
    for (let u = -2.62; u <= -1.55; u += 0.05) {
      let p = computePointData(u, vSpoil);
      if (p.nz > -0.05) spPts.push([p.px, p.py]);
    }
    if (spPts.length > 3) {
      brush.set("laserCyan", Math.abs(vSpoil - 0.37) < 0.04 ? "#caf0f8" : "#00e5ff", 0.38);
      brush.spline(spPts, 0.35);
    }
  }
}

function drawVisorPivotWireframe() {
  // Concentric radial-triangulated mechanical CAD mesh for the left visor pivot boss
  let uC = -1.12, vC = 0.448;
  let centerP = computePointData(uC, vC);
  if (centerP.nz < 0.05) return;

  // Subtle cyan glow under pivot mechanism
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fill("#0096c7", 55);
  brush.circle(centerP.px, centerP.py, 42, 0.15);
  brush.noFill();

  const radii = [0.028, 0.058, 0.095, 0.135, 0.175, 0.215];
  const nSpokes = 20;
  let rings = [];

  for (let r of radii) {
    let ring = [];
    for (let k = 0; k <= nSpokes; k++) {
      let ang = (k / nSpokes) * (2 * Math.PI);
      let u = uC + Math.cos(ang) * r * 0.95;
      let v = vC + Math.sin(ang) * r * 0.42;
      let p = computePointData(u, v);
      ring.push([p.px, p.py]);
    }
    rings.push(ring);
  }

  // Draw concentric rings
  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let isKeyRing = rIdx === 1 || rIdx === 3 || rIdx === 5;
    brush.set(isKeyRing ? "razorGlint" : "laserCyan", isKeyRing ? "#caf0f8" : "#00f5ff", isKeyRing ? 0.44 : 0.32);
    brush.spline(rings[rIdx], 0.25);
  }

  // Draw radial spokes & diagonal ratchet gear triangulations
  brush.set("laserCyan", "#48cae4", 0.30);
  for (let k = 0; k < nSpokes; k++) {
    for (let rIdx = 0; rIdx < rings.length - 1; rIdx++) {
      let p00 = rings[rIdx][k];
      let p10 = rings[rIdx + 1][k];
      let p11 = rings[rIdx + 1][k + 1];
      brush.line(p00[0], p00[1], p10[0], p10[1]);
      if ((k + rIdx) % 2 === 0) {
        brush.line(p00[0], p00[1], p11[0], p11[1]);
      }
    }
  }
}

// ============================================================================
// 11. PROGRESSIVE DISSOLUTION TANGENTS & MICRO-INCIDENTS
// ============================================================================

function drawFinalPolish() {
  // Detached/dissolving wireframe triangles & tangent construction rays floating off the far-left silhouette
  brush.set("rotring", "#0096c7", 0.26);
  for (let j = 6; j < NV - 4; j += 2) {
    // Find leftmost silhouette point in row j
    let leftP = null;
    for (let i = 1; i < seamCol[j]; i++) {
      let p = grid[i][j];
      if (p.nz >= -0.02 && (!leftP || p.px < leftP.px)) {
        leftP = p;
      }
    }
    if (leftP) {
      // Extend tangent construction line slightly into deep slate space
      let len = random(14, 42);
      let ang = random(155, 205);
      let ex = leftP.px + cos(ang) * len;
      let ey = leftP.py + sin(ang) * len;
      brush.line(leftP.px, leftP.py, ex, ey);

      // Occasional detached floating micro-triangle mid-dissolution
      if (j % 4 === 0) {
        let tx = ex + random(-22, -6);
        let ty = ey + random(-12, 12);
        let s = random(7, 15);
        brush.set("laserCyan", "#48cae4", 0.28);
        drawPoly([
          [tx, ty],
          [tx - s, ty + s * 0.6],
          [tx - s * 0.4, ty - s * 0.7]
        ], 0);
        brush.set("rotring", "#0096c7", 0.26);
      }
    }
  }
}

// Hyperreal Dusty Tractor Tyre — Kuba Raffia Labyrinth
// p5.js 2.x + p5.brush (WEBGL)

let lugs = [];
let grooves = [];

const PALETTE = {
  voidBlack: "#08090d",
  sootDeep: "#0e1016",
  sootDark: "#151720",
  sootMid: "#1e202b",
  sootNap: "#292c38",
  sootSheen: "#3a3e4d",
  twilightSlate: "#4c5061",
  siennaDark: "#5e3417",
  siennaDeep: "#7a441e",
  siennaRaw: "#9c5a28",
  siennaBright: "#b56e35",
  ochreDark: "#c2803d",
  ochreWarm: "#d6974f",
  ochrePale: "#e3b26d",
  boneShadow: "#cbbba6",
  boneWarm: "#dfd1be",
  boneLight: "#eee3d3",
  boneCrest: "#f7f0e4"
};

// Skewed chevron lattice basis (off-kilter tractor V-angle)
const SCALE_UV = 96;
const ANG_U = 33 * (Math.PI / 180);
const ANG_V = 131 * (Math.PI / 180);
const EUX = Math.cos(ANG_U) * SCALE_UV;
const EUY = Math.sin(ANG_U) * SCALE_UV;
const EVX = Math.cos(ANG_V) * SCALE_UV;
const EVY = Math.sin(ANG_V) * SCALE_UV;

// Light direction: grazing dusky twilight from upper-left
const LIGHT_X = -0.67;
const LIGHT_Y = -0.74;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(8831);

  // Custom brush for the velvety cut-pile rubber nap
  brush.add("velvet_nap", {
    type: "default",
    weight: 1.1,
    scatter: 0.45,
    sharpness: 0.28,
    grain: 16,
    opacity: 155,
    spacing: 0.55,
    pressure: [0.5, 1.35, 0.4],
    rotate: "natural",
    noise: 0.85
  });

  // Custom brush for powdery raw sienna, ochre, and bone dust drifts
  brush.add("dust_drift", {
    type: "default",
    weight: 1.6,
    scatter: 1.35,
    sharpness: 0.14,
    grain: 22,
    opacity: 95,
    spacing: 0.65,
    pressure: [0.25, 1.2, 0.2],
    rotate: "random",
    noise: 1.0
  });

  // Custom vector field echoing curved tire carcass & weave grain
  brush.addField("tyre_weave", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let baseAng = (col + row) % 2 === 0 ? 33 : 131;
        let wave = Math.sin(nx * 6.0 + ny * 4.0) * 14;
        field[col][row] = baseAng + wave;
      }
    }
    return field;
  });

  buildTreadLabyrinth();
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.voidBlack);

  // 1. Deep recessed groove floor: twilight soot + drifted sienna/ochre dust beds + dense crosshatching
  drawGrooveFloor();

