// ============================================================================
// 3D TYRE SURFACE MAPPING & GEOMETRY ENGINE
// ============================================================================

function uvToXY(u, v) {
  let lx = u * EUX + v * EVX;
  let ly = u * EUY + v * EVY;

  // Rotate into tire axis frame (~82 deg rolling axis) for subtle 3D barrel warp
  let rot = -8 * (Math.PI / 180);
  let cosR = Math.cos(rot);
  let sinR = Math.sin(rot);
  let ax = lx * cosR - ly * sinR;
  let ay = lx * sinR + ly * cosR;

  // Cylindrical tire crown curvature across width (ax) and circumference (ay)
  let sx = ax / 1080;
  let sy = ay / 1350;
  let warpedAx = 1080 * Math.sin(sx * 0.42) / 0.42;
  let warpedAy = 1350 * Math.sin(sy * 0.32) / 0.32;

  // Subtle organic carcass distortion
  let n1 = (noise(u * 0.18 + 10, v * 0.18 + 10) - 0.5) * 11;
  let n2 = (noise(u * 0.18 + 50, v * 0.18 + 50) - 0.5) * 11;

  let wx = warpedAx * cosR + warpedAy * sinR + 585 + n1;
  let wy = -warpedAx * sinR + warpedAy * cosR + 595 + n2;
  return [wx, wy];
}

// Extrusion offset from lug top crown down to groove floor
function getExtrudeVector(x, y, heightScale) {
  let dx = 4.5 + (x - 560) * 0.011;
  let dy = 7.5 + (y - 540) * 0.011;
  return [dx * heightScale, dy * heightScale];
}

// Ensure clockwise winding in Y-down screen coords so outward normal is (dy, -dx)
function ensureClockwise(pts) {
  let area = 0;
  for (let i = 0; i < pts.length; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % pts.length];
    area += p1[0] * p2[1] - p2[0] * p1[1];
  }
  if (area < 0) {
    return pts.slice().reverse();
  }
  return pts;
}

// Subdivide and organically roughen polygon edges in screen space to feel like worn vulcanized rubber
function refineRubberPolygon(uvPts, jitterAmp = 1.6) {
  let screenPts = uvPts.map(p => uvToXY(p[0], p[1]));
  screenPts = ensureClockwise(screenPts);

  let refined = [];
  let n = screenPts.length;
  for (let i = 0; i < n; i++) {
    let p1 = screenPts[i];
    let p2 = screenPts[(i + 1) % n];
    let distSeg = Math.hypot(p2[0] - p1[0], p2[1] - p1[1]);
    let steps = Math.max(1, Math.min(7, Math.floor(distSeg / 18)));

    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let x = lerp(p1[0], p2[0], t);
      let y = lerp(p1[1], p2[1], t);

      // Mold edge wear jitter
      let jx = (noise(x * 0.025, y * 0.025, 1.7) - 0.5) * jitterAmp * 2.0;
      let jy = (noise(x * 0.025, y * 0.025, 9.3) - 0.5) * jitterAmp * 2.0;
      refined.push([x + jx, y + jy]);
    }
  }
  return ensureClockwise(refined);
}

// Compute outward vertex normals and build beveled base polygon on groove floor
function computeLug3DGeometry(topPoly, draftWidth, heightScale) {
  let n = topPoly.length;
  let edgeNormals = [];

  for (let i = 0; i < n; i++) {
    let p1 = topPoly[i];
    let p2 = topPoly[(i + 1) % n];
    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let len = Math.hypot(dx, dy) || 1;
    // For clockwise polygon in Y-down coords, outward normal is (dy, -dx) / len
    edgeNormals.push([dy / len, -dx / len]);
  }

  let vertNormals = [];
  let basePoly = [];
  let terracePoly = [];

  for (let i = 0; i < n; i++) {
    let nPrev = edgeNormals[(i - 1 + n) % n];
    let nCurr = edgeNormals[i];
    let bx = nPrev[0] + nCurr[0];
    let by = nPrev[1] + nCurr[1];
    let blen = Math.hypot(bx, by) || 1;
    bx /= blen;
    by /= blen;
    // Clamp miter expansion
    let dot = nPrev[0] * bx + nPrev[1] * by;
    let miter = Math.min(1.35, 1 / Math.max(0.5, dot));
    vertNormals.push([bx * miter, by * miter]);

    let p = topPoly[i];
    let ext = getExtrudeVector(p[0], p[1], heightScale);
    basePoly.push([
      p[0] + ext[0] + bx * miter * draftWidth,
      p[1] + ext[1] + by * miter * draftWidth
    ]);

    terracePoly.push([
      p[0] + ext[0] * 0.55 + bx * miter * (draftWidth * 0.62),
      p[1] + ext[1] * 0.55 + by * miter * (draftWidth * 0.62)
    ]);
  }

  return { edgeNormals, vertNormals, basePoly, terracePoly };
}

// Check if polygon intersects visible 1200x1200 frame (with margin)
function isPolyVisible(pts, margin = 90) {
  for (let i = 0; i < pts.length; i++) {
    let x = pts[i][0];
    let y = pts[i][1];
    if (x >= -margin && x <= width + margin && y >= -margin && y <= height + margin) {
      return true;
    }
  }
  return false;
}

function getPolyBounds(pts) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  let cx = 0, cy = 0;
  for (let p of pts) {
    if (p[0] < minX) minX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] > maxY) maxY = p[1];
    cx += p[0];
    cy += p[1];
  }
  cx /= pts.length;
  cy /= pts.length;
  return { minX, minY, maxX, maxY, cx, cy };
}

// ============================================================================
// ORTHOGONAL & STEPPED KUBA-TRACTOR POLYGON BUILDERS IN (U, V) SPACE
// ============================================================================

// Builds a chamfered thick rubber lug polygon around an orthogonal path in (u, v) space
function makeOrthogonalLugUV(pts, hw, startSlant = 0, endSlant = 0, ch = 0.08) {
  let m = pts.length;
  if (m < 2) return [];

  let dirs = [];
  let norms = [];
  for (let i = 0; i < m - 1; i++) {
    let du = pts[i + 1][0] - pts[i][0];
    let dv = pts[i + 1][1] - pts[i][1];
    let len = Math.hypot(du, dv) || 1;
    let dx = du / len;
    let dy = dv / len;
    dirs.push([dx, dy]);
    norms.push([-dy, dx]); // left normal
  }

  let leftRail = [];
  let rightRail = [];
  let c = Math.min(ch, hw * 0.55);

  // Start cap at pts[0]
  let p0 = pts[0];
  let d0 = dirs[0];
  let n0 = norms[0];
  let sL0 = -startSlant * hw;
  let sR0 = startSlant * hw;

  leftRail.push([
    p0[0] + n0[0] * (hw - c) + d0[0] * sL0,
    p0[1] + n0[1] * (hw - c) + d0[1] * sL0
  ]);
  leftRail.push([
    p0[0] + n0[0] * hw + d0[0] * (sL0 + c),
    p0[1] + n0[1] * hw + d0[1] * (sL0 + c)
  ]);

  rightRail.push([
    p0[0] - n0[0] * (hw - c) + d0[0] * sR0,
    p0[1] - n0[1] * (hw - c) + d0[1] * sR0
  ]);
  rightRail.push([
    p0[0] - n0[0] * hw + d0[0] * (sR0 + c),
    p0[1] - n0[1] * hw + d0[1] * (sR0 + c)
  ]);

  // Interior corners
  for (let i = 1; i < m - 1; i++) {
    let pk = pts[i];
    let dPrev = dirs[i - 1];
    let dNext = dirs[i];
    let nPrev = norms[i - 1];
    let nNext = norms[i];
    let cross = dPrev[0] * dNext[1] - dPrev[1] * dNext[0];

    if (Math.abs(cross) < 0.01) {
      leftRail.push([pk[0] + nPrev[0] * hw, pk[1] + nPrev[1] * hw]);
      rightRail.push([pk[0] - nPrev[0] * hw, pk[1] - nPrev[1] * hw]);
    } else if (cross < 0) {
      // Right turn: left is outer bevel, right is inner corner
      leftRail.push([
        pk[0] + nPrev[0] * hw + dPrev[0] * (hw - c * 1.4),
        pk[1] + nPrev[1] * hw + dPrev[1] * (hw - c * 1.4)
      ]);
      leftRail.push([
        pk[0] + nNext[0] * hw - dNext[0] * (hw - c * 1.4),
        pk[1] + nNext[1] * hw - dNext[1] * (hw - c * 1.4)
      ]);

      rightRail.push([
        pk[0] - nPrev[0] * hw - dPrev[0] * (hw + c * 0.5),
        pk[1] - nPrev[1] * hw - dPrev[1] * (hw + c * 0.5)
      ]);
      rightRail.push([
        pk[0] - nNext[0] * hw + dNext[0] * (hw + c * 0.5),
        pk[1] - nNext[1] * hw + dNext[1] * (hw + c * 0.5)
      ]);
    } else {
      // Left turn: left is inner corner, right is outer bevel
      leftRail.push([
        pk[0] + nPrev[0] * hw - dPrev[0] * (hw + c * 0.5),
        pk[1] + nPrev[1] * hw - dPrev[1] * (hw + c * 0.5)
      ]);
      leftRail.push([
        pk[0] + nNext[0] * hw + dNext[0] * (hw + c * 0.5),
        pk[1] + nNext[1] * hw + dNext[1] * (hw + c * 0.5)
      ]);

      rightRail.push([
        pk[0] - nPrev[0] * hw + dPrev[0] * (hw - c * 1.4),
        pk[1] - nPrev[1] * hw + dPrev[1] * (hw - c * 1.4)
      ]);
      rightRail.push([
        pk[0] - nNext[0] * hw - dNext[0] * (hw - c * 1.4),
        pk[1] - nNext[1] * hw - dNext[1] * (hw - c * 1.4)
      ]);
    }
  }

  // End cap at pts[m - 1]
  let pm = pts[m - 1];
  let dm = dirs[m - 2];
  let nm = norms[m - 2];
  let sLm = endSlant * hw;
  let sRm = -endSlant * hw;

  leftRail.push([
    pm[0] + nm[0] * hw + dm[0] * (sLm - c),
    pm[1] + nm[1] * hw + dm[1] * (sLm - c)
  ]);
  leftRail.push([
    pm[0] + nm[0] * (hw - c) + dm[0] * sLm,
    pm[1] + nm[1] * (hw - c) + dm[1] * sLm
  ]);

  rightRail.push([
    pm[0] - nm[0] * hw + dm[0] * (sRm - c),
    pm[1] - nm[1] * hw + dm[1] * (sRm - c)
  ]);
  rightRail.push([
    pm[0] - nm[0] * (hw - c) + dm[0] * sRm,
    pm[1] - nm[1] * (hw - c) + dm[1] * sRm
  ]);

  return leftRail.concat(rightRail.reverse());
}

// Builds a Kuba stepped diamond lozenge centered at (cu, cv) in (u, v) space
function makeSteppedDiamondUV(cu, cv, r, steps = 2) {
  let pts = [];
  if (steps === 1) {
    let s = r * 0.46;
    let c = r * 0.12;
    // Cross / 1-step terraced diamond
    pts = [
      [cu - s, cv - r], [cu + s, cv - r],
      [cu + s, cv - s], [cu + r, cv - s],
      [cu + r, cv + s], [cu + s, cv + s],
      [cu + s, cv + r], [cu - s, cv + r],
      [cu - s, cv + s], [cu - r, cv + s],
      [cu - r, cv - s], [cu - s, cv - s]
    ];
    // Chamfer tips slightly
    return chamferLoopUV(pts, c);
  } else {
    let s1 = r * 0.32;
    let s2 = r * 0.66;
    pts = [
      [cu - s1, cv - r], [cu + s1, cv - r],
      [cu + s1, cv - s2], [cu + s2, cv - s2],
      [cu + s2, cv - s1], [cu + r, cv - s1],
      [cu + r, cv + s1], [cu + s2, cv + s1],
      [cu + s2, cv + s2], [cu + s1, cv + s2],
      [cu + s1, cv + r], [cu - s1, cv + r],
      [cu - s1, cv + s2], [cu - s2, cv + s2],
      [cu - s2, cv + s1], [cu - r, cv + s1],
      [cu - r, cv - s1], [cu - s2, cv - s1],
      [cu - s2, cv - s2], [cu - s1, cv - s2]
    ];
    return chamferLoopUV(pts, r * 0.07);
  }
}

function chamferLoopUV(pts, ch) {
  let out = [];
  let n = pts.length;
  for (let i = 0; i < n; i++) {
    let pPrev = pts[(i - 1 + n) % n];
    let pCurr = pts[i];
    let pNext = pts[(i + 1) % n];
    let d1u = pPrev[0] - pCurr[0], d1v = pPrev[1] - pCurr[1];
    let l1 = Math.hypot(d1u, d1v) || 1;
    let d2u = pNext[0] - pCurr[0], d2v = pNext[1] - pCurr[1];
    let l2 = Math.hypot(d2u, d2v) || 1;
    let c1 = Math.min(ch, l1 * 0.35);
    let c2 = Math.min(ch, l2 * 0.35);
    out.push([pCurr[0] + (d1u / l1) * c1, pCurr[1] + (d1v / l1) * c1]);
    out.push([pCurr[0] + (d2u / l2) * c2, pCurr[1] + (d2v / l2) * c2]);
  }
  return out;
}

function registerLug(uvPts, options = {}) {
  let topPoly = refineRubberPolygon(uvPts, options.jitter ?? 1.5);
  if (!isPolyVisible(topPoly, 110)) return;

  let draftWidth = options.draftWidth ?? random(12.5, 15.5);
  let heightScale = options.heightScale ?? random(0.9, 1.18);
  let geom = computeLug3DGeometry(topPoly, draftWidth, heightScale);
  let bounds = getPolyBounds(topPoly);

  // Determine cut-pile nap orientation (echoing Kuba directional raffia weave)
  let napAngle = options.napAngle ?? (random() < 0.5 ? 33 : 131) + random(-8, 8);
  let hasTerrace = options.hasTerrace ?? (random() < 0.42);
  let dustWeight = options.dustWeight ?? random(0.75, 1.35);
  let sipes = [];

  if (options.sipeUVs) {
    for (let s of options.sipeUVs) {
      sipes.push([uvToXY(s[0][0], s[0][1]), uvToXY(s[1][0], s[1][1])]);
    }
  }

  lugs.push({
    topPoly,
    basePoly: geom.basePoly,
    terracePoly: geom.terracePoly,
    edgeNormals: geom.edgeNormals,
    vertNormals: geom.vertNormals,
    bounds,
    napAngle,
    hasTerrace,
    dustWeight,
    heightScale,
    sipes,
    crownTone: random([PALETTE.sootDark, PALETTE.sootMid, "#1a1c26"])
  });
}

// ============================================================================
// TECTONIC LABYRINTH GENERATOR (KUBA RAFFIA + TRACTOR CHEVRONS)
// ============================================================================

function buildTreadLabyrinth() {
  // Partition the (u, v) grid [-9..9] x [-9..9] into non-repeating tectonic patches
  // where motifs abruptly break, shift phase, and restart without warning
  let U_MIN = -9, U_MAX = 9;
  let V_MIN = -9, V_MAX = 9;
  let cols = U_MAX - U_MIN;
  let rows = V_MAX - V_MIN;
  let occupied = Array.from({ length: cols }, () => Array(rows).fill(false));

  let candidateSizes = [
    [3, 3], [4, 3], [3, 4], [3, 2], [2, 3], [4, 2], [2, 4], [2, 2]
  ];

  for (let iu = 0; iu < cols; iu++) {
    for (let iv = 0; iv < rows; iv++) {
      if (occupied[iu][iv]) continue;

      // Pick a patch size that fits unoccupied cells
      let choices = shuffle(candidateSizes.slice());
      let chosenW = 2, chosenH = 2;
      let found = false;

      for (let [pw, ph] of choices) {
        if (iu + pw <= cols && iv + ph <= rows) {
          let ok = true;
          for (let du = 0; du < pw && ok; du++) {
            for (let dv = 0; dv < ph && ok; dv++) {
              if (occupied[iu + du][iv + dv]) ok = false;
            }
          }
          if (ok) {
            chosenW = pw;
            chosenH = ph;
            found = true;
            break;
          }
        }
      }

      if (!found) {
        chosenW = 1;
        chosenH = 1;
      }

      for (let du = 0; du < chosenW; du++) {
        for (let dv = 0; dv < chosenH; dv++) {
          if (iu + du < cols && iv + dv < rows) {
            occupied[iu + du][iv + dv] = true;
          }
        }
      }

      // Tectonic phase slip (creates the Kuba "breaks and restarts without warning" fault effect)
      let slipU = random([-0.14, 0, 0.14]);
      let slipV = random([-0.14, 0, 0.14]);
      let u0 = U_MIN + iu + slipU;
      let v0 = V_MIN + iv + slipV;

      populatePatch(u0, v0, chosenW, chosenH, iu * 31 + iv * 17);
    }
  }

  // Sort lugs back-to-front along the viewing extrusion direction (x * 0.4 + y * 0.7)
  lugs.sort((a, b) => (a.bounds.cx * 0.4 + a.bounds.cy * 0.7) - (b.bounds.cx * 0.4 + b.bounds.cy * 0.7));
}

function populatePatch(u0, v0, w, h, patchId) {
  let pad = 0.17; // Groove margin around tectonic patch
  let uA = u0 + pad;
  let vA = v0 + pad;
  let uB = u0 + w - pad;
  let vB = v0 + h - pad;
  let uw = uB - uA;
  let vh = vB - vA;
  let cu = (uA + uB) * 0.5;
  let cv = (vA + vB) * 0.5;

  if (w === 1 && h === 1) {
    // Compact single stepped diamond or split chevron button
    let poly = makeSteppedDiamondUV(cu, cv, Math.min(uw, vh) * 0.46, 1);
    registerLug(poly, {
      napAngle: 33,
      hasTerrace: true,
      sipeUVs: [[[cu - 0.15, cv], [cu + 0.15, cv]]]
    });
    return;
  }

  // Select motif archetype based on patch aspect and random Kuba variation
  let motifRoll = random();

  if (w >= 3 && h >= 3 && motifRoll < 0.46) {
    // MOTIF A: Kuba Kasai Stepped Diamond Complex + Framing Chevron Cradles
    buildSteppedDiamondComplex(uA, vA, uB, vB, cu, cv, uw, vh);
  } else if (motifRoll < 0.68) {
    // MOTIF B: Heavy Interlocking Tractor Chevrons with Interrupted Phase Shift
    buildInterlockingTractorChevrons(uA, vA, uB, vB, uw, vh, patchId % 2 === 0);
  } else if (motifRoll < 0.86) {
    // MOTIF C: Kuba Meander Hooks & Stepped Labyrinth Bars
    buildKubaMeanderLabyrinth(uA, vA, uB, vB, uw, vh, patchId % 3);
  } else {
    // MOTIF D: Fractured Split-Pitch Ribs & Offset Lozenges
    buildFracturedSplitRibs(uA, vA, uB, vB, uw, vh, w >= h);
  }
}

// MOTIF A: Stepped diamond core surrounded by stepped V-chevron cradles
function buildSteppedDiamondComplex(uA, vA, uB, vB, cu, cv, uw, vh) {
  let hw = Math.min(uw, vh) * 0.088;

  // Outer upper-left stepped chevron cradle
  let cradle1 = [
    [uA + hw, vA + vh * 0.68],
    [uA + hw, vA + vh * 0.24],
    [uA + uw * 0.24, vA + vh * 0.24],
    [uA + uw * 0.24, vA + hw],
    [uA + uw * 0.68, vA + hw]
  ];
  registerLug(makeOrthogonalLugUV(cradle1, hw, 0.35, -0.35), {
    napAngle: 33,
    hasTerrace: true,
    dustWeight: 1.25,
    sipeUVs: [[[uA + uw * 0.24, vA + vh * 0.12], [uA + uw * 0.24, vA + vh * 0.24]]]
  });

  // Outer lower-right stepped chevron cradle
  let cradle2 = [
    [uB - hw, vB - vh * 0.68],
    [uB - hw, vB - vh * 0.24],
    [uB - uw * 0.24, vB - vh * 0.24],
    [uB - uw * 0.24, vB - hw],
    [uB - uw * 0.68, vB - hw]
  ];
  registerLug(makeOrthogonalLugUV(cradle2, hw, 0.35, -0.35), {
    napAngle: 131,
    hasTerrace: true,
    dustWeight: 1.25,
    sipeUVs: [[[uB - uw * 0.24, vB - vh * 0.12], [uB - uw * 0.24, vB - vh * 0.24]]]
  });

  // Secondary corner L-chevrons in the opposite corners
  let cornerTR = [
    [uA + uw * 0.82, vA + hw],
    [uB - hw, vA + hw],
    [uB - hw, vA + vh * 0.22]
  ];
  registerLug(makeOrthogonalLugUV(cornerTR, hw * 0.9, 0.2, -0.2), { napAngle: 131 });

  let cornerBL = [
    [uA + hw, vB - vh * 0.22],
    [uA + hw, vB - hw],
    [uA + uw * 0.22, vB - hw]
  ];
  registerLug(makeOrthogonalLugUV(cornerBL, hw * 0.9, 0.2, -0.2), { napAngle: 33 });

  // Inner concentric chevron pair
  let inOff = Math.min(uw, vh) * 0.26;
  let inner1 = [
    [uA + inOff, cv + vh * 0.14],
    [uA + inOff, vA + inOff],
    [cu + uw * 0.14, vA + inOff]
  ];
  registerLug(makeOrthogonalLugUV(inner1, hw * 0.86, 0.3, -0.3), {
    napAngle: 131,
    sipeUVs: [[[uA + inOff, vA + inOff], [uA + inOff + 0.12, vA + inOff + 0.12]]]
  });

  let inner2 = [
    [uB - inOff, cv - vh * 0.14],
    [uB - inOff, vB - inOff],
    [cu - uw * 0.14, vB - inOff]
  ];
  registerLug(makeOrthogonalLugUV(inner2, hw * 0.86, 0.3, -0.3), {
    napAngle: 33
  });

  // Central Kuba stepped diamond core
  let coreRadius = Math.min(uw, vh) * 0.19;
  let diamondCore = makeSteppedDiamondUV(cu, cv, coreRadius, 2);
  registerLug(diamondCore, {
    napAngle: 82,
    hasTerrace: true,
    heightScale: 1.15,
    dustWeight: 1.35,
    sipeUVs: [
      [[cu - coreRadius * 0.45, cv], [cu + coreRadius * 0.45, cv]],
      [[cu, cv - coreRadius * 0.45], [cu, cv + coreRadius * 0.45]]
    ]
  });
}

// MOTIF B: Chunky interlocking tractor chevrons that jog and shift phase mid-field
function buildInterlockingTractorChevrons(uA, vA, uB, vB, uw, vh, flip) {
  let numPitch = Math.max(2, Math.round((uw + vh) * 0.45));
  let stepV = vh / numPitch;
  let hw = Math.min(0.24, stepV * 0.29);

  for (let i = 0; i < numPitch; i++) {
    let vBase = vA + (i + 0.5) * stepV;
    let midU = uA + uw * (i % 2 === 0 ? 0.56 : 0.44);

    if (flip) {
      // Left-sweeping bent tractor lug with stepped hammerhead
      let ptsL = [
        [uA + hw, vBase - stepV * 0.18],
        [uA + uw * 0.28, vBase - stepV * 0.18],
        [uA + uw * 0.28, vBase + stepV * 0.12],
        [midU - hw * 0.7, vBase + stepV * 0.12]
      ];
      registerLug(makeOrthogonalLugUV(ptsL, hw, 0.2, 0.55), {
        napAngle: 33,
        hasTerrace: i % 2 === 0,
        sipeUVs: [[[uA + uw * 0.15, vBase - stepV * 0.18], [uA + uw * 0.26, vBase - stepV * 0.18]]]
      });

      // Right-sweeping interlocking chevron lug
      let ptsR = [
        [midU + hw * 0.7, vBase - stepV * 0.12],
        [uB - uw * 0.25, vBase - stepV * 0.12],
        [uB - uw * 0.25, vBase + stepV * 0.22],
        [uB - hw, vBase + stepV * 0.22]
      ];
      registerLug(makeOrthogonalLugUV(ptsR, hw, -0.55, -0.2), {
        napAngle: 131,
        hasTerrace: i % 2 === 1,
        dustWeight: 1.2
      });
    } else {
      // Deep V-chevron bar spanning across patch with a break on one flank
      let apexU = uA + uw * (i % 2 === 0 ? 0.64 : 0.36);
      let vTop = Math.max(vA + hw, vBase - stepV * 0.34);
      let vBot = Math.min(vB - hw, vBase + stepV * 0.34);

      let chevronPts = [
        [uA + hw, vTop],
        [apexU, vTop],
        [apexU, vBot]
      ];
      registerLug(makeOrthogonalLugUV(chevronPts, hw, 0.35, -0.45), {
        napAngle: 33,
        hasTerrace: true,
        sipeUVs: [[[apexU - 0.25, vTop], [apexU, vTop]]]
      });

      // Counter-lug filling the interrupted side
      if (uB - apexU > hw * 3.2) {
        let counterPts = [
          [apexU + hw * 2.1, vTop],
          [uB - hw, vTop],
          [uB - hw, vBot]
        ];
        registerLug(makeOrthogonalLugUV(counterPts, hw * 0.92, 0.4, -0.3), {
          napAngle: 131
        });
      }
    }
  }
}

// MOTIF C: Kuba interlocking hooks & stepped meander ribs
function buildKubaMeanderLabyrinth(uA, vA, uB, vB, uw, vh, variant) {
  let hw = Math.min(uw, vh) * 0.095;
  let cu = (uA + uB) * 0.5;
  let cv = (vA + vB) * 0.5;

  if (variant === 0) {
    // Twin interlocking G-hooks wrapping around each other
    let hook1 = [
      [uA + hw, vB - hw],
      [uA + hw, vA + hw],
      [uB - hw, vA + hw],
      [uB - hw, cv - hw * 0.4],
      [cu - hw * 0.6, cv - hw * 0.4]
    ];
    registerLug(makeOrthogonalLugUV(hook1, hw, 0.3, -0.4), {
      napAngle: 33,
      hasTerrace: true,
      dustWeight: 1.3,
      sipeUVs: [[[uA + hw, vA + vh * 0.35], [uA + hw, vA + vh * 0.65]]]
    });

    let hook2 = [
      [uB - hw, vA + vh * 0.62],
      [uB - hw, vB - hw],
      [uA + uw * 0.34, vB - hw],
      [uA + uw * 0.34, cv + hw * 1.4],
      [cu + uw * 0.18, cv + hw * 1.4]
    ];
    registerLug(makeOrthogonalLugUV(hook2, hw, 0.3, 0.4), {
      napAngle: 131,
      hasTerrace: true,
      dustWeight: 1.25
    });
  } else {
    // Stepped staircase diagonals flanked by chevron wedges
    let stair = [
      [uA + hw, vB - vh * 0.35],
      [uA + hw, cv],
      [cu, cv],
      [cu, vA + hw],
      [uB - vh * 0.3, vA + hw]
    ];
    registerLug(makeOrthogonalLugUV(stair, hw * 1.05, 0.35, -0.35), {
      napAngle: 33,
      hasTerrace: true,
      heightScale: 1.12,
      sipeUVs: [[[cu - 0.2, cv], [cu, cv]]]
    });

    let stair2 = [
      [uA + uw * 0.38, vB - hw],
      [cu + uw * 0.16, vB - hw],
      [cu + uw * 0.16, cv + vh * 0.12],
      [uB - hw, cv + vh * 0.12],
      [uB - hw, vA + vh * 0.38]
    ];
    registerLug(makeOrthogonalLugUV(stair2, hw * 0.98, 0.4, -0.4), {
      napAngle: 131,
      hasTerrace: true
    });

    // Corner diamond button
    let btn1 = makeSteppedDiamondUV(uA + uw * 0.22, vA + vh * 0.22, hw * 1.35, 1);
    registerLug(btn1, { napAngle: 82 });

    let btn2 = makeSteppedDiamondUV(uB - uw * 0.2, vB - vh * 0.2, hw * 1.3, 1);
    registerLug(btn2, { napAngle: 82 });
  }
}

// MOTIF D: Fractured parallel tractor bars interrupted by a cross-fault channel
function buildFracturedSplitRibs(uA, vA, uB, vB, uw, vh, alongU) {
  let count = 3;
  if (alongU) {
    let stepV = vh / count;
    let hw = Math.min(0.22, stepV * 0.31);
    let faultU = uA + uw * random(0.42, 0.58);

    for (let i = 0; i < count; i++) {
      let vc = vA + (i + 0.5) * stepV;
      let shift = (i % 2 === 0 ? 1 : -1) * stepV * 0.14;

      // Left bar segment before fault
      let seg1 = [
        [uA + hw, vc],
        [faultU - hw * 0.9, vc]
      ];
      registerLug(makeOrthogonalLugUV(seg1, hw, 0.3, 0.55), {
        napAngle: 33,
        sipeUVs: [[[uA + uw * 0.18, vc], [uA + uw * 0.32, vc]]]
      });

      // Right bar segment restarted across the fault with phase shift
      let vc2 = constrain(vc + shift, vA + hw * 1.2, vB - hw * 1.2);
      let seg2 = [
        [faultU + hw * 0.9, vc2],
        [uB - hw, vc2]
      ];
      registerLug(makeOrthogonalLugUV(seg2, hw, -0.55, -0.3), {
        napAngle: 131,
        hasTerrace: i === 1
      });
    }
  } else {
    let stepU = uw / count;
    let hw = Math.min(0.22, stepU * 0.31);
    let faultV = vA + vh * random(0.42, 0.58);

    for (let i = 0; i < count; i++) {
      let uc = uA + (i + 0.5) * stepU;
      let shift = (i % 2 === 0 ? 1 : -1) * stepU * 0.14;

      let seg1 = [
        [uc, vA + hw],
        [uc, faultV - hw * 0.9]
      ];
      registerLug(makeOrthogonalLugUV(seg1, hw, 0.3, 0.55), {
        napAngle: 131
      });

      let uc2 = constrain(uc + shift, uA + hw * 1.2, uB - hw * 1.2);
      let seg2 = [
        [uc2, faultV + hw * 0.9],
        [uc2, vB - hw]
      ];
      registerLug(makeOrthogonalLugUV(seg2, hw, -0.55, -0.3), {
        napAngle: 33,
        hasTerrace: i === 1,
        sipeUVs: [[[uc2, faultV + vh * 0.18], [uc2, faultV + vh * 0.32]]]
      });
    }
  }
}

