// PASS 1: Recessed Groove Floor (Soot-black abyss + raw sienna dust beds + deep crosshatching)
function drawGrooveFloor() {
  // Base dark twilight wash
  brush.noStroke();
  brush.wash(PALETTE.sootDeep, 245);
  brush.rect(0, 0, width, height, "corner");
  brush.noWash();

  // Batch watercolor washes for drifted raw sienna & ochre dirt beds in the deep channels
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.45);

  let dustWashColors = [PALETTE.siennaDark, PALETTE.siennaDeep, PALETTE.siennaRaw, "#3b2312"];
  for (let c of dustWashColors) {
    brush.fill(c, 55);
    for (let i = 0; i < 6; i++) {
      let cx = random(-60, width + 60);
      let cy = random(-60, height + 60);
      let rx = random(140, 320);
      let ry = random(90, 240);
      brush.beginShape(0.4);
      for (let a = 0; a < 360; a += 45) {
        let rad = lerp(rx, ry, (Math.sin(a * 2 * (Math.PI / 180)) + 1) * 0.5) * random(0.75, 1.25);
        brush.vertex(cx + Math.cos(a * (Math.PI / 180)) * rad, cy + Math.sin(a * (Math.PI / 180)) * rad);
      }
      brush.endShape(true);
    }
  }
  brush.noFill();

  // Deep crosshatched shadows sinking into the grooves across the entire carcass
  let fullFrame = new brush.Polygon([[-40, -40], [width + 40, -40], [width + 40, height + 40], [-40, height + 40]]);

  // Pass A: Diagonal groove-axis charcoal hatching (33 deg)
  brush.hatchStyle("charcoal", PALETTE.voidBlack, 0.65);
  fullFrame.hatch(7.5, 33, { rand: 0.08 });

  // Pass B: Counter-chevron graphite crosshatching (131 deg)
  brush.hatchStyle("2B", "#14161f", 0.55);
  fullFrame.hatch(8.5, 131, { rand: 0.08 });

  // Pass C: Raw sienna dusty crosshatching in the recessed valleys (-12 deg)
  brush.hatchStyle("cpencil", PALETTE.siennaDeep, 0.45);
  fullFrame.hatch(14, -12, { rand: 0.15 });

  // Pass D: Flow-field carcass fibers & dried mud cracks in the groove bed
  brush.field("tyre_weave");
  for (let i = 0; i < 180; i++) {
    let fx = random(-20, width + 20);
    let fy = random(-20, height + 20);
    let col = random([PALETTE.voidBlack, PALETTE.siennaRaw, PALETTE.ochreDark, "#22160f"]);
    brush.set("charcoal", col, random(0.35, 0.75));
    brush.flowLine(fx, fy, random(35, 95), random() < 0.5 ? 33 : 131);
  }
  brush.noField();
}

// PASS 2: Deep Cast Shadows & Concave Raw Sienna Dust Drifts at Lug Bases
function drawLugCastShadowsAndBaseDust() {
  for (let lug of lugs) {
    let base = lug.basePoly;
    let n = base.length;

    // Project cast shadow along twilight grazing light vector (+15, +17)
    let shadowPolyPts = base.map(p => [p[0] + 15 * lug.heightScale, p[1] + 17 * lug.heightScale]);
    let shadowPoly = new brush.Polygon(shadowPolyPts);

    brush.noStroke();
    shadowPoly.wash(PALETTE.voidBlack, 210);

    // Dense crosshatching inside the cast shadow trench
    brush.hatchStyle("rotring", PALETTE.voidBlack, 0.5);
    shadowPoly.hatch(4.8, 52, { rand: 0.05 });

    // Concave raw sienna & ochre dust drifted against the base of the rubber walls
    for (let i = 0; i < n; i++) {
      let b1 = base[i];
      let b2 = base[(i + 1) % n];
      let segLen = Math.hypot(b2[0] - b1[0], b2[1] - b1[1]);
      if (segLen < 6) continue;

      let norm = lug.edgeNormals[i];
      let lightDot = norm[0] * LIGHT_X + norm[1] * LIGHT_Y;

      // Dust collects heavily in windward/upper-left base fillets and step pockets
      if (lightDot > -0.35) {
        let offset = 3.5;
        let p1x = b1[0] + norm[0] * offset;
        let p1y = b1[1] + norm[1] * offset;
        let p2x = b2[0] + norm[0] * offset;
        let p2y = b2[1] + norm[1] * offset;

        brush.set("dust_drift", PALETTE.siennaRaw, random(0.55, 0.95) * lug.dustWeight);
        brush.line(p1x, p1y, p2x, p2y);

        if (lightDot > 0.15 && random() < 0.75) {
          brush.set("cpencil", PALETTE.ochreDark, random(0.4, 0.65) * lug.dustWeight);
          brush.line(b1[0] + norm[0] * 1.5, b1[1] + norm[1] * 1.5, b2[0] + norm[0] * 1.5, b2[1] + norm[1] * 1.5);
        }
      } else {
        // Deepest shadow crease right under shadow wall
        brush.set("charcoal", PALETTE.voidBlack, 0.75);
        brush.line(b1[0], b1[1], b2[0], b2[1]);
      }
    }
  }
}

// PASS 3: Lower Molded Rubber Buttress Terraces (Stepped Relief)
function drawLugTerraces() {
  for (let lug of lugs) {
    if (!lug.hasTerrace) continue;

    let terrPoly = new brush.Polygon(lug.terracePoly);
    terrPoly.wash(PALETTE.sootDeep, 245);

    // Hatched rubber buttress shelf dusted with raw sienna
    brush.hatchStyle("charcoal", PALETTE.siennaDeep, 0.48);
    terrPoly.hatch(5.2, lug.napAngle + 45, { rand: 0.08 });

    terrPoly.draw("2B", PALETTE.ochreDark, 0.42);
  }
}

// PASS 4: 3D Extruded & Beveled Sidewalls of the Chunky Rubber Lugs
function drawLugSidewalls() {
  for (let lug of lugs) {
    let top = lug.topPoly;
    let base = lug.basePoly;
    let norms = lug.edgeNormals;
    let n = top.length;

    // Build all sidewall facets and sort from lit-back to shadow-front
    let facets = [];
    for (let i = 0; i < n; i++) {
      let next = (i + 1) % n;
      let norm = norms[i];
      let lightDot = norm[0] * LIGHT_X + norm[1] * LIGHT_Y;
      facets.push({
        idx: i,
        p1: top[i],
        p2: top[next],
        b2: base[next],
        b1: base[i],
        norm,
        lightDot
      });
    }

    facets.sort((a, b) => b.lightDot - a.lightDot);

    for (let f of facets) {
      let quadPts = [f.p1, f.p2, f.b2, f.b1];
      let quadPoly = new brush.Polygon(quadPts);
      let segLen = Math.hypot(f.p2[0] - f.p1[0], f.p2[1] - f.p1[1]);

      if (f.lightDot > 0.22) {
        // Lit upper-left beveled sidewall catching twilight & raw sienna/ochre dust
        quadPoly.wash("#2b231e", 252);

        if (segLen > 10) {
          let edgeAng = atan2(f.p2[1] - f.p1[1], f.p2[0] - f.p1[0]);
          brush.hatchStyle("cpencil", PALETTE.siennaBright, 0.48);
          quadPoly.hatch(4.2, edgeAng, { rand: 0.06 });

          // Mold draft striations running from crown lip down to groove base
          let striaSteps = Math.max(2, Math.floor(segLen / 11));
          for (let s = 0; s <= striaSteps; s++) {
            let t = s / striaSteps;
            let tx = lerp(f.p1[0], f.p2[0], t);
            let ty = lerp(f.p1[1], f.p2[1], t);
            let bx = lerp(f.b1[0], f.b2[0], t);
            let by = lerp(f.b1[1], f.b2[1], t);
            let col = s % 2 === 0 ? PALETTE.ochreWarm : PALETTE.siennaRaw;
            brush.set("2B", col, 0.38);
            brush.line(tx, ty, bx, by);
          }
        }
      } else if (f.lightDot > -0.22) {
        // Grazing sidewall in mid-tone dusty soot & raw sienna
        quadPoly.wash(PALETTE.sootDark, 252);

        if (segLen > 10) {
          let edgeAng = atan2(f.p2[1] - f.p1[1], f.p2[0] - f.p1[0]);
          brush.hatchStyle("2B", PALETTE.siennaDeep, 0.45);
          quadPoly.hatch(4.5, edgeAng + 25, { rand: 0.07 });
        }
      } else {
        // Deep shadow sidewall (facing lower-right): heavy soot-black charcoal crosshatching
        quadPoly.wash(PALETTE.voidBlack, 254);

        if (segLen > 10) {
          let edgeAng = atan2(f.p2[1] - f.p1[1], f.p2[0] - f.p1[0]);
          brush.hatchStyle("charcoal", PALETTE.voidBlack, 0.62);
          quadPoly.hatch(3.8, edgeAng, { rand: 0.05 });

          // Subtle reflected sienna bounce light from groove floor along bottom of shadow wall
          brush.set("cpencil", PALETTE.siennaDark, 0.38);
          brush.line(
            lerp(f.p1[0], f.b1[0], 0.72),
            lerp(f.p1[1], f.b1[1], 0.72),
            lerp(f.p2[0], f.b2[0], 0.72),
            lerp(f.p2[1], f.b2[1], 0.72)
          );
        }
      }
    }
  }
}

// PASS 5: Top Tread Faces — Velvety Cut-Pile Nap (Graphite & Charcoal Hatching)
function drawLugCrowns() {
  for (let lug of lugs) {
    let poly = new brush.Polygon(lug.topPoly);
    let b = lug.bounds;

    // Solid opaque rubber crown base so groove lines underneath are occluded
    poly.wash(lug.crownTone, 254);

    // Layer 1: Primary cut-pile charcoal hatching along the lug's weave grain
    brush.hatchStyle("charcoal", PALETTE.voidBlack, 0.56);
    poly.hatch(4.0, lug.napAngle, { rand: 0.07, gradient: 0.18 });

    // Layer 2: Cross-bias graphite hatching giving the rubber its velvety cut-pile sheen
    let sheenCol = random([PALETTE.sootNap, PALETTE.sootSheen, "#383333"]);
    brush.hatchStyle("2B", sheenCol, 0.42);
    poly.hatch(4.8, lug.napAngle + 26, { rand: 0.09 });

    // Layer 3: Subtle third directional pass on larger lugs for rich Kuba plush density
    let areaApprox = (b.maxX - b.minX) * (b.maxY - b.minY);
    if (areaApprox > 12000) {
      brush.hatchStyle("HB", PALETTE.twilightSlate, 0.34);
      poly.hatch(7.5, lug.napAngle - 35, { rand: 0.1 });
    }

    // Layer 4: Short velvety cut-pile tuft strokes & scuffed dust across the crown
    let tuftCount = Math.min(28, Math.max(6, Math.floor(areaApprox / 1100)));
    let napRad = lug.napAngle * (Math.PI / 180);
    let dx = Math.cos(napRad) * 6.5;
    let dy = Math.sin(napRad) * 6.5;

    for (let t = 0; t < tuftCount; t++) {
      // Pick points near the interior by averaging 3 random polygon vertices
      let v1 = random(lug.topPoly);
      let v2 = random(lug.topPoly);
      let v3 = random(lug.topPoly);
      let px = (v1[0] + v2[0] + v3[0]) / 3;
      let py = (v1[1] + v2[1] + v3[1]) / 3;

      let tuftCol = random([
        PALETTE.voidBlack,
        PALETTE.sootSheen,
        PALETTE.siennaDeep,
        PALETTE.twilightSlate
      ]);
      brush.set("velvet_nap", tuftCol, random(0.35, 0.65));
      brush.line(px - dx, py - dy, px + dx, py + dy);
    }

    // Crisp dark graphite contour inside the crown edge
    poly.draw("2B", PALETTE.voidBlack, 0.45);
  }
}

// PASS 6: Recessed Sipes, Mold Vents & Abraded Rubber Gouges
function drawLugSipesAndWear() {
  for (let lug of lugs) {
    // Draw molded traction sipes (narrow recessed slits across the rubber blocks)
    for (let sipe of lug.sipes) {
      let p1 = sipe[0];
      let p2 = sipe[1];
      let dx = p2[0] - p1[0];
      let dy = p2[1] - p1[1];
      let len = Math.hypot(dx, dy) || 1;
      let nx = -dy / len;
      let ny = dx / len;

      // Sipe shadow trench
      brush.set("rotring", PALETTE.voidBlack, 1.15);
      brush.line(p1[0], p1[1], p2[0], p2[1]);

      // Raw sienna dust packed inside the sipe slit
      brush.set("cpencil", PALETTE.siennaRaw, 0.55);
      brush.line(p1[0] + nx * 1.3, p1[1] + ny * 1.3, p2[0] + nx * 1.3, p2[1] + ny * 1.3);

      // Pale bone/ochre rim highlight on the lit lip of the sipe
      brush.set("2H", PALETTE.boneWarm, 0.45);
      brush.line(p1[0] - nx * 1.8, p1[1] - ny * 1.8, p2[0] - nx * 1.8, p2[1] - ny * 1.8);
    }

    // Molded inner offset crease (gives each chunky lug a subtly sunken center plateau like Kuba embroidery)
    let n = lug.topPoly.length;
    if (n >= 6 && random() < 0.72) {
      let cx = lug.bounds.cx;
      let cy = lug.bounds.cy;
      let step = Math.max(1, Math.floor(n / 8));
      for (let i = 0; i < n; i += step) {
        let pA = lug.topPoly[i];
        let pB = lug.topPoly[(i + 1) % n];
        let inA = [lerp(pA[0], cx, 0.22), lerp(pA[1], cy, 0.22)];
        let inB = [lerp(pB[0], cx, 0.22), lerp(pB[1], cy, 0.22)];
        brush.set("2B", PALETTE.voidBlack, 0.36);
        brush.line(inA[0], inA[1], inB[0], inB[1]);
      }
    }
  }
}

// PASS 7: Pale Dust Drifts (Raw Sienna, Ochre & Bone) Settling Along Every Ridge
function drawAllRidgeDustDrifts() {
  for (let lug of lugs) {
    let top = lug.topPoly;
    let norms = lug.edgeNormals;
    let n = top.length;

    for (let i = 0; i < n; i++) {
      let p1 = top[i];
      let p2 = top[(i + 1) % n];
      let segLen = Math.hypot(p2[0] - p1[0], p2[1] - p1[1]);
      if (segLen < 3) continue;

      let norm = norms[i];
      let inX = -norm[0];
      let inY = -norm[1];

      // How strongly this ridge catches the twilight light & drifted dust
      let lightDot = norm[0] * LIGHT_X + norm[1] * LIGHT_Y;
      let nVal = noise(p1[0] * 0.008, p1[1] * 0.008, 4.2);
      let driftStrength = constrain((lightDot + 0.65) * 0.75 + nVal * 0.5, 0.2, 1.45) * lug.dustWeight;

      // 1. Broad Raw Sienna under-drift feathering inward onto the velvety black crown
      brush.set("dust_drift", PALETTE.siennaRaw, 0.55 * driftStrength);
      brush.line(
        p1[0] + inX * 4.2,
        p1[1] + inY * 4.2,
        p2[0] + inX * 4.2,
        p2[1] + inY * 4.2
      );

      // Wind-blown short dust plumes creeping across the cut-pile rubber nap from the ridge
      if (segLen > 14 && driftStrength > 0.52) {
        let plumeSteps = Math.max(1, Math.floor(segLen / 16));
        for (let k = 0; k <= plumeSteps; k++) {
          let t = k / plumeSteps;
          let rx = lerp(p1[0], p2[0], t);
          let ry = lerp(p1[1], p2[1], t);
          let plumeLen = random(6, 17) * driftStrength;

          brush.set("cpencil", k % 2 === 0 ? PALETTE.siennaBright : PALETTE.ochreDark, random(0.32, 0.52));
          brush.line(rx, ry, rx + inX * plumeLen, ry + inY * plumeLen);
        }
      }

      // 2. Warm Ochre mid-drift hugging the ridge lip
      brush.set("cpencil", PALETTE.ochreWarm, 0.52 * driftStrength);
      brush.line(
        p1[0] + inX * 1.8,
        p1[1] + inY * 1.8,
        p2[0] + inX * 1.8,
        p2[1] + inY * 1.8
      );

      // 3. Pale Bone dust crest settled right along the ridge edge
      if (lightDot > -0.35) {
        let boneCol = lightDot > 0.25 ? PALETTE.boneCrest : (lightDot > -0.05 ? PALETTE.boneLight : PALETTE.boneShadow);
        let boneWeight = map(lightDot, -0.35, 0.85, 0.28, 0.68, true) * lug.dustWeight;

        brush.set("cpencil", boneCol, boneWeight);
        brush.line(p1[0], p1[1], p2[0], p2[1]);

        // Extra chalky bone drift pooled at stepped corners and chevron apexes
        if (lightDot > 0.1 && random() < 0.65) {
          brush.set("2H", PALETTE.boneCrest, boneWeight * 0.75);
          brush.line(
            p1[0] + inX * 0.9,
            p1[1] + inY * 0.9,
            lerp(p1[0], p2[0], 0.55) + inX * 2.2,
            lerp(p1[1], p2[1], 0.55) + inY * 2.2
          );
        }
      } else {
        // Shadowed trailing ridge still catches a faint rim of dusty bone-taupe and ochre
        brush.set("2H", PALETTE.ochreDark, 0.32 * lug.dustWeight);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }
}

// PASS 8: Hyperreal Surface Micro-Incidents (Granular Dust Specks, Gouges & Mold Flash)
function drawSurfaceMicroIncidents() {
  // Fine spray of raw sienna, ochre, and bone dust particles across ridges and grooves
  for (let i = 0; i < 95; i++) {
    let x1 = random(-20, width + 20);
    let y1 = random(-20, height + 20);
    let ang = random(360) * (Math.PI / 180);
    let len = random(18, 55);
    let col = random([PALETTE.siennaRaw, PALETTE.ochreWarm, PALETTE.boneWarm]);
    brush.set("spray", col, random(0.28, 0.52));
    brush.line(x1, y1, x1 + Math.cos(ang) * len, y1 + Math.sin(ang) * len);
  }

  // Tiny compacted dust crumbs, pebble scars, and hairline rubber weather-cracks
  for (let i = 0; i < 220; i++) {
    let x = random(0, width);
    let y = random(0, height);
    if (random() < 0.58) {
      // Pale bone / ochre dust granule cluster
      let col = random([PALETTE.boneLight, PALETTE.boneCrest, PALETTE.ochrePale, PALETTE.siennaBright]);
      brush.set("2H", col, random(0.35, 0.65));
      let d = random(2, 5.5);
      let a = random(360) * (Math.PI / 180);
      brush.line(x, y, x + Math.cos(a) * d, y + Math.sin(a) * d);
    } else {
      // Micro stress crack or rock nick in the vulcanized rubber
      brush.set("rotring", PALETTE.voidBlack, random(0.3, 0.55));
      let d = random(5, 14);
      let a = (random() < 0.5 ? 33 : 131) * (Math.PI / 180) + random(-0.4, 0.4);
      brush.line(x, y, x + Math.cos(a) * d, y + Math.sin(a) * d);
    }
  }
}
